input.new_string:
const selectableStatuses =
  allowedStatuses ?? getAllowedAppointmentStatuses(currentStatus);
const hasAvailableTransitions = selectableStatuses.length > 0;
const isFinalStatus = !hasAvailableTransitions && !isLoading;
const isTriggerDisabled = isLoading || !hasAvailableTransitions;
const statusLabel = statusConfig[currentStatus]?.label ?? currentStatus;
const finalStatusTooltip = isFinalStatus
  ? `This session is ${statusLabel.toLowerCase()}. Its status is final and can't be changed.`
  : null;

const triggerButton = (
  <button
    type="button"
    className={cn(
      "outline-none",
      isTriggerDisabled ? "opacity-60" : "cursor-pointer",
    )}
    disabled={isTriggerDisabled}
    aria-disabled={isTriggerDisabled}
    aria-label={
      finalStatusTooltip ?? (isLoading ? "Updating session status" : "Change session status")
    }
  >
    {isLoading ? (
      <Loader2 className="w-5 h-5 text-(--text-neutral-600) animate-spin" />
    ) : (
      <MoreVertical className="w-5 h-5 text-(--text-neutral-600)" />
    )}
  </button>
);

if (isTriggerDisabled) {
  if (finalStatusTooltip) {
    return (
      <TooltipProvider>
        <Tooltip delayDuration={200}>
          <TooltipTrigger asChild>
            <span className="inline-flex cursor-not-allowed rounded">
              {triggerButton}
            </span>
          </TooltipTrigger>
          <TooltipContent
            side="top"
            className="max-w-[220px] text-center leading-snug"
          >
            {finalStatusTooltip}
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>
    );
  }

  return triggerButton;
}

