import { useEffect, useRef, useState } from "react";
import { ChevronDown, Plus, Trash2 } from "lucide-react";
import { useFieldArray, useWatch, type Control } from "react-hook-form";
import CustomInput from "@/components/form/CustomInput";
import CustomTextarea from "@/components/form/CustomTextarea";
import CustomDatePicker from "@/components/form/CustomDatePicker";
import { Checkbox } from "@/components/ui/checkbox";
import { FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { cn } from "@/lib/utils";
import type { EducationEntryFormValues } from "@/schemas/user-profile-education.schema";
import { createEmptyEducationEntry } from "@/utils/userProfileEducation";

export type EducationEntriesFormValues = {
  education: EducationEntryFormValues[];
};

interface EducationEntryCardProps {
  control: Control<EducationEntriesFormValues>;
  fieldId: string;
  index: number;
  isExpanded: boolean;
  onToggleExpanded: () => void;
  onRemove: () => void;
}

const EducationEntryCard = ({
  control,
  fieldId,
  index,
  isExpanded,
  onToggleExpanded,
  onRemove,
}: EducationEntryCardProps) => {
  const degreeType = useWatch({
    control,
    name: `education.${index}.degreeType`,
  });
  const institution = useWatch({
    control,
    name: `education.${index}.institution`,
  });
  const fieldOfStudy = useWatch({
    control,
    name: `education.${index}.fieldOfStudy`,
  });

  const summaryParts = [degreeType, institution, fieldOfStudy]
    .map((value) => (typeof value === "string" ? value.trim() : ""))
    .filter(Boolean);
  const summary =
    summaryParts.length > 0 ? summaryParts.join(" · ") : `Education ${index + 1}`;

  return (
    <div className="rounded-xl border border-(--neutral-100) overflow-hidden">
      <div className="flex items-center justify-between gap-3 p-4">
        <button
          type="button"
          onClick={onToggleExpanded}
          className="flex min-w-0 flex-1 items-center gap-2 text-left cursor-pointer"
        >
          <ChevronDown
            size={18}
            className={cn(
              "shrink-0 text-(--text-neutral-400) transition-transform duration-300",
              isExpanded && "rotate-180",
            )}
          />
          <span
            className="min-w-0 truncate text-sm font-medium text-(--text-primary-dark)"
            title={summary}
          >
            {summary}
          </span>
        </button>
        <button
          type="button"
          onClick={onRemove}
          className="inline-flex shrink-0 items-center gap-1 text-sm text-(--status-denied) hover:opacity-80 cursor-pointer"
        >
          <Trash2 size={16} />
          Remove
        </button>
      </div>

      <div
        className={cn(
          "overflow-hidden transition-[max-height,opacity] duration-300 ease-in-out",
          isExpanded ? "max-h-[1200px] opacity-100" : "max-h-0 opacity-0",
        )}
      >
        <div className="space-y-4 border-t border-(--neutral-100) px-4 pb-4 pt-4">
          <CustomInput
            control={control}
            name={`education.${index}.degreeType`}
            label="Degree Type"
            required
            maxLength={100}
          />

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <CustomInput
              control={control}
              name={`education.${index}.fieldOfStudy`}
              label="Field of Study"
              maxLength={100}
            />
            <CustomInput
              control={control}
              name={`education.${index}.institution`}
              label="Institution"
              required
              maxLength={150}
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <CustomInput
              control={control}
              name={`education.${index}.graduationYear`}
              label="Graduation Year"
              inputMode="numeric"
              pattern="[0-9]*"
              digitsOnly
              maxLength={4}
            />
            <CustomDatePicker
              control={control}
              name={`education.${index}.graduationDate`}
              label="Graduation Date"
              valueType="date"
              minYear={2000}
              maxYear={new Date().getFullYear() + 50}
            />
          </div>

          <CustomInput
            control={control}
            name={`education.${index}.accreditationBody`}
            label="Accreditation Body"
            maxLength={100}
          />

          <FormField
            control={control}
            name={`education.${index}.isAccredited`}
            render={({ field: accreditedField }) => (
              <FormItem className="flex items-center gap-3 space-y-0">
                <FormControl>
                  <Checkbox
                    id={`education-accredited-${fieldId}`}
                    checked={Boolean(accreditedField.value)}
                    onCheckedChange={(checked) => accreditedField.onChange(checked)}
                  />
                </FormControl>
                <FormLabel
                  htmlFor={`education-accredited-${fieldId}`}
                  className="text-sm font-medium text-(--text-primary-dark)"
                >
                  Institution is accredited
                </FormLabel>
              </FormItem>
            )}
          />

          <CustomTextarea
            control={control}
            name={`education.${index}.notes`}
            label="Notes"
            rows={3}
            maxLength={500}
          />
        </div>
      </div>
    </div>
  );
};

interface EducationEntriesFieldProps {
  control: Control<EducationEntriesFormValues>;
  initialEducation?: EducationEntryFormValues[];
  syncToken?: string | number;
}

const EducationEntriesField = ({
  control,
  initialEducation,
  syncToken,
}: EducationEntriesFieldProps) => {
  const { fields, append, remove, replace } = useFieldArray({
    control,
    name: "education",
  });
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
  const pendingExpandRef = useRef(false);

  useEffect(() => {
    if (initialEducation === undefined) return;
    replace(initialEducation);
    setExpandedIds(new Set());
  }, [initialEducation, syncToken, replace]);

  useEffect(() => {
    if (!pendingExpandRef.current || fields.length === 0) return;
    const lastField = fields[fields.length - 1];
    setExpandedIds((previous) => new Set([...previous, lastField.id]));
    pendingExpandRef.current = false;
  }, [fields]);

  const toggleExpanded = (fieldId: string) => {
    setExpandedIds((previous) => {
      const next = new Set(previous);
      if (next.has(fieldId)) {
        next.delete(fieldId);
      } else {
        next.add(fieldId);
      }
      return next;
    });
  };

  const handleAddEducation = () => {
    append(createEmptyEducationEntry());
    pendingExpandRef.current = true;
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between gap-3">
        <h3 className="text-sm font-semibold text-(--text-primary-dark)">
          Education
        </h3>
        <button
          type="button"
          onClick={handleAddEducation}
          className="inline-flex items-center gap-1 text-sm font-semibold text-(--text-primary-500) hover:opacity-80 cursor-pointer"
        >
          <Plus size={16} />
          Add Education
        </button>
      </div>

      {fields.length === 0 ? (
        <p className="text-sm text-(--text-neutral-500)">
          No education entries added yet.
        </p>
      ) : (
        fields.map((field, index) => (
          <EducationEntryCard
            key={field.id}
            control={control}
            fieldId={field.id}
            index={index}
            isExpanded={expandedIds.has(field.id)}
            onToggleExpanded={() => toggleExpanded(field.id)}
            onRemove={() => {
              setExpandedIds((previous) => {
                const next = new Set(previous);
                next.delete(field.id);
                return next;
              });
              remove(index);
            }}
          />
        ))
      )}
      <FormField
        control={control}
        name="education"
        render={() => (
          <FormItem>
            <FormMessage />
          </FormItem>
        )}
      />
    </div>
  );
};

export default EducationEntriesField;

