function truncateText(value: string, maxLength: number): string {
  if (value.length <= maxLength) return value;
  return `${value.slice(0, Math.max(0, maxLength - 1))}…`;
}

function buildCollapsedSummary(
  parts: string[],
  fallback: string,
): { display: string; full: string } {
  const trimmedParts = parts
    .map((value) => value.trim())
    .filter(Boolean)
    .map((value) =>
      truncateText(value, EDUCATION_FIELD_LIMITS.collapsedSummaryPart),
    );

  const full =
    trimmedParts.length > 0 ? trimmedParts.join(" · ") : fallback;
  const display = truncateText(full, EDUCATION_FIELD_LIMITS.collapsedSummaryTotal);

  return { display, full };
}

