/**
 * IndexedDB-backed store for failed session-recording chunks.
 * Mirrors ClientHubAI recording-blob-store.ts so audio survives tab refresh.
 */

const DB_NAME = "therapy-flow-recording";
const DB_VERSION = 1;
const STORE = "failed-chunks";

export interface StoredFailedChunk {
  key: string;
  uploadId: string;
  sessionId?: number;
  clientId?: number;
  index: number;
  durationSec: number;
  mime: string;
  blob: Blob;
  savedAt: number;
}

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === "undefined") {
      reject(new Error("IndexedDB not available"));
      return;
    }
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE)) {
        const store = db.createObjectStore(STORE, { keyPath: "key" });
        store.createIndex("byUploadId", "uploadId", { unique: false });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function tx(db: IDBDatabase, mode: IDBTransactionMode) {
  return db.transaction(STORE, mode).objectStore(STORE);
}

function makeKey(uploadId: string, index: number): string {
  return `${uploadId}::${index}`;
}

export async function putFailedChunk(
  entry: Omit<StoredFailedChunk, "key" | "savedAt">,
): Promise<void> {
  try {
    const db = await openDb();
    await new Promise<void>((resolve, reject) => {
      const req = tx(db, "readwrite").put({
        ...entry,
        key: makeKey(entry.uploadId, entry.index),
        savedAt: Date.now(),
      });
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
    db.close();
  } catch (err) {
    console.warn("[recording-blob-store] put failed:", err);
  }
}

export async function deleteFailedChunk(uploadId: string, index: number): Promise<void> {
  try {
    const db = await openDb();
    await new Promise<void>((resolve, reject) => {
      const req = tx(db, "readwrite").delete(makeKey(uploadId, index));
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
    db.close();
  } catch (err) {
    console.warn("[recording-blob-store] delete failed:", err);
  }
}

export async function listFailedChunksForUpload(
  uploadId: string,
): Promise<StoredFailedChunk[]> {
  try {
    const db = await openDb();
    const result = await new Promise<StoredFailedChunk[]>((resolve, reject) => {
      const idx = tx(db, "readonly").index("byUploadId");
      const req = idx.getAll(IDBKeyRange.only(uploadId));
      req.onsuccess = () => resolve((req.result as StoredFailedChunk[]) || []);
      req.onerror = () => reject(req.error);
    });
    db.close();
    return result;
  } catch (err) {
    console.warn("[recording-blob-store] list failed:", err);
    return [];
  }
}

export async function clearFailedChunksForUpload(uploadId: string): Promise<void> {
  try {
    const db = await openDb();
    await new Promise<void>((resolve, reject) => {
      const store = tx(db, "readwrite");
      const idx = store.index("byUploadId");
      const cursorReq = idx.openCursor(IDBKeyRange.only(uploadId));
      cursorReq.onsuccess = () => {
        const cursor = cursorReq.result;
        if (cursor) {
          cursor.delete();
          cursor.continue();
        } else {
          resolve();
        }
      };
      cursorReq.onerror = () => reject(cursorReq.error);
    });
    db.close();
  } catch (err) {
    console.warn("[recording-blob-store] clear failed:", err);
  }
}

export const SLICE_SECONDS = 20;
export const SLICE_MS = SLICE_SECONDS * 1000;
export const LIVE_TIMESLICE_MS = 250;
export const SILENCE_RMS_THRESHOLD = 0.0008;
export const MAX_EXPECTED_CHUNKS = 5000;
export const RETENTION_DAYS = 90;
export const CHUNK_UPLOAD_MAX_ATTEMPTS = 3;
export const UPLOAD_STALL_MS = 90_000;

const LIVE_SUPPORTED_LANGUAGE_CODES = new Set([
  "en",
  "es",
  "fr",
  "de",
  "it",
  "pt",
  "nl",
  "ru",
  "hi",
  "zh",
  "ja",
  "ko",
  "tr",
  "pl",
]);

export function recoveryStorageKey(sessionId: number): string {
  return `therapy-flow.session-recorder.recovery.v1.${sessionId}`;
}

export function normalizeTranscriptText(value: string): string {
  return value.replace(/\s+/g, " ").trim();
}

export function primaryLanguageCode(language: string): string {
  const trimmed = language.trim();
  if (!trimmed) return "en";
  return trimmed.split("-")[0].toLowerCase();
}

export function isLivePreviewSupported(language: string): boolean {
  return LIVE_SUPPORTED_LANGUAGE_CODES.has(primaryLanguageCode(language));
}

export function findClusterStart(bytes: Uint8Array): number {
  for (let i = 0; i + 3 < bytes.length; i += 1) {
    if (
      bytes[i] === 0x1f &&
      bytes[i + 1] === 0x43 &&
      bytes[i + 2] === 0xb6 &&
      bytes[i + 3] === 0x75
    ) {
      return i;
    }
  }
  return -1;
}

export function pickRecorderMimeType(): string {
  if (typeof MediaRecorder === "undefined") return "audio/webm";
  if (MediaRecorder.isTypeSupported("audio/webm;codecs=opus")) {
    return "audio/webm;codecs=opus";
  }
  if (MediaRecorder.isTypeSupported("audio/webm")) {
    return "audio/webm";
  }
  if (MediaRecorder.isTypeSupported("audio/mp4")) {
    return "audio/mp4";
  }
  return "audio/webm";
}

export function buildDownloadFileName(clientName: string): string {
  return `${clientName.toLowerCase().replace(/[^a-z0-9]+/g, "-") || "session"}-transcript.txt`;
}

import { getAuthSession } from "@/utils/authStorage";
import { buildTenantApiBase } from "@/utils/tenantUrls";

export interface UploadSessionTranscriptAudioChunkParams {
  sessionId: number;
  blob: Blob;
  uploadId: string;
  chunkIndex: number;
  chunkDurationSeconds: number;
  language?: string;
  mimeType: string;
}

export interface UploadSessionTranscriptAudioChunkResponse {
  chunkText?: string;
  receivedChunks?: number;
  chunksReceived?: number;
}

export async function uploadSessionTranscriptAudioChunk(
  params: UploadSessionTranscriptAudioChunkParams,
): Promise<UploadSessionTranscriptAudioChunkResponse> {
  const session = getAuthSession();
  const base = buildTenantApiBase(session?.tenantSubdomain ?? undefined);
  const ext = params.mimeType.includes("mp4") ? "mp4" : "webm";

  const formData = new FormData();
  formData.append("audio", params.blob, `chunk-${params.chunkIndex}.${ext}`);
  formData.append("uploadId", params.uploadId);
  formData.append("chunkIndex", String(params.chunkIndex));
  formData.append("chunkDurationSeconds", String(params.chunkDurationSeconds));
  if (params.language) {
    formData.append("language", params.language);
  }

  const response = await fetch(
    `${base}/api/v1/sessions/${params.sessionId}/transcribe-chunk`,
    {
      method: "POST",
      headers: session?.accessToken
        ? { Authorization: `Bearer ${session.accessToken}` }
        : undefined,
      body: formData,
    },
  );

  if (!response.ok) {
    const errText = await response.text();
    throw new Error(errText.slice(0, 300) || "Chunk upload failed");
  }

  return (await response.json()) as UploadSessionTranscriptAudioChunkResponse;
}

