import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Copy, Download, Loader2, Mic, Pause, Play, Square, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Switch } from "@/components/ui/switch";
import {
  buildStoredSessionTranscript,
  saveStoredSessionTranscript,
  type StoredSessionTranscript,
} from "./sessionTranscriptStore";
import {
  useFinalizeSessionTranscriptionMutation,
  useStartSessionTranscriptionMutation,
  type SessionNoteTranscriptionResponse,
} from "@/store/api/admin";
import { getApiErrorMessage } from "@/utils/apiError";
import { getAuthSession } from "@/utils/authStorage";
import { buildTenantApiBase } from "@/utils/tenantUrls";
import {
  clearFailedChunksForUpload,
  deleteFailedChunk,
  putFailedChunk,
} from "@/utils/recording/recordingBlobStore";
import {
  buildDownloadFileName,
  findClusterStart,
  isLivePreviewSupported,
  MAX_EXPECTED_CHUNKS,
  normalizeTranscriptText,
  pickRecorderMimeType,
  primaryLanguageCode,
  recoveryStorageKey,
  RETENTION_DAYS,
  SILENCE_RMS_THRESHOLD,
  SLICE_MS,
  UPLOAD_STALL_MS,
  CHUNK_UPLOAD_MAX_ATTEMPTS,
  LIVE_TIMESLICE_MS,
} from "@/utils/recording/sessionRecordingUtils";
import { uploadSessionTranscriptAudioChunk } from "@/utils/recording/uploadSessionTranscriptAudioChunk";

interface RecordSessionModalProps {
  isOpen: boolean;
  onClose: () => void;
  sessionData: {
    sessionId: number;
    clientId: number | null;
    therapistId: number | null;
    dateTime: string;
    sessionType: string;
    clientName: string;
  } | null;
  onTranscriptSaved: (
    transcript: StoredSessionTranscript,
    transcriptionResponse: SessionNoteTranscriptionResponse,
  ) => void;
  onToast: (message: string, type: "success" | "error" | "info") => void;
}

type RecordingStage = "setup" | "recording" | "paused" | "finalizing";

const LANGUAGE_OPTIONS = [
  { label: "English", value: "en-US" },
  { label: "Arabic", value: "ar-SA" },
  { label: "Urdu", value: "ur-PK" },
  { label: "Hindi", value: "hi-IN" },
];

function getWebSocketUrl(uploadId: string, language: string) {
  const session = getAuthSession();
  const base = buildTenantApiBase(session?.tenantSubdomain ?? undefined);
  const url = new URL(base);
  url.protocol = url.protocol === "https:" ? "wss:" : "ws:";
  url.pathname = "/ws/transcribe-live";
  url.searchParams.set("uploadId", uploadId);
  url.searchParams.set("language", primaryLanguageCode(language));
  if (session?.accessToken) {
    url.searchParams.set("token", session.accessToken);
  }
  return url.toString();
}

const RecordSessionModal = ({
  isOpen,
  onClose,
  sessionData,
  onTranscriptSaved,
  onToast,
}: RecordSessionModalProps) => {
  const [stage, setStage] = useState<RecordingStage>("setup");
  const [recordingSeconds, setRecordingSeconds] = useState(0);
  const [micLevel, setMicLevel] = useState(0);
  const [selectedLanguage, setSelectedLanguage] = useState(LANGUAGE_OPTIONS[0].value);
  const [translateToEnglish, setTranslateToEnglish] = useState(false);
  const [availableMics, setAvailableMics] = useState<MediaDeviceInfo[]>([]);
  const [selectedMicId, setSelectedMicId] = useState("");
  const [livePreview, setLivePreview] = useState("");
  const [liveInterim, setLiveInterim] = useState("");
  const [hidePreview, setHidePreview] = useState(false);
  const [createdChunks, setCreatedChunks] = useState(0);
  const [receivedChunks, setReceivedChunks] = useState(0);
  const [silentSkipped, setSilentSkipped] = useState(0);
  const [uploadId, setUploadId] = useState<string | null>(null);

  const streamRef = useRef<MediaStream | null>(null);
  const recorderRef = useRef<MediaRecorder | null>(null);
  const liveRecorderRef = useRef<MediaRecorder | null>(null);
  const liveWsRef = useRef<WebSocket | null>(null);
  const liveStoppedRef = useRef(false);
  const liveActiveRef = useRef(false);
  const liveReconnectAttemptRef = useRef(0);
  const liveAudioBacklogRef = useRef<ArrayBuffer[]>([]);
  const liveReconnectTimerRef = useRef<number | null>(null);
  const webmInitRef = useRef<Uint8Array | null>(null);
  const segmentStartRef = useRef(0);
  const uploadQueueRef = useRef<Promise<void>>(Promise.resolve());
  const chunkIndexRef = useRef(0);
  const uploadIdRef = useRef("");
  const mimeTypeRef = useRef("audio/webm");
  const stoppingRef = useRef(false);
  const isPausedRef = useRef(false);
  const silentChunksRef = useRef<Map<number, number>>(new Map());
  const failedChunksRef = useRef<Map<number, { blob: Blob; durationSec: number; mime: string }>>(
    new Map(),
  );
  const stopFlushedRef = useRef<Promise<void>>(Promise.resolve());
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const meterRafRef = useRef<number | null>(null);
  const meterIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const segmentMaxRmsRef = useRef(0);
  const lastUploadAtRef = useRef(0);
  const livePreviewRef = useRef<HTMLDivElement | null>(null);
  const isUnmountingRef = useRef(false);

  const [startSessionTranscription, { isLoading: isStarting }] =
    useStartSessionTranscriptionMutation();
  const [finalizeSessionTranscription, { isLoading: isFinalizing }] =
    useFinalizeSessionTranscriptionMutation();

  const displayedChunkTotal = useMemo(() => {
    if (stage === "recording" || stage === "paused") {
      return Math.max(createdChunks + 1, 1);
    }
    return Math.max(createdChunks, 1);
  }, [createdChunks, stage]);

  const progressPercentage = useMemo(() => {
    if (displayedChunkTotal <= 0) return 0;
    return Math.min(100, Math.round((receivedChunks / displayedChunkTotal) * 100));
  }, [displayedChunkTotal, receivedChunks]);

  const previewDisplayText = useMemo(() => {
    const base = normalizeTranscriptText(livePreview);
    const interim = normalizeTranscriptText(liveInterim);
    if (!base && !interim) return "";
    if (!interim) return base;
    return base ? `${base} ${interim}` : interim;
  }, [livePreview, liveInterim]);

  const recordingInProgress =
    stage === "recording" || stage === "paused" || stage === "finalizing";

  const loadMicrophones = useCallback(async () => {
    if (!navigator.mediaDevices?.enumerateDevices) return;
    try {
      const devices = await navigator.mediaDevices.enumerateDevices();
      const microphones = devices.filter((device) => device.kind === "audioinput");
      setAvailableMics(microphones);
      if (!selectedMicId && microphones[0]?.deviceId) {
        setSelectedMicId(microphones[0].deviceId);
      }
    } catch {
      setAvailableMics([]);
    }
  }, [selectedMicId]);

  const stopLevelMeter = useCallback(() => {
    if (meterRafRef.current !== null) {
      cancelAnimationFrame(meterRafRef.current);
      meterRafRef.current = null;
    }
    if (meterIntervalRef.current !== null) {
      clearInterval(meterIntervalRef.current);
      meterIntervalRef.current = null;
    }
    if (audioContextRef.current) {
      void audioContextRef.current.close();
      audioContextRef.current = null;
    }
    analyserRef.current = null;
    setMicLevel(0);
    segmentMaxRmsRef.current = 0;
  }, []);

  const stopLiveTranscription = useCallback(() => {
    liveStoppedRef.current = true;
    if (liveReconnectTimerRef.current !== null) {
      clearTimeout(liveReconnectTimerRef.current);
      liveReconnectTimerRef.current = null;
    }
    liveAudioBacklogRef.current = [];
    liveReconnectAttemptRef.current = 0;
    if (liveRecorderRef.current && liveRecorderRef.current.state !== "inactive") {
      try {
        liveRecorderRef.current.stop();
      } catch {
        // no-op
      }
    }
    liveRecorderRef.current = null;
    if (liveWsRef.current) {
      try {
        liveWsRef.current.close();
      } catch {
        // no-op
      }
      liveWsRef.current = null;
    }
    liveActiveRef.current = false;
    setLiveInterim("");
  }, []);

  const cleanupMedia = useCallback(() => {
    stopLevelMeter();
    stopLiveTranscription();
    if (recorderRef.current && recorderRef.current.state !== "inactive") {
      try {
        recorderRef.current.stop();
      } catch {
        // no-op
      }
    }
    recorderRef.current = null;
    webmInitRef.current = null;
    streamRef.current?.getTracks().forEach((track) => track.stop());
    streamRef.current = null;
  }, [stopLevelMeter, stopLiveTranscription]);

  const startLevelMeter = useCallback((stream: MediaStream) => {
    try {
      const Ctx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      if (!Ctx) return;
      const ctx = new Ctx();
      const src = ctx.createMediaStreamSource(stream);
      const analyser = ctx.createAnalyser();
      analyser.fftSize = 1024;
      src.connect(analyser);
      audioContextRef.current = ctx;
      analyserRef.current = analyser;
      const buf = new Uint8Array(analyser.fftSize);
      const sample = () => {
        const a = analyserRef.current;
        if (!a) return;
        a.getByteTimeDomainData(buf);
        let sum = 0;
        for (let i = 0; i < buf.length; i += 1) {
          const v = (buf[i] - 128) / 128;
          sum += v * v;
        }
        const rms = Math.sqrt(sum / buf.length);
        if (rms > segmentMaxRmsRef.current) segmentMaxRmsRef.current = rms;
        return rms;
      };
      const tick = () => {
        const rms = sample();
        if (rms !== undefined) {
          setMicLevel(Math.min(100, Math.round(rms * 4 * 100)));
        }
        meterRafRef.current = requestAnimationFrame(tick);
      };
      tick();
      meterIntervalRef.current = setInterval(sample, 100);
    } catch (err) {
      console.warn("Level meter setup failed:", err);
    }
  }, []);

  const pauseLiveTranscription = useCallback(() => {
    if (liveRecorderRef.current && liveRecorderRef.current.state === "recording") {
      try {
        liveRecorderRef.current.pause();
      } catch {
        // no-op
      }
    }
  }, []);

  const resumeLiveTranscription = useCallback(() => {
    if (liveRecorderRef.current && liveRecorderRef.current.state === "paused") {
      try {
        liveRecorderRef.current.resume();
      } catch {
        // no-op
      }
    }
  }, []);

  const startLiveTranscription = useCallback(
    (stream: MediaStream, language: string, nextUploadId: string) => {
      liveStoppedRef.current = false;
      liveActiveRef.current = false;
      setLiveInterim("");
      liveReconnectAttemptRef.current = 0;
      liveAudioBacklogRef.current = [];

      const wsUrl = getWebSocketUrl(nextUploadId, language);
      let liveMime = mimeTypeRef.current;
      if (!liveMime || liveMime === "audio/webm") {
        liveMime = pickRecorderMimeType();
        mimeTypeRef.current = liveMime;
      }

      const ondata = (ev: BlobEvent) => {
        if (!ev.data || ev.data.size === 0) return;
        void ev.data.arrayBuffer().then((buffer) => {
          const ws = liveWsRef.current;
          if (ws && ws.readyState === WebSocket.OPEN) {
            if (liveAudioBacklogRef.current.length > 0) {
              const queued = liveAudioBacklogRef.current;
              liveAudioBacklogRef.current = [];
              for (const b of queued) {
                try {
                  ws.send(b);
                } catch {
                  // no-op
                }
              }
            }
            try {
              ws.send(buffer);
            } catch {
              // no-op
            }
          } else if (!liveStoppedRef.current) {
            if (liveAudioBacklogRef.current.length < 120) {
              liveAudioBacklogRef.current.push(buffer);
            }
          }
        });
      };

      const ensureRecorderRunning = () => {
        if (liveRecorderRef.current && liveRecorderRef.current.state !== "inactive") return;
        try {
          const rec = new MediaRecorder(stream, {
            mimeType: liveMime,
            audioBitsPerSecond: 128_000,
          });
          rec.ondataavailable = ondata;
          rec.start(LIVE_TIMESLICE_MS);
          liveRecorderRef.current = rec;
        } catch (err) {
          console.warn("[live] failed to start live MediaRecorder:", err);
        }
      };

      const scheduleReconnect = () => {
        if (liveStoppedRef.current) return;
        const attempt = ++liveReconnectAttemptRef.current;
        if (attempt > 6) {
          if (liveRecorderRef.current && liveRecorderRef.current.state !== "inactive") {
            try {
              liveRecorderRef.current.stop();
            } catch {
              // no-op
            }
          }
          liveRecorderRef.current = null;
          liveActiveRef.current = false;
          setLiveInterim("");
          onToast(
            "Live preview disconnected. Audio is still being recorded — transcript will be finalised on Stop.",
            "error",
          );
          return;
        }
        const delayMs = Math.min(500 * 2 ** (attempt - 1), 4000);
        if (liveReconnectTimerRef.current !== null) {
          clearTimeout(liveReconnectTimerRef.current);
        }
        liveReconnectTimerRef.current = window.setTimeout(() => {
          liveReconnectTimerRef.current = null;
          connect();
        }, delayMs);
      };

      const connect = () => {
        if (liveStoppedRef.current) return;
        let ws: WebSocket;
        try {
          ws = new WebSocket(wsUrl);
        } catch {
          scheduleReconnect();
          return;
        }
        ws.binaryType = "arraybuffer";
        liveWsRef.current = ws;

        ws.onopen = () => {
          if (liveStoppedRef.current) {
            try {
              ws.close();
            } catch {
              // no-op
            }
            if (liveWsRef.current === ws) liveWsRef.current = null;
            return;
          }
          liveReconnectAttemptRef.current = 0;
          ensureRecorderRunning();
        };

        ws.onmessage = (ev) => {
          try {
            const msg = JSON.parse(typeof ev.data === "string" ? ev.data : "") as {
              type?: string;
              isFinal?: boolean;
              text?: string;
              message?: string;
            };
            if (msg.type === "transcript") {
              if (!liveActiveRef.current) {
                liveActiveRef.current = true;
              }
              if (msg.isFinal) {
                const text = String(msg.text || "").trim();
                if (text) {
                  setLivePreview((prev) => (prev ? `${prev} ${text}` : text));
                }
                setLiveInterim("");
              } else {
                setLiveInterim(String(msg.text || ""));
              }
            }
          } catch {
            // ignore non-JSON
          }
        };

        ws.onclose = () => {
          if (liveWsRef.current === ws) liveWsRef.current = null;
          if (liveStoppedRef.current) {
            if (liveRecorderRef.current && liveRecorderRef.current.state !== "inactive") {
              try {
                liveRecorderRef.current.stop();
              } catch {
                // no-op
              }
            }
            liveRecorderRef.current = null;
            liveActiveRef.current = false;
            setLiveInterim("");
            return;
          }
          scheduleReconnect();
        };
      };

      connect();
    },
    [onToast],
  );

  const uploadChunk = useCallback(
    async (blob: Blob, index: number, durationSec: number, mime: string) => {
      if (!sessionData) return;

      for (let attempt = 1; attempt <= CHUNK_UPLOAD_MAX_ATTEMPTS; attempt += 1) {
        try {
          const data = await uploadSessionTranscriptAudioChunk({
            sessionId: sessionData.sessionId,
            blob,
            uploadId: uploadIdRef.current,
            chunkIndex: index,
            chunkDurationSeconds: durationSec,
            language: selectedLanguage,
            mimeType: mime,
          });

          failedChunksRef.current.delete(index);
          if (uploadIdRef.current) {
            void deleteFailedChunk(uploadIdRef.current, index);
          }

          const received =
            typeof data.receivedChunks === "number"
              ? data.receivedChunks
              : typeof data.chunksReceived === "number"
                ? data.chunksReceived
                : receivedChunks;

          lastUploadAtRef.current = Date.now();
          setReceivedChunks((prev) =>
            Math.max(prev, received, silentSkipped + failedChunksRef.current.size === 0 ? index + 1 : prev),
          );

          if (data.chunkText && !liveActiveRef.current) {
            setLivePreview((prev) => (prev ? `${prev} ${data.chunkText}` : data.chunkText || ""));
          }
          return;
        } catch (err) {
          console.error(`Chunk ${index} attempt ${attempt} failed:`, err);
          if (attempt === CHUNK_UPLOAD_MAX_ATTEMPTS) {
            failedChunksRef.current.set(index, { blob, durationSec, mime });
            if (uploadIdRef.current) {
              void putFailedChunk({
                uploadId: uploadIdRef.current,
                sessionId: sessionData.sessionId,
                index,
                durationSec,
                mime,
                blob,
              });
            }
            onToast(
              `Chunk ${index} failed to transcribe. Recording continues — retry by stopping and saving again when uploads recover.`,
              "error",
            );
            return;
          }
          await new Promise((resolve) => setTimeout(resolve, 1000 * attempt));
        }
      }
    },
    [onToast, receivedChunks, selectedLanguage, sessionData, silentSkipped],
  );

  const startSegmentRecorder = useCallback(() => {
    const stream = streamRef.current;
    if (!stream) return;

    const supportedMime = pickRecorderMimeType();
    mimeTypeRef.current = supportedMime;

    const recorder = new MediaRecorder(stream, {
      mimeType: supportedMime,
      audioBitsPerSecond: 128_000,
    });
    segmentStartRef.current = Date.now();
    webmInitRef.current = null;

    let resolveStopped: () => void = () => {};
    stopFlushedRef.current = new Promise<void>((resolve) => {
      resolveStopped = resolve;
    });

    recorder.ondataavailable = (event) => {
      if (!event.data || event.data.size === 0) return;

      const segmentDurationSec = (Date.now() - segmentStartRef.current) / 1000;
      segmentStartRef.current = Date.now();
      const segmentPeakRms = segmentMaxRmsRef.current;
      segmentMaxRmsRef.current = 0;
      const wasSilent = segmentPeakRms < SILENCE_RMS_THRESHOLD;

      const idx = chunkIndexRef.current;
      chunkIndexRef.current += 1;
      setCreatedChunks(chunkIndexRef.current);

      if (wasSilent) {
        silentChunksRef.current.set(idx, segmentDurationSec);
        setSilentSkipped((count) => count + 1);
        setReceivedChunks((prev) => Math.max(prev, chunkIndexRef.current));
        return;
      }

      const eventData = event.data;
      const mime = mimeTypeRef.current;

      uploadQueueRef.current = uploadQueueRef.current.then(async () => {
        let blobToSend: Blob = eventData;
        if (!webmInitRef.current && mime.includes("webm")) {
          try {
            const arr = new Uint8Array(await eventData.arrayBuffer());
            const clusterStart = findClusterStart(arr);
            if (clusterStart > 0) {
              webmInitRef.current = arr.slice(0, clusterStart);
            }
          } catch (err) {
            console.warn("[session-recorder] init-segment extract failed:", err);
          }
        } else if (webmInitRef.current && mime.includes("webm")) {
          blobToSend = new Blob([webmInitRef.current, eventData], { type: mime });
        }
        await uploadChunk(blobToSend, idx, segmentDurationSec, mime);
      });
    };

    recorder.onstop = () => {
      resolveStopped();
    };

    recorder.start(SLICE_MS);
    recorderRef.current = recorder;
  }, [uploadChunk]);

  useEffect(() => {
    if (!isOpen) return;
    setStage("setup");
    setRecordingSeconds(0);
    setMicLevel(0);
    setSelectedLanguage(LANGUAGE_OPTIONS[0].value);
    setTranslateToEnglish(false);
    setLivePreview("");
    setLiveInterim("");
    setHidePreview(false);
    setCreatedChunks(0);
    setReceivedChunks(0);
    setSilentSkipped(0);
    setUploadId(null);
    chunkIndexRef.current = 0;
    uploadIdRef.current = "";
    silentChunksRef.current = new Map();
    failedChunksRef.current = new Map();
    uploadQueueRef.current = Promise.resolve();
    void loadMicrophones();
  }, [isOpen, loadMicrophones]);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval> | null = null;
    if (stage === "recording") {
      interval = setInterval(() => {
        setRecordingSeconds((prev) => prev + 1);
      }, 1000);
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [stage]);

  useEffect(() => {
    if (isOpen) return;
    cleanupMedia();
  }, [cleanupMedia, isOpen]);

  useEffect(() => {
    return () => {
      isUnmountingRef.current = true;
      cleanupMedia();
    };
  }, [cleanupMedia]);

  useEffect(() => {
    if (!livePreviewRef.current || hidePreview) return;
    livePreviewRef.current.scrollTop = livePreviewRef.current.scrollHeight;
  }, [hidePreview, previewDisplayText]);

  useEffect(() => {
    if (!recordingInProgress) return;
    const handler = (event: BeforeUnloadEvent) => {
      event.preventDefault();
      event.returnValue = "";
      return "";
    };
    window.addEventListener("beforeunload", handler);
    return () => window.removeEventListener("beforeunload", handler);
  }, [recordingInProgress]);

  useEffect(() => {
    const goOffline = () => {
      if (recordingInProgress) {
        onToast(
          "Internet connection lost. Recording continues, but chunks will fail to upload until you're back online. They will retry automatically.",
          "error",
        );
      }
    };
    window.addEventListener("offline", goOffline);
    return () => window.removeEventListener("offline", goOffline);
  }, [onToast, recordingInProgress]);

  useEffect(() => {
    if (stage !== "recording") return;
    const timer = setInterval(() => {
      const now = Date.now();
      if (
        chunkIndexRef.current > 0 &&
        lastUploadAtRef.current > 0 &&
        now - lastUploadAtRef.current > UPLOAD_STALL_MS
      ) {
        onToast(
          "Chunk uploads appear stalled. Check your connection — recording continues and chunks will keep retrying.",
          "info",
        );
        lastUploadAtRef.current = now;
      }
    }, 5_000);
    return () => clearInterval(timer);
  }, [onToast, stage]);

  const handleStartRecording = async () => {
    if (!sessionData) return;

    try {
      const startResponse = await startSessionTranscription({
        sessionId: sessionData.sessionId,
        expectedChunks: MAX_EXPECTED_CHUNKS,
        language: selectedLanguage,
        retentionDays: RETENTION_DAYS,
      }).unwrap();

      const stream = await navigator.mediaDevices.getUserMedia({
        audio: selectedMicId
          ? {
              deviceId: { exact: selectedMicId },
              echoCancellation: true,
              noiseSuppression: true,
              autoGainControl: true,
              sampleRate: { ideal: 48000 },
              channelCount: { ideal: 1 },
            }
          : {
              echoCancellation: true,
              noiseSuppression: true,
              autoGainControl: true,
              sampleRate: { ideal: 48000 },
              channelCount: { ideal: 1 },
            },
      });

      await loadMicrophones();

      streamRef.current = stream;
      uploadIdRef.current = startResponse.uploadId;
      setUploadId(startResponse.uploadId);
      setReceivedChunks(startResponse.receivedChunks ?? 0);
      chunkIndexRef.current = 0;
      stoppingRef.current = false;
      isPausedRef.current = false;
      silentChunksRef.current = new Map();
      failedChunksRef.current = new Map();
      uploadQueueRef.current = Promise.resolve();
      lastUploadAtRef.current = Date.now();

      try {
        localStorage.setItem(
          recoveryStorageKey(sessionData.sessionId),
          JSON.stringify({ uploadId: startResponse.uploadId, startedAt: Date.now() }),
        );
      } catch {
        // no-op
      }

      startLevelMeter(stream);
      startSegmentRecorder();

      if (isLivePreviewSupported(selectedLanguage)) {
        startLiveTranscription(stream, selectedLanguage, startResponse.uploadId);
      }

      window.setTimeout(() => {
        if (
          !isPausedRef.current &&
          !stoppingRef.current &&
          streamRef.current &&
          segmentMaxRmsRef.current < 0.001
        ) {
          onToast(
            "No sound detected from microphone. Open the app in a new browser tab and allow microphone access.",
            "error",
          );
        }
      }, 4000);

      setStage("recording");
    } catch (error) {
      onToast(getApiErrorMessage(error), "error");
      setStage("setup");
      cleanupMedia();
    }
  };

  const handlePauseResume = () => {
    const recorder = recorderRef.current;
    if (!recorder) return;

    if (stage === "recording" && recorder.state === "recording") {
      recorder.pause();
      isPausedRef.current = true;
      pauseLiveTranscription();
      setStage("paused");
      return;
    }

    if (stage === "paused" && recorder.state === "paused") {
      segmentMaxRmsRef.current = 0;
      segmentStartRef.current = Date.now();
      recorder.resume();
      isPausedRef.current = false;
      resumeLiveTranscription();
      setStage("recording");
    }
  };

  const handleCopyPreview = () => {
    void navigator.clipboard.writeText(previewDisplayText);
  };

  const handleDownloadPreview = () => {
    const blob = new Blob([previewDisplayText], { type: "text/plain;charset=utf-8" });
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = buildDownloadFileName(sessionData?.clientName ?? "session");
    anchor.click();
    window.URL.revokeObjectURL(url);
  };

  const handleStopAndSave = async () => {
    if (!recorderRef.current || !sessionData || !uploadId) return;
    setStage("finalizing");
    stoppingRef.current = true;
    isPausedRef.current = true;

    try {
      if (
        recorderRef.current.state === "recording" ||
        recorderRef.current.state === "paused"
      ) {
        const flushed = stopFlushedRef.current;
        recorderRef.current.stop();
        try {
          await flushed;
        } catch {
          // no-op
        }
      }

      stopLiveTranscription();
      streamRef.current?.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
      stopLevelMeter();

      await uploadQueueRef.current;

      if (failedChunksRef.current.size > 0) {
        const failedList = Array.from(failedChunksRef.current.keys()).sort((a, b) => a - b);
        onToast(
          `Cannot save transcript — chunk(s) ${failedList.join(", ")} failed to transcribe. Check your connection and try again.`,
          "error",
        );
        setStage("paused");
        stoppingRef.current = false;
        isPausedRef.current = true;
        return;
      }

      const finalizeResponse = await finalizeSessionTranscription({
        sessionId: sessionData.sessionId,
        uploadId,
        expectedChunks: chunkIndexRef.current,
        totalChunks: chunkIndexRef.current,
        silentChunks: Array.from(silentChunksRef.current.entries()).map(
          ([index, durationSeconds]) => ({ index, durationSeconds }),
        ),
      }).unwrap();

      const transcript = buildStoredSessionTranscript({
        sessionId: sessionData.sessionId,
        uploadId: finalizeResponse.uploadId,
        clientId: sessionData.clientId,
        therapistId: sessionData.therapistId,
        clientName: sessionData.clientName,
        sessionType: sessionData.sessionType,
        sessionDateTime: sessionData.dateTime,
        durationSeconds: recordingSeconds,
        status: finalizeResponse.status,
        expectedChunks: finalizeResponse.expectedChunks,
        receivedChunks: finalizeResponse.receivedChunks,
        rawTranscription: finalizeResponse.finalTranscript,
        mappedFields: {},
        finalizedAt: finalizeResponse.finalizedAt,
      });

      try {
        localStorage.removeItem(recoveryStorageKey(sessionData.sessionId));
      } catch {
        // no-op
      }
      if (uploadIdRef.current) {
        void clearFailedChunksForUpload(uploadIdRef.current);
      }

      saveStoredSessionTranscript(transcript);
      cleanupMedia();
      onTranscriptSaved(transcript, {
        success: true,
        rawTranscription: finalizeResponse.finalTranscript,
        mappedFields: {},
      });
    } catch (error) {
      onToast(getApiErrorMessage(error), "error");
      setStage("setup");
    }
  };

  if (!isOpen || !sessionData) return null;

  const formattedDuration = `00:${Math.floor(recordingSeconds / 60)
    .toString()
    .padStart(2, "0")}:${(recordingSeconds % 60).toString().padStart(2, "0")}`;

  return (
    <div className="fixed inset-0 z-[10000] flex items-center justify-center bg-black/50 p-4">
      <div className="flex max-h-[90vh] w-full max-w-5xl flex-col overflow-hidden rounded-[24px] bg-white shadow-xl">
        <div className="flex items-start justify-between border-b border-(--neutral-200) px-6 py-5">
          <div className="space-y-1">
            <h2 className="flex items-center gap-3 text-[30px] font-semibold leading-none text-(--text-primary-dark)">
              <span className="flex h-10 w-10 items-center justify-center rounded-full bg-[#fff1f1] text-[#ff4d4f]">
                <Mic size={20} />
              </span>
              Record Session
