export function sliceTranscriptDelta(previousText: string, currentText: string): string {
  const previousTokens = normalizeTranscriptText(previousText).split(" ").filter(Boolean);
  const currentTokens = normalizeTranscriptText(currentText).split(" ").filter(Boolean);

  let sharedTokenCount = 0;
  while (
    sharedTokenCount < previousTokens.length &&
    sharedTokenCount < currentTokens.length &&
    previousTokens[sharedTokenCount] === currentTokens[sharedTokenCount]
  ) {
    sharedTokenCount += 1;
  }

  return currentTokens.slice(sharedTokenCount).join(" ");
}

