import FormsAndDocsTab from "./FormsAndDocs/FormsAndDocsTab";
import { useEffect, useRef, useState } from "react";
import { ChevronsRight } from "lucide-react";
import ClientProfileHeader from "./ClientProfileHeader";
import ClientProfileTabs from "./ClientProfileTabs";
import OverviewTab from "./OverviewTab";
import SessionsTab from "./SessionsTab";
import type { Client } from "../../../../types/client.type";

import AssessmentTab from "../../../assessments/AssessmentTab";
import BillingTab from "./Billing/BillingTab";
import TasksTab from "./Tasks/TasksTab";
import ChecklistsTab from "./Checklists/ChecklistsTab";
import HistoryTab from "./History/HistoryTab";

interface ClientProfileProps {
  client: Client | null;
  isOpen: boolean;
  viewMode?: "closed" | "half" | "full";
  onClose?: () => void;
  onToggleFullView?: () => void;
  onEdit?: (clientId: string) => void;
  onDelete?: (clientId: string) => void;
  isPortalAccessUpdating?: boolean;
  isPortalActivationSending?: boolean;
  onUpdatePortalAccess?: (enable: boolean) => void;
  onResendPortalActivation?: () => void;
  requestedAction?: "checklist" | "scheduled-session" | "create-task" | null;
  requestedActionNonce?: number;
  onRequestedActionHandled?: () => void;
}

const ClientProfile = ({
  client,
  isOpen,
  viewMode = "half",
  onClose,
  onToggleFullView,
  onEdit,
  onDelete,
  isPortalAccessUpdating = false,
  isPortalActivationSending = false,
  onUpdatePortalAccess,
  onResendPortalActivation,
  requestedAction = null,
  requestedActionNonce = 0,
  onRequestedActionHandled,
}: ClientProfileProps) => {
  const [activeTab, setActiveTab] = useState<string>("Overview");
  const [mountedTabs, setMountedTabs] = useState<Set<string>>(new Set(["Overview"]));
  const [openCreateTaskTrigger, setOpenCreateTaskTrigger] = useState(0);
  const scrollRef = useRef<HTMLDivElement>(null);
  const lastHandledActionNonceRef = useRef(0);
  const pendingCreateTaskRef = useRef(false);

  const tabs = [
    "Overview",
    "Sessions",
    "Assessments",
    "Forms & Docs",
    "Billing",
    "Tasks",
    "Checklists",
    "History",
  ];

  useEffect(() => {
    setMountedTabs((previous) => {
      if (previous.has(activeTab)) return previous;
      const next = new Set(previous);
      next.add(activeTab);
      return next;
    });
  }, [activeTab]);

  useEffect(() => {
    if (!requestedAction || !requestedActionNonce) return;
    if (lastHandledActionNonceRef.current === requestedActionNonce) return;
    lastHandledActionNonceRef.current = requestedActionNonce;

    if (requestedAction === "checklist") {
      setActiveTab("Checklists");
      onRequestedActionHandled?.();
      return;
    }

    if (requestedAction === "scheduled-session") {
      setActiveTab("Sessions");
      setMountedTabs((previous) => {
        if (previous.has("Sessions")) return previous;
        const next = new Set(previous);
        next.add("Sessions");
        return next;
      });
      onRequestedActionHandled?.();
      return;
    }

    if (requestedAction === "create-task") {
      setActiveTab("Tasks");
      setMountedTabs((previous) => {
        if (previous.has("Tasks")) return previous;
        const next = new Set(previous);
        next.add("Tasks");
        return next;
      });
      pendingCreateTaskRef.current = true;
      onRequestedActionHandled?.();
    }
  }, [requestedAction, requestedActionNonce, onRequestedActionHandled]);

  useEffect(() => {
    if (!pendingCreateTaskRef.current || activeTab !== "Tasks" || !client) return;
    pendingCreateTaskRef.current = false;
    setOpenCreateTaskTrigger((previous) => previous + 1);
  }, [activeTab, client?.id]);

  if (!isOpen || !client) return null;

  const renderTabContent = (tab: string) => {
    if (!mountedTabs.has(tab)) return null;
    const className = activeTab === tab ? "block h-full" : "hidden h-full";

    switch (tab) {
      case "Overview":
        return (
          <div className={className}>
            <OverviewTab
              client={client}
              isPortalAccessUpdating={isPortalAccessUpdating}
              isPortalActivationSending={isPortalActivationSending}
              onUpdatePortalAccess={onUpdatePortalAccess}
              onResendPortalActivation={onResendPortalActivation}
            />
          </div>
        );
      case "Sessions":
        return (
          <div className={className}>
            <SessionsTab
              client={client}
              scrollRef={scrollRef}
              isAdmin={true}
              isActive={activeTab === "Sessions"}
            />
          </div>
        );
      case "Assessments":
        return (
          <div className={className}>
            <AssessmentTab clientId={Number(client.id)} />
          </div>
        );
      case "Forms & Docs":
        return (
          <div className={className}>
            <FormsAndDocsTab client={client} />
          </div>
        );
      case "Billing":
        return (
          <div className={className}>
            <BillingTab scrollRef={scrollRef} client={client} isActive={activeTab === "Billing"} />
          </div>
        );
      case "Tasks":
        return (
          <div className={className}>
            <TasksTab
              key={client.id}
              client={client}
              openCreateTrigger={openCreateTaskTrigger}
            />
          </div>
        );
      case "Checklists":
        return (
          <div className={className}>
            <ChecklistsTab client={client} />
          </div>
        );
      case "History":
        return (
          <div className={className}>
            <HistoryTab clientId={Number(client.id)} isActive={activeTab === "History"} />
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="bg-white flex flex-col h-full overflow-hidden">
      {/* Top Controls Row - Above Tabs */}
      <div className="flex items-center justify-between px-6 py-3">
        {/* Left: Control Buttons */}
        <div className="flex items-center gap-2">
          {viewMode === "half" && onClose && (
            <button
              onClick={onClose}
              className="p-1.5 rounded-lg hover:bg-gray-100 transition-colors cursor-pointer"
              title="Close"
            >
              <ChevronsRight size={20} className="text-gray-600" />
            </button>
          )}
          {viewMode === "half" && onToggleFullView && (
            <button
              onClick={onToggleFullView}
              className="p-1.5 rounded-lg hover:bg-gray-100 transition-colors cursor-pointer"
              title="Expand to full view"
            >
              <svg
                width="20"
                height="20"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                className="text-gray-600"
              >
                <path d="M8 3H5a2 2 0 0 0-2 2v3m18 0V5a2 2 0 0 0-2-2h-3m0 18h3a2 2 0 0 0 2-2v-3M3 16v3a2 2 0 0 0 2 2h3" />
              </svg>
            </button>
          )}
          {viewMode === "full" && onToggleFullView && (
            <button
              onClick={onToggleFullView}
              className="p-1.5 rounded-lg hover:bg-gray-100 transition-colors cursor-pointer"
              title="Return to half view"
            >
              <svg
                width="20"
                height="20"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                className="text-gray-600"
              >
                <path d="M8 3v3a2 2 0 0 1-2 2H3m18 0h-3a2 2 0 0 1-2-2V3m0 18v-3a2 2 0 0 1 2-2h3M3 16h3a2 2 0 0 1 2 2v3" />
              </svg>
            </button>
          )}
        </div>
      </div>

      {/* Tabs Row - With Gray Background */}
      <div className="px-6">
        <ClientProfileTabs
          tabs={tabs}
          activeTab={activeTab}
          onTabChange={setActiveTab}
        />
      </div>

      {/* Client Header - Only show on Overview tab */}
      {activeTab === "Overview" && (
        <ClientProfileHeader
          client={client}
          onEdit={() => onEdit?.(client.id)}
          onDelete={() => onDelete?.(client.id)}
        />
      )}

      {/* Content */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto overflow-x-hidden">
        {tabs.map((tab) => (
          <div key={tab}>{renderTabContent(tab)}</div>
        ))}
      </div>
    </div>
  );
};

export default ClientProfile;

