/** Locate the first WebM Cluster element (EBML ID 0x1F43B675) in a buffer. */
export function findClusterStart(bytes: Uint8Array): number {
  for (let i = 0; i + 3 < bytes.length; i += 1) {
    if (
      bytes[i] === 0x1f &&
      bytes[i + 1] === 0x43 &&
      bytes[i + 2] === 0xb6 &&
      bytes[i + 3] === 0x75
    ) {
      return i;
    }
  }
  return -1;
}

export function pickRecorderMimeType(): string {
  if (typeof MediaRecorder === "undefined") return "audio/webm";
  if (MediaRecorder.isTypeSupported("audio/webm;codecs=opus")) {
    return "audio/webm;codecs=opus";
  }
  if (MediaRecorder.isTypeSupported("audio/webm")) return "audio/webm";
  if (MediaRecorder.isTypeSupported("audio/mp4")) return "audio/mp4";
  return "audio/webm";
}

export function toRecordingLanguageCode(value: string): string {
  const trimmed = value.trim();
  if (!trimmed) return "en";
  return trimmed.split("-")[0]?.toLowerCase() || "en";
}

const DB_NAME = "therapy-flow-recording";
const DB_VERSION = 1;
const STORE = "failed-chunks";

export interface StoredFailedChunk {
  key: string;
  uploadId: string;
  sessionId?: number;
  index: number;
  durationSec: number;
  mime: string;
  blob: Blob;
  savedAt: number;
}

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === "undefined") {
      reject(new Error("IndexedDB not available"));
      return;
    }
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE)) {
        const store = db.createStore(STORE, { keyPath: "key" });
        store.createIndex("byUploadId", "uploadId", { unique: false });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function tx(db: IDBDatabase, mode: IDBTransactionMode) {
  return db.transaction(STORE, mode).objectStore(STORE);
}

function makeKey(uploadId: string, index: number): string {
  return `${uploadId}::${index}`;
}

export async function putFailedChunk(
  entry: Omit<StoredFailedChunk, "key" | "savedAt">,
): Promise<void> {
  try {
    const db = await openDb();
    await new Promise<void>((resolve, reject) => {
      const req = tx(db, "readwrite").put({
        ...entry,
        key: makeKey(entry.uploadId, entry.index),
        savedAt: Date.now(),
      });
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
    db.close();
  } catch (error) {
    console.warn("[recording-blob-store] put failed:", error);
  }
}

export async function deleteFailedChunk(uploadId: string, index: number): Promise<void> {
  try {
    const db = await openDb();
    await new Promise<void>((resolve, reject) => {
      const req = tx(db, "readwrite").delete(makeKey(uploadId, index));
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
    db.close();
  } catch (error) {
    console.warn("[recording-blob-store] delete failed:", error);
  }
}

export async function clearFailedChunksForUpload(uploadId: string): Promise<void> {
  try {
    const db = await openDb();
    await new Promise<void>((resolve, reject) => {
      const store = tx(db, "readwrite");
      const idx = store.index("byUploadId");
      const cursorReq = idx.openCursor(IDBKeyRange.only(uploadId));
      cursorReq.onsuccess = () => {
        const cursor = cursorReq.result;
        if (cursor) {
          cursor.delete();
          cursor.continue();
        } else {
          resolve();
        }
      };
      cursorReq.onerror = () => reject(cursorReq.error);
    });
    db.close();
  } catch (error) {
    console.warn("[recording-blob-store] clear failed:", error);
  }
}

import { baseApi } from "../baseApi";

export interface SessionTranscriptStartRequest {
  sessionId: number;
  language?: string;
  translateToEnglish?: boolean;
}

export interface SessionTranscriptStartResponse {
  uploadId: string;
}

export interface AppendSessionTranscriptChunkRequest {
  sessionId: number;
  uploadId: string;
  chunkIndex: number;
  chunkDurationSeconds: number;
  language?: string;
  audio: Blob;
}

export interface AppendSessionTranscriptChunkResponse {
  uploadId: string;
  chunkIndex: number;
  chunkText: string;
  chunksReceived: number;
}

export interface SilentChunkMarker {
  index: number;
  durationSeconds: number;
}

export interface FinalizeSessionTranscriptRequest {
  sessionId: number;
  uploadId: string;
  expectedChunks?: number;
  totalChunks?: number;
  silentChunks?: SilentChunkMarker[];
}

export interface FinalizeSessionTranscriptResponse {
  id: number;
  sessionId: number;
  clientId: number;
  content: string;
  status: string;
  language: string;
  durationSeconds: number;
  wordCount: number;
  uploadId: string;
}

export interface SmartFillSessionTranscriptResponse {
  sessionId: number;
  uploadId: string;
  transcript: string;
  mappedFields: Record<string, string>;
}

export interface SessionTranscriptChunkDto {
  chunkIndex: number;
  chunkStatus: string;
  chunkText: string;
  failureReason?: string;
  receivedAt?: string;
}

export interface GetSessionTranscriptResponse {
  transcriptId: number;
  sessionId: number;
  clientId: number;
  clientName: string;
  uploadId: string;
  status: string;
  language: string;
  expectedChunks: number;
  receivedChunks: number;
  finalTranscript: string;
  failureReason?: string;
  startedAt?: string;
  finalizedAt?: string;
  expiresAt?: string;
  updatedAt?: string;
  chunks: SessionTranscriptChunkDto[];
}

function normalizeGetSessionTranscriptResponse(
  payload: Record<string, unknown>,
): GetSessionTranscriptResponse {
  const finalTranscript =
    typeof payload.finalTranscript === "string"
      ? payload.finalTranscript
      : typeof payload.content === "string"
        ? payload.content
        : "";

  return {
    ...(payload as unknown as GetSessionTranscriptResponse),
    transcriptId:
      typeof payload.transcriptId === "number"
        ? payload.transcriptId
        : typeof payload.id === "number"
          ? payload.id
          : 0,
    finalTranscript,
  };
}

export const sessionTranscriptsApi = baseApi.injectEndpoints({
  endpoints: (builder) => ({
    startSessionTranscription: builder.mutation<
      SessionTranscriptStartResponse,
      SessionTranscriptStartRequest
    >({
      query: ({ sessionId, language, translateToEnglish }) => ({
        url: `/api/v1/sessions/${sessionId}/transcribe-start`,
        method: "POST",
        body: {
          language,
          translateToEnglish,
        },
      }),
    }),
    appendSessionTranscriptChunk: builder.mutation<
      AppendSessionTranscriptChunkResponse,
      AppendSessionTranscriptChunkRequest
    >({
      query: ({
        sessionId,
        uploadId,
        chunkIndex,
        chunkDurationSeconds,
        language,
        audio,
      }) => {
        const formData = new FormData();
        const ext = audio.type.includes("mp4") ? "mp4" : "webm";
        formData.append("audio", audio, `chunk-${chunkIndex}.${ext}`);

        const params = new URLSearchParams({
          uploadId,
          chunkIndex: String(chunkIndex),
          chunkDurationSeconds: String(chunkDurationSeconds),
        });
        if (language) {
          params.set("language", language);
        }

        return {
          url: `/api/v1/sessions/${sessionId}/transcribe-chunk?${params.toString()}`,
          method: "POST",
          body: formData,
        };
      },
    }),
    finalizeSessionTranscription: builder.mutation<
      FinalizeSessionTranscriptResponse,
      FinalizeSessionTranscriptRequest
    >({
      query: ({ sessionId, uploadId, expectedChunks, totalChunks, silentChunks }) => ({
        url: `/api/v1/sessions/${sessionId}/transcribe-finalize`,
        method: "POST",
        body: {
          uploadId,
          ...(expectedChunks !== undefined ? { expectedChunks } : {}),
          ...(totalChunks !== undefined ? { totalChunks } : {}),
          ...(silentChunks?.length ? { silentChunks } : {}),
        },
      }),
    }),
    smartFillSessionTranscript: builder.mutation<
      SmartFillSessionTranscriptResponse,
      { sessionId: number }
    >({
      query: ({ sessionId }) => ({
        url: `/api/v1/sessions/${sessionId}/transcript/smart-fill`,
        method: "POST",
      }),
    }),
    getSessionTranscript: builder.query<GetSessionTranscriptResponse, number>({
      query: (sessionId) => `/api/v1/sessions/${sessionId}/transcript`,
      transformResponse: (payload: unknown) =>
        normalizeGetSessionTranscriptResponse(
          typeof payload === "object" && payload !== null
            ? (payload as Record<string, unknown>)
            : {},
        ),
    }),
    deleteSessionTranscript: builder.mutation<void, number>({
      query: (sessionId) => ({
        url: `/api/v1/sessions/${sessionId}/transcript`,
        method: "DELETE",
      }),
    }),
    downloadSessionTranscript: builder.query<string, number>({
      query: (sessionId) => ({
        url: `/api/v1/sessions/${sessionId}/transcript/download`,
        responseHandler: "text",
      }),
      transformResponse: (payload: unknown) =>
        typeof payload === "string" ? payload : "",
    }),
  }),
});

export const {
  useStartSessionTranscriptionMutation,
  useAppendSessionTranscriptChunkMutation,
  useFinalizeSessionTranscriptionMutation,
  useSmartFillSessionTranscriptMutation,
  useLazyGetSessionTranscriptQuery,
  useDeleteSessionTranscriptMutation,
  useLazyDownloadSessionTranscriptQuery,
} = sessionTranscriptsApi;

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Copy, Download, Loader2, Mic, Pause, Play, Square, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Switch } from "@/components/ui/switch";
import {
  buildStoredSessionTranscript,
  saveStoredSessionTranscript,
  type StoredSessionTranscript,
} from "./sessionTranscriptStore";
import {
  useAppendSessionTranscriptChunkMutation,
  useFinalizeSessionTranscriptionMutation,
  useStartSessionTranscriptionMutation,
  type SessionNoteTranscriptionResponse,
} from "@/store/api/admin";
import { getApiErrorMessage } from "@/utils/apiError";
import { getAuthSession } from "@/utils/authStorage";
import { buildTenantApiBase } from "@/utils/tenantUrls";
import {
  clearFailedChunksForUpload,
  deleteFailedChunk,
  putFailedChunk,
} from "@/utils/recording/recordingBlobStore";
import {
  findClusterStart,
  pickRecorderMimeType,
  toRecordingLanguageCode,
} from "@/utils/recording/webmChunkUtils";

interface RecordSessionModalProps {
  isOpen: boolean;
  onClose: () => void;
  sessionData: {
    sessionId: number;
    clientId: number | null;
    therapistId: number | null;
    dateTime: string;
    sessionType: string;
    clientName: string;
  } | null;
  onTranscriptSaved: (
    transcript: StoredSessionTranscript,
    transcriptionResponse: SessionNoteTranscriptionResponse,
  ) => void;
  onToast: (message: string, type: "success" | "error" | "info") => void;
}

type RecordingStage = "setup" | "recording" | "paused" | "finalizing";

const LANGUAGE_OPTIONS = [
  { label: "English", value: "en" },
  { label: "Arabic", value: "ar" },
  { label: "Urdu", value: "ur" },
  { label: "Hindi", value: "hi" },
];

const SLICE_MS = 20_000;
const LIVE_TIMESLICE_MS = 250;
const SILENCE_RMS_THRESHOLD = 0.0008;
const CHUNK_UPLOAD_MAX_ATTEMPTS = 3;

function normalizeTranscriptText(value: string) {
  return value.replace(/\s+/g, " ").trim();
}

function buildDownloadFileName(clientName: string) {
  return `${clientName.toLowerCase().replace(/[^a-z0-9]+/g, "-") || "session"}-transcript.txt`;
}

function getWebSocketUrl(uploadId: string, language: string) {
  const session = getAuthSession();
  const base = buildTenantApiBase(session?.tenantSubdomain ?? undefined);
  const url = new URL(base);
  url.protocol = url.protocol === "https:" ? "wss:" : "ws:";
  url.pathname = "/ws/transcribe-live";
  url.searchParams.set("uploadId", uploadId);
  url.searchParams.set("language", language);
  if (session?.accessToken) {
    url.searchParams.set("token", session.accessToken);
  }
  return url.toString();
}

const RecordSessionModal = ({
  isOpen,
  onClose,
  sessionData,
  onTranscriptSaved,
  onToast,
}: RecordSessionModalProps) => {
  const [stage, setStage] = useState<RecordingStage>("setup");
  const [recordingSeconds, setRecordingSeconds] = useState(0);
  const [micLevel, setMicLevel] = useState(0);
  const [selectedLanguage, setSelectedLanguage] = useState(LANGUAGE_OPTIONS[0].value);
  const [translateToEnglish, setTranslateToEnglish] = useState(false);
  const [availableMics, setAvailableMics] = useState<MediaDeviceInfo[]>([]);
  const [selectedMicId, setSelectedMicId] = useState("");
  const [livePreview, setLivePreview] = useState("");
  const [hidePreview, setHidePreview] = useState(false);
  const [chunksSent, setChunksSent] = useState(0);
  const [chunksUploaded, setChunksUploaded] = useState(0);
  const [totalSlices, setTotalSlices] = useState(0);
  const [uploadId, setUploadId] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const liveRecorderRef = useRef<MediaRecorder | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const animationFrameRef = useRef<number | null>(null);
  const meterIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const socketRef = useRef<WebSocket | null>(null);
  const livePreviewRef = useRef<HTMLDivElement | null>(null);
  const uploadQueueRef = useRef<Promise<void>>(Promise.resolve());
  const chunkIndexRef = useRef(0);
  const webmInitRef = useRef<Uint8Array | null>(null);
  const mimeTypeRef = useRef("audio/webm");
  const uploadIdRef = useRef("");
  const segmentStartRef = useRef(0);
  const segmentMaxRmsRef = useRef(0);
  const silentChunksRef = useRef<Map<number, number>>(new Map());
  const failedChunksRef = useRef<
    Map<number, { blob: Blob; durationSec: number; mime: string }>
  >(new Map());
  const isPausedRef = useRef(false);
  const stoppingRef = useRef(false);
  const liveActiveRef = useRef(false);
  const liveStoppedRef = useRef(false);
  const stopFlushedRef = useRef<Promise<void>>(Promise.resolve());

  const [startSessionTranscription, { isLoading: isStarting }] =
    useStartSessionTranscriptionMutation();
  const [appendSessionTranscriptChunk] = useAppendSessionTranscriptChunkMutation();
  const [finalizeSessionTranscription, { isLoading: isFinalizing }] =
    useFinalizeSessionTranscriptionMutation();

  const displayedChunkTotal = useMemo(() => {
    if (stage === "recording" || stage === "paused") {
      return Math.max(totalSlices + 1, 1);
    }
    return Math.max(totalSlices, 1);
  }, [stage, totalSlices]);

  const progressPercentage = useMemo(() => {
    if (displayedChunkTotal <= 0) return 0;
    return Math.min(100, Math.round((chunksUploaded / displayedChunkTotal) * 100));
  }, [chunksUploaded, displayedChunkTotal]);

  const hasMediaRecorder = useMemo(
    () => typeof window !== "undefined" && typeof MediaRecorder !== "undefined",
    [],
  );

  const loadMicrophones = useCallback(async () => {
    if (!navigator.mediaDevices?.enumerateDevices) return;
    try {
      const devices = await navigator.mediaDevices.enumerateDevices();
      const microphones = devices.filter((device) => device.kind === "audioinput");
      setAvailableMics(microphones);
      if (!selectedMicId && microphones[0]?.deviceId) {
        setSelectedMicId(microphones[0].deviceId);
      }
    } catch {
      setAvailableMics([]);
    }
  }, [selectedMicId]);

  const stopLiveSocket = useCallback(() => {
    liveStoppedRef.current = true;
    if (liveRecorderRef.current && liveRecorderRef.current.state !== "inactive") {
      try {
        liveRecorderRef.current.stop();
      } catch {
        // no-op
      }
    }
    liveRecorderRef.current = null;
    if (socketRef.current) {
      try {
        if (socketRef.current.readyState === WebSocket.OPEN) {
          socketRef.current.send("finalize");
        }
        socketRef.current.close();
      } catch {
        // no-op
      }
      socketRef.current = null;
    }
    liveActiveRef.current = false;
  }, []);

  const cleanupMedia = useCallback(() => {
    if (animationFrameRef.current !== null) {
      cancelAnimationFrame(animationFrameRef.current);
      animationFrameRef.current = null;
    }
    if (meterIntervalRef.current !== null) {
      clearInterval(meterIntervalRef.current);
      meterIntervalRef.current = null;
    }
    stopLiveSocket();
    if (audioContextRef.current) {
      void audioContextRef.current.close();
      audioContextRef.current = null;
    }
    analyserRef.current = null;
    mediaRecorderRef.current = null;
    mediaStreamRef.current?.getTracks().forEach((track) => track.stop());
    mediaStreamRef.current = null;
    webmInitRef.current = null;
    segmentMaxRmsRef.current = 0;
  }, [stopLiveSocket]);

  const resetRecordingState = useCallback(() => {
    setStage("setup");
    setRecordingSeconds(0);
    setMicLevel(0);
    setSelectedLanguage(LANGUAGE_OPTIONS[0].value);
    setTranslateToEnglish(false);
    setLivePreview("");
    setHidePreview(false);
    setChunksSent(0);
    setChunksUploaded(0);
    setTotalSlices(0);
    setUploadId(null);
    chunkIndexRef.current = 0;
    uploadIdRef.current = "";
    silentChunksRef.current = new Map();
    failedChunksRef.current = new Map();
    isPausedRef.current = false;
    stoppingRef.current = false;
    liveStoppedRef.current = false;
    liveActiveRef.current = false;
    uploadQueueRef.current = Promise.resolve();
    stopFlushedRef.current = Promise.resolve();
  }, []);

  useEffect(() => {
    if (!isOpen) return;
    resetRecordingState();
    void loadMicrophones();
  }, [isOpen, loadMicrophones, resetRecordingState]);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval> | null = null;
    if (stage === "recording") {
      interval = setInterval(() => {
        setRecordingSeconds((prev) => prev + 1);
      }, 1000);
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [stage]);

  useEffect(() => {
    if (isOpen) return;
    cleanupMedia();
  }, [cleanupMedia, isOpen]);

  useEffect(() => {
    return () => {
      cleanupMedia();
    };
  }, [cleanupMedia]);

  useEffect(() => {
    if (!livePreviewRef.current || hidePreview) return;
    livePreviewRef.current.scrollTop = livePreviewRef.current.scrollHeight;
  }, [hidePreview, livePreview]);

  const appendPreviewText = useCallback((text: string) => {
    const normalized = normalizeTranscriptText(text);
    if (!normalized) return;
    setLivePreview((previous) => {
      const next = normalizeTranscriptText(
        previous ? `${previous} ${normalized}` : normalized,
      );
      return next;
    });
  }, []);

  const connectLiveSocket = useCallback(
    (nextUploadId: string, language: string) => {
      liveStoppedRef.current = false;
      try {
        const socket = new WebSocket(getWebSocketUrl(nextUploadId, language));
        socket.binaryType = "arraybuffer";
        socket.onmessage = (event) => {
          if (typeof event.data !== "string") return;
          try {
            const parsed = JSON.parse(event.data) as Record<string, unknown>;
            if (parsed.type === "transcript") {
              liveActiveRef.current = true;
              const text = typeof parsed.text === "string" ? parsed.text : "";
              if (parsed.isFinal && text.trim()) {
                appendPreviewText(text);
              }
              return;
            }
            const preview =
              typeof parsed.previewText === "string"
                ? parsed.previewText
                : typeof parsed.transcript === "string"
                  ? parsed.transcript
                  : typeof parsed.text === "string"
                    ? parsed.text
                    : typeof parsed.chunkText === "string"
                      ? parsed.chunkText
                      : "";
            if (preview) {
              liveActiveRef.current = true;
              appendPreviewText(preview);
            }
            if (typeof parsed.chunksReceived === "number") {
              setChunksUploaded((previousCount) =>
                Math.max(previousCount, parsed.chunksReceived as number),
              );
            }
          } catch {
            if (event.data.trim()) {
              liveActiveRef.current = true;
              appendPreviewText(event.data);
            }
          }
        };
        socketRef.current = socket;
      } catch {
        socketRef.current = null;
      }
    },
    [appendPreviewText],
  );

  const startLiveRecorder = useCallback((stream: MediaStream, language: string) => {
    const mimeType = mimeTypeRef.current;
    try {
      const recorder = new MediaRecorder(stream, {
        mimeType,
        audioBitsPerSecond: 128_000,
      });
      recorder.ondataavailable = (event) => {
        if (!event.data || event.data.size === 0 || liveStoppedRef.current) return;
        void event.data.arrayBuffer().then((buffer) => {
          if (socketRef.current?.readyState === WebSocket.OPEN) {
            socketRef.current.send(buffer);
          }
        });
      };
      recorder.start(LIVE_TIMESLICE_MS);
      liveRecorderRef.current = recorder;
      connectLiveSocket(uploadIdRef.current, language);
    } catch {
      liveRecorderRef.current = null;
    }
  }, [connectLiveSocket]);

  const pauseLiveRecorder = useCallback(() => {
    if (liveRecorderRef.current?.state === "recording") {
      try {
        liveRecorderRef.current.pause();
      } catch {
        // no-op
      }
    }
  }, []);

  const resumeLiveRecorder = useCallback(() => {
    if (liveRecorderRef.current?.state === "paused") {
      try {
        liveRecorderRef.current.resume();
      } catch {
        // no-op
      }
    }
  }, []);

  const startMicMeter = useCallback((stream: MediaStream) => {
    const audioContext = new window.AudioContext();
    const analyser = audioContext.createAnalyser();
    analyser.fftSize = 1024;
    const source = audioContext.createMediaStreamSource(stream);
    source.connect(analyser);
    audioContextRef.current = audioContext;
    analyserRef.current = analyser;

    const data = new Uint8Array(analyser.fftSize);
    const sample = () => {
      if (!analyserRef.current) return;
      analyserRef.current.getByteTimeDomainData(data);
      let sum = 0;
      for (let i = 0; i < data.length; i += 1) {
        const value = (data[i] - 128) / 128;
        sum += value * value;
      }
      const rms = Math.sqrt(sum / data.length);
      if (rms > segmentMaxRmsRef.current) {
        segmentMaxRmsRef.current = rms;
      }
      setMicLevel(Math.min(100, Math.round(rms * 400)));
      return rms;
    };

    const updateLevel = () => {
      sample();
      animationFrameRef.current = requestAnimationFrame(updateLevel);
    };
    updateLevel();
    meterIntervalRef.current = setInterval(sample, 100);
  }, []);

  const uploadChunk = useCallback(
    async (blob: Blob, index: number, durationSec: number, mime: string) => {
      if (!sessionData || !uploadIdRef.current) return;

      for (let attempt = 1; attempt <= CHUNK_UPLOAD_MAX_ATTEMPTS; attempt += 1) {
        try {
          const response = await appendSessionTranscriptChunk({
            sessionId: sessionData.sessionId,
            uploadId: uploadIdRef.current,
            chunkIndex: index,
            chunkDurationSeconds: durationSec,
            language: toRecordingLanguageCode(selectedLanguage),
            audio: blob,
          }).unwrap();

          failedChunksRef.current.delete(index);
          void deleteFailedChunk(uploadIdRef.current, index);
          setChunksUploaded((count) => Math.max(count, response.chunksReceived));
          if (response.chunkText && !liveActiveRef.current) {
            appendPreviewText(response.chunkText);
          }
          return;
        } catch (error) {
          if (attempt === CHUNK_UPLOAD_MAX_ATTEMPTS) {
            failedChunksRef.current.set(index, { blob, durationSec, mime });
            void putFailedChunk({
              uploadId: uploadIdRef.current,
              sessionId: sessionData.sessionId,
              index,
              durationSec,
              mime,
              blob,
            });
            onToast(
              `Chunk ${index} failed to upload. Stop and retry before saving.`,
              "error",
            );
            return;
          }
          await new Promise((resolve) => {
            setTimeout(resolve, 1000 * attempt);
          });
        }
      }
    },
    [appendPreviewText, appendSessionTranscriptChunk, onToast, selectedLanguage, sessionData],
  );

  const startSegmentRecorder = useCallback(() => {
    const stream = mediaStreamRef.current;
    if (!stream) return;

    const mimeType = pickRecorderMimeType();
    mimeTypeRef.current = mimeType;
    webmInitRef.current = null;
    segmentStartRef.current = Date.now();

    let resolveStopped = () => {};
    stopFlushedRef.current = new Promise<void>((resolve) => {
      resolveStopped = resolve;
    });

    const recorder = new MediaRecorder(stream, {
      mimeType,
      audioBitsPerSecond: 128_000,
    });

    recorder.ondataavailable = (event) => {
      if (!event.data || event.data.size === 0) return;

      const segmentDurationSec = (Date.now() - segmentStartRef.current) / 1000;
      segmentStartRef.current = Date.now();
      const segmentPeakRms = segmentMaxRmsRef.current;
      segmentMaxRmsRef.current = 0;
      const wasSilent = segmentPeakRms < SILENCE_RMS_THRESHOLD;
      const index = chunkIndexRef.current;
      chunkIndexRef.current += 1;
      setTotalSlices(index + 1);

      if (wasSilent) {
        silentChunksRef.current.set(index, segmentDurationSec);
        return;
      }

      setChunksSent((count) => count + 1);
      const eventData = event.data;
      uploadQueueRef.current = uploadQueueRef.current.then(async () => {
        let blobToSend: Blob = eventData;
        if (!webmInitRef.current && mimeType.includes("webm")) {
          try {
            const bytes = new Uint8Array(await eventData.arrayBuffer());
            const clusterStart = findClusterStart(bytes);
            if (clusterStart > 0) {
              webmInitRef.current = bytes.slice(0, clusterStart);
            }
          } catch {
            // no-op
          }
        } else if (webmInitRef.current && mimeType.includes("webm")) {
          blobToSend = new Blob([webmInitRef.current, eventData], { type: mimeType });
        }
        await uploadChunk(blobToSend, index, segmentDurationSec, mimeType);
      });
    };

    recorder.onstop = () => {
      resolveStopped();
    };

    recorder.start(SLICE_MS);
    mediaRecorderRef.current = recorder;
  }, [uploadChunk]);

  const handleStartRecording = async () => {
    if (!sessionData) return;
    if (!hasMediaRecorder) {
      onToast("This browser does not support audio recording.", "error");
      return;
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: selectedMicId
          ? {
              deviceId: { exact: selectedMicId },
              echoCancellation: true,
              noiseSuppression: true,
              autoGainControl: true,
            }
          : {
              echoCancellation: true,
              noiseSuppression: true,
              autoGainControl: true,
            },
      });

      const startResponse = await startSessionTranscription({
        sessionId: sessionData.sessionId,
        language: toRecordingLanguageCode(selectedLanguage),
        translateToEnglish,
      }).unwrap();

      mediaStreamRef.current = stream;
      uploadIdRef.current = startResponse.uploadId;
      setUploadId(startResponse.uploadId);
      await loadMicrophones();

      startMicMeter(stream);
      startSegmentRecorder();
      startLiveRecorder(stream, toRecordingLanguageCode(selectedLanguage));
      setStage("recording");
    } catch (error) {
      onToast(getApiErrorMessage(error), "error");
      setStage("setup");
      cleanupMedia();
    }
  };

  const handlePauseResume = () => {
    const recorder = mediaRecorderRef.current;
    if (!recorder) return;

    if (stage === "recording" && recorder.state === "recording") {
      recorder.pause();
      pauseLiveRecorder();
      isPausedRef.current = true;
      setStage("paused");
      return;
    }

    if (stage === "paused" && recorder.state === "paused") {
      segmentMaxRmsRef.current = 0;
      segmentStartRef.current = Date.now();
      recorder.resume();
      resumeLiveRecorder();
      isPausedRef.current = false;
      setStage("recording");
    }
  };

  const handleCopyPreview = () => {
    void navigator.clipboard.writeText(livePreview);
  };

  const handleDownloadPreview = () => {
    const blob = new Blob([livePreview], { type: "text/plain;charset=utf-8" });
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = buildDownloadFileName(sessionData?.clientName ?? "session");
    anchor.click();
    window.URL.revokeObjectURL(url);
  };

  const handleStopAndSave = async () => {
    if (!mediaRecorderRef.current || !sessionData || !uploadId) return;

    if (failedChunksRef.current.size > 0) {
      onToast(
        "Some chunks failed to upload. Resolve failed chunks before saving.",
        "error",
      );
      return;
    }

    setStage("finalizing");
    stoppingRef.current = true;

    try {
      const recorder = mediaRecorderRef.current;
      if (recorder.state === "recording" || recorder.state === "paused") {
        const flushed = stopFlushedRef.current;
        recorder.stop();
        await flushed;
      }

      stopLiveSocket();
      mediaStreamRef.current?.getTracks().forEach((track) => track.stop());
      mediaStreamRef.current = null;

      if (animationFrameRef.current !== null) {
        cancelAnimationFrame(animationFrameRef.current);
        animationFrameRef.current = null;
      }
      if (meterIntervalRef.current !== null) {
        clearInterval(meterIntervalRef.current);
        meterIntervalRef.current = null;
      }
      if (audioContextRef.current) {
        await audioContextRef.current.close();
        audioContextRef.current = null;
      }

      await uploadQueueRef.current;

      const totalChunks = chunkIndexRef.current;
      const finalizeResponse = await finalizeSessionTranscription({
        sessionId: sessionData.sessionId,
        uploadId,
        expectedChunks: totalChunks,
        totalChunks,
        silentChunks: Array.from(silentChunksRef.current.entries()).map(
          ([index, durationSeconds]) => ({ index, durationSeconds }),
        ),
      }).unwrap();

      const transcript = buildStoredSessionTranscript({
        transcriptId: finalizeResponse.id,
        sessionId: sessionData.sessionId,
        uploadId: finalizeResponse.uploadId,
        clientId: sessionData.clientId ?? finalizeResponse.clientId,
        therapistId: sessionData.therapistId,
        clientName: sessionData.clientName,
        sessionType: sessionData.sessionType,
        sessionDateTime: sessionData.dateTime,
        durationSeconds: finalizeResponse.durationSeconds || recordingSeconds,
        status: finalizeResponse.status,
        expectedChunks: totalChunks,
        receivedChunks: chunksUploaded,
        rawTranscription: finalizeResponse.content,
        mappedFields: {},
      });

      void clearFailedChunksForUpload(uploadId);
      saveStoredSessionTranscript(transcript);
      cleanupMedia();
      onTranscriptSaved(transcript, {
        success: true,
        rawTranscription: finalizeResponse.content,
        mappedFields: {},
      });
    } catch (error) {
      onToast(getApiErrorMessage(error), "error");
      setStage(chunksUploaded > 0 ? "paused" : "setup");
      isPausedRef.current = true;
      stoppingRef.current = false;
    }
  };

  if (!isOpen || !sessionData) return null;

  const formattedDuration = `00:${Math.floor(recordingSeconds / 60)
    .toString()
    .padStart(2, "0")}:${(recordingSeconds % 60).toString().padStart(2, "0")}`;

  return (
    <div className="fixed inset-0 z-[10000] flex items-center justify-center bg-black/50 p-4">
      <div className="flex max-h-[90vh] w-full max-w-5xl flex-col overflow-hidden rounded-[24px] bg-white shadow-xl">
        <div className="flex items-start justify-between border-b border-(--neutral-200) px-6 py-5">
          <div className="space-y-1">
            <h2 className="flex items-center gap-3 text-[30px] font-semibold leading-none text-(--text-primary-dark)">
              <span className="flex h-10 w-10 items-center justify-center rounded-full bg-[#fff1f1] text-[#ff4d4f]">
                <Mic size={20} />
              </span>
              Record Session
            </h2>
            <p className="max-w-3xl text-base text-(--text-neutral-600)">
              Record the session audio. The transcript is saved to this session and can be used to smart-fill the note later.
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="rounded-full p-2 text-(--text-neutral-500) transition-colors hover:bg-(--neutral-100)"
          >
            <X size={22} />
          </button>
        </div>

        <div className="overflow-y-auto px-6 py-6">
          <div className="rounded-[24px] border border-(--neutral-200) bg-white p-6 shadow-sm">
            <div className="mb-6 flex items-center gap-3">
              <span className="flex h-11 w-11 items-center justify-center rounded-full bg-(--neutral-50) text-(--text-primary-dark)">
                <Mic size={20} />
              </span>
              <div>
                <h3 className="text-[22px] font-semibold text-(--text-primary-dark)">
                  Session Transcript
                </h3>
                <p className="text-sm text-(--text-neutral-600)">
                  {sessionData.clientName} · {sessionData.dateTime}
                </p>
              </div>
            </div>

            {stage === "setup" ? (
              <div className="mx-auto max-w-3xl space-y-6">
                <div className="space-y-2">
                  <label className="text-sm font-medium text-(--text-neutral-700)">
                    Microphone
                  </label>
                  <select
                    value={selectedMicId}
                    onChange={(event) => setSelectedMicId(event.target.value)}
                    className="h-14 w-full rounded-[18px] border border-(--neutral-200) px-4 text-base text-(--text-primary-dark) outline-none focus:border-(--primary-400)"
                  >
                    {availableMics.length > 0 ? (
                      availableMics.map((device, index) => (
                        <option key={device.deviceId || index} value={device.deviceId}>
                          {device.label || `Microphone ${index + 1}`}
                        </option>
                      ))
                    ) : (
                      <option value="">Default microphone</option>
                    )}
                  </select>
                </div>

                <div className="space-y-2">
