/** Constants and helpers aligned with transcription-api-integration.md (v2). */

export const TRANSCRIPT_PLANNING_MAX_CHUNKS = 5000;
export const TRANSCRIPT_RETENTION_DAYS = 90;
export const TRANSCRIPT_SLICE_MS = 20_000;
export const TRANSCRIPT_MAX_CHUNK_INDEX = 500;
export const TRANSCRIPT_CHUNK_UPLOAD_MAX_ATTEMPTS = 3;
export const TRANSCRIPT_SILENCE_RMS_THRESHOLD = 0.0008;
export const TRANSCRIPT_LIVE_TIMESLICE_MS = 250;

export const TRANSCRIPT_READY_STATUS = "ready";

export function toTranscriptionLanguageCode(value: string): string {
  const trimmed = value.trim();
  if (!trimmed) return "en-us";
  return trimmed.toLowerCase();
}

export function getTranscriptContent(payload: {
  content?: string | null;
  finalTranscript?: string | null;
}): string {
  const content = payload.content?.trim() ?? "";
  if (content) return content;
  return payload.finalTranscript?.trim() ?? "";
}

export function isTranscriptReady(status: string | null | undefined): boolean {
  return status?.toLowerCase() === TRANSCRIPT_READY_STATUS;
}

export class TranscriptChunkUploadError extends Error {
  readonly status: number;
  readonly retryAfterSec?: number;

  constructor(message: string, status: number, retryAfterSec?: number) {
    super(message);
    this.name = "TranscriptChunkUploadError";
    this.status = status;
    this.retryAfterSec = retryAfterSec;
  }
}

import { getAuthSession } from "@/utils/authStorage";
import { buildTenantApiBase } from "@/utils/tenantUrls";
import type { AppendSessionTranscriptChunkResponse } from "@/store/api/admin/sessionTranscripts.api";
import { TranscriptChunkUploadError } from "@/utils/recording/transcriptionApi";

export interface UploadTranscriptChunkArgs {
  sessionId: number;
  uploadId: string;
  chunkIndex: number;
  chunkDurationSeconds: number;
  language?: string;
  audio: Blob;
}

export async function uploadTranscriptChunk(
  args: UploadTranscriptChunkArgs,
): Promise<AppendSessionTranscriptChunkResponse> {
  const session = getAuthSession();
  const base = buildTenantApiBase(session?.tenantSubdomain ?? undefined);
  const mimeType = args.audio.type || "audio/webm";
  const ext = mimeType.includes("mp4") ? "mp4" : "webm";

  const formData = new FormData();
  formData.append("uploadId", args.uploadId);
  formData.append("chunkIndex", String(args.chunkIndex));
  formData.append("chunkDurationSeconds", String(args.chunkDurationSeconds));
  formData.append("audio", args.audio, `chunk-${args.chunkIndex}.${ext}`);
  if (args.language) {
    formData.append("language", args.language);
  }

  const headers: HeadersInit = {};
  if (session?.accessToken) {
    headers.Authorization = `Bearer ${session.accessToken}`;
  }

  const response = await fetch(
    `${base}/api/v1/sessions/${args.sessionId}/transcribe-chunk`,
    {
      method: "POST",
      headers,
      body: formData,
    },
  );

  const payload = (await response.json().catch(() => ({}))) as Record<string, unknown>;
  if (!response.ok) {
    const message =
      typeof payload.message === "string"
        ? payload.message
        : `Chunk upload failed (${response.status})`;
    const retryAfterHeader = response.headers.get("Retry-After");
    const retryAfterSec = retryAfterHeader
      ? Number.parseInt(retryAfterHeader, 10)
      : undefined;

    throw new TranscriptChunkUploadError(
      message,
      response.status,
      Number.isFinite(retryAfterSec) ? retryAfterSec : undefined,
    );
  }

  return payload as AppendSessionTranscriptChunkResponse;
}

import { baseApi } from "../baseApi";
import {
  getTranscriptContent,
  TRANSCRIPT_PLANNING_MAX_CHUNKS,
  TRANSCRIPT_RETENTION_DAYS,
} from "@/utils/recording/transcriptionApi";
import { uploadTranscriptChunk } from "@/utils/recording/uploadTranscriptChunk";

export interface SessionTranscriptStartRequest {
  sessionId: number;
  language?: string;
  translateToEnglish?: boolean;
  expectedChunks?: number;
  retentionDays?: number;
}

export interface SessionTranscriptStartResponse {
  uploadId: string;
}

export interface AppendSessionTranscriptChunkRequest {
  sessionId: number;
  uploadId: string;
  chunkIndex: number;
  chunkDurationSeconds: number;
  language?: string;
  audio: Blob;
}

export interface AppendSessionTranscriptChunkResponse {
  uploadId: string;
  chunkIndex: number;
  chunkText: string;
  chunksReceived: number;
}

export interface SilentChunkMarker {
  index: number;
  durationSeconds: number;
}

export interface FinalizeSessionTranscriptRequest {
  sessionId: number;
  uploadId: string;
  expectedChunks: number;
  totalChunks?: number;
  silentChunks?: SilentChunkMarker[];
}

export interface FinalizeSessionTranscriptResponse {
  id: number;
  sessionId: number;
  clientId: number;
  uploadId: string;
  status: string;
  language: string;
  content: string;
  durationSeconds: number;
  wordCount: number;
}

export interface SmartFillSessionTranscriptResponse {
  sessionId: number;
  uploadId: string;
  transcript: string;
  mappedFields: Record<string, string>;
}

export interface SessionTranscriptChunkDto {
  chunkIndex: number;
  chunkStatus: string;
  chunkText: string;
  failureReason?: string;
  receivedAt?: string;
}

export interface GetSessionTranscriptResponse {
  transcriptId: number;
  sessionId: number;
  clientId: number;
  clientName: string;
  uploadId: string;
  status: string;
  language: string;
  expectedChunks: number;
  receivedChunks: number;
  finalTranscript: string;
  content: string;
  durationSeconds: number | null;
  wordCount: number | null;
  failureReason?: string;
  startedAt?: string;
  finalizedAt?: string;
  expiresAt?: string;
  updatedAt?: string;
  chunks: SessionTranscriptChunkDto[];
}

function normalizeGetSessionTranscriptResponse(
  payload: Record<string, unknown>,
): GetSessionTranscriptResponse {
  const finalTranscript = getTranscriptContent({
    content: typeof payload.content === "string" ? payload.content : null,
    finalTranscript:
      typeof payload.finalTranscript === "string" ? payload.finalTranscript : null,
  });

  return {
    ...(payload as unknown as GetSessionTranscriptResponse),
    transcriptId:
      typeof payload.transcriptId === "number"
        ? payload.transcriptId
        : typeof payload.id === "number"
          ? payload.id
          : 0,
    finalTranscript,
    content: finalTranscript,
    durationSeconds:
      typeof payload.durationSeconds === "number" ? payload.durationSeconds : null,
    wordCount: typeof payload.wordCount === "number" ? payload.wordCount : null,
    chunks: Array.isArray(payload.chunks)
      ? (payload.chunks as SessionTranscriptChunkDto[])
      : [],
  };
}

export const sessionTranscriptsApi = baseApi.injectEndpoints({
  endpoints: (builder) => ({
    startSessionTranscription: builder.mutation<
      SessionTranscriptStartResponse,
      SessionTranscriptStartRequest
    >({
      query: ({
        sessionId,
        language,
        translateToEnglish,
        expectedChunks = TRANSCRIPT_PLANNING_MAX_CHUNKS,
        retentionDays = TRANSCRIPT_RETENTION_DAYS,
      }) => ({
        url: `/api/v1/sessions/${sessionId}/transcribe-start`,
        method: "POST",
        body: {
          language,
          translateToEnglish,
          expectedChunks,
          retentionDays,
        },
      }),
    }),
    appendSessionTranscriptChunk: builder.mutation<
      AppendSessionTranscriptChunkResponse,
      AppendSessionTranscriptChunkRequest
    >({
      async queryFn(args) {
        try {
          const data = await uploadTranscriptChunk(args);
          return { data };
        } catch (error) {
          return {
            error: {
              status: "CUSTOM_ERROR",
              error: error instanceof Error ? error.message : "Chunk upload failed",
              data: error,
            },
          };
        }
      },
    }),
    finalizeSessionTranscription: builder.mutation<
      FinalizeSessionTranscriptResponse,
      FinalizeSessionTranscriptRequest
    >({
      query: ({ sessionId, uploadId, expectedChunks, totalChunks, silentChunks }) => ({
        url: `/api/v1/sessions/${sessionId}/transcribe-finalize`,
        method: "POST",
        body: {
          uploadId,
          expectedChunks,
          ...(totalChunks !== undefined ? { totalChunks } : {}),
          ...(silentChunks?.length ? { silentChunks } : {}),
        },
      }),
    }),
    smartFillSessionTranscript: builder.mutation<
      SmartFillSessionTranscriptResponse,
      { sessionId: number }
    >({
      query: ({ sessionId }) => ({
        url: `/api/v1/sessions/${sessionId}/transcript/smart-fill`,
        method: "POST",
      }),
