import type { CustomSelectOption } from "@/components/form/CustomSelect";

export const CLIENT_STAGE_TRANSITIONS: Record<string, string[]> = {
  INTAKE: ["ASSESSMENT"],
  ASSESSMENT: ["ACTIVE_TREATMENT", "DISCHARGE"],
  ACTIVE_TREATMENT: ["MAINTENANCE", "DISCHARGE_PLANNING"],
  MAINTENANCE: ["DISCHARGE_PLANNING"],
  DISCHARGE_PLANNING: ["DISCHARGE"],
  DISCHARGE: ["FOLLOW_UP"],
  FOLLOW_UP: [],
};

export const CLIENT_STATUS_TRANSITIONS: Record<string, string[]> = {
  PENDING: ["ACTIVE", "WAITLIST"],
  ACTIVE: ["ON_HOLD", "DISCHARGED"],
  ON_HOLD: ["ACTIVE", "DISCHARGED"],
  WAITLIST: ["ACTIVE", "INACTIVE"],
  INACTIVE: [],
  DISCHARGED: [],
};

const STAGE_LABEL_TO_CONSTANT: Record<string, string> = {
  INTAKE: "INTAKE",
  ASSESSMENT: "ASSESSMENT",
  ACTIVE_TREATMENT: "ACTIVE_TREATMENT",
  MAINTENANCE: "MAINTENANCE",
  DISCHARGE_PLANNING: "DISCHARGE_PLANNING",
  DISCHARGE: "DISCHARGE",
  FOLLOW_UP: "FOLLOW_UP",
  Intake: "INTAKE",
  Assessment: "ASSESSMENT",
  "Active Treatment": "ACTIVE_TREATMENT",
  Maintenance: "MAINTENANCE",
  "Discharge Planning": "DISCHARGE_PLANNING",
  Discharge: "DISCHARGE",
  "Follow-Up": "FOLLOW_UP",
};

const STATUS_LABEL_TO_CONSTANT: Record<string, string> = {
  PENDING: "PENDING",
  ACTIVE: "ACTIVE",
  INACTIVE: "INACTIVE",
  DISCHARGED: "DISCHARGED",
  ON_HOLD: "ON_HOLD",
  WAITLIST: "WAITLIST",
  Pending: "PENDING",
  Active: "ACTIVE",
  Inactive: "INACTIVE",
  Discharged: "DISCHARGED",
  "On Hold": "ON_HOLD",
  Waitlist: "WAITLIST",
};

export function normalizeClientStageConstant(stage?: string | null): string {
  if (!stage?.trim()) return "INTAKE";
  const trimmed = stage.trim();
  if (STAGE_LABEL_TO_CONSTANT[trimmed]) return STAGE_LABEL_TO_CONSTANT[trimmed];
  return trimmed.toUpperCase().replace(/[\s-]+/g, "_");
}

export function normalizeClientStatusConstant(status?: string | null): string {
  if (!status?.trim()) return "ACTIVE";
  const trimmed = status.trim();
  if (STATUS_LABEL_TO_CONSTANT[trimmed]) return STATUS_LABEL_TO_CONSTANT[trimmed];
  return trimmed.toUpperCase().replace(/[\s-]+/g, "_");
}

export function isClientStageTransitionAllowed(
  currentStage: string,
  nextStage: string,
): boolean {
  const current = normalizeClientStageConstant(currentStage);
  const next = normalizeClientStageConstant(nextStage);
  if (current === next) return true;
  return CLIENT_STAGE_TRANSITIONS[current]?.includes(next) ?? false;
}

export function isClientStatusTransitionAllowed(
  currentStatus: string,
  nextStatus: string,
): boolean {
  const current = normalizeClientStatusConstant(currentStatus);
  const next = normalizeClientStatusConstant(nextStatus);
  if (current === next) return true;
  return CLIENT_STATUS_TRANSITIONS[current]?.includes(next) ?? false;
}

function withSelectableOptions(
  currentValue: string,
  options: CustomSelectOption[],
  transitions: Record<string, string[]>,
  normalize: (value?: string | null) => string,
): CustomSelectOption[] {
  const current = normalize(currentValue);
  const allowedNext = transitions[current] ?? [];
  const allowed = new Set([current, ...allowedNext]);

  return options.map((option) => ({
    ...option,
    disabled: !allowed.has(normalize(option.value)),
  }));
}

export function getSelectableClientStageOptions(
  currentStage: string,
  options: CustomSelectOption[],
  mode: "create" | "edit" = "edit",
): CustomSelectOption[] {
  if (mode !== "edit") return options;
  return withSelectableOptions(
    currentStage,
    options,
    CLIENT_STAGE_TRANSITIONS,
    normalizeClientStageConstant,
  );
}

export function getSelectableClientStatusOptions(
  currentStatus: string,
  options: CustomSelectOption[],
  mode: "create" | "edit" = "edit",
): CustomSelectOption[] {
  if (mode !== "edit") return options;
  return withSelectableOptions(
    currentStatus,
    options,
    CLIENT_STATUS_TRANSITIONS,
    normalizeClientStatusConstant,
  );
}

