    const details = data?.details;
    if (
      typeof details === "object" &&
      details !== null &&
      "errors" in details &&
      typeof (details as { errors?: unknown }).errors === "object" &&
      (details as { errors?: Record<string, unknown> }).errors !== null
    ) {
      const fieldErrors = Object.values(
        (details as { errors: Record<string, unknown> }).errors,
      ).find((value) => typeof value === "string" && value.trim());
      if (typeof fieldErrors === "string") return fieldErrors;
