import type { AdminDashboardSession } from "@/store/api/admin/dashboard.api";

export type RecurrenceType = "weekly" | "monthly";
export type RecurrenceEndMode = "count" | "until";
export type SessionModeApi = "online" | "in-person";

export interface RecurrenceRuleRequest {
  clientId: number;
  therapistId: number;
  serviceId: number;
  roomId?: number;
  sessionMode: SessionModeApi;
  sessionType?: string;
  notes?: string;
  zoomEnabled?: boolean;
  startDate: string;
  sessionTime: string;
  recurrenceType: RecurrenceType;
  daysOfWeek?: number[];
  monthsOfYear?: number[];
  interval?: number;
  endMode: RecurrenceEndMode;
  count?: number;
  untilDate?: string;
}

export interface RecurrencePreviewSession {
  sessionDate: string;
  localDate: string;
  sessionTime: string;
  hasConflict: boolean;
  reasons: string[];
}

export interface RecurrencePreviewResponse {
  sessions: RecurrencePreviewSession[];
  totalRequested: number;
  freeCount: number;
  conflictCount: number;
}

export interface RecurrenceSkippedSession {
  sessionDate: string;
  localDate: string;
  sessionTime: string;
  reasons: string[];
}

export interface CreateRecurringSessionsResponse {
  groupId: string;
  created: AdminDashboardSession[];
  createdCount: number;
  skipped: RecurrenceSkippedSession[];
  skippedCount: number;
  warning?: string | null;
}

export interface UpdateRecurringFutureRequest {
  anchorId: number;
  sessionDate: string;
  roomId?: number;
  notes?: string;
  serviceId?: number;
  therapistId?: number;
  sessionType?: string;
  sessionMode?: SessionModeApi;
  zoomEnabled?: boolean;
  ignoreConflicts?: boolean;
}

export interface CancelRecurringSeriesResponse {
  groupId: string;
  cancelledCount: number;
}

export interface RecurrenceFormState {
  isRecurring: boolean;
  recurrenceType: RecurrenceType;
  daysOfWeek: number[];
  monthsOfYear: number[];
  interval: number;
  endMode: RecurrenceEndMode;
  count: number;
  untilDate: Date | null;
}

export const DEFAULT_RECURRENCE_FORM: RecurrenceFormState = {
  isRecurring: false,
  recurrenceType: "weekly",
  daysOfWeek: [],
  monthsOfYear: [],
  interval: 1,
  endMode: "count",
  count: 4,
  untilDate: null,
};

import { formatDateOnly } from "@/utils/transformer/dates.transformer";
import type {
  RecurrenceFormState,
  RecurrenceRuleRequest,
  RecurrenceType,
} from "@/types/recurringSessions";

export function isRecurringSeriesSession(
  recurrenceGroupId?: string | null,
): boolean {
  return Boolean(recurrenceGroupId?.trim().startsWith("rec-"));
}

export function timeSlotTo24Hour(time: string): string {
  const trimmed = time.trim();
  const match = trimmed.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)?$/i);
  if (!match) return trimmed;

  let hours = Number.parseInt(match[1], 10);
  const minutes = match[2];
  const suffix = match[3]?.toUpperCase();

  if (suffix === "AM" && hours === 12) hours = 0;
  if (suffix === "PM" && hours !== 12) hours += 12;

  return `${String(hours).padStart(2, "0")}:${minutes}`;
}

export function formatRecurrenceSummary(state: RecurrenceFormState): string {
  if (!state.isRecurring) return "One-time session";

  const intervalLabel = state.interval > 1 ? `every ${state.interval} ` : "every ";
  if (state.recurrenceType === "weekly") {
    const dayNames = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    const days = state.daysOfWeek.map((day) => dayNames[day]).join(", ");
    const end =
      state.endMode === "count"
        ? `${state.count} session${state.count === 1 ? "" : "s"}`
        : `until ${state.untilDate ? formatDateOnly(state.untilDate) : "—"}`;
    return `Weekly ${intervalLabel}week on ${days || "selected days"} · ${end}`;
  }

  const months =
    state.monthsOfYear.length > 0
      ? ` in months ${state.monthsOfYear.join(", ")}`
      : "";
  const end =
    state.endMode === "count"
      ? `${state.count} session${state.count === 1 ? "" : "s"}`
      : `until ${state.untilDate ? formatDateOnly(state.untilDate) : "—"}`;
  return `Monthly ${intervalLabel}month${months} · ${end}`;
}

export function buildRecurrenceRuleRequest(input: {
  clientId: number;
  therapistId: number;
  serviceId: number;
  roomId?: number;
  sessionMode: "virtual" | "in-person";
  sessionType?: string;
  notes?: string;
  startDate: Date;
  sessionTime12h: string;
  recurrence: RecurrenceFormState;
}): RecurrenceRuleRequest | null {
  if (!input.recurrence.isRecurring) return null;

  const body: RecurrenceRuleRequest = {
    clientId: input.clientId,
    therapistId: input.therapistId,
    serviceId: input.serviceId,
    sessionMode: input.sessionMode === "virtual" ? "online" : "in-person",
    sessionType: input.sessionType?.trim() || undefined,
    notes: input.notes?.trim() || undefined,
    zoomEnabled: input.sessionMode === "virtual",
    startDate: formatDateOnly(input.startDate),
    sessionTime: timeSlotTo24Hour(input.sessionTime12h),
    recurrenceType: input.recurrence.recurrenceType,
    interval: input.recurrence.interval,
    endMode: input.recurrence.endMode,
  };

  if (input.sessionMode === "in-person" && input.roomId) {
    body.roomId = input.roomId;
  }

  if (input.recurrence.recurrenceType === "weekly") {
    body.daysOfWeek = [...input.recurrence.daysOfWeek].sort((a, b) => a - b);
  } else if (input.recurrence.monthsOfYear.length > 0) {
    body.monthsOfYear = [...input.recurrence.monthsOfYear].sort((a, b) => a - b);
  }

  if (input.recurrence.endMode === "count") {
    body.count = input.recurrence.count;
  } else if (input.recurrence.untilDate) {
    body.untilDate = formatDateOnly(input.recurrence.untilDate);
  }

  return body;
}

export function canPreviewRecurrence(
  recurrence: RecurrenceFormState,
  startDate: Date | null,
  sessionTime: string,
): boolean {
  if (!recurrence.isRecurring || !startDate || !sessionTime.trim()) return false;
  if (recurrence.recurrenceType === "weekly" && recurrence.daysOfWeek.length === 0) {
    return false;
  }
  if (recurrence.endMode === "count" && (!recurrence.count || recurrence.count < 1)) {
    return false;
  }
  if (recurrence.endMode === "until" && !recurrence.untilDate) return false;
  return true;
}

export function getDefaultWeeklyDay(startDate: Date | null): number[] {
  if (!startDate) return [];
  return [startDate.getDay()];
}

export function toggleDayOfWeek(days: number[], day: number): number[] {
  return days.includes(day) ? days.filter((value) => value !== day) : [...days, day];
}

export function toggleMonthOfYear(months: number[], month: number): number[] {
  return months.includes(month)
    ? months.filter((value) => value !== month)
    : [...months, month];
}

export const WEEKDAY_OPTIONS = [
  { value: 0, label: "Sun" },
  { value: 1, label: "Mon" },
  { value: 2, label: "Tue" },
  { value: 3, label: "Wed" },
  { value: 4, label: "Thu" },
  { value: 5, label: "Fri" },
  { value: 6, label: "Sat" },
] as const;

export const MONTH_OPTIONS = Array.from({ length: 12 }, (_, index) => ({
  value: index + 1,
  label: new Date(2000, index, 1).toLocaleString("en-US", { month: "short" }),
}));

export function isValidRecurrenceType(value: string): value is RecurrenceType {
  return value === "weekly" || value === "monthly";
}

import { baseApi } from "../baseApi";
import type {
  CancelRecurringSeriesResponse,
  CreateRecurringSessionsResponse,
  RecurrencePreviewResponse,
  RecurrenceRuleRequest,
  UpdateRecurringFutureRequest,
} from "@/types/recurringSessions";
import {
  normalizeSession,
  type AdminDashboardSession,
} from "./dashboard.api";

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function asString(value: unknown): string {
  return typeof value === "string" ? value : "";
}

function asNumber(value: unknown): number {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && value.trim()) {
    const parsed = Number.parseInt(value, 10);
    return Number.isNaN(parsed) ? 0 : parsed;
  }
  return 0;
}

function normalizePreviewSession(entry: unknown) {
  if (!isRecord(entry)) return null;
  const reasons = Array.isArray(entry.reasons)
    ? entry.reasons.filter((item): item is string => typeof item === "string")
    : [];
  return {
    sessionDate: asString(entry.sessionDate),
    localDate: asString(entry.localDate),
    sessionTime: asString(entry.sessionTime),
    hasConflict: Boolean(entry.hasConflict),
    reasons,
  };
}

function normalizePreviewResponse(payload: unknown): RecurrencePreviewResponse {
  const root = isRecord(payload) ? payload : {};
  const sessions = Array.isArray(root.sessions)
    ? root.sessions.map(normalizePreviewSession).filter(Boolean)
    : [];

  return {
    sessions: sessions as RecurrencePreviewResponse["sessions"],
    totalRequested: asNumber(root.totalRequested),
    freeCount: asNumber(root.freeCount),
    conflictCount: asNumber(root.conflictCount),
  };
}

function normalizeSkippedSession(entry: unknown) {
  if (!isRecord(entry)) return null;
  const reasons = Array.isArray(entry.reasons)
    ? entry.reasons.filter((item): item is string => typeof item === "string")
    : [];
  return {
    sessionDate: asString(entry.sessionDate),
    localDate: asString(entry.localDate),
    sessionTime: asString(entry.sessionTime),
    reasons,
  };
}

function normalizeCreateRecurringResponse(
  payload: unknown,
): CreateRecurringSessionsResponse {
  const root = isRecord(payload) ? payload : {};
  const created = Array.isArray(root.created)
    ? root.created.map(normalizeSession).filter(Boolean)
    : [];
  const skipped = Array.isArray(root.skipped)
    ? root.skipped.map(normalizeSkippedSession).filter(Boolean)
    : [];

  return {
    groupId: asString(root.groupId),
    created: created as AdminDashboardSession[],
    createdCount: asNumber(root.createdCount) || created.length,
    skipped: skipped as CreateRecurringSessionsResponse["skipped"],
    skippedCount: asNumber(root.skippedCount) || skipped.length,
    warning: asString(root.warning) || null,
  };
}

export const adminRecurringSessionsApi = baseApi.injectEndpoints({
  endpoints: (builder) => ({
    previewRecurringSessions: builder.mutation<
      RecurrencePreviewResponse,
      RecurrenceRuleRequest
    >({
      query: (body) => ({
        url: "/api/v1/sessions/recurring/preview",
        method: "POST",
        body,
      }),
      transformResponse: (payload) => normalizePreviewResponse(payload),
    }),
    createRecurringSessions: builder.mutation<
      CreateRecurringSessionsResponse,
      RecurrenceRuleRequest
    >({
      query: (body) => ({
        url: "/api/v1/sessions/recurring",
        method: "POST",
        body,
      }),
      transformResponse: (payload) => normalizeCreateRecurringResponse(payload),
    }),
    updateRecurringFutureSessions: builder.mutation<
      AdminDashboardSession[],
      { groupId: string; body: UpdateRecurringFutureRequest }
    >({
      query: ({ groupId, body }) => ({
        url: `/api/v1/sessions/recurring/${groupId}/future`,
        method: "PUT",
        body,
      }),
      transformResponse: (payload) => {
        if (!Array.isArray(payload)) return [];
        return payload.map(normalizeSession).filter(Boolean) as AdminDashboardSession[];
      },
    }),
    cancelRecurringSeries: builder.mutation<
      CancelRecurringSeriesResponse,
      string
    >({
      query: (groupId) => ({
        url: `/api/v1/sessions/recurring/${groupId}`,
        method: "DELETE",
      }),
      transformResponse: (payload) => {
        const root = isRecord(payload) ? payload : {};
        return {
          groupId: asString(root.groupId),
          cancelledCount: asNumber(root.cancelledCount),
        };
      },
    }),
  }),
});

export const {
  usePreviewRecurringSessionsMutation,
  useCreateRecurringSessionsMutation,
  useUpdateRecurringFutureSessionsMutation,
  useCancelRecurringSeriesMutation,
} = adminRecurringSessionsApi;

import { Switch } from "@/components/ui/switch";
import CustomDatePicker from "@/components/form/CustomDatePicker";
import CustomInput from "@/components/form/CustomInput";
import type { RecurrenceFormState } from "@/types/recurringSessions";
import {
  MONTH_OPTIONS,
  WEEKDAY_OPTIONS,
  formatRecurrenceSummary,
  toggleDayOfWeek,
  toggleMonthOfYear,
} from "@/utils/recurringSessions";
import { cn } from "@/lib/utils";

interface RecurrenceFieldsProps {
  value: RecurrenceFormState;
  onChange: (next: RecurrenceFormState) => void;
  disabled?: boolean;
}

const RecurrenceFields = ({ value, onChange, disabled = false }: RecurrenceFieldsProps) => {
  const setField = <K extends keyof RecurrenceFormState>(
    key: K,
    fieldValue: RecurrenceFormState[K],
  ) => {
    onChange({ ...value, [key]: fieldValue });
  };

  return (
    <div className="space-y-4 rounded-2xl border border-(--neutral-100) bg-(--neutral-50) p-4">
      <div className="flex items-center justify-between gap-4">
        <div>
          <p className="text-sm font-semibold text-(--text-primary-dark)">
            Recurring appointment
          </p>
          <p className="text-xs text-(--text-neutral-600) mt-1">
            Schedule multiple sessions with one rule. Times use practice timezone (ET).
          </p>
        </div>
        <Switch
          checked={value.isRecurring}
          onCheckedChange={(checked) => setField("isRecurring", checked)}
          disabled={disabled}
        />
      </div>

      {value.isRecurring ? (
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-3">
            <label className="text-sm font-medium text-(--text-primary-dark)">
              Repeat
              <select
                value={value.recurrenceType}
                disabled={disabled}
                onChange={(event) =>
                  setField(
                    "recurrenceType",
                    event.target.value === "monthly" ? "monthly" : "weekly",
                  )
                }
                className="mt-1.5 h-12 w-full rounded-xl border border-(--neutral-200) bg-white px-3 text-sm text-(--text-primary-dark) outline-none focus:border-(--neutral-600)"
              >
                <option value="weekly">Weekly</option>
                <option value="monthly">Monthly</option>
              </select>
            </label>

            <label className="text-sm font-medium text-(--text-primary-dark)">
              Every
              <div className="mt-1.5 flex items-center gap-2">
                <input
                  type="number"
                  min={1}
                  max={8}
                  disabled={disabled}
                  value={value.interval}
                  onChange={(event) => {
                    const parsed = Number.parseInt(event.target.value, 10);
                    setField(
                      "interval",
                      Number.isFinite(parsed)
                        ? Math.min(8, Math.max(1, parsed))
                        : 1,
                    );
                  }}
                  className="h-12 w-20 rounded-xl border border-(--neutral-200) bg-white px-3 text-sm"
                />
                <span className="text-sm text-(--text-neutral-600)">
                  {value.recurrenceType === "weekly" ? "week(s)" : "month(s)"}
                </span>
              </div>
            </label>
          </div>

          {value.recurrenceType === "weekly" ? (
            <div>
              <p className="text-sm font-medium text-(--text-primary-dark) mb-2">
                Days of week
              </p>
              <div className="flex flex-wrap gap-2">
                {WEEKDAY_OPTIONS.map((day) => {
                  const selected = value.daysOfWeek.includes(day.value);
                  return (
                    <button
                      key={day.value}
                      type="button"
                      disabled={disabled}
                      onClick={() =>
                        setField("daysOfWeek", toggleDayOfWeek(value.daysOfWeek, day.value))
                      }
                      className={cn(
                        "h-9 min-w-12 rounded-full px-3 text-sm font-medium transition-colors",
                        selected
                          ? "bg-(--bg-primary-dark) text-white"
