              <CustomDatePicker
                label="Until date"
                date={value.untilDate}
                onDateChange={(date) => setField("untilDate", date)}
                disablePast
                disabled={disabled}
              />
            )}
          </div>

          <p className="text-xs text-(--text-neutral-600)">
            {formatRecurrenceSummary(value)}
          </p>
        </div>
      ) : null}
    </div>
  );
};

