/** Combine a calendar date + 12h AM/PM slot into a UTC ISO-8601 instant (same as single-session create). */
export function toSessionIsoDateTime(date: Date, time12h: string): string {
  const [clock, suffix] = time12h.trim().split(" ");
  const [hoursString, minutes = "00"] = clock.split(":");
  let hours = Number.parseInt(hoursString, 10);
  if (suffix === "AM" && hours === 12) hours = 0;
  if (suffix === "PM" && hours !== 12) hours += 12;

  return new Date(
    date.getFullYear(),
    date.getMonth(),
    date.getDate(),
    hours,
    Number.parseInt(minutes, 10),
    0,
    0,
  ).toISOString();
}

/** End-of-selected-day UTC instant for recurrence `untilDate` when sent as ISO. */
export function toUntilDateIsoDateTime(date: Date): string {
  return new Date(
    date.getFullYear(),
    date.getMonth(),
    date.getDate(),
    23,
    59,
    59,
    999,
  ).toISOString();
}

