import { X } from "lucide-react";

interface AssessmentHeaderProps {
    title: string;
    clientId: string;
    clientName: string;
    assessmentName: string;
    assignedDate: string;
    progress: number;
    totalQuestions: number;
    onClose: () => void;
}

const AssessmentHeader = ({
    title,
    clientId,
    clientName,
    assessmentName,
    assignedDate,
    progress,
    totalQuestions,
    onClose
}: AssessmentHeaderProps) => {
    const progressPercentage = totalQuestions > 0
        ? Math.round((progress / totalQuestions) * 100)
        : 0;

    return (
        <div className="sticky top-0 z-10 w-full min-w-0 overflow-hidden rounded-t-2xl border-b border-gray-100/50 bg-white px-8 pt-8 pb-4">
            <div className="mb-8 flex items-center justify-between">
                <h2 className="text-xl font-semibold text-gray-900">{title}</h2>
                <button
                    onClick={onClose}
                    className="shrink-0 rounded-full p-2 transition-colors hover:bg-gray-100 cursor-pointer"
                >
                    <X className="text-gray-500" size={20} />
                </button>
            </div>

            <div className="mb-6 grid min-w-0 grid-cols-1 gap-4 rounded-xl bg-gray-50/80 p-4 sm:grid-cols-2 lg:grid-cols-4">
                <div className="min-w-0">
                    <span className="mb-1 block text-xs text-gray-400">ID</span>
                    <span
                        className="block truncate text-sm font-medium text-gray-900"
                        title={clientId}
                    >
                        {clientId}
                    </span>
                </div>
                <div className="min-w-0">
                    <span className="mb-1 block text-xs text-gray-400">Client</span>
                    <span
                        className="block truncate text-sm font-medium text-gray-600"
                        title={clientName}
                    >
                        {clientName}
                    </span>
                </div>
                <div className="min-w-0">
                    <span className="mb-1 block text-xs text-gray-400">Assessment</span>
                    <span
                        className="block truncate text-sm font-medium text-gray-900"
                        title={assessmentName}
                    >
                        {assessmentName}
                    </span>
                </div>
                <div className="min-w-0">
                    <span className="mb-1 block text-xs text-gray-400">Assigned date</span>
                    <span
                        className="block truncate text-sm font-medium text-gray-900"
                        title={assignedDate}
                    >
                        {assignedDate}
                    </span>
                </div>
            </div>

            <div className="space-y-2">
                <div className="text-sm font-medium text-gray-400">
                    Progress: <span className="text-gray-900">{progress}/{totalQuestions} Questions</span>
                </div>
                <div className="h-1 w-full overflow-hidden rounded-full bg-gray-100">
                    <div
                        className="h-full rounded-full bg-slate-800 transition-all duration-300"
                        style={{ width: `${progressPercentage}%` }}
                    />
                </div>
            </div>
        </div>
    );
};

export default AssessmentHeader;

