export const TIMELINE_HOUR_HEIGHT_PX = 48;
export const TIMELINE_MIN_SESSION_HEIGHT_PX = 20;
export const TIMELINE_SHORT_SESSION_HOURS = 0.5;

export const getTimelineSessionTop = (startHour: number): number =>
  (startHour + 1) * TIMELINE_HOUR_HEIGHT_PX;

export const getTimelineSessionHeight = (durationHours: number): number =>
  Math.max(durationHours * TIMELINE_HOUR_HEIGHT_PX, TIMELINE_MIN_SESSION_HEIGHT_PX);

export const isShortTimelineSession = (durationHours: number): boolean =>
  durationHours < TIMELINE_SHORT_SESSION_HOURS;

