import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import {
  loginSchema,
  type LoginFormValues,
} from "../../../schemas/login.schema";
import { NavLink, useNavigate } from "react-router-dom";
import { ArrowUpRight } from "lucide-react";
import { AUTH_STATIC_CONTENT } from "../auth.static";
import { getRedirectPathByRole } from "../../../utils/redirectPathByRole";
import AuthLayoutWrapper from "@/components/auth/AuthLayoutWrapper";
import AuthLoginForm from "@/components/auth/AuthLoginForm";
import { usePortalLoginMutation } from "@/store/api/portalAuthApi";
import { setAuthSession } from "@/utils/authStorage";
import { useAppDispatch } from "@/store/hooks";
import { setSession } from "@/store/authSlice";
import { getApiErrorMessage } from "@/utils/apiError";

const Login = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const [portalLogin, { isLoading, isError, error }] = usePortalLoginMutation();
  const form = useForm<LoginFormValues>({
    resolver: zodResolver(loginSchema),
    defaultValues: {
      email: "",
      password: "",
    },
  });

  const onSubmit = async (values: LoginFormValues) => {
    if (!values.email || !values.password) {
      return;
    }

    try {
      const response = await portalLogin({
        email: values.email.trim(),
        password: values.password,
      }).unwrap();

      const session = {
        accessToken: response.accessToken,
        refreshToken: response.refreshToken,
        role: "user" as const,
        client: response.client,
      };

      setAuthSession(session);
      dispatch(setSession(session));
      navigate(getRedirectPathByRole("user"), { replace: true });
    } catch (loginError) {
      console.error("Client portal login failed:", loginError);
    }
  };

  const bottomContent = (
    <>
      <p className="text-(--text-neutral-600) text-[14px] leading-5.5 text-center font-normal mt-2">
        Staff member?
      </p>
      <NavLink
        to="/auth/staff/login"
        className="text-[14px] text-(--text-primary-500) font-semibold leading-5.5 mt-2 flex justify-center gap-2"
      >
        Access Staff Portal
        <ArrowUpRight size={20} />
      </NavLink>
    </>
  );

  return (
    <AuthLayoutWrapper
      title={AUTH_STATIC_CONTENT?.loginTitle}
      bottomContent={bottomContent}
      showRightBar={true}
    >
      <AuthLoginForm
        form={form}
        onSubmit={onSubmit}
        forgotPasswordPath="/auth/forgot-password"
        submitLabel={isLoading ? "Signing In..." : "Sign In"}
        errorMessage={isError ? getApiErrorMessage(error) : undefined}
      />
      <div className="mt-4 text-(--text-neutral-600) text-[14px] leading-5.5 text-center font-normal">
        {AUTH_STATIC_CONTENT?.newClientGuide}
      </div>
    </AuthLayoutWrapper>
  );
};

export default Login;

import { useForm } from "react-hook-form";
