import { getRedirectPathByRole } from "@/utils/redirectPathByRole";

const ClientActivateAccount = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const dispatch = useAppDispatch();
  const [activateAccount, { isLoading, isError, error }] =
    usePortalActivateMutation();
  const form = useForm<SetNewPasswordFormValues>({
    resolver: zodResolver(setNewPasswordSchema),
    defaultValues: {
      password: "",
      confirmPassword: "",
    },
  });

  const onSubmit = async (values: SetNewPasswordFormValues) => {
    const params = new URLSearchParams(location.search);
    const token = params.get("token") || "";

    if (!token) {
      console.error("No activation token found in URL");
      return;
    }

    try {
      const response = await activateAccount({
        token,
        password: values.password,
      }).unwrap();

      const session = {
        accessToken: response.accessToken,
        refreshToken: response.refreshToken,
        role: "user" as const,
        client: response.client,
      };

      setAuthSession(session);
      dispatch(setSession(session));
      navigate(getRedirectPathByRole("user"), { replace: true });
    } catch (activateError) {
      console.error("Client portal activation failed:", activateError);
    }
  };

  return (
    <div className="bg-white max-w-134.75 max-h-auto w-full h-full shadow-xs shadow-(--shadow) rounded-xl border-none">
      <div className="md:px-12 md:py-16 px-4 py-8 flex flex-col items-center justify-between gap-8 mb-8 md:mb-0">
        <div className="w-full flex flex-col">
          <h2 className="md:text-2xl text-xl font-semibold text-center text-(--text-primary-dark) mb-2">
            Activate Your Account
          </h2>

          <p className="text-(--text-neutral-600) text-center text-sm leading-6 mb-6">
            Set a secure password to activate your client portal access
          </p>

          <TherapistSetNewPasswordForm
            form={form}
            onSubmit={onSubmit}
            buttonText={isLoading ? "Activating..." : "Activate Account"}
            errorMessage={isError ? getApiErrorMessage(error) : undefined}
          />
        </div>
      </div>
    </div>
  );
};

export default ClientActivateAccount;

