import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import {
  loginSchema,
  type LoginFormValues,
} from "../../../schemas/login.schema";
import { useState } from "react";
import { NavLink, useNavigate } from "react-router-dom";
import { ArrowUpRight } from "lucide-react";
import { AUTH_STATIC_CONTENT } from "../auth.static";
import { getRedirectPathByRole } from "../../../utils/redirectPathByRole";
import AuthLayoutWrapper from "@/components/auth/AuthLayoutWrapper";
import AuthLoginForm from "@/components/auth/AuthLoginForm";
import { usePortalLoginMutation } from "@/store/api/portalAuthApi";
import {
  useResolveTenantMutation,
  type ResolveTenantOrganisation,
} from "@/store/api/authApi";
import { setAuthSession } from "@/utils/authStorage";
import { useAppDispatch } from "@/store/hooks";
import { setSession } from "@/store/authSlice";
import { getApiErrorMessage } from "@/utils/apiError";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

const Login = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const [resolveTenant, { isLoading: isResolving, isError: isResolveError, error: resolveError }] =
    useResolveTenantMutation();
  const [portalLogin, { isLoading: isPortalLoginLoading, isError: isPortalLoginError, error: portalLoginError }] =
    usePortalLoginMutation();
  const [tenantOptions, setTenantOptions] = useState<ResolveTenantOrganisation[]>([]);
  const [pendingCredentials, setPendingCredentials] = useState<{
    email: string;
    password: string;
  } | null>(null);
  const [isTenantModalOpen, setIsTenantModalOpen] = useState(false);
  const form = useForm<LoginFormValues>({
    resolver: zodResolver(loginSchema),
    defaultValues: {
      email: "",
      password: "",
    },
  });

  const onSubmit = async (values: LoginFormValues) => {
    if (!values.email || !values.password) {
      return;
    }

    const email = values.email.trim();

    try {
      const resolved = await resolveTenant({ email }).unwrap();
      const organisations = resolved.organisations ?? [];
      const credentials = { email, password: values.password };
      setPendingCredentials(credentials);
      setTenantOptions(organisations);

      if (organisations.length === 1) {
        await handleTenantSelect(organisations[0], credentials);
        return;
      }

      setIsTenantModalOpen(true);
    } catch (loginError) {
      console.error("Client portal login failed:", loginError);
    }
  };

  async function handleTenantSelect(
    organisation: ResolveTenantOrganisation,
    credentials?: { email: string; password: string },
  ) {
    const resolvedCredentials = credentials ?? pendingCredentials;
    if (!resolvedCredentials) {
      return;
    }

    try {
      const response = await portalLogin({
        email: resolvedCredentials.email,
        password: resolvedCredentials.password,
        orgSlug: organisation.slug || undefined,
        orgId: organisation.organisationId
          ? String(organisation.organisationId)
          : undefined,
      }).unwrap();

      const session = {
        accessToken: response.accessToken,
        refreshToken: response.refreshToken,
        role: "user" as const,
        tenantSubdomain: organisation.subdomain || undefined,
        tenantSlug: organisation.slug || undefined,
        client: response.client,
      };

      setAuthSession(session);
      dispatch(setSession(session));
      setIsTenantModalOpen(false);
      navigate(getRedirectPathByRole("user"), { replace: true });
    } catch (loginError) {
      console.error("Client portal login failed:", loginError);
    }
  }

  const bottomContent = (
    <>
      <p className="text-(--text-neutral-600) text-[14px] leading-5.5 text-center font-normal mt-2">
        Staff member?
      </p>
      <NavLink
        to="/auth/staff/login"
        className="text-[14px] text-(--text-primary-500) font-semibold leading-5.5 mt-2 flex justify-center gap-2"
      >
        Access Staff Portal
        <ArrowUpRight size={20} />
      </NavLink>
    </>
  );

  return (
    <AuthLayoutWrapper
      title={AUTH_STATIC_CONTENT?.loginTitle}
      bottomContent={bottomContent}
      showRightBar={true}
    >
      <AuthLoginForm
        form={form}
        onSubmit={onSubmit}
        forgotPasswordPath="/auth/forgot-password"
        submitLabel={
          isResolving
            ? "Resolving..."
            : isPortalLoginLoading
              ? "Signing In..."
              : "Sign In"
        }
        errorMessage={
          isResolveError
            ? getApiErrorMessage(resolveError)
            : isPortalLoginError
              ? getApiErrorMessage(portalLoginError)
              : undefined
        }
      />
      <div className="mt-4 text-(--text-neutral-600) text-[14px] leading-5.5 text-center font-normal">
        {AUTH_STATIC_CONTENT?.newClientGuide}
      </div>

      {isTenantModalOpen ? (
        <div className="fixed inset-0 z-50">
          <button
            type="button"
            className="absolute inset-0 bg-black/30"
            aria-label="Close tenant selector"
            onClick={() => setIsTenantModalOpen(false)}
          />
          <div className="absolute left-1/2 top-1/2 w-full max-w-[520px] -translate-x-1/2 -translate-y-1/2 rounded-[16px] border border-[#e3ebf3] bg-white p-6 shadow-[0_20px_40px_rgba(15,23,42,0.2)]">
            <div className="text-[18px] font-semibold text-[#1f2d38]">
              Select Organization
            </div>
            <p className="mt-1 text-[13px] text-[#6b7a88]">
              Choose the organization for your client portal access.
            </p>

            <div className="mt-4 flex flex-col gap-3">
              {tenantOptions.length === 0 ? (
                <div className="text-sm text-[#8a96a3]">
                  No organizations found for this email.
                </div>
              ) : null}

              {tenantOptions.map((org) => (
                <button
                  key={org.organisationId}
                  type="button"
                  onClick={() => void handleTenantSelect(org)}
                  className={cn(
                    "flex items-center justify-between rounded-[12px] border border-[#e4ecf3] px-4 py-3 text-left transition",
                    "hover:border-[#c9d6e3] hover:bg-[#f7fafc]",
                  )}
                >
                  <div>
                    <div className="text-[14px] font-semibold text-[#1f2d38]">
                      {org.name}
                    </div>
                    <div className="text-[12px] text-[#6b7a88]">
                      {org.subdomain}
                    </div>
                  </div>
                  <Button variant="outline" className="h-9 rounded-full px-4 text-[12px]">
                    Continue
                  </Button>
                </button>
              ))}
            </div>

            <div className="mt-5 flex justify-end">
              <Button
                variant="outline"
                className="h-9 rounded-full px-4 text-[12px]"
                onClick={() => setIsTenantModalOpen(false)}
              >
                Cancel
              </Button>
            </div>
          </div>
        </div>
      ) : null}
    </AuthLayoutWrapper>
  );
};

export default Login;

