import { useEffect, useMemo, useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { ArrowLeft, Loader2 } from "lucide-react";
import { useNavigate } from "react-router-dom";
import CustomSelect from "@/components/form/CustomSelect";
import CustomInput from "@/components/form/CustomInput";
import { Button } from "@/components/ui/button";
import { Form } from "@/components/ui/form";
import Toast from "@/components/shared/Toast";
import {
  useGetPortalMeQuery,
  useGetPortalTimezoneQuery,
  useUpdatePortalTimezoneMutation,
} from "@/store/api/portalApi";
import { useGetMyTimezonesQuery } from "@/store/api/userProfile.api";
import { getApiErrorMessage } from "@/utils/apiError";
import { TIME_ZONE_OPTIONS } from "@/utils/functions/timezone";

const clientProfileSchema = z.object({
  timezone: z.string().min(1, "Timezone is required"),
});

type ClientProfileFormValues = z.infer<typeof clientProfileSchema>;

const ClientMyProfile = () => {
  const navigate = useNavigate();
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const [toastType, setToastType] = useState<"success" | "error">("success");
  const { data: profile, isLoading: isProfileLoading } = useGetPortalMeQuery();
  const { data: timezoneData, isLoading: isTimezoneLoading } =
    useGetPortalTimezoneQuery();
  const { data: timezoneOptionsResponse, isLoading: isTimezoneOptionsLoading } =
    useGetMyTimezonesQuery();
  const [updateTimezone, { isLoading: isSaving }] =
    useUpdatePortalTimezoneMutation();

  const form = useForm<ClientProfileFormValues>({
    resolver: zodResolver(clientProfileSchema),
    defaultValues: {
      timezone: "",
    },
  });

  const timezoneOptions = useMemo(() => {
    const apiTimezones = timezoneOptionsResponse?.timezones ?? [];
    if (apiTimezones.length > 0) {
      return apiTimezones.map((timezone) => ({
        label: timezone,
        value: timezone,
      }));
    }

    return TIME_ZONE_OPTIONS.map((option) => ({
      label: option.label,
      value: option.value,
    }));
  }, [timezoneOptionsResponse?.timezones]);

  useEffect(() => {
    const resolvedTimezone =
      timezoneData?.timezone || profile?.timezone || "";
    if (resolvedTimezone) {
      form.reset({ timezone: resolvedTimezone });
    }
  }, [form, profile?.timezone, timezoneData?.timezone]);

  const onSubmit = async (values: ClientProfileFormValues) => {
    try {
      setToastMessage(null);
      await updateTimezone({ timezone: values.timezone }).unwrap();
      setToastType("success");
      setToastMessage("Profile updated successfully.");
    } catch (error) {
      setToastType("error");
      setToastMessage(getApiErrorMessage(error));
    }
  };

  const isLoading = isProfileLoading || isTimezoneLoading || isTimezoneOptionsLoading;

  return (
    <div className="mx-auto w-full max-w-3xl space-y-6">
      <button
        type="button"
        onClick={() => navigate(-1)}
        className="mb-2 flex cursor-pointer items-center gap-2 text-(--text-neutral-600) transition-colors hover:text-(--text-primary-dark)"
      >
        <ArrowLeft size={20} />
        <span className="text-sm font-medium">Back</span>
      </button>

      <div className="rounded-xl bg-white p-6 shadow-xs md:p-8">
        <div className="mb-6">
          <h1 className="text-xl font-semibold text-(--text-primary-dark) md:text-2xl">
            My Profile
          </h1>
          <p className="mt-1 text-sm text-(--text-neutral-600)">
            View your account details and set your timezone for appointments.
          </p>
        </div>

        {isLoading ? (
          <div className="flex items-center justify-center gap-2 py-16">
            <Loader2 className="h-5 w-5 animate-spin text-(--bg-primary-dark)" />
            <span className="text-sm text-(--text-neutral-600)">
              Loading profile...
            </span>
          </div>
        ) : (
          <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-5">
              <CustomInput
                label="Full Name"
                value={profile?.fullName || "-"}
                disabled
              />
              <CustomInput
                label="Client ID"
                value={profile?.clientId || "-"}
                disabled
              />
              <CustomInput
                label="Email"
                value={profile?.email || "-"}
                disabled
              />
              <CustomInput
                label="Phone"
                value={profile?.phone || "-"}
                disabled
              />
              <CustomSelect
                control={form.control}
                name="timezone"
                label="Timezone"
                options={timezoneOptions}
                required
                isSearch
                placeholder="Search timezone..."
              />

              <div className="flex justify-end pt-2">
                <Button
                  type="submit"
                  disabled={isSaving}
                  className="h-11.5 rounded-full bg-(--bg-primary-dark) px-8 text-white"
                >
                  {isSaving ? "Saving..." : "Save changes"}
                </Button>
              </div>
            </form>
          </Form>
        )}
      </div>

      {toastMessage ? (
        <Toast
          message={toastMessage}
          type={toastType}
          onClose={() => setToastMessage(null)}
        />
      ) : null}
    </div>
  );
};

export default ClientMyProfile;

