import { DateTime } from "luxon";

const FALLBACK_TIMEZONE = "UTC";

export function getBrowserTimezone(): string {
  if (typeof Intl === "undefined" || typeof Intl.DateTimeFormat !== "function") {
    return FALLBACK_TIMEZONE;
  }

  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || FALLBACK_TIMEZONE;
  } catch {
    return FALLBACK_TIMEZONE;
  }
}

export function isValidIanaTimezone(timezone: string): boolean {
  const trimmed = timezone.trim();
  if (!trimmed) return false;

  return DateTime.now().setZone(trimmed).isValid;
}

/**
 * Returns a browser-detected IANA timezone safe to send to the API,
 * or null when detection is unavailable.
 */
export function getSafeBrowserTimezone(): string | null {
  const browserTimezone = getBrowserTimezone().trim();
  if (!browserTimezone) return null;

  if (!isValidIanaTimezone(browserTimezone)) {
    return isValidIanaTimezone(FALLBACK_TIMEZONE) ? FALLBACK_TIMEZONE : null;
  }

  return browserTimezone;
}

export function hasPortalTimezone(
  timezone: string | null | undefined,
): boolean {
  if (timezone === null || timezone === undefined) return false;

  const trimmed = timezone.trim();
  return trimmed.length > 0 && trimmed.toLowerCase() !== "null";
}

import { useEffect, useRef } from "react";
import { useAppSelector } from "@/store/hooks";
import {
  useGetPortalMeQuery,
  useUpdatePortalTimezoneMutation,
} from "@/store/api/portalApi";
import {
  getSafeBrowserTimezone,
  hasPortalTimezone,
} from "@/utils/browserTimezone";

/**
 * On first portal login, if GET /portal/me has no timezone, detect the
 * browser timezone and persist it via PUT /portal/me/timezone.
 * Failures are silent and non-blocking.
 */
export function usePortalTimezoneBootstrap(): void {
  const accessToken = useAppSelector((state) => state.auth.accessToken);
  const authRole = useAppSelector((state) => state.auth.role);
  const isPortalClient = Boolean(accessToken) && authRole === "user";

  const { data: profile, isLoading, isFetching, isError } =
    useGetPortalMeQuery(undefined, {
      skip: !isPortalClient,
    });
  const [updateTimezone] = useUpdatePortalTimezoneMutation();
  const syncAttemptedRef = useRef(false);

  useEffect(() => {
    if (!isPortalClient) return;
    if (isLoading || isFetching) return;
    if (isError || !profile) return;
    if (hasPortalTimezone(profile.timezone)) return;
    if (syncAttemptedRef.current) return;

    const browserTimezone = getSafeBrowserTimezone();
    if (!browserTimezone) return;

    syncAttemptedRef.current = true;

    void updateTimezone({ timezone: browserTimezone }).unwrap().catch(() => {
      // Keep attempted=true for this mount to avoid retry loops on failure.
      // A full page reload will try again once.
    });
  }, [
    isPortalClient,
    isError,
    isFetching,
    isLoading,
    profile,
    updateTimezone,
  ]);
}

