import type { PortalInvoice } from "@/store/api/portalApi";
import type { Invoice, InvoiceOverview, InvoiceStatus } from "@/types/invoice.type";

function formatCurrency(amount: number): string {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  }).format(amount);
}

function formatInvoiceDate(value: string | null | undefined): string {
  if (!value) return "-";

  const dateOnlyMatch = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value.trim());
  const parsed = dateOnlyMatch
    ? new Date(
        Number.parseInt(dateOnlyMatch[1], 10),
        Number.parseInt(dateOnlyMatch[2], 10) - 1,
        Number.parseInt(dateOnlyMatch[3], 10),
      )
    : new Date(value);

  if (Number.isNaN(parsed.getTime())) {
    return value;
  }

  return parsed.toLocaleDateString("en-US", {
    month: "short",
    day: "2-digit",
    year: "numeric",
  });
}

function formatPaidDate(value: string | null | undefined): string | undefined {
  if (!value) return undefined;
  const formatted = formatInvoiceDate(value);
  return formatted === "-" ? undefined : formatted;
}

function normalizeBillingStatus(
  invoice: PortalInvoice,
): string {
  const paymentStatus = (invoice.paymentStatus || "").trim().toLowerCase();
  if (paymentStatus) return paymentStatus;

  const billingStatus = (invoice.billingStatus || "").trim().toLowerCase();
  if (billingStatus) return billingStatus;

  const totalAmount = invoice.totalAmount ?? 0;
  const paymentAmount = invoice.paymentAmount ?? 0;

  if (totalAmount > 0 && paymentAmount >= totalAmount) {
    return "paid";
  }

  if (paymentAmount > 0) {
    return "billed";
  }

  return "pending";
}

export function resolvePortalInvoiceStatus(invoice: PortalInvoice): InvoiceStatus {
  const status = normalizeBillingStatus(invoice);

  if (status === "paid") return "paid";
  if (status === "denied") return "denied";
  if (status === "follow_up" || status === "follow-up") return "follow_up";
  if (status === "refunded") return "refunded";
  if (status === "billed" || status === "pending" || status === "unpaid") {
    return "pending";
  }
  if (status === "cancelled" || status === "canceled") return "denied";

  return "pending";
}

export function canPayPortalInvoice(invoice: PortalInvoice): boolean {
  const status = resolvePortalInvoiceStatus(invoice);
  return status !== "paid" && status !== "denied" && status !== "refunded";
}

export function getPortalInvoiceStatusLabel(status: InvoiceStatus): string {
  switch (status) {
    case "paid":
      return "Paid";
    case "denied":
      return "Denied";
    case "follow_up":
      return "Follow-up";
    case "refunded":
      return "Refunded";
    case "billed":
      return "Billed";
    case "pending":
    default:
      return "Pending";
  }
}

export function getPortalInvoiceStatusStyles(status: InvoiceStatus): string {
  switch (status) {
    case "paid":
      return "bg-[#EBFEF4] text-[#007C54] border-[#EBFEF4]";
    case "denied":
      return "bg-[#FEF2F2] text-[#EF4444] border-[#FEF2F2]";
    case "follow_up":
      return "bg-[#FFF7ED] text-[#FBAC00] border-[#FFF7ED]";
    case "refunded":
      return "bg-[#EDEEF1] text-(--text-neutral-600) border-[#EDEEF1]";
    case "billed":
    case "pending":
    default:
      return "bg-[#EDEEF1] text-(--text-neutral-600) border-[#EDEEF1]";
  }
}

export function formatInsuranceLabel(insuranceCovered: boolean): string {
  return insuranceCovered ? "Covered" : "Self-pay";
}

export function formatCopayLabel(
  copayAmount: number | null | undefined,
): string {
  if (copayAmount === null || copayAmount === undefined) {
    return "--";
  }

  return formatCurrency(copayAmount);
}

export interface ClientInvoiceRow extends Invoice {
  canPay: boolean;
  serviceCode?: string;
  billingDateRaw: string;
}

export function mapPortalInvoiceToRow(invoice: PortalInvoice): ClientInvoiceRow {
  const status = resolvePortalInvoiceStatus(invoice);

  return {
    id: String(invoice.id),
    date: formatInvoiceDate(invoice.billingDate || invoice.sessionDate),
    service: invoice.serviceName || "Session",
    amount: formatCurrency(invoice.totalAmount ?? 0),
    insurance: formatInsuranceLabel(Boolean(invoice.insuranceCovered)),
    copay: formatCopayLabel(invoice.copayAmount),
    status,
    paidDate: formatPaidDate(invoice.paymentDate),
    paymentMethod: undefined,
    canPay: canPayPortalInvoice(invoice),
    serviceCode: invoice.serviceCode || undefined,
    billingDateRaw: invoice.billingDate || invoice.sessionDate || "",
  };
}

export function buildPortalInvoiceOverview(
  invoices: PortalInvoice[],
): InvoiceOverview {
  const totalBilled = invoices.reduce(
    (sum, invoice) => sum + (invoice.totalAmount ?? 0),
    0,
  );
  const totalPaid = invoices.reduce((sum, invoice) => {
    const status = resolvePortalInvoiceStatus(invoice);
    if (status !== "paid") {
      return sum;
    }

    return sum + (invoice.paymentAmount ?? invoice.totalAmount ?? 0);
  }, 0);

  return {
    totalInvoices: invoices.length,
    totalBilled: formatCurrency(totalBilled),
    totalPaid: formatCurrency(totalPaid),
  };
}

export function sortPortalInvoicesNewestFirst(
  invoices: PortalInvoice[],
): PortalInvoice[] {
  return [...invoices].sort((left, right) => {
    const leftDate = new Date(left.billingDate || left.sessionDate || left.createdAt);
    const rightDate = new Date(right.billingDate || right.sessionDate || right.createdAt);
    return rightDate.getTime() - leftDate.getTime();
  });
}

import type { PortalInvoice } from "@/store/api/portalApi";
import { resolvePortalInvoiceStatus } from "@/utils/portalInvoiceDisplay";

export interface ClientInvoiceFilters {
  startDate: Date | null;
  endDate: Date | null;
  status: string | null;
  insuranceCovered: string | null;
}

export const DEFAULT_CLIENT_INVOICE_FILTERS: ClientInvoiceFilters = {
  startDate: null,
  endDate: null,
  status: null,
  insuranceCovered: null,
};

export const CLIENT_INVOICE_STATUS_OPTIONS = [
  { value: "", label: "All Statuses" },
  { value: "pending", label: "Pending" },
  { value: "paid", label: "Paid" },
  { value: "denied", label: "Denied" },
  { value: "follow_up", label: "Follow-up" },
  { value: "refunded", label: "Refunded" },
];

export const CLIENT_INVOICE_INSURANCE_OPTIONS = [
  { value: "", label: "All Coverage" },
  { value: "covered", label: "Insurance covered" },
  { value: "self_pay", label: "Self-pay" },
];

function parseInvoiceDate(value: string | null | undefined): Date | null {
  if (!value) return null;

  const dateOnlyMatch = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value.trim());
  const parsed = dateOnlyMatch
    ? new Date(
        Number.parseInt(dateOnlyMatch[1], 10),
        Number.parseInt(dateOnlyMatch[2], 10) - 1,
        Number.parseInt(dateOnlyMatch[3], 10),
      )
    : new Date(value);

  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

export function hasActiveClientInvoiceFilters(
  filters: ClientInvoiceFilters,
): boolean {
  return Boolean(
    filters.startDate ||
      filters.endDate ||
      filters.status ||
      filters.insuranceCovered,
  );
}

export function applyClientInvoiceFilters(
  invoices: PortalInvoice[],
  filters: ClientInvoiceFilters,
): PortalInvoice[] {
  return invoices.filter((invoice) => {
    if (filters.status) {
      const invoiceStatus = resolvePortalInvoiceStatus(invoice);
      if (invoiceStatus !== filters.status) {
        return false;
      }
    }

    if (filters.insuranceCovered === "covered" && !invoice.insuranceCovered) {
      return false;
    }

    if (filters.insuranceCovered === "self_pay" && invoice.insuranceCovered) {
      return false;
    }

    if (filters.startDate || filters.endDate) {
      const invoiceDate = parseInvoiceDate(
        invoice.billingDate || invoice.sessionDate,
      );
      if (!invoiceDate) {
        return false;
      }

      if (filters.startDate) {
        const start = new Date(filters.startDate);
        start.setHours(0, 0, 0, 0);
        if (invoiceDate < start) {
          return false;
        }
      }

      if (filters.endDate) {
        const end = new Date(filters.endDate);
        end.setHours(23, 59, 59, 999);
        if (invoiceDate > end) {
          return false;
        }
      }
    }

    return true;
  });
}

export function filterPortalInvoicesBySearch(
  invoices: PortalInvoice[],
  searchQuery: string,
): PortalInvoice[] {
  const needle = searchQuery.trim().toLowerCase();
  if (!needle) return invoices;

  return invoices.filter((invoice) => {
    const status = resolvePortalInvoiceStatus(invoice);
    const values = [
      invoice.serviceName,
      invoice.serviceCode,
      invoice.billingDate,
      invoice.sessionDate,
      String(invoice.totalAmount ?? ""),
      String(invoice.paymentAmount ?? ""),
      status,
      invoice.insuranceCovered ? "covered" : "self-pay",
    ];

    return values.some((value) =>
      String(value ?? "")
        .toLowerCase()
        .includes(needle),
    );
  });
}

