import { useCallback, useState } from "react";
import { Loader, Loader2 } from "lucide-react";
import { Button } from "../ui/button";
import { Badge } from "../ui/badge";
import { Search } from "lucide-react";
import InvoiceTableComponent, {
  type InvoiceTableColumn,
} from "../shared/InvoiceTable";
import CustomInput from "../form/CustomInput";
import ClientInvoicesFilterPanel from "./ClientInvoicesFilterPanel";
import { useInfiniteScroll } from "@/hooks/useInfiniteScroll";
import type { ClientInvoiceRow } from "@/utils/portalInvoiceDisplay";
import {
  getPortalInvoiceStatusLabel,
  getPortalInvoiceStatusStyles,
} from "@/utils/portalInvoiceDisplay";
import type { ClientInvoiceFilters } from "@/utils/clientInvoiceFilters";

interface InvoiceTableProps {
  invoices: ClientInvoiceRow[];
  isLoading?: boolean;
  searchQuery: string;
  onSearchChange: (value: string) => void;
  filters: ClientInvoiceFilters;
  setFilters: (filters: ClientInvoiceFilters) => void;
  payingInvoiceId: string | null;
  onPayNow: (invoiceId: string) => void;
}

const InvoiceTable = ({
  invoices,
  isLoading = false,
  searchQuery,
  onSearchChange,
  filters,
  setFilters,
  payingInvoiceId,
  onPayNow,
}: InvoiceTableProps) => {
  const [displayedItems, setDisplayedItems] = useState(20);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const itemsPerPage = 20;

  const handleLoadMore = useCallback(() => {
    setIsLoadingMore(true);
    setDisplayedItems((prev) => prev + itemsPerPage);
    setIsLoadingMore(false);
  }, []);

  const { observerTarget } = useInfiniteScroll({
    onLoadMore: handleLoadMore,
    hasMore: displayedItems < invoices.length,
    isLoading: isLoadingMore,
  });

  const currentInvoices = invoices.slice(0, displayedItems);

  const columns: InvoiceTableColumn<ClientInvoiceRow>[] = [
    {
      key: "date",
      label: "Date",
      width: "130px",
      padding: "20px 12px",
      headerPadding: "12px",
    },
    {
      key: "service",
      label: "Service",
      width: "340px",
      padding: "16px 8px",
      headerPadding: "12px",
      render: (_, invoice) => (
        <div className="flex min-w-0 flex-col gap-1.5">
          <span className="truncate" title={invoice.service}>
            {invoice.service}
          </span>
          {invoice.serviceCode ? (
            <span className="text-xs text-(--text-neutral-600)">
              {invoice.serviceCode}
            </span>
          ) : null}
        </div>
      ),
    },
    {
      key: "amount",
      label: "Amount",
      width: "100px",
      padding: "20px 8px",
      className: "font-medium",
    },
    {
      key: "insurance",
      label: "Insurance",
      width: "120px",
      padding: "20px 8px",
      render: (value) => (
        <Badge
          variant="outline"
          className="w-fit border-[#EDEEF1] bg-[#EDEEF1] text-xs font-normal text-(--text-neutral-600)"
        >
          {value}
        </Badge>
      ),
    },
    {
      key: "copay",
      label: "Copay",
      width: "110px",
      padding: "20px 8px",
    },
    {
      key: "status",
      label: "Status",
      width: "170px",
      padding: "20px 8px",
      render: (_, invoice) => (
        <div className="flex flex-col gap-1">
          <Badge
            variant="outline"
            className={`w-fit text-xs font-normal ${getPortalInvoiceStatusStyles(invoice.status)}`}
          >
            {getPortalInvoiceStatusLabel(invoice.status)}
          </Badge>
          {invoice.status === "paid" && invoice.paidDate ? (
            <span className="text-xs text-(--text-neutral-600)">
              {invoice.paidDate}
            </span>
          ) : null}
        </div>
      ),
    },
    {
      key: "actions",
      label: "Actions",
      width: "162px",
      padding: "20px 8px",
      render: (_, invoice) =>
        invoice.canPay ? (
          <Button
            type="button"
            className="h-9 min-w-27.75 cursor-pointer rounded-full px-4 text-[14px] font-semibold"
            disabled={payingInvoiceId === invoice.id}
            onClick={() => onPayNow(invoice.id)}
          >
            {payingInvoiceId === invoice.id ? (
              <>
                <Loader2 className="h-4 w-4 animate-spin" />
                Processing...
              </>
            ) : (
              <>
                <img
                  src="/invoice/receipt.svg"
                  alt=""
                  className="h-5 w-5"
                  aria-hidden="true"
                />
                Pay now
              </>
            )}
          </Button>
        ) : (
          <span className="text-xs text-(--text-neutral-500)">—</span>
        ),
    },
  ];

  return (
    <div className="w-full">
      <div className="mb-4 flex flex-col justify-between gap-4 md:flex-row md:items-center">
        <h3 className="text-xl leading-6 font-semibold tracking-0 text-(--text-primary-dark)">
          My invoices
        </h3>
        <div className="flex items-center gap-2">
          <div className="flex w-full items-center gap-2">
            <CustomInput
              placeholder="Search..."
              value={searchQuery}
              onChange={(event) => onSearchChange(event.target.value)}
              icon={<Search size={18} className="text-(--text-neutral-600)" />}
              className="min-h-10 rounded-full pt-1.75 pb-0 md:w-79"
            />
            <ClientInvoicesFilterPanel
              filters={filters}
              setFilters={setFilters}
            />
          </div>
        </div>
      </div>

      {isLoading ? (
        <div className="flex items-center justify-center gap-2 py-16">
          <Loader2 className="h-5 w-5 animate-spin text-(--bg-primary-dark)" />
          <span className="text-sm text-(--text-neutral-600)">
            Loading invoices...
          </span>
        </div>
      ) : currentInvoices.length === 0 ? (
        <div className="rounded-lg border border-(--neutral-100) bg-white px-4 py-12 text-center text-sm text-(--text-neutral-600)">
          No invoices found.
        </div>
      ) : (
        <InvoiceTableComponent
          columns={columns}
          data={currentInvoices}
          rowKey={(invoice) => invoice.id}
        />
      )}

      <div
        ref={observerTarget}
        className="mt-4 flex h-10 w-full items-center justify-center"
      >
        {isLoadingMore ? (
          <Loader className="animate-spin text-(--primary-500)" />
        ) : null}
      </div>
    </div>
  );
};

export default InvoiceTable;

import { useEffect, useMemo, useState } from "react";
import { useSearchParams } from "react-router-dom";
import InvoiceOverviewCards from "../../../components/invoices/InvoiceOverviewCards";
import InvoiceTable from "../../../components/invoices/InvoiceTable";
import ScrollToTopButton from "@/components/shared/ScrollToTopButton";
import Toast from "@/components/shared/Toast";
import {
  useGetPortalInvoicesQuery,
  usePayPortalInvoiceMutation,
} from "@/store/api/portalApi";
import { getApiErrorMessage } from "@/utils/apiError";
import {
  applyClientInvoiceFilters,
  DEFAULT_CLIENT_INVOICE_FILTERS,
  filterPortalInvoicesBySearch,
  type ClientInvoiceFilters,
} from "@/utils/clientInvoiceFilters";
import {
  buildPortalInvoiceOverview,
  mapPortalInvoiceToRow,
  sortPortalInvoicesNewestFirst,
} from "@/utils/portalInvoiceDisplay";

const Invoices = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const [searchQuery, setSearchQuery] = useState("");
  const [invoiceFilters, setInvoiceFilters] = useState<ClientInvoiceFilters>(
    DEFAULT_CLIENT_INVOICE_FILTERS,
  );
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const [toastType, setToastType] = useState<"success" | "error">("error");
  const [payingInvoiceId, setPayingInvoiceId] = useState<string | null>(null);

  const {
    data: invoicesData = [],
    isLoading,
    isFetching,
    isError,
    error,
    refetch,
  } = useGetPortalInvoicesQuery(undefined, {
    refetchOnMountOrArgChange: true,
  });
  const [payInvoice] = usePayPortalInvoiceMutation();

  const sortedInvoices = useMemo(
    () => sortPortalInvoicesNewestFirst(invoicesData),
    [invoicesData],
  );

  const filteredInvoices = useMemo(() => {
    const panelFiltered = applyClientInvoiceFilters(sortedInvoices, invoiceFilters);
    return filterPortalInvoicesBySearch(panelFiltered, searchQuery);
  }, [invoiceFilters, searchQuery, sortedInvoices]);

  const invoiceRows = useMemo(
    () => filteredInvoices.map(mapPortalInvoiceToRow),
    [filteredInvoices],
  );

  const overview = useMemo(
    () => buildPortalInvoiceOverview(sortedInvoices),
    [sortedInvoices],
  );

  useEffect(() => {
    if (!isError) return;
    setToastType("error");
    setToastMessage(getApiErrorMessage(error));
  }, [error, isError]);

  useEffect(() => {
    const paymentResult = searchParams.get("payment");
    if (!paymentResult) return;

    if (paymentResult === "success") {
      setToastType("success");
      setToastMessage("Payment completed successfully.");
      void refetch();
    } else if (paymentResult === "cancelled") {
      setToastType("error");
      setToastMessage("Payment was cancelled.");
    }

    const nextParams = new URLSearchParams(searchParams);
    nextParams.delete("payment");
    nextParams.delete("session_id");
    setSearchParams(nextParams, { replace: true });
  }, [refetch, searchParams, setSearchParams]);

  const handlePayNow = async (invoiceId: string) => {
    const numericId = Number.parseInt(invoiceId, 10);
    if (Number.isNaN(numericId)) return;

    try {
      setPayingInvoiceId(invoiceId);
      setToastMessage(null);
      const response = await payInvoice(numericId).unwrap();

      if (!response.checkoutUrl) {
        setToastType("error");
        setToastMessage("Unable to start checkout. Please try again.");
        return;
      }

      window.location.assign(response.checkoutUrl);
    } catch (payError) {
      setToastType("error");
      setToastMessage(getApiErrorMessage(payError));
    } finally {
      setPayingInvoiceId(null);
    }
  };

  return (
    <div className="flex flex-col gap-6">
      <ScrollToTopButton />
      <InvoiceOverviewCards overview={overview} />
      <InvoiceTable
        invoices={invoiceRows}
        isLoading={isLoading || isFetching}
        searchQuery={searchQuery}
        onSearchChange={setSearchQuery}
        filters={invoiceFilters}
        setFilters={setInvoiceFilters}
        payingInvoiceId={payingInvoiceId}
        onPayNow={(invoiceId) => void handlePayNow(invoiceId)}
      />
      {toastMessage ? (
        <Toast
          message={toastMessage}
          type={toastType}
          onClose={() => setToastMessage(null)}
        />
      ) : null}
    </div>
  );
};

export default Invoices;

import type { PortalInvoicesQueryParams } from "@/store/api/portalApi";

export interface ClientInvoiceFilters {
  startDate: Date | null;
  endDate: Date | null;
  paymentStatus: string | null;
  insuranceCovered: string | null;
}

export const DEFAULT_CLIENT_INVOICE_FILTERS: ClientInvoiceFilters = {
  startDate: null,
  endDate: null,
  paymentStatus: null,
  insuranceCovered: null,
};

export const CLIENT_INVOICE_STATUS_OPTIONS = [
  { value: "", label: "All Statuses" },
  { value: "unpaid", label: "Pending" },
  { value: "paid", label: "Paid" },
  { value: "partial", label: "Partial" },
  { value: "denied", label: "Denied" },
  { value: "cancelled", label: "Cancelled" },
];

export const CLIENT_INVOICE_INSURANCE_OPTIONS = [
  { value: "", label: "All Coverage" },
  { value: "covered", label: "Insurance covered" },
  { value: "self_pay", label: "Self-pay" },
];

export const PORTAL_INVOICES_PAGE_SIZE = 20;

function formatQueryDate(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

export function hasActiveClientInvoiceFilters(
  filters: ClientInvoiceFilters,
): boolean {
  return Boolean(
    filters.startDate ||
      filters.endDate ||
      filters.paymentStatus ||
      filters.insuranceCovered,
  );
}

export function buildPortalInvoicesQueryArgs(
  page: number,
  filters: ClientInvoiceFilters,
  search: string,
  pageSize = PORTAL_INVOICES_PAGE_SIZE,
): PortalInvoicesQueryParams {
  const params: PortalInvoicesQueryParams = {
    page,
    pageSize,
  };

  if (filters.paymentStatus) {
    params.paymentStatus = filters.paymentStatus;
  }

  if (filters.insuranceCovered === "covered") {
    params.insuranceCovered = true;
  } else if (filters.insuranceCovered === "self_pay") {
    params.insuranceCovered = false;
  }

  if (filters.startDate) {
    params.startDate = formatQueryDate(filters.startDate);
  }

  if (filters.endDate) {
    params.endDate = formatQueryDate(filters.endDate);
  }

  const trimmedSearch = search.trim();
  if (trimmedSearch) {
    params.search = trimmedSearch;
  }

  return params;
}

import type {
  PortalInvoice,
  PortalInvoiceStats,
} from "@/store/api/portalApi";
import type { Invoice, InvoiceOverview, InvoiceStatus } from "@/types/invoice.type";

function formatCurrency(amount: number): string {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  }).format(amount);
}

function formatInvoiceDate(value: string | null | undefined): string {
  if (!value) return "-";

  const dateOnlyMatch = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value.trim());
  const parsed = dateOnlyMatch
    ? new Date(
        Number.parseInt(dateOnlyMatch[1], 10),
        Number.parseInt(dateOnlyMatch[2], 10) - 1,
        Number.parseInt(dateOnlyMatch[3], 10),
      )
    : new Date(value);

  if (Number.isNaN(parsed.getTime())) {
    return value;
  }

  return parsed.toLocaleDateString("en-US", {
    month: "short",
    day: "2-digit",
    year: "numeric",
  });
}

function formatPaidDate(value: string | null | undefined): string | undefined {
  if (!value) return undefined;
  const formatted = formatInvoiceDate(value);
  return formatted === "-" ? undefined : formatted;
}

function formatPaymentMethod(
  value: string | null | undefined,
): string | undefined {
  if (!value?.trim()) return undefined;

  return value
    .trim()
    .replace(/_/g, " ")
    .replace(/\b\w/g, (char) => char.toUpperCase());
}

export function resolvePortalInvoiceStatus(invoice: PortalInvoice): InvoiceStatus {
  const paymentStatus = (invoice.paymentStatus || "").trim().toLowerCase();

  if (paymentStatus === "paid") return "paid";
  if (paymentStatus === "unpaid") return "pending";
  if (paymentStatus === "partial") return "partial";
  if (paymentStatus === "denied") return "denied";
  if (paymentStatus === "cancelled" || paymentStatus === "canceled") {
    return "cancelled";
  }

  const billingStatus = (invoice.billingStatus || "").trim().toLowerCase();
  if (billingStatus === "paid") return "paid";
  if (billingStatus === "denied") return "denied";
  if (billingStatus === "follow_up" || billingStatus === "follow-up") {
    return "follow_up";
  }
  if (billingStatus === "cancelled" || billingStatus === "canceled") {
    return "cancelled";
  }
  if (billingStatus === "billed" || billingStatus === "pending") {
    return "pending";
  }

  const totalAmount = invoice.totalAmount ?? 0;
  const paymentAmount = invoice.paymentAmount ?? 0;

  if (totalAmount > 0 && paymentAmount >= totalAmount) {
    return "paid";
  }

  if (paymentAmount > 0) {
    return "partial";
  }

  return "pending";
}

export function canPayPortalInvoice(invoice: PortalInvoice): boolean {
  const paymentStatus = (invoice.paymentStatus || "").trim().toLowerCase();
  if (paymentStatus === "paid" || paymentStatus === "denied" || paymentStatus === "cancelled") {
    return false;
  }

  const status = resolvePortalInvoiceStatus(invoice);
  return status === "pending" || status === "partial";
}

export function canDownloadPortalInvoiceReceipt(invoice: PortalInvoice): boolean {
  const paymentStatus = (invoice.paymentStatus || "").trim().toLowerCase();
  if (paymentStatus === "paid" || paymentStatus === "partial") {
    return true;
  }

  const status = resolvePortalInvoiceStatus(invoice);
  return status === "paid" || status === "partial";
}

export function getPortalInvoiceStatusLabel(status: InvoiceStatus): string {
  switch (status) {
    case "paid":
      return "Paid";
    case "partial":
      return "Partial";
    case "denied":
      return "Denied";
    case "cancelled":
      return "Cancelled";
    case "follow_up":
      return "Follow-up";
    case "refunded":
      return "Refunded";
    case "billed":
      return "Billed";
    case "pending":
    default:
      return "Pending";
  }
}

export function getPortalInvoiceStatusStyles(status: InvoiceStatus): string {
  switch (status) {
    case "paid":
      return "bg-[#EBFEF4] text-[#007C54] border-[#EBFEF4]";
    case "partial":
      return "bg-[#EEF4FF] text-[#1D4ED8] border-[#EEF4FF]";
    case "denied":
    case "cancelled":
      return "bg-[#FEF2F2] text-[#EF4444] border-[#FEF2F2]";
    case "follow_up":
      return "bg-[#FFF7ED] text-[#FBAC00] border-[#FFF7ED]";
    case "refunded":
      return "bg-[#EDEEF1] text-(--text-neutral-600) border-[#EDEEF1]";
    case "billed":
    case "pending":
    default:
      return "bg-[#EDEEF1] text-(--text-neutral-600) border-[#EDEEF1]";
  }
}

export function formatInsuranceLabel(insuranceCovered: boolean): string {
  return insuranceCovered ? "Covered" : "Self-pay";
}

export function formatCopayLabel(
  copayAmount: number | null | undefined,
): string {
  if (copayAmount === null || copayAmount === undefined) {
    return "--";
  }

  return formatCurrency(copayAmount);
}

export interface ClientInvoiceRow extends Invoice {
  canPay: boolean;
  canDownloadReceipt: boolean;
  serviceCode?: string;
  billingDateRaw: string;
}

export function mapPortalInvoiceToRow(invoice: PortalInvoice): ClientInvoiceRow {
  const status = resolvePortalInvoiceStatus(invoice);
  const paymentMethod = formatPaymentMethod(invoice.paymentMethod);

  return {
    id: String(invoice.id),
    date: formatInvoiceDate(invoice.billingDate || invoice.sessionDate),
    service: invoice.serviceName || "Session",
    amount: formatCurrency(invoice.totalAmount ?? 0),
    insurance: formatInsuranceLabel(Boolean(invoice.insuranceCovered)),
    copay: formatCopayLabel(invoice.copayAmount),
    status,
    paidDate: formatPaidDate(invoice.paymentDate),
    paymentMethod,
    canPay: canPayPortalInvoice(invoice),
    canDownloadReceipt: canDownloadPortalInvoiceReceipt(invoice),
    serviceCode: invoice.serviceCode || undefined,
    billingDateRaw: invoice.billingDate || invoice.sessionDate || "",
  };
}

export function mapPortalInvoiceStatsToOverview(
  stats: PortalInvoiceStats,
): InvoiceOverview {
  return {
    totalInvoices: stats.totalInvoices,
    totalBilled: formatCurrency(stats.totalBilled),
    totalPaid: formatCurrency(stats.totalPaid),
  };
}

export function downloadPortalInvoiceReceiptBlob(
  blob: Blob,
  invoiceId: number,
): void {
  const fileUrl = window.URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = fileUrl;
  link.download = `invoice-${invoiceId}-receipt.pdf`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.URL.revokeObjectURL(fileUrl);
}

