interface InvoiceTableProps {
  invoices: ClientInvoiceRow[];
  isLoading?: boolean;
  isLoadingMore?: boolean;
  hasMore?: boolean;
  onLoadMore: () => void;
  searchQuery: string;
  onSearchChange: (value: string) => void;
