  isLoading = false,
  isLoadingMore = false,
  hasMore = false,
  onLoadMore,
  searchQuery,
  onSearchChange,
  filters,
  setFilters,
  payingInvoiceId,
  downloadingInvoiceId,
  onPayNow,
  onDownloadReceipt,
}: InvoiceTableProps) => {
  const { observerTarget } = useInfiniteScroll({
    onLoadMore,
    hasMore,
    isLoading: isLoadingMore,
  });

  const columns: InvoiceTableColumn<ClientInvoiceRow>[] = [
    {
      key: "date",
      label: "Date",
      width: "130px",
      padding: "20px 12px",
      headerPadding: "12px",
    },
    {
      key: "service",
      label: "Service",
      width: "340px",
      padding: "16px 8px",
      headerPadding: "12px",
      render: (_, invoice) => (
        <div className="flex min-w-0 flex-col gap-1.5">
