            {invoice.service}
          </span>
          {invoice.serviceCode ? (
            <span className="text-xs text-(--text-neutral-600)">
              {invoice.serviceCode}
            </span>
          ) : null}
        </div>
      ),
    },
    {
      key: "amount",
      label: "Amount",
      width: "100px",
      padding: "20px 8px",
      className: "font-medium",
    },
    {
      key: "insurance",
      label: "Insurance",
      width: "120px",
      padding: "20px 8px",
      render: (value) => (
        <Badge
          variant="outline"
          className="w-fit border-[#EDEEF1] bg-[#EDEEF1] text-xs font-normal text-(--text-neutral-600)"
        >
          {value}
        </Badge>
      ),
    },
    {
      key: "copay",
      label: "Copay",
      width: "110px",
      padding: "20px 8px",
    },
