import type { PortalDocument } from "@/store/api/portalApi";
import type { Document } from "@/types/document.type";

const DOCUMENT_TYPE_LABELS: Record<string, string> = {
  intake_form: "Forms and Intake",
  consent: "Consent",
  insurance_card: "Insurance Documents",
  id_document: "ID Document",
  medical_record: "Medical Records",
  prescription: "Prescription",
  lab_result: "Lab Results",
  referral_letter: "Referral Letter",
};

function formatDocumentDate(value: string | null | undefined): string {
  if (!value) return "-";

  const dateOnlyMatch = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value.trim());
  const parsed = dateOnlyMatch
    ? new Date(
        Number.parseInt(dateOnlyMatch[1], 10),
        Number.parseInt(dateOnlyMatch[2], 10) - 1,
        Number.parseInt(dateOnlyMatch[3], 10),
      )
    : new Date(value);

  if (Number.isNaN(parsed.getTime())) {
    return value;
  }

  return parsed.toLocaleDateString("en-US", {
    month: "short",
    day: "2-digit",
    year: "numeric",
  });
}

export function formatPortalDocumentBytes(value?: number | null): string {
  if (!value || value <= 0) return "-";

  const units = ["B", "KB", "MB", "GB"];
  let size = value;
  let unitIndex = 0;

  while (size >= 1024 && unitIndex < units.length - 1) {
    size /= 1024;
    unitIndex += 1;
  }

  return `${size.toFixed(size >= 10 ? 0 : 1)} ${units[unitIndex]}`;
}

export function formatPortalDocumentCategory(document: PortalDocument): string {
  const documentType = document.documentType?.trim();
  if (documentType) {
    return (
      DOCUMENT_TYPE_LABELS[documentType] ||
      documentType
        .replace(/_/g, " ")
        .replace(/\b\w/g, (char) => char.toUpperCase())
    );
  }

  const category = document.category?.trim();
  if (category) return category;

  return "Document";
}

export interface PortalDocumentRow extends Document {
  mimeType?: string;
  previewUrl?: string;
  downloadUrl?: string;
}

export function mapPortalDocumentToRow(
  document: PortalDocument,
): PortalDocumentRow {
  return {
    id: String(document.id),
    name: document.originalName || document.fileName || "Untitled document",
    category: formatPortalDocumentCategory(document),
    size: formatPortalDocumentBytes(document.fileSize),
    uploadedDate: formatDocumentDate(document.uploadedAt || document.createdAt),
    mimeType: document.mimeType || undefined,
    previewUrl: document.previewUrl || undefined,
    downloadUrl: document.downloadUrl || undefined,
  };
}

export function filterPortalDocuments(
  documents: PortalDocumentRow[],
  searchQuery: string,
): PortalDocumentRow[] {
  const normalizedQuery = searchQuery.trim().toLowerCase();
  if (!normalizedQuery) return documents;

  return documents.filter((document) => {
    const haystack = [
      document.name,
      document.category,
      document.size,
      document.uploadedDate,
    ]
      .join(" ")
      .toLowerCase();

    return haystack.includes(normalizedQuery);
  });
}

export function downloadPortalDocumentBlob(blob: Blob, fileName: string): void {
  const fileUrl = window.URL.createObjectURL(blob);
  const link = window.document.createElement("a");
  link.href = fileUrl;
  link.download = fileName;
  window.document.body.appendChild(link);
  link.click();
  link.remove();
  window.URL.revokeObjectURL(fileUrl);
}

import { getRefreshPathForRole } from "@/utils/authApiPaths";
import { getAuthSession, setAuthSession } from "@/utils/authStorage";
import { buildTenantApiBase } from "@/utils/tenantUrls";

export type PortalDocumentAssetResult =
  | { kind: "url"; value: string }
  | { kind: "blob"; value: Blob };

const normalizeDocumentUrl = (value: string): string => {
  const trimmed = value.trim();
  if (
    (trimmed.startsWith('"') && trimmed.endsWith('"')) ||
    (trimmed.startsWith("'") && trimmed.endsWith("'"))
  ) {
    return trimmed.slice(1, -1);
  }

  return trimmed;
};

async function fetchWithAuth(path: string): Promise<Response> {
  const session = getAuthSession();
  const baseUrl = buildTenantApiBase(session?.tenantSubdomain);
  const response = await fetch(`${baseUrl}${path}`, {
    headers: session?.accessToken
      ? { Authorization: `Bearer ${session.accessToken}` }
      : undefined,
  });

  if (response.status === 401 && session?.refreshToken && session.role) {
    const refreshResponse = await fetch(
      `${baseUrl}${getRefreshPathForRole(session.role)}`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ refreshToken: session.refreshToken }),
      },
    );

    if (refreshResponse.ok) {
      const refreshPayload = (await refreshResponse.json()) as {
        accessToken: string;
        refreshToken?: string;
      };

      const nextSession = {
        ...session,
        accessToken: refreshPayload.accessToken,
        refreshToken: refreshPayload.refreshToken ?? session.refreshToken,
      };

      setAuthSession(nextSession);

      return fetch(`${baseUrl}${path}`, {
        headers: {
          Authorization: `Bearer ${nextSession.accessToken}`,
        },
      });
    }
  }

  return response;
}

export async function fetchPortalDocumentAsset(
  path: string,
): Promise<PortalDocumentAssetResult> {
  const response = await fetchWithAuth(path);

  if (!response.ok) {
    throw new Error(`Request failed with status ${response.status}`);
  }

  const contentType = response.headers.get("content-type") || "";
  if (contentType.includes("application/json")) {
    const text = normalizeDocumentUrl(await response.text());
    return { kind: "url", value: text };
  }

  return { kind: "blob", value: await response.blob() };
}

export function getPortalDocumentViewPath(documentId: number): string {
  return `/api/v1/portal/documents/${documentId}/view`;
}

export function getPortalDocumentDownloadPath(documentId: number): string {
  return `/api/v1/portal/documents/${documentId}/download`;
}

import { useEffect, useMemo, useRef, useState } from "react";
import mammoth from "mammoth";
import DocumentsTable from "../../../components/documents/DocumentsTable";
import DocumentPreviewModal from "@/components/shared/DocumentPreviewModal";
import ScrollToTopButton from "@/components/shared/ScrollToTopButton";
import Toast from "@/components/shared/Toast";
import {
  useGetPortalDocumentsQuery,
  useUploadPortalDocumentMutation,
  validatePortalDocumentFile,
} from "@/store/api/portalApi";
import { getApiErrorMessage } from "@/utils/apiError";
import {
  downloadPortalDocumentBlob,
  filterPortalDocuments,
  mapPortalDocumentToRow,
  type PortalDocumentRow,
} from "@/utils/portalDocumentDisplay";
import {
  fetchPortalDocumentAsset,
  getPortalDocumentDownloadPath,
  getPortalDocumentViewPath,
} from "@/utils/portalDocumentAssets";

interface PreviewDocumentState {
  id: string;
  name: string;
  size?: string;
  uploadedDate?: string;
  previewUrl?: string;
  mimeType?: string;
  previewHtml?: string;
}

const Documents = () => {
  const listScrollRef = useRef<HTMLDivElement>(null);
  const previewObjectUrlRef = useRef<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const [toastType, setToastType] = useState<"success" | "error" | "info">(
    "error",
  );
  const [viewingDocumentId, setViewingDocumentId] = useState<string | null>(
    null,
  );
  const [downloadingDocumentId, setDownloadingDocumentId] = useState<
    string | null
  >(null);
  const [previewDoc, setPreviewDoc] = useState<PreviewDocumentState | null>(
    null,
  );
  const [isPreviewModalOpen, setIsPreviewModalOpen] = useState(false);
  const [isPreviewLoading, setIsPreviewLoading] = useState(false);

  const {
    data: portalDocuments = [],
    isLoading,
    isFetching,
    isError,
    error,
    refetch,
  } = useGetPortalDocumentsQuery(undefined, {
    refetchOnMountOrArgChange: true,
  });

  const [uploadPortalDocument, { isLoading: isUploading }] =
    useUploadPortalDocumentMutation();

  const documentRows = useMemo(
    () => portalDocuments.map(mapPortalDocumentToRow),
    [portalDocuments],
  );

  const filteredDocuments = useMemo(
    () => filterPortalDocuments(documentRows, searchQuery),
    [documentRows, searchQuery],
  );

  const isInitialLoading =
    (isLoading || isFetching) && portalDocuments.length === 0;

  useEffect(() => {
    if (!isError) return;
    setToastType("error");
    setToastMessage(getApiErrorMessage(error));
  }, [error, isError]);

  const clearPreviewObjectUrl = () => {
    if (previewObjectUrlRef.current) {
      window.URL.revokeObjectURL(previewObjectUrlRef.current);
      previewObjectUrlRef.current = null;
    }
  };

  const handleClosePreview = () => {
    setIsPreviewModalOpen(false);
    setPreviewDoc(null);
    setIsPreviewLoading(false);
    setViewingDocumentId(null);
    clearPreviewObjectUrl();
  };

  const resolveDocumentAsset = async (
    path: string,
    fallbackUrl?: string,
  ): Promise<{
    previewUrl?: string;
    mimeType?: string;
    previewHtml?: string;
    blob?: Blob;
  }> => {
    const payload = await fetchPortalDocumentAsset(path);

    if (payload.kind === "url") {
      const trimmed = payload.value.trim();
      if (trimmed.startsWith("http://") || trimmed.startsWith("https://")) {
        return { previewUrl: trimmed };
      }

      return { previewUrl: fallbackUrl };
    }

    const mimeType = payload.value.type || undefined;

    if (
      mimeType?.includes(
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      )
    ) {
      const buffer = await payload.value.arrayBuffer();
      const result = await mammoth.convertToHtml({ arrayBuffer: buffer });
      return { previewHtml: result.value, mimeType };
    }

    clearPreviewObjectUrl();
    const objectPreviewUrl = window.URL.createObjectURL(payload.value);
    previewObjectUrlRef.current = objectPreviewUrl;

    return {
      previewUrl: objectPreviewUrl,
      mimeType,
      blob: payload.value,
    };
  };

  const handleView = async (document: PortalDocumentRow) => {
    const parsedId = Number.parseInt(document.id, 10);
    if (Number.isNaN(parsedId)) return;

    setViewingDocumentId(document.id);
    setIsPreviewLoading(true);
    setIsPreviewModalOpen(true);
    setPreviewDoc({
      id: document.id,
      name: document.name,
      size: document.size,
      uploadedDate: document.uploadedDate,
    });
    setToastMessage(null);

    try {
      const asset = await resolveDocumentAsset(
        getPortalDocumentViewPath(parsedId),
        document.previewUrl,
      );

      setPreviewDoc({
        id: document.id,
        name: document.name,
        size: document.size,
        uploadedDate: document.uploadedDate,
        previewUrl: asset.previewUrl,
        mimeType: asset.mimeType || document.mimeType,
        previewHtml: asset.previewHtml,
      });
    } catch (viewError) {
      setToastType("error");
      setToastMessage(getApiErrorMessage(viewError));
      handleClosePreview();
    } finally {
      setIsPreviewLoading(false);
      setViewingDocumentId(null);
    }
  };

  const handleDownload = async (document: PortalDocumentRow) => {
    const parsedId = Number.parseInt(document.id, 10);
    if (Number.isNaN(parsedId)) return;

    setDownloadingDocumentId(document.id);
    setToastType("info");
    setToastMessage("Preparing download...");
    setToastMessage(null);

    try {
      const payload = await fetchPortalDocumentAsset(
        getPortalDocumentDownloadPath(parsedId),
      );

      if (payload.kind === "url") {
        const trimmed = payload.value.trim();
        if (trimmed.startsWith("http://") || trimmed.startsWith("https://")) {
          const response = await fetch(trimmed);
          if (!response.ok) {
            throw new Error(`Download failed with status ${response.status}`);
          }
          downloadPortalDocumentBlob(
            await response.blob(),
            document.name,
          );
        } else {
          const blob = new Blob([payload.value], { type: "text/plain" });
          downloadPortalDocumentBlob(blob, document.name);
        }
      } else {
        downloadPortalDocumentBlob(payload.value, document.name);
      }

      setToastType("success");
      setToastMessage("Document downloaded successfully.");
    } catch (downloadError) {
      setToastType("error");
      setToastMessage(getApiErrorMessage(downloadError));
    } finally {
      setDownloadingDocumentId(null);
    }
  };

  const handleUpload = async (
    files: { file: File }[],
    documentType: string,
  ) => {
    const fileEntry = files[0];
    if (!fileEntry) return;

    const validationError = validatePortalDocumentFile(fileEntry.file);
    if (validationError) {
      setToastType("error");
      setToastMessage(validationError);
      return;
    }

    try {
      setToastMessage(null);
      await uploadPortalDocument({
        file: fileEntry.file,
        documentType,
      }).unwrap();
      await refetch();
      setToastType("success");
      setToastMessage("Document uploaded successfully.");
    } catch (uploadError) {
      setToastType("error");
      setToastMessage(getApiErrorMessage(uploadError));
      throw uploadError;
    }
  };

  return (
    <div className="flex h-[calc(100vh-10rem)] min-h-0 flex-col overflow-hidden">
      <ScrollToTopButton containerRef={listScrollRef} />
      <DocumentsTable
        documents={filteredDocuments}
        isLoading={isInitialLoading}
        searchQuery={searchQuery}
        onSearchChange={setSearchQuery}
        isUploading={isUploading}
        onUpload={handleUpload}
        onView={(document) => void handleView(document)}
        onDownload={(document) => void handleDownload(document)}
        viewingDocumentId={viewingDocumentId}
        downloadingDocumentId={downloadingDocumentId}
        scrollContainerRef={listScrollRef}
      />
      <DocumentPreviewModal
        isOpen={isPreviewModalOpen}
        onClose={handleClosePreview}
        isLoading={isPreviewLoading}
        document={previewDoc}
        onDownload={() => {
          if (!previewDoc) return;
          const row = filteredDocuments.find((doc) => doc.id === previewDoc.id);
          if (row) {
            void handleDownload(row);
          }
        }}
      />
      {toastMessage ? (
        <Toast
          message={toastMessage}
          type={toastType === "info" ? "error" : toastType}
          onClose={() => setToastMessage(null)}
        />
      ) : null}
    </div>
  );
};

export default Documents;

