interface UploadedFile {
  id: string;
  file: File;
  name: string;
  type: string;
}

interface DocumentsTableProps {
  documents: PortalDocumentRow[];
  isLoading?: boolean;
  searchQuery: string;
  onSearchChange: (value: string) => void;
  isUploading?: boolean;
  onUpload: (files: UploadedFile[], documentType: string) => Promise<void>;
  onView: (document: PortalDocumentRow) => void;
  onDownload: (document: PortalDocumentRow) => void;
  viewingDocumentId: string | null;
  downloadingDocumentId: string | null;
  scrollContainerRef?: React.RefObject<HTMLDivElement | null>;
}

const ITEMS_PER_PAGE = 20;

const DocumentsTable = ({
  documents,
  isLoading = false,
  searchQuery,
  onSearchChange,
  isUploading = false,
  onUpload,
  onView,
  onDownload,
  viewingDocumentId,
  downloadingDocumentId,
  scrollContainerRef,
}: DocumentsTableProps) => {
  const internalScrollRef = useRef<HTMLDivElement>(null);
  const listScrollRef = scrollContainerRef ?? internalScrollRef;
  const [displayedItems, setDisplayedItems] = useState(ITEMS_PER_PAGE);
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);

  const handleLoadMore = useCallback(() => {
    setDisplayedItems((prev) => prev + ITEMS_PER_PAGE);
  }, []);

  const { observerTarget } = useInfiniteScroll({
    onLoadMore: handleLoadMore,
    hasMore: displayedItems < documents.length,
    isLoading: false,
    scrollRootRef: listScrollRef,
  });

  const currentDocuments = documents.slice(0, displayedItems);

  const handleUpload = async (files: UploadedFile[], documentType: string) => {
    try {
      await onUpload(files, documentType);
      setIsUploadModalOpen(false);
      setDisplayedItems(ITEMS_PER_PAGE);
    } catch {
      // Parent shows toast for upload errors.
    }
  };

  const columns: DocumentTableColumn<PortalDocumentRow>[] = [
    {
      key: "name",
      label: "Name",
      width: "400px",
      padding: "20px 8px",
      headerPadding: "12px 8px",
      render: (_, document) => {
        const iconSrc = getDocumentIcon(document.name);
        return (
          <div className="flex min-w-0 items-center gap-2.5 overflow-hidden">
            <img
              src={iconSrc}
              alt=""
              className="h-8 w-8 shrink-0"
              aria-hidden="true"
            />
            <span
              className="min-w-0 truncate text-[14px] leading-[22px] font-normal text-(--text-primary-dark)"
              title={document.name}
            >
              {document.name}
            </span>
          </div>
        );
      },
    },
    {
      key: "category",
      label: "Category",
      width: "150px",
      padding: "20px 8px",
      headerPadding: "12px 8px",
      render: (value) => (
        <span className="block min-w-0 truncate" title={String(value ?? "")}>
          {value}
        </span>
      ),
    },
    {
      key: "size",
      label: "Size",
      width: "120px",
      padding: "20px 8px",
      headerPadding: "12px 8px",
    },
    {
      key: "uploadedDate",
      label: "Uploaded Date",
      width: "180px",
      padding: "20px 8px",
      headerPadding: "12px 8px",
      headerContent: (
        <div className="flex items-center gap-1">
          Uploaded Date
          <ChevronDown size={16} className="text-(--text-primary-dark)" />
        </div>
      ),
    },
    {
      key: "actions",
      label: "Actions",
      width: "120px",
      padding: "20px 8px",
      headerPadding: "12px 8px",
      render: (_, document) => (
        <div className="flex items-center gap-2">
          <Button
            type="button"
            variant="outline"
            size="icon"
            className="h-9 w-9 cursor-pointer rounded-xl border border-(--text-neutral-100) bg-white p-0 hover:bg-gray-50"
            disabled={viewingDocumentId === document.id}
            onClick={() => onView(document)}
            aria-label={`View ${document.name}`}
          >
            {viewingDocumentId === document.id ? (
              <Loader2 className="h-4 w-4 animate-spin text-(--bg-primary-dark)" />
            ) : (
              <img
                src="/documents/view.svg"
                alt=""
                className="h-9 w-9"
                aria-hidden="true"
              />
            )}
          </Button>
          <Button
            type="button"
            variant="outline"
            size="icon"
            className="h-9 w-9 cursor-pointer rounded-xl border border-(--text-neutral-100) bg-white p-0 hover:bg-gray-50"
            disabled={downloadingDocumentId === document.id}
            onClick={() => onDownload(document)}
            aria-label={`Download ${document.name}`}
          >
            {downloadingDocumentId === document.id ? (
              <Loader2 className="h-4 w-4 animate-spin text-(--bg-primary-dark)" />
            ) : (
              <img
                src="/documents/download.svg"
                alt=""
                className="h-9 w-9"
                aria-hidden="true"
              />
            )}
          </Button>
        </div>
      ),
    },
  ];

  return (
    <div className="flex min-h-0 w-full flex-1 flex-col overflow-hidden">
      <div className="mb-4 flex shrink-0 items-center justify-between gap-4">
        <h3 className="text-xl leading-6 font-semibold tracking-0 text-(--text-primary-dark)">
          Uploaded Documents
        </h3>
        <div className="flex items-center gap-2">
          <CustomInput
            placeholder="Search..."
            value={searchQuery}
            onChange={(event) => {
              onSearchChange(event.target.value);
              setDisplayedItems(ITEMS_PER_PAGE);
            }}
            icon={<Search size={18} className="text-(--text-neutral-600)" />}
            className="min-h-10 rounded-full pt-1.75 pb-0 md:w-79"
          />
          <Button
            type="button"
            onClick={() => setIsUploadModalOpen(true)}
            className="flex h-10 cursor-pointer items-center gap-2 rounded-full text-sm font-semibold"
          >
            <Upload size={16} />
            Upload Document
          </Button>
        </div>
      </div>

      <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
        {isLoading ? (
          <div className="flex flex-1 items-center justify-center gap-2">
            <Loader2 className="h-5 w-5 animate-spin text-(--bg-primary-dark)" />
            <span className="text-sm text-(--text-neutral-600)">
              Loading documents...
            </span>
          </div>
        ) : documents.length === 0 ? (
          <div className="flex flex-1 items-center justify-center rounded-lg border border-(--neutral-100) bg-white px-4 py-12 text-center text-sm text-(--text-neutral-600)">
            {searchQuery.trim()
              ? "No documents match your search."
              : "No documents found."}
          </div>
        ) : (
          <div
            ref={listScrollRef}
            className="min-h-0 flex-1 overflow-y-auto overscroll-contain rounded-xl border border-[#EDEEF1] bg-white shadow-[0px_2px_2px_0px_#1E282E0A]"
          >
            <DocumentTableComponent
              columns={columns}
              data={currentDocuments}
              rowKey={(document) => document.id}
              stickyHeader
              containerClassName="overflow-visible border-0 shadow-none"
              containerStyle={{
                border: "none",
                boxShadow: "none",
                borderRadius: 0,
                background: "transparent",
              }}
            />
            <div
              ref={observerTarget}
              className="flex h-10 w-full items-center justify-center"
            >
              {displayedItems < documents.length ? (
                <Loader className="animate-spin text-(--primary-500)" />
              ) : null}
            </div>
          </div>
        )}
      </div>

      <UploadDocumentModal
        isOpen={isUploadModalOpen}
        onClose={() => setIsUploadModalOpen(false)}
        onUpload={handleUpload}
        isUploading={isUploading}
      />
    </div>
  );
};

