import { baseApi } from "./baseApi";

export interface PortalNotificationItem {
  id: number;
  userId: number | null;
  clientId: number | null;
  type: string;
  category: string;
  title: string;
  message: string;
  data: string | null;
  priority: string;
  isRead: boolean;
  readAt: string | null;
  actionUrl: string | null;
  actionLabel: string | null;
  relatedEntityType: string | null;
  relatedEntityId: number | null;
  expiresAt: string | null;
  createdAt: string;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function asNumber(value: unknown): number {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  return 0;
}

function asNullableNumber(value: unknown): number | null {
  if (value === null || value === undefined) return null;
  return asNumber(value);
}

function asNullableString(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed || null;
}

function normalizePortalNotificationItem(
  entry: unknown,
): PortalNotificationItem | null {
  if (!isRecord(entry)) return null;

  return {
    id: asNumber(entry.id),
    userId: asNullableNumber(entry.userId),
    clientId: asNullableNumber(entry.clientId),
    type: asNullableString(entry.type) ?? "",
    category: asNullableString(entry.category) ?? "",
    title: asNullableString(entry.title) ?? "",
    message: asNullableString(entry.message) ?? "",
    data: asNullableString(entry.data),
    priority: asNullableString(entry.priority) ?? "",
    isRead: Boolean(entry.isRead),
    readAt: asNullableString(entry.readAt),
    actionUrl: asNullableString(entry.actionUrl),
    actionLabel: asNullableString(entry.actionLabel),
    relatedEntityType: asNullableString(entry.relatedEntityType),
    relatedEntityId: asNullableNumber(entry.relatedEntityId),
    expiresAt: asNullableString(entry.expiresAt),
    createdAt: asNullableString(entry.createdAt) ?? "",
  };
}

function normalizePortalNotificationsResponse(
  payload: unknown,
): PortalNotificationItem[] {
  if (Array.isArray(payload)) {
    return payload
      .map((entry) => normalizePortalNotificationItem(entry))
      .filter((entry): entry is PortalNotificationItem => entry !== null);
  }

  if (isRecord(payload) && Array.isArray(payload.items)) {
    return payload.items
      .map((entry) => normalizePortalNotificationItem(entry))
      .filter((entry): entry is PortalNotificationItem => entry !== null);
  }

  return [];
}

function normalizePortalUnreadCount(payload: unknown): number {
  if (typeof payload === "number" && Number.isFinite(payload)) return payload;
  if (!isRecord(payload)) return 0;
  return asNumber(payload.count ?? payload.unread ?? payload.unreadCount);
}

export const portalNotificationsApi = baseApi.injectEndpoints({
  endpoints: (builder) => ({
    getPortalNotifications: builder.query<
      PortalNotificationItem[],
      { unreadOnly?: boolean } | void
    >({
      query: (params) => {
        const unreadOnly =
          params && "unreadOnly" in params ? params.unreadOnly : undefined;

        return {
          url: "/api/v1/portal/notifications",
          params: unreadOnly === undefined ? undefined : { unreadOnly },
        };
      },
      transformResponse: (payload) => normalizePortalNotificationsResponse(payload),
      providesTags: ["PortalNotifications"],
    }),
    getPortalNotificationUnreadCount: builder.query<number, void>({
      query: () => "/api/v1/portal/notifications/unread/count",
      transformResponse: (payload) => normalizePortalUnreadCount(payload),
      providesTags: ["PortalNotifications"],
    }),
    markPortalNotificationRead: builder.mutation<void, number>({
      query: (id) => ({
        url: `/api/v1/portal/notifications/${id}/read`,
        method: "PATCH",
      }),
      invalidatesTags: ["PortalNotifications"],
    }),
    markAllPortalNotificationsRead: builder.mutation<void, void>({
      query: () => ({
        url: "/api/v1/portal/notifications/read-all",
        method: "PATCH",
      }),
      invalidatesTags: ["PortalNotifications"],
    }),
    deletePortalNotification: builder.mutation<void, number>({
      query: (id) => ({
        url: `/api/v1/portal/notifications/${id}`,
        method: "DELETE",
      }),
      invalidatesTags: ["PortalNotifications"],
    }),
  }),
});

export const {
  useGetPortalNotificationsQuery,
  useLazyGetPortalNotificationsQuery,
  useGetPortalNotificationUnreadCountQuery,
  useMarkPortalNotificationReadMutation,
  useMarkAllPortalNotificationsReadMutation,
  useDeletePortalNotificationMutation,
} = portalNotificationsApi;

import type { PortalNotificationItem } from "@/store/api/portalNotificationsApi";
import type { Notification } from "@/types/notification";

function formatNotificationTimestamp(value: string | null | undefined): string {
  if (!value) return "-";

  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return value;

  return parsed.toLocaleString("en-US", {
    month: "short",
    day: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function formatNotificationDateGroup(value: string | null | undefined): string | undefined {
  if (!value) return undefined;

  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return undefined;

  const today = new Date();
  const startOfToday = new Date(
    today.getFullYear(),
    today.getMonth(),
    today.getDate(),
  );
  const startOfTarget = new Date(
    parsed.getFullYear(),
    parsed.getMonth(),
    parsed.getDate(),
  );
  const dayDiff = Math.round(
    (startOfToday.getTime() - startOfTarget.getTime()) / (24 * 60 * 60 * 1000),
  );

  if (dayDiff === 0) return undefined;
  if (dayDiff === 1) return "Yesterday";

  return parsed.toLocaleDateString("en-US", {
    month: "short",
    day: "2-digit",
  });
}

export function resolvePortalNotificationActionUrl(
  actionUrl: string | null | undefined,
): string | null {
  if (!actionUrl?.trim()) return null;

  const trimmed = actionUrl.trim();
  if (trimmed.startsWith("/user/")) return trimmed;
  if (trimmed.startsWith("http://") || trimmed.startsWith("https://")) {
    return trimmed;
  }

  if (trimmed.startsWith("/portal/")) {
    const remainder = trimmed.slice("/portal/".length);
    const [section] = remainder.split("/").filter(Boolean);
    const routeMap: Record<string, string> = {
      appointments: "/user/appointments",
      invoices: "/user/invoices",
      documents: "/user/documents",
      forms: "/user/clinical-forms",
      "clinical-forms": "/user/clinical-forms",
      assessments: "/user/clinical-forms",
      "privacy-settings": "/user/privacy-settings",
      "my-profile": "/user/my-profile",
    };

    if (section && routeMap[section]) {
      return routeMap[section];
    }
  }

  return trimmed.startsWith("/") ? trimmed : null;
}

export function mapPortalNotificationToUi(
  notification: PortalNotificationItem,
  previousCreatedAt?: string,
): Notification {
  const dateGroup =
    previousCreatedAt &&
    formatNotificationDateGroup(previousCreatedAt) ===
      formatNotificationDateGroup(notification.createdAt)
      ? undefined
      : formatNotificationDateGroup(notification.createdAt);

  return {
    id: String(notification.id),
    title: notification.title || notification.type || "Notification",
    description: notification.message || "-",
    timestamp: formatNotificationTimestamp(notification.createdAt),
    isRead: Boolean(notification.isRead),
    dateGroup,
    actionUrl:
      resolvePortalNotificationActionUrl(notification.actionUrl) ?? undefined,
    actionLabel: notification.actionLabel || undefined,
  };
}

export function mapPortalNotificationsToUi(
  notifications: PortalNotificationItem[],
): Notification[] {
  return notifications.map((notification, index) =>
    mapPortalNotificationToUi(
      notification,
      index > 0 ? notifications[index - 1]?.createdAt : undefined,
    ),
  );
}

