import { baseApi } from "./baseApi";

export interface PortalNotificationItem {
  id: number;
  userId: number | null;
  clientId: number | null;
  type: string;
  category: string;
  title: string;
  message: string;
  data: string | null;
  priority: string;
  isRead: boolean;
  readAt: string | null;
  actionUrl: string | null;
  actionLabel: string | null;
  relatedEntityType: string | null;
  relatedEntityId: number | null;
  expiresAt: string | null;
  createdAt: string;
}

export interface PortalNotificationsQueryParams {
  page?: number;
  pageSize?: number;
  unreadOnly?: boolean;
}

export interface PortalNotificationsPage {
  items: PortalNotificationItem[];
  totalCount: number;
  page: number;
  pageSize: number;
  totalPages: number;
}

export const PORTAL_NOTIFICATIONS_PAGE_SIZE = 20;
export const PORTAL_NOTIFICATIONS_DROPDOWN_PAGE_SIZE = 5;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function asNumber(value: unknown): number {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  return 0;
}

function asNullableNumber(value: unknown): number | null {
  if (value === null || value === undefined) return null;
  return asNumber(value);
}

function asNullableString(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed || null;
}

function normalizePortalNotificationItem(
  entry: unknown,
): PortalNotificationItem | null {
  if (!isRecord(entry)) return null;

  return {
    id: asNumber(entry.id),
    userId: asNullableNumber(entry.userId),
    clientId: asNullableNumber(entry.clientId),
    type: asNullableString(entry.type) ?? "",
    category: asNullableString(entry.category) ?? "",
    title: asNullableString(entry.title) ?? "",
    message: asNullableString(entry.message) ?? "",
    data: asNullableString(entry.data),
    priority: asNullableString(entry.priority) ?? "",
    isRead: Boolean(entry.isRead),
    readAt: asNullableString(entry.readAt),
    actionUrl: asNullableString(entry.actionUrl),
    actionLabel: asNullableString(entry.actionLabel),
    relatedEntityType: asNullableString(entry.relatedEntityType),
    relatedEntityId: asNullableNumber(entry.relatedEntityId),
    expiresAt: asNullableString(entry.expiresAt),
    createdAt: asNullableString(entry.createdAt) ?? "",
  };
}

function normalizePortalNotificationsPageResponse(
  payload: unknown,
): PortalNotificationsPage {
  if (Array.isArray(payload)) {
    const items = payload
      .map((entry) => normalizePortalNotificationItem(entry))
      .filter((entry): entry is PortalNotificationItem => entry !== null);

    return {
      items,
      totalCount: items.length,
      page: 1,
      pageSize: items.length || PORTAL_NOTIFICATIONS_PAGE_SIZE,
      totalPages: 1,
    };
  }

  const root = isRecord(payload) ? payload : {};
  const itemsRaw = Array.isArray(root.items) ? root.items : [];

  return {
    items: itemsRaw
      .map((entry) => normalizePortalNotificationItem(entry))
      .filter((entry): entry is PortalNotificationItem => entry !== null),
    totalCount: asNumber(root.totalCount),
    page: asNumber(root.page) || 1,
    pageSize: asNumber(root.pageSize) || PORTAL_NOTIFICATIONS_PAGE_SIZE,
    totalPages: asNumber(root.totalPages) || 1,
  };
}

function normalizePortalUnreadCount(payload: unknown): number {
  if (typeof payload === "number" && Number.isFinite(payload)) return payload;
  if (!isRecord(payload)) return 0;
  return asNumber(payload.count ?? payload.unread ?? payload.unreadCount);
}

export const portalNotificationsApi = baseApi.injectEndpoints({
  endpoints: (builder) => ({
    getPortalNotifications: builder.query<
      PortalNotificationsPage,
      PortalNotificationsQueryParams | void
    >({
      query: (params) => {
        const unreadOnly =
          params && "unreadOnly" in params ? params.unreadOnly : undefined;

        return {
          url: "/api/v1/portal/notifications",
          params: {
            page: params?.page,
            pageSize: params?.pageSize,
            unreadOnly,
          },
        };
      },
      transformResponse: (payload) =>
        normalizePortalNotificationsPageResponse(payload),
      providesTags: ["PortalNotifications"],
    }),
    getPortalNotificationUnreadCount: builder.query<number, void>({
      query: () => "/api/v1/portal/notifications/unread/count",
      transformResponse: (payload) => normalizePortalUnreadCount(payload),
      providesTags: ["PortalNotifications"],
    }),
    markPortalNotificationRead: builder.mutation<void, number>({
      query: (id) => ({
        url: `/api/v1/portal/notifications/${id}/read`,
        method: "PATCH",
      }),
      invalidatesTags: ["PortalNotifications"],
    }),
    markAllPortalNotificationsRead: builder.mutation<void, void>({
      query: () => ({
        url: "/api/v1/portal/notifications/read-all",
        method: "PATCH",
      }),
      invalidatesTags: ["PortalNotifications"],
    }),
    deletePortalNotification: builder.mutation<void, number>({
      query: (id) => ({
        url: `/api/v1/portal/notifications/${id}`,
        method: "DELETE",
      }),
      invalidatesTags: ["PortalNotifications"],
    }),
  }),
});

export const {
  useGetPortalNotificationsQuery,
  useLazyGetPortalNotificationsQuery,
  useGetPortalNotificationUnreadCountQuery,
  useMarkPortalNotificationReadMutation,
  useMarkAllPortalNotificationsReadMutation,
  useDeletePortalNotificationMutation,
} = portalNotificationsApi;

import { Search, Loader2 } from "lucide-react";
import NotificationListing from "./NotificationListing";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { Notification } from "../../types/notification";
import CustomSelect from "../form/CustomSelect";
import { Button } from "../ui/button";
import CustomInput from "../form/CustomInput";
import {
  type SuperAdminNotificationHistoryItem,
  useGetSuperAdminNotificationHistoryQuery,
  useReadSuperAdminNotificationMutation,
  useReadAllSuperAdminNotificationsMutation,
} from "@/store/api/superAdminApi";
import {
  useGetPortalNotificationUnreadCountQuery,
  useGetPortalNotificationsQuery,
  useMarkAllPortalNotificationsReadMutation,
  useMarkPortalNotificationReadMutation,
  PORTAL_NOTIFICATIONS_PAGE_SIZE,
  type PortalNotificationItem,
} from "@/store/api/portalNotificationsApi";
import { getApiErrorMessage } from "@/utils/apiError";
import { useInfiniteScroll } from "@/hooks/useInfiniteScroll";
import { mapPortalNotificationsToUi } from "@/utils/portalNotificationDisplay";

type FilterType = "All" | "Pending" | "Sent" | "Failed";

interface NotificationTabProps {
  notifications: Notification[];
  onMarkAllRead?: () => void;
  useApi?: boolean;
  usePortalApi?: boolean;
  onNotificationAction?: (notification: Notification) => void;
}

const NotificationTab = ({
  notifications,
  onMarkAllRead,
  useApi = false,
  usePortalApi = false,
  onNotificationAction,
}: NotificationTabProps) => {
  const listScrollRef = useRef<HTMLDivElement>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [filter, setFilter] = useState<FilterType>("All");
  const [page, setPage] = useState(0);
  const pageSize = 25;
  const [allRows, setAllRows] = useState<SuperAdminNotificationHistoryItem[]>([]);
  const [portalPage, setPortalPage] = useState(1);
  const [accumulatedPortalNotifications, setAccumulatedPortalNotifications] =
    useState<PortalNotificationItem[]>([]);
  const [totalPortalPages, setTotalPortalPages] = useState(1);

  const { data, isLoading, isFetching, isError, error } =
    useGetSuperAdminNotificationHistoryQuery(
      useApi
        ? {
            page,
            size: pageSize,
          }
        : undefined,
      {
        skip: !useApi,
        refetchOnMountOrArgChange: true,
      },
    );

  const [readNotification] = useReadSuperAdminNotificationMutation();
  const [readAllNotifications, { isLoading: isMarkingAllAdminRead }] =
    useReadAllSuperAdminNotificationsMutation();

  const portalListQueryArgs = useMemo(
    () => ({
      page: portalPage,
      pageSize: PORTAL_NOTIFICATIONS_PAGE_SIZE,
    }),
    [portalPage],
  );

  const {
    data: portalNotificationsPage,
    isLoading: isPortalLoading,
    isFetching: isPortalFetching,
    isError: isPortalError,
    error: portalError,
  } = useGetPortalNotificationsQuery(portalListQueryArgs, {
    skip: !usePortalApi,
    refetchOnMountOrArgChange: true,
  });
  const { data: portalUnreadCount = 0 } = useGetPortalNotificationUnreadCountQuery(
    undefined,
    { skip: !usePortalApi },
  );
  const [markPortalNotificationRead] = useMarkPortalNotificationReadMutation();
  const [markAllPortalNotificationsRead, { isLoading: isMarkingAllPortalRead }] =
    useMarkAllPortalNotificationsReadMutation();

  useEffect(() => {
    if (!usePortalApi) return;
    setPortalPage(1);
    setAccumulatedPortalNotifications([]);
    setTotalPortalPages(1);
  }, [usePortalApi]);

  useEffect(() => {
    if (!usePortalApi || !portalNotificationsPage) return;

    setTotalPortalPages(portalNotificationsPage.totalPages || 1);

    setAccumulatedPortalNotifications((current) => {
      if (portalNotificationsPage.page <= 1) {
        return portalNotificationsPage.items;
      }

      const existingIds = new Set(current.map((item) => item.id));
      const nextItems = portalNotificationsPage.items.filter(
        (item) => !existingIds.has(item.id),
      );
      return [...current, ...nextItems];
    });
  }, [portalNotificationsPage, usePortalApi]);

  const handleMarkRead = useCallback(
    async (id: string) => {
      if (usePortalApi) {
        try {
          await markPortalNotificationRead(Number(id)).unwrap();
        } catch {
          // Keep panel lightweight.
        }
        return;
      }

      if (!useApi) return;
      setAllRows((prev) =>
        prev.map((row) => (String(row.id) === id ? { ...row, isRead: true } : row)),
      );
      try {
        await readNotification(Number(id)).unwrap();
      } catch {
        // Optimistic update fallback
      }
    },
    [useApi, usePortalApi, markPortalNotificationRead, readNotification],
  );

  const handleMarkAllRead = useCallback(async () => {
    if (usePortalApi) {
      if (isMarkingAllPortalRead || portalUnreadCount === 0) return;
      try {
        await markAllPortalNotificationsRead().unwrap();
        setPortalPage(1);
        setAccumulatedPortalNotifications([]);
        setTotalPortalPages(1);
      } catch {
        // Keep panel lightweight.
      }
      return;
    }

    if (useApi) {
      if (isMarkingAllAdminRead) return;
      setAllRows((prev) => prev.map((row) => ({ ...row, isRead: true })));
      try {
        await readAllNotifications().unwrap();
      } catch {
        // Optimistic update fallback
      }
    }
    onMarkAllRead?.();
  }, [
    useApi,
    usePortalApi,
    onMarkAllRead,
    markAllPortalNotificationsRead,
    readAllNotifications,
    isMarkingAllPortalRead,
    isMarkingAllAdminRead,
    portalUnreadCount,
  ]);

  const rows = data ?? [];
  const hasMoreAdmin = useApi ? rows.length === pageSize : false;
  const hasMorePortal = usePortalApi ? portalPage < totalPortalPages : false;
  const hasMore = usePortalApi ? hasMorePortal : hasMoreAdmin;

  useEffect(() => {
    if (!useApi) return;
    if (!data) return;
    setAllRows((previous) => {
      if (page === 0) return data;
      const ids = new Set(previous.map((item) => item.id));
      const nextRows = data.filter((item) => !ids.has(item.id));
      return [...previous, ...nextRows];
    });
  }, [data, page, useApi]);

  useEffect(() => {
    if (!useApi) {
      setPage(0);
      setAllRows([]);
    }
  }, [useApi]);

  const onLoadMore = useCallback(() => {
    if (usePortalApi) {
      if (!hasMorePortal || isPortalFetching) return;
      setPortalPage((currentPage) => currentPage + 1);
      return;
    }

    if (!useApi || !hasMoreAdmin || isFetching) return;
    setPage((previous) => previous + 1);
  }, [hasMoreAdmin, hasMorePortal, isFetching, isPortalFetching, useApi, usePortalApi]);

  const isLoadingMore = usePortalApi
    ? isPortalFetching && portalPage > 1 && accumulatedPortalNotifications.length > 0
    : useApi && isFetching && page > 0 && allRows.length > 0;

  const { observerTarget } = useInfiniteScroll({
    onLoadMore,
    hasMore,
    isLoading: isLoadingMore,
    scrollRootRef: listScrollRef,
  });

  const mappedApiNotifications = useMemo<Notification[]>(() => {
    if (!useApi) return [];
    return allRows.map((item) => {
      const status = item.status.trim().toUpperCase();
      const isRead =
        item.isRead ??
        (status === "SENT" || status === "DELIVERED" || status === "SUCCESS");
      const timestampSource = item.sentAt || item.scheduledAt || item.createdAt;
      const parsedDate = timestampSource ? new Date(timestampSource) : null;
      const timestamp =
        parsedDate && !Number.isNaN(parsedDate.getTime())
          ? parsedDate.toLocaleString("en-US", {
              month: "short",
              day: "2-digit",
              year: "numeric",
              hour: "2-digit",
              minute: "2-digit",
            })
          : timestampSource || "—";
      const title = item.title || item.jobType || "Notification";
      const description =
        item.message || item.errorMessage || item.targetJson || "—";
      return {
        id: String(item.id),
        title,
        description,
        timestamp,
        isRead,
      };
    });
  }, [allRows, useApi]);

  const mappedPortalNotifications = useMemo<Notification[]>(() => {
    if (!usePortalApi) return [];
    return mapPortalNotificationsToUi(accumulatedPortalNotifications);
  }, [accumulatedPortalNotifications, usePortalApi]);

  const sourceNotifications = useApi
    ? mappedApiNotifications
    : usePortalApi
      ? mappedPortalNotifications
      : notifications;

  const filteredNotifications = sourceNotifications.filter((notification) => {
    const matchesSearch =
      notification.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      notification.description
        .toLowerCase()
        .includes(searchQuery.toLowerCase());

    let matchesFilter = true;
    if (filter === "Pending") matchesFilter = !notification.isRead;
    if (filter === "Sent") matchesFilter = notification.isRead;
    if (filter === "Failed") {
      const plainText =
        `${notification.title} ${notification.description}`.toLowerCase();
      matchesFilter =
        plainText.includes("failed") ||
        plainText.includes("error") ||
        plainText.includes("unsent");
    }

    return matchesSearch && matchesFilter;
  });

  const isMarkingAllRead = usePortalApi
    ? isMarkingAllPortalRead
    : useApi
      ? isMarkingAllAdminRead
      : false;

  const isMarkAllReadDisabled =
    isMarkingAllRead || (usePortalApi && portalUnreadCount === 0);

  return (
    <div className="flex flex-col gap-5 overflow-auto">
      <div className="flex items-center justify-between gap-2 px-6">
        <div className="flex items-center gap-2">
          <CustomInput
            icon={<Search size={18} className="text-(--text-neutral-600)" />}
            type="text"
            placeholder="Search notifications..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="min-h-10 max-w-70 rounded-full pt-1.75 pb-0"
          />

          <CustomSelect
            options={[
              { label: "All", value: "All" },
              { label: "Pending", value: "Pending" },
              { label: "Sent", value: "Sent" },
              { label: "Failed", value: "Failed" },
            ]}
            value={filter}
            onChange={(value) => setFilter(value as FilterType)}
            className="max-h-10 w-33 rounded-full pb-0 pt-0"
            isSearch={false}
          />
        </div>
        <Button
          onClick={handleMarkAllRead}
          disabled={isMarkAllReadDisabled}
          className="flex h-auto w-fit cursor-pointer items-center gap-2 bg-transparent p-0 text-sm font-medium text-(--text-primary-500) transition-colors hover:bg-transparent hover:text-(--text-primary-500)/80 disabled:cursor-not-allowed disabled:opacity-60"
        >
          {isMarkingAllRead ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              Marking...
            </>
          ) : (
            "Mark all as read"
          )}
        </Button>
      </div>
      <div ref={listScrollRef} className="flex-1 overflow-y-auto">
        {useApi && isLoading && allRows.length === 0 ? (
          <div className="px-6 py-4 text-sm text-[#667483]">
            Loading notifications...
          </div>
        ) : usePortalApi &&
          (isPortalLoading || isPortalFetching) &&
          accumulatedPortalNotifications.length === 0 ? (
          <div className="px-6 py-4 text-sm text-[#667483]">
            Loading notifications...
          </div>
        ) : useApi && isError ? (
          <div className="px-6 py-4 text-sm text-(--status-denied)">
            {getApiErrorMessage(error)}
          </div>
        ) : usePortalApi && isPortalError ? (
          <div className="px-6 py-4 text-sm text-(--status-denied)">
            {getApiErrorMessage(portalError)}
          </div>
        ) : filteredNotifications.length > 0 ? (
          filteredNotifications.map((notification) => (
            <NotificationListing
              key={notification.id}
              notification={notification}
              onMarkRead={useApi || usePortalApi ? handleMarkRead : undefined}
              onAction={usePortalApi ? undefined : onNotificationAction}
            />
          ))
        ) : (
          <div className="flex h-full flex-col items-center justify-center px-6 text-center">
            <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-(--neutral-100)">
              <Search className="text-(--text-neutral-600)" size={32} />
            </div>
            <p className="mb-1 text-lg font-medium text-(--text-title-dark)">
              No notifications found
            </p>
            <p className="text-sm text-(--text-neutral-600)">
              Try adjusting your filters or search query
            </p>
          </div>
        )}
        {(useApi || usePortalApi) && filteredNotifications.length > 0 ? (
          <div
            ref={observerTarget}
            className="flex h-10 w-full items-center justify-center"
          >
            {isLoadingMore ? (
              <Loader2 className="h-4 w-4 animate-spin text-(--primary-500)" />
            ) : null}
          </div>
        ) : null}
      </div>
    </div>
  );
};

