  | "PHOTOGRAPHY"
  | "ELECTRONIC_RECORDS"
  | "PARENTAL_CONSENT"
  | "EMERGENCY_CONTACT"
  | "OTHER";

export interface PortalConsent {
  id: number;
  clientId: number;
  consentType: string;
  consentVersion: string;
  granted: boolean;
  grantedAt: string | null;
  withdrawnAt: string | null;
  notes: string | null;
  createdAt: string;
  updatedAt?: string;
}

export interface PortalConsentTogglePayload {
  consentType: PortalConsentTypeEnum;
  granted: boolean;
  consentVersion?: string;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function asNumber(value: unknown): number {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  return 0;
}

function asNullableString(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed || null;
}

function normalizePortalConsent(entry: unknown): PortalConsent | null {
  if (!isRecord(entry)) return null;

  return {
    id: asNumber(entry.id),
    clientId: asNumber(entry.clientId),
    consentType: asNullableString(entry.consentType) ?? "",
    consentVersion: asNullableString(entry.consentVersion) ?? "1.0",
    granted: Boolean(entry.granted),
    grantedAt: asNullableString(entry.grantedAt),
    withdrawnAt: asNullableString(entry.withdrawnAt),
    notes: asNullableString(entry.notes),
    createdAt: asNullableString(entry.createdAt) ?? "",
    updatedAt: asNullableString(entry.updatedAt) ?? undefined,
  };
}

function normalizePortalConsentsResponse(payload: unknown): PortalConsent[] {
  const rows = Array.isArray(payload) ? payload : [];
  return rows
    .map((entry) => normalizePortalConsent(entry))
    .filter((entry): entry is PortalConsent => entry !== null);
}

export const portalConsentsApi = baseApi.injectEndpoints({
  endpoints: (builder) => ({
    getPortalConsents: builder.query<PortalConsent[], void>({
      query: () => "/api/v1/portal/consents",
      transformResponse: (payload) => normalizePortalConsentsResponse(payload),
      providesTags: ["PortalConsents"],
    }),
    togglePortalConsent: builder.mutation<
      PortalConsent,
      PortalConsentTogglePayload
    >({
      query: (body) => ({
        url: "/api/v1/portal/consents/toggle",
        method: "PUT",
        body: {
          consentType: body.consentType,
          granted: body.granted,
          consentVersion: body.consentVersion ?? "1.0",
        },
      }),
      transformResponse: (payload) =>
        normalizePortalConsent(payload) ?? {
          id: 0,
          clientId: 0,
          consentType: "",
          consentVersion: "1.0",
          granted: false,
          grantedAt: null,
          withdrawnAt: null,
          notes: null,
          createdAt: "",
        },
      invalidatesTags: ["PortalConsents"],
    }),
  }),
});

export const {
  useGetPortalConsentsQuery,
  useTogglePortalConsentMutation,
} = portalConsentsApi;

import type { PortalConsent, PortalConsentTypeEnum } from "@/store/api/portalConsentsApi";
import type {
  ConsentSetting,
  ConsentSettingTemplate,
} from "@/types/privacy-settings.type";

const CONSENT_TYPE_DISPLAY_NAMES: Record<PortalConsentTypeEnum, string> = {
  AI_PROCESSING: "AI Processing Consent",
  DATA_SHARING: "Data Sharing",
  RESEARCH: "Research Participation",
  MARKETING: "Marketing Communications",
  SMS_COMMUNICATION: "SMS Communication",
  EMAIL_COMMUNICATION: "Email Communication",
  TELEHEALTH: "Telehealth Consent",
  AUDIO_RECORDING: "Audio Recording",
  VIDEO_RECORDING: "Video Recording",
  HIPAA_PRIVACY: "HIPAA Privacy Notice",
  HIPAA_AUTHORIZATION: "HIPAA Authorization",
  TREATMENT: "Consent for Treatment",
  INSURANCE_SHARING: "Insurance Information Sharing",
  PAYMENT_AUTHORIZATION: "Payment Authorization",
  PHOTOGRAPHY: "Photography Consent",
  ELECTRONIC_RECORDS: "Electronic Health Records",
  PARENTAL_CONSENT: "Parental/Guardian Consent",
  EMERGENCY_CONTACT: "Emergency Contact Authorization",
  OTHER: "Other",
};

function normalizeConsentTypeKey(value: string): string {
  return value.trim().toLowerCase().replace(/[^a-z0-9]+/g, "");
}

function consentTypeKeys(consentType: PortalConsentTypeEnum): Set<string> {
  const displayName = CONSENT_TYPE_DISPLAY_NAMES[consentType];
  return new Set(
    [
      consentType,
      displayName,
      consentType.replace(/_/g, " "),
    ].map(normalizeConsentTypeKey),
  );
}

export function matchesPortalConsentType(
  apiConsentType: string,
  consentType: PortalConsentTypeEnum,
): boolean {
  const normalizedApiType = normalizeConsentTypeKey(apiConsentType);
  return consentTypeKeys(consentType).has(normalizedApiType);
}

function getConsentTimestamp(consent: PortalConsent): number {
  const value =
    consent.grantedAt ??
    consent.updatedAt ??
    consent.createdAt ??
    "";
  const parsed = Date.parse(value);
  return Number.isNaN(parsed) ? 0 : parsed;
}

export function getLatestPortalConsentForType(
  consents: PortalConsent[],
  consentType: PortalConsentTypeEnum,
): PortalConsent | null {
  const matches = consents.filter((consent) =>
    matchesPortalConsentType(consent.consentType, consentType),
  );

  if (matches.length === 0) return null;

  return matches.sort(
    (left, right) => getConsentTimestamp(right) - getConsentTimestamp(left),
  )[0];
}

export function buildConsentSettingsFromApi(
  templates: ConsentSettingTemplate[],
  apiConsents: PortalConsent[],
): ConsentSetting[] {
  return templates.map((template) => {
    const record = getLatestPortalConsentForType(
      apiConsents,
      template.consentType,
    );
    const granted = record?.granted ?? false;

    return {
      ...template,
      enabled: granted,
      status: granted ? "granted" : "withdrawn",
    };
  });
}

