import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { ArrowLeft, ChevronDown, ChevronUp, Info, Loader2 } from "lucide-react";
import { Badge } from "../../../components/ui/badge";
import { Switch } from "../../../components/ui/switch";
import Toast from "@/components/shared/Toast";
import { PRIVACY_SETTINGS_STATIC_CONTENT } from "../user.static";
import {
  useGetPortalConsentsQuery,
  useTogglePortalConsentMutation,
} from "@/store/api/portalConsentsApi";
import { getApiErrorMessage } from "@/utils/apiError";
import { buildConsentSettingsFromApi } from "@/utils/portalConsentDisplay";
import type { ConsentSetting } from "../../../types/privacy-settings.type";

type ConsentOverride = Pick<ConsentSetting, "enabled" | "status">;

const PrivacySettings = () => {
  const navigate = useNavigate();
  const consentTemplates = PRIVACY_SETTINGS_STATIC_CONTENT.consentSettings;

  const [expandedSections, setExpandedSections] = useState<Set<string>>(
    new Set(["ai-documentation"]),
  );
  const [consentOverrides, setConsentOverrides] = useState<
    Record<string, ConsentOverride>
  >({});
  const [togglingConsentId, setTogglingConsentId] = useState<string | null>(
    null,
  );
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const [toastType, setToastType] = useState<"success" | "error" | "info">(
    "error",
  );

  const {
    data: portalConsents = [],
    isLoading,
    isFetching,
    isError,
    error,
  } = useGetPortalConsentsQuery();

  const [togglePortalConsent] = useTogglePortalConsentMutation();

  const consentSettings = useMemo(
    () => buildConsentSettingsFromApi(consentTemplates, portalConsents),
    [consentTemplates, portalConsents],
  );

  const displayConsentSettings = useMemo(
    () =>
      consentSettings.map((setting) => {
        const override = consentOverrides[setting.id];
        return override ? { ...setting, ...override } : setting;
      }),
    [consentSettings, consentOverrides],
  );

  const isInitialLoading =
    (isLoading || isFetching) && portalConsents.length === 0;

  useEffect(() => {
    if (!isError || !error) return;
    setToastType("error");
    setToastMessage(getApiErrorMessage(error));
  }, [isError, error]);

  const toggleSection = (id: string) => {
    const newExpanded = new Set(expandedSections);
    if (newExpanded.has(id)) {
      newExpanded.delete(id);
    } else {
      newExpanded.add(id);
    }
    setExpandedSections(newExpanded);
  };

  const handleToggle = async (setting: ConsentSetting, checked: boolean) => {
    if (togglingConsentId) return;

    const previousState: ConsentOverride = {
      enabled: setting.enabled,
      status: setting.status,
    };

    setConsentOverrides((current) => ({
      ...current,
      [setting.id]: {
        enabled: checked,
        status: checked ? "granted" : "withdrawn",
      },
    }));
    setTogglingConsentId(setting.id);

    try {
      await togglePortalConsent({
        consentType: setting.consentType,
        granted: checked,
      }).unwrap();

      setConsentOverrides((current) => {
        const next = { ...current };
        delete next[setting.id];
        return next;
      });
    } catch (toggleError) {
      setConsentOverrides((current) => ({
        ...current,
        [setting.id]: previousState,
      }));
      setToastType("error");
      setToastMessage(getApiErrorMessage(toggleError));
    } finally {
      setTogglingConsentId(null);
    }
  };

  const dataProtectionCards =
    PRIVACY_SETTINGS_STATIC_CONTENT.dataProtectionCards;

  return (
    <div className="min-h-screen bg-(--bg-primary-light) py-8 px-4">
      <div className="max-w-4xl mx-auto space-y-6">
        <button
          onClick={() => navigate(-1)}
          className="flex items-center gap-2 text-gray-600 mb-6 hover:text-gray-900 cursor-pointer transition-colors"
        >
          <ArrowLeft size={20} />
          <span className="text-sm font-medium">Back</span>
        </button>

        {/* Privacy & Consent Settings Card */}
        <div className="bg-white rounded-xl shadow-sm p-8">
          <div className="flex items-center gap-3 mb-2">
            <img
              src="/settings/privacy.svg"
              alt="Privacy Settings"
              className="text-(--bg-primary-dark)"
            />
          </div>
          <h1 className="text-[20px] leading-[28px] font-semibold text-[#1B1C20]">
            Privacy & Consent Settings
          </h1>
          <p className="text-[16px] leading-[24px] font-normal text-[#33363D] mb-4">
            Manage how your personal health information is used. You can change
            these settings at any time.
          </p>
          <div className="border-b border-[#EDEEF1] mb-8"></div>

          {/* Consent Settings */}
          <div className="space-y-6">
            {isInitialLoading ? (
              <div className="flex items-center justify-center gap-2 py-12 text-sm text-[#5B616E]">
                <Loader2 className="h-5 w-5 animate-spin" />
                <span>Loading consent settings...</span>
              </div>
            ) : (
              displayConsentSettings.map((setting) => {
                const isToggling = togglingConsentId === setting.id;
                const isSwitchDisabled =
                  isInitialLoading || Boolean(togglingConsentId);

                return (
                  <div
                    key={setting.id}
                    className="border-b border-[#EDEEF1] pb-6 last:border-b-0 last:pb-0"
                  >
                    <div className="flex items-start justify-between gap-4">
                      <div className="flex-1">
                        <h3 className="text-[18px] leading-[26px] font-semibold text-[#1B1C20] mb-2">
                          {setting.title}
                        </h3>
                        <p className="text-[14px] leading-[22px] font-normal text-[#5B616E] mb-3">
                          {setting.description}
                        </p>
                        <div className="flex items-center gap-2 mb-2">
                          <span className="text-[12px] leading-[18px] font-medium text-[#1B1C20]">
                            Status:
                          </span>
                          <Badge
                            variant={
                              setting.status === "granted"
                                ? "default"
                                : "outline"
                            }
                            className={
                              setting.status === "granted"
                                ? "bg-[#D0FBE3] text-[#007C54] border-[#D0FBE3]"
                                : "bg-[#EDEEF1] text-[#1B1C20] border-[#EDEEF1]"
                            }
                          >
                            {setting.status === "granted"
                              ? "Consent Granted"
                              : "Consent Withdrawn"}
                          </Badge>
                          {isToggling ? (
                            <Loader2 className="h-4 w-4 animate-spin text-[#5B616E]" />
                          ) : null}
                        </div>
                        {setting.details && (
                          <button
                            onClick={() => toggleSection(setting.id)}
                            className="inline-flex h-[36px] items-center justify-between gap-2 rounded-full py-[7px] text-[14px] leading-[22px] font-semibold text-(--btn-link-text) hover:text-(--btn-link-text-hover) active:text-(--btn-link-text-pressed) transition-colors cursor-pointer"
                          >
                            <Info size={20} />
                            <span className="whitespace-nowrap">Show details</span>
                            {expandedSections.has(setting.id) ? (
                              <ChevronUp size={20} />
                            ) : (
                              <ChevronDown size={20} />
                            )}
                          </button>
                        )}
                        {setting.details && expandedSections.has(setting.id) && (
                          <ul className="mt-4 space-y-2 pl-6 list-disc">
                            {setting.details.map((detail, index) => (
                              <li
                                key={index}
                                className="text-sm text-(--text-neutral-600)"
                              >
                                {detail}
                              </li>
                            ))}
                          </ul>
                        )}
                      </div>
                      <Switch
                        checked={setting.enabled}
                        disabled={isSwitchDisabled}
                        onCheckedChange={(checked) =>
                          handleToggle(setting, checked)
                        }
                      />
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>

        {/* Data Protection Information Section */}
        <div className="rounded-xl">
          <h2 className="text-[16px] leading-[24px] font-semibold text-[#1B1C20] mb-2">
            Data Protection Information
          </h2>
          <p className="text-[14px] leading-[22px] font-normal text-[#33363D] mb-6">
            Manage how your personal health information is used. You can change
            these settings at any time.
          </p>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {dataProtectionCards.map((card, index) => (
              <div
                key={index}
                className="bg-white rounded-lg p-4 border border-[#EDEEF1]"
              >
                <img
                  src={card.iconSrc}
                  alt={card.title}
                  className="mb-3 h-12 w-12"
                />
                <h3 className="text-[18px] leading-[26px] font-semibold text-[#1B1C20] mb-2">
                  {card.title}
                </h3>
                <p className="text-[14px] leading-[22px] font-normal text-[#5B616E]">
                  {card.title === "Questions?" ? (
                    <>
                      Contact our Privacy Officer at{" "}
                      <a
                        href="mailto:privacy@smarthub.com"
                        className="font-semibold text-[#000000] underline underline-offset-[3px] cursor-pointer"
                      >
                        privacy@smarthub.com
                      </a>{" "}
                      or speak with your therapist.
                    </>
                  ) : (
                    card.description
                  )}
                </p>
              </div>
            ))}
          </div>
        </div>
      </div>

      {toastMessage ? (
        <Toast
          message={toastMessage}
          type={toastType}
          onClose={() => setToastMessage(null)}
        />
      ) : null}
    </div>
  );
};

export default PrivacySettings;

import type { PortalConsent, PortalConsentTypeEnum } from "@/store/api/portalConsentsApi";
import type { ConsentSetting } from "@/types/privacy-settings.type";

const CONSENT_TYPE_DISPLAY_NAMES: Record<PortalConsentTypeEnum, string> = {
