interface PortalFormFieldRendererProps {
  field: PortalFormAssignmentField;
  control: Control<PortalClinicalFormValues>;
  value: string;
  disabled?: boolean;
  onValueChange: (fieldId: number, value: string) => void;
}

const PortalFormFieldRenderer = ({
  field,
  control,
  value,
  disabled = false,
  onValueChange,
}: PortalFormFieldRendererProps) => {
  const fieldType = field.fieldType.trim().toLowerCase();

  if (isPortalFormSignatureField(field)) {
    return null;
  }

  if (fieldType === "heading") {
    return (
      <section>
        <h2 className="text-lg font-semibold text-(--text-primary-dark)">
          {field.label}
        </h2>
        {field.helpText ? (
          <p className="mt-2 text-sm text-(--text-neutral-600)">{field.helpText}</p>
        ) : null}
      </section>
    );
  }

  if (fieldType === "info_text") {
    return (
      <section>
        {field.label ? (
          <h3 className="mb-2 text-base font-semibold text-(--text-primary-dark)">
            {field.label}
          </h3>
        ) : null}
        <p className="text-sm leading-relaxed text-(--text-primary-dark) whitespace-pre-wrap">
          {field.helpText || field.placeholder || field.label}
        </p>
      </section>
    );
  }

  if (fieldType === "textarea") {
    return (
      <section className="space-y-2">
        <label className="text-sm font-medium text-(--text-primary-dark)">
          {field.label}
          {field.isRequired ? <span className="text-red-500"> *</span> : null}
        </label>
        <textarea
          value={value}
          disabled={disabled}
          placeholder={field.placeholder ?? undefined}
          onChange={(event) => onValueChange(field.id, event.target.value)}
          className="min-h-28 w-full rounded-xl border border-(--neutral-100) px-4 py-3 text-sm text-(--text-primary-dark) outline-none focus:border-(--bg-primary-dark) disabled:cursor-not-allowed disabled:bg-gray-50"
        />
        {field.helpText ? (
          <p className="text-xs text-(--text-neutral-600)">{field.helpText}</p>
        ) : null}
      </section>
    );
  }

  if (fieldType === "select") {
    const options = parsePortalFormFieldOptions(field.options);

    return (
      <section className="space-y-2">
        <label className="text-sm font-medium text-(--text-primary-dark)">
          {field.label}
          {field.isRequired ? <span className="text-red-500"> *</span> : null}
        </label>
        <select
          value={value}
          disabled={disabled}
          onChange={(event) => onValueChange(field.id, event.target.value)}
          className="h-11 w-full rounded-xl border border-(--neutral-100) px-4 text-sm text-(--text-primary-dark) outline-none focus:border-(--bg-primary-dark) disabled:cursor-not-allowed disabled:bg-gray-50"
        >
          <option value="">Select an option</option>
          {options.map((option) => (
            <option key={option} value={option}>
              {option}
            </option>
          ))}
        </select>
      </section>
    );
  }

  if (fieldType === "radio") {
    const options = parsePortalFormFieldOptions(field.options);

    return (
      <section className="space-y-3">
        <p className="text-sm font-medium text-(--text-primary-dark)">
          {field.label}
          {field.isRequired ? <span className="text-red-500"> *</span> : null}
        </p>
        <div className="space-y-2">
          {options.map((option) => (
            <label
              key={option}
              className="flex items-center gap-2 text-sm text-(--text-primary-dark)"
            >
              <input
                type="radio"
                name={`field-${field.id}`}
                value={option}
                checked={value === option}
                disabled={disabled}
                onChange={() => onValueChange(field.id, option)}
                className="h-4 w-4"
              />
              <span>{option}</span>
            </label>
          ))}
        </div>
      </section>
    );
  }

  if (fieldType === "checkbox") {
    return (
      <section>
        <label className="flex items-start gap-3 text-sm text-(--text-primary-dark)">
          <input
            type="checkbox"
            checked={value === "true"}
            disabled={disabled}
            onChange={(event) =>
              onValueChange(field.id, event.target.checked ? "true" : "false")
            }
            className="mt-1 h-4 w-4"
          />
          <span>
            {field.label}
            {field.isRequired ? <span className="text-red-500"> *</span> : null}
          </span>
        </label>
        {field.helpText ? (
          <p className="mt-2 pl-7 text-xs text-(--text-neutral-600)">
            {field.helpText}
          </p>
        ) : null}
      </section>
    );
  }

  if (fieldType === "multi_select") {
    const options = parsePortalFormFieldOptions(field.options);
    const selectedValues = value
      ? value.split("||").map((entry) => entry.trim()).filter(Boolean)
      : [];

    return (
      <section className="space-y-3">
        <p className="text-sm font-medium text-(--text-primary-dark)">
          {field.label}
          {field.isRequired ? <span className="text-red-500"> *</span> : null}
        </p>
        <div className="space-y-2">
          {options.map((option) => (
            <label
              key={option}
              className="flex items-center gap-2 text-sm text-(--text-primary-dark)"
            >
              <input
                type="checkbox"
                checked={selectedValues.includes(option)}
                disabled={disabled}
                onChange={(event) => {
                  const nextValues = event.target.checked
                    ? [...selectedValues, option]
                    : selectedValues.filter((entry) => entry !== option);
                  onValueChange(field.id, nextValues.join("||"));
                }}
                className="h-4 w-4"
              />
              <span>{option}</span>
            </label>
          ))}
        </div>
      </section>
    );
  }

  if (fieldType === "date") {
    return (
      <section className="space-y-2">
        <CustomDatePicker
          label={field.label}
          required={field.isRequired}
          disabled={disabled}
          date={value ? new Date(value) : null}
          onDateChange={(nextDate) =>
            onValueChange(
              field.id,
              nextDate ? nextDate.toISOString().slice(0, 10) : "",
            )
          }
        />
      </section>
    );
  }

  if (isPortalFormReadOnlyField(field)) {
    return null;
  }

  return (
    <section>
      <CustomInput
        control={control}
        name={`field_${field.id}`}
        label={field.label}
        required={field.isRequired}
        disabled={disabled}
        placeholder={field.placeholder ?? undefined}
        hint={field.helpText ?? undefined}
        value={value}
        onChange={(event) => onValueChange(field.id, event.target.value)}
      />
    </section>
  );
};

export default PortalFormFieldRenderer;

