import { useCallback, useEffect, useMemo, useState } from "react";
import FilterDropdown from "../../../components/clinical-forms/FilterDropdown";
import ClinicalFormCard from "../../../components/clinical-forms/ClinicalFormCard";
import { Loader, Loader2 } from "lucide-react";
import { useInfiniteScroll } from "@/hooks/useInfiniteScroll";
import type { FormStatus } from "../../../types/clinical-form.type";
import CustomInput from "@/components/form/CustomInput";
import { Search } from "lucide-react";
import ScrollToTopButton from "@/components/shared/ScrollToTopButton";
import Toast from "@/components/shared/Toast";
import { useGetPortalFormAssignmentsQuery } from "@/store/api/portalFormsApi";
import { getApiErrorMessage } from "@/utils/apiError";
import {
  filterPortalFormCards,
  mapPortalFormAssignmentToCard,
} from "@/utils/portalFormDisplay";

const ITEMS_PER_PAGE = 20;

const ClinicalForms = () => {
  const [selectedFilters, setSelectedFilters] = useState<FormStatus[]>([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [displayedItems, setDisplayedItems] = useState(ITEMS_PER_PAGE);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const {
    data: assignments = [],
    isLoading,
    isFetching,
    isError,
    error,
  } = useGetPortalFormAssignmentsQuery();

  const formCards = useMemo(
    () => assignments.map(mapPortalFormAssignmentToCard),
    [assignments],
  );

  const filteredForms = useMemo(
    () => filterPortalFormCards(formCards, searchQuery, selectedFilters),
    [formCards, searchQuery, selectedFilters],
  );

  const isInitialLoading = (isLoading || isFetching) && assignments.length === 0;

  useEffect(() => {
    if (!isError || !error) return;
    setToastMessage(getApiErrorMessage(error));
  }, [error, isError]);

  useEffect(() => {
    setDisplayedItems(ITEMS_PER_PAGE);
  }, [searchQuery, selectedFilters, assignments.length]);

  const handleLoadMore = useCallback(() => {
    setDisplayedItems((previous) => previous + ITEMS_PER_PAGE);
  }, []);

  const { observerTarget } = useInfiniteScroll({
    onLoadMore: handleLoadMore,
    hasMore: displayedItems < filteredForms.length,
    isLoading: false,
  });

  const currentForms = filteredForms.slice(0, displayedItems);

  return (
    <div className="w-full">
      <ScrollToTopButton />
      <div className="mb-6 flex items-center gap-2 justify-start">
        <div>
          <CustomInput
            placeholder="Search"
            value={searchQuery}
            onChange={(event) => setSearchQuery(event.target.value)}
            icon={<Search size={18} className="text-(--text-neutral-600)" />}
            className="rounded-full min-h-10 md:w-79 pb-0 pt-1.75"
          />
        </div>
        <FilterDropdown
          selectedFilters={selectedFilters}
          onFilterChange={setSelectedFilters}
        />
      </div>

      {isInitialLoading ? (
        <div className="flex items-center justify-center gap-2 py-16 text-sm text-(--text-neutral-600)">
          <Loader2 className="h-5 w-5 animate-spin" />
          <span>Loading clinical forms...</span>
        </div>
      ) : currentForms.length === 0 ? (
        <div className="py-16 text-center text-sm text-(--text-neutral-600)">
          No clinical forms found.
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {currentForms.map((form) => (
            <ClinicalFormCard key={form.id} form={form} />
          ))}
        </div>
      )}

      <div
        ref={observerTarget}
        className="h-10 w-full flex items-center justify-center mt-4"
      >
        {displayedItems < filteredForms.length ? (
          <Loader className="animate-spin text-(--primary-500)" />
        ) : null}
      </div>

      {toastMessage ? (
        <Toast
          message={toastMessage}
          type="error"
          onClose={() => setToastMessage(null)}
        />
      ) : null}
    </div>
  );
};

export default ClinicalForms;

import { useEffect, useMemo, useRef, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { ArrowLeft, Clock, Loader2 } from "lucide-react";
import { Badge } from "../../../components/ui/badge";
import { Form } from "../../../components/ui/form";
import SignatureForm from "../../../components/clinical-forms/SignatureForm";
import PortalFormFieldRenderer from "../../../components/clinical-forms/PortalFormFieldRenderer";
import Toast from "@/components/shared/Toast";
import { useForm } from "react-hook-form";
import { cn } from "@/lib/utils";
import { useGetPortalMeQuery } from "@/store/api/portalApi";
import {
  useGetPortalFormAssignmentByIdQuery,
  useGetPortalFormResponsesQuery,
  useGetPortalFormSignatureQuery,
  useSavePortalFormResponseMutation,
  useSavePortalFormSignatureMutation,
  useSubmitPortalFormAssignmentMutation,
} from "@/store/api/portalFormsApi";
import { getApiErrorMessage } from "@/utils/apiError";
import {
  buildPortalFormFieldValues,
  calculatePortalFormProgress,
  getPortalFormDetailTitle,
  getPortalFormStatusLabel,
  isPortalFormReadOnly,
  isPortalFormSignatureField,
  mapPortalFormStatus,
} from "@/utils/portalFormDisplay";
import type { PortalClinicalFormValues } from "@/components/clinical-forms/PortalFormFieldRenderer";

const ClinicalFormDetail = () => {
  const navigate = useNavigate();
  const { formId } = useParams<{ formId: string }>();
  const assignmentId = Number(formId);
  const hasValidAssignmentId = Number.isFinite(assignmentId) && assignmentId > 0;

  const [fieldValues, setFieldValues] = useState<Record<number, string>>({});
  const [signedAt, setSignedAt] = useState<Date | undefined>(undefined);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const [toastType, setToastType] = useState<"success" | "error">("error");
  const saveTimersRef = useRef<Record<number, ReturnType<typeof setTimeout>>>(
    {},
  );

  const { data: portalMe } = useGetPortalMeQuery();

  const {
    data: assignmentDetail,
    isLoading: isLoadingDetail,
    isFetching: isFetchingDetail,
    isError: isDetailError,
    error: detailError,
  } = useGetPortalFormAssignmentByIdQuery(assignmentId, {
    skip: !hasValidAssignmentId,
  });

  const {
    data: savedResponses = [],
    isLoading: isLoadingResponses,
    isFetching: isFetchingResponses,
    isError: isResponsesError,
    error: responsesError,
  } = useGetPortalFormResponsesQuery(assignmentId, {
    skip: !hasValidAssignmentId,
  });

  const {
    data: savedSignature,
    isLoading: isLoadingSignature,
    isFetching: isFetchingSignature,
    isError: isSignatureError,
    error: signatureError,
  } = useGetPortalFormSignatureQuery(assignmentId, {
    skip: !hasValidAssignmentId,
  });

  const [savePortalFormResponse] = useSavePortalFormResponseMutation();
  const [savePortalFormSignature] = useSavePortalFormSignatureMutation();
  const [submitPortalFormAssignment] = useSubmitPortalFormAssignmentMutation();

  const form = useForm<PortalClinicalFormValues>({
    defaultValues: {
      clientName: "",
      date: new Date().toISOString().slice(0, 10),
      signature: "",
    },
  });

  const isReadOnly = isPortalFormReadOnly(assignmentDetail?.status);
  const formStatus = mapPortalFormStatus(assignmentDetail?.status);
  const requiresSignature =
    Boolean(assignmentDetail?.requiresSignature) ||
    (assignmentDetail?.fields ?? []).some(isPortalFormSignatureField);

  const interactiveFields = useMemo(
    () =>
      (assignmentDetail?.fields ?? []).filter(
        (field) => !isPortalFormSignatureField(field),
      ),
    [assignmentDetail?.fields],
  );

  const isInitialLoading =
    !hasValidAssignmentId ||
    ((isLoadingDetail ||
      isFetchingDetail ||
      isLoadingResponses ||
      isFetchingResponses ||
      isLoadingSignature ||
      isFetchingSignature) &&
      !assignmentDetail);

  useEffect(() => {
    if (!portalMe?.fullName) return;
    form.setValue("clientName", portalMe.fullName);
  }, [form, portalMe?.fullName]);

  useEffect(() => {
    if (!savedResponses.length) return;
    setFieldValues(buildPortalFormFieldValues(savedResponses));
  }, [savedResponses]);

  useEffect(() => {
    if (!savedSignature?.signatureData) return;
    form.setValue("signature", savedSignature.signatureData);
    if (savedSignature.signedAt) {
      const parsed = new Date(savedSignature.signedAt);
      if (!Number.isNaN(parsed.getTime())) {
        setSignedAt(parsed);
      }
    }
  }, [form, savedSignature]);

  useEffect(() => {
    const loadError = detailError ?? responsesError ?? signatureError;
    if (!isDetailError && !isResponsesError && !isSignatureError) return;
    setToastType("error");
    setToastMessage(getApiErrorMessage(loadError));
  }, [
    detailError,
    isDetailError,
    isResponsesError,
    isSignatureError,
    responsesError,
    signatureError,
  ]);

  useEffect(() => {
    return () => {
      Object.values(saveTimersRef.current).forEach((timer) => {
        clearTimeout(timer);
      });
    };
  }, []);

  const signatureValue = form.watch("signature");
  const progress = useMemo(
    () =>
      calculatePortalFormProgress(
        assignmentDetail?.fields ?? [],
        fieldValues,
        Boolean(signatureValue?.trim()),
        requiresSignature,
      ),
    [
      assignmentDetail?.fields,
      fieldValues,
      requiresSignature,
      signatureValue,
    ],
  );

  const persistFieldValue = async (fieldId: number, value: string) => {
    if (!hasValidAssignmentId || isReadOnly) return;

    try {
      await savePortalFormResponse({
        assignmentId,
        assignmentFieldId: fieldId,
        value,
      }).unwrap();
    } catch (saveError) {
      setToastType("error");
      setToastMessage(getApiErrorMessage(saveError));
    }
  };

  const handleFieldValueChange = (fieldId: number, value: string) => {
    setFieldValues((current) => ({
      ...current,
      [fieldId]: value,
    }));

    if (isReadOnly) return;

    if (saveTimersRef.current[fieldId]) {
      clearTimeout(saveTimersRef.current[fieldId]);
    }

    saveTimersRef.current[fieldId] = setTimeout(() => {
      void persistFieldValue(fieldId, value);
    }, 500);
  };

  const validateBeforeSubmit = () => {
    const missingRequiredField = interactiveFields.find(
      (field) =>
        field.isRequired && !isPortalFormSignatureField(field) && !fieldValues[field.id]?.trim(),
    );

    if (missingRequiredField) {
      setToastType("error");
      setToastMessage(`Please complete "${missingRequiredField.label}" before submitting.`);
      return false;
    }

    if (requiresSignature && !signatureValue?.trim()) {
      setToastType("error");
      setToastMessage("Please add your signature before submitting.");
      return false;
    }

    return true;
  };

  const onSubmit = async (data: PortalClinicalFormValues) => {
    if (!hasValidAssignmentId || isReadOnly || isSubmitting) return;
    if (!validateBeforeSubmit()) return;

    setIsSubmitting(true);

    try {
      const pendingSaves = interactiveFields
        .filter((field) => fieldValues[field.id] !== undefined)
        .map((field) =>
          savePortalFormResponse({
            assignmentId,
            assignmentFieldId: field.id,
            value: fieldValues[field.id] ?? "",
          }).unwrap(),
        );

      if (pendingSaves.length > 0) {
        await Promise.all(pendingSaves);
      }

      if (requiresSignature && data.signature.trim()) {
        await savePortalFormSignature({
          assignmentId,
          signatureData: data.signature.trim(),
        }).unwrap();
      }

      await submitPortalFormAssignment(assignmentId).unwrap();
      setSignedAt(new Date());
      setToastType("success");
      setToastMessage("Form submitted successfully.");
    } catch (submitError) {
      setToastType("error");
      setToastMessage(getApiErrorMessage(submitError));
    } finally {
      setIsSubmitting(false);
    }
  };

  if (!hasValidAssignmentId) {
    return (
      <div className="min-h-screen bg-(--bg-primary-light) py-8 px-4">
        <div className="max-w-4xl mx-auto text-sm text-(--text-neutral-600)">
          Invalid form assignment.
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-(--bg-primary-light) py-8 px-4">
      <div className="max-w-4xl mx-auto">
        <button
          onClick={() => navigate("/user/clinical-forms")}
          className="flex items-center gap-2 text-gray-600 mb-6 hover:text-gray-900 cursor-pointer transition-colors"
        >
          <ArrowLeft size={20} />
          <span className="text-sm font-medium">Back to Forms</span>
        </button>

        <div className="bg-white rounded-xl shadow-sm p-8">
          {isInitialLoading ? (
            <div className="flex items-center justify-center gap-2 py-16 text-sm text-(--text-neutral-600)">
              <Loader2 className="h-5 w-5 animate-spin" />
              <span>Loading form...</span>
            </div>
          ) : (
            <>
              <div className="mb-6">
                <div className="flex items-start justify-between mb-4 gap-4">
                  <h1 className="text-2xl font-semibold text-(--text-primary-dark)">
                    {assignmentDetail
                      ? getPortalFormDetailTitle(assignmentDetail)
                      : "Clinical Form"}
                  </h1>
                  <Badge
                    variant="outline"
                    className={cn(
                      "text-xs font-normal flex items-center gap-1.5 border-none shrink-0",
                      formStatus === "completed"
                        ? "bg-(--status-completed-light) text-(--status-completed-dark)"
                        : "bg-gray-100 text-gray-600",
                    )}
                  >
                    <Clock size={14} />
                    {getPortalFormStatusLabel(formStatus)}
                  </Badge>
                </div>

                {assignmentDetail?.templateDescription ? (
                  <p className="mb-4 text-sm text-(--text-neutral-600)">
                    {assignmentDetail.templateDescription}
                  </p>
                ) : null}

                {assignmentDetail?.templateInstructions ? (
                  <p className="mb-4 text-sm text-(--text-primary-dark)">
                    {assignmentDetail.templateInstructions}
                  </p>
                ) : null}

                <div className="mb-6">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-sm text-(--text-neutral-600)">
                      Progress: {progress}%
                    </span>
                  </div>
                  <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
                    <div
                      className="h-full bg-[var(--btn-default-bg)] rounded-full transition-all"
                      style={{ width: `${progress}%` }}
                    />
                  </div>
                </div>
              </div>

              <div className="space-y-6 mb-8">
                {interactiveFields.length > 0 ? (
                  interactiveFields.map((field) => (
                    <PortalFormFieldRenderer
                      key={field.id}
                      field={field}
                      value={fieldValues[field.id] ?? ""}
                      disabled={isReadOnly || isSubmitting}
                      onValueChange={handleFieldValueChange}
                    />
                  ))
                ) : (
                  <p className="text-sm text-(--text-neutral-600)">
                    No form fields are available for this assignment.
                  </p>
                )}
              </div>

              {requiresSignature ? (
                <section>
                  <Form {...form}>
                    <SignatureForm
                      control={form.control}
                      form={form}
                      onSubmit={onSubmit}
                      isReadOnly={isReadOnly || isSubmitting}
                      signedAt={signedAt}
                    />
                  </Form>
                </section>
              ) : !isReadOnly ? (
                <div className="flex justify-end">
                  <button
                    type="button"
                    disabled={isSubmitting}
                    onClick={form.handleSubmit(onSubmit)}
                    className="inline-flex h-11 items-center justify-center rounded-full bg-(--bg-primary-dark) px-6 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-60"
                  >
                    {isSubmitting ? (
                      <span className="inline-flex items-center gap-2">
                        <Loader2 className="h-4 w-4 animate-spin" />
                        Submitting...
                      </span>
                    ) : (
                      "Submit Form"
                    )}
                  </button>
                </div>
              ) : null}
            </>
          )}
        </div>
      </div>

      {toastMessage ? (
        <Toast
          message={toastMessage}
          type={toastType}
          onClose={() => setToastMessage(null)}
        />
      ) : null}
    </div>
  );
};

export default ClinicalFormDetail;

