                className={`text-left ${stickyHeader ? "sticky top-0 z-10" : ""} ${column.headerClassName || ""}`}
                style={{
                  width: column.width,
                  height: headerHeight,
                  padding: column.headerPadding || column.padding || "12px 8px",
                  background: "#F3F7F8",
                  ...defaultHeaderCellStyle,
                }}
              >
                {column.headerContent || column.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {data.map((row, index) => (
            <tr
              key={rowKey(row, index)}
              className={getRowClassName?.(row, index)}
              style={{
                height: rowHeight,
                borderTop: "1px solid #EDEEF1",
                ...getRowStyle?.(row, index),
              }}
            >
              {columns.map((column) => {
                const value = row[column.key];
                const cellContent = column.render
                  ? column.render(value, row, index)
                  : value;

                return (
                  <td
                    key={column.key}
                    className={`min-w-0 max-w-0 overflow-hidden text-[14px] leading-5.5 text-(--text-primary-dark) ${column.className || ""}`}
                    style={{
                      width: column.width,
                      height: rowHeight,
                      padding: column.padding || "20px 8px",
                    }}
                  >
                    {cellContent}
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

