function applyNotesPartialUpdate(
  partialBody: Record<string, unknown>,
  current: AddClientFormValues,
  initial: AddClientFormValues,
): void {
  const currentReferral = current.referralNotes ?? "";
  const initialReferral = initial.referralNotes ?? "";
  const currentGeneral = current.generalNotes ?? "";
  const initialGeneral = initial.generalNotes ?? "";

  if (currentReferral === initialReferral && currentGeneral === initialGeneral) {
    return;
  }

  const referralChanged = currentReferral !== initialReferral;
  const generalChanged = currentGeneral !== initialGeneral;

  if (referralChanged && !generalChanged) {
    partialBody.notes = currentReferral.trim();
    return;
  }

  if (generalChanged && !referralChanged) {
    partialBody.notes = currentGeneral.trim();
    return;
  }

  partialBody.notes =
    trimToUndefined(current.generalNotes) ??
    trimToUndefined(current.referralNotes) ??
    "";
}

