import type { Client } from "@/types/client.type";
import {
  normalizeClientStageConstant,
  normalizeClientStatusConstant,
} from "@/utils/clientClinicalTransitions";

export function isClientInactive(client: Pick<Client, "clientStatus">): boolean {
  return normalizeClientStatusConstant(client.clientStatus) === "INACTIVE";
}

export function isClientClosedFile(
  client: Pick<Client, "clientStatus" | "clientStage">,
): boolean {
  return (
    isClientInactive(client) &&
    normalizeClientStageConstant(client.clientStage) === "CLOSED"
  );
}

