import { useState } from "react";
import { User, Shield, Pencil, Folder, FolderOpen, Trash2, Users } from "lucide-react";
import { Avatar, AvatarFallback } from "../../../ui/avatar";
import { Badge } from "../../../ui/badge";
import ConfirmationModal from "../../../shared/ConfirmationModal";
import type { Client } from "../../../../types/client.type";
import { isClientClosedFile } from "@/utils/clientStatus";

interface ClientProfileHeaderProps {
  client: Client;
  readOnly?: boolean;
  onEdit?: () => void;
  onDelete?: () => void;
  onCloseFile?: () => Promise<void> | void;
  onActivateFile?: () => Promise<void> | void;
  isClosingFile?: boolean;
  isActivatingFile?: boolean;
}

const ClientProfileHeader = ({
  client,
  readOnly = false,
  onEdit,
  onDelete,
  onCloseFile,
  onActivateFile,
  isClosingFile = false,
  isActivatingFile = false,
}: ClientProfileHeaderProps) => {
  const [isCloseFileModalOpen, setIsCloseFileModalOpen] = useState(false);
  const [isActivateFileModalOpen, setIsActivateFileModalOpen] = useState(false);
  const showActivateFile = isClientClosedFile(client);

  const getInitials = (name: string): string => {
    return name
      .split(" ")
      .map((n) => n[0])
      .join("")
      .toUpperCase()
      .slice(0, 2);
  };

  const handleCloseFile = async () => {
    if (!onCloseFile) return;
    await onCloseFile();
    setIsCloseFileModalOpen(false);
  };

  const handleActivateFile = async () => {
    if (!onActivateFile) return;
    await onActivateFile();
    setIsActivateFileModalOpen(false);
  };

  return (
    <>
      <div className="p-6 bg-white border-b border-gray-100 min-w-0 overflow-hidden">
        {/* Client Header */}
        <div className="flex items-start gap-4 mb-6 min-w-0">
          <Avatar className="w-12 h-12 shrink-0">
            <AvatarFallback className="bg-gray-700 text-white text-base font-semibold">
              {getInitials(client.name)}
            </AvatarFallback>
          </Avatar>

          <div className="flex-1 min-w-0">
            <div className="mb-1 flex min-w-0 flex-wrap items-center gap-3">
              <h2
                className="min-w-0 break-words text-base font-semibold text-gray-900 [overflow-wrap:anywhere]"
                title={client.name}
              >
                {client.name}
              </h2>
              {client.serviceType && (
                <Badge className="shrink-0 bg-green-50 text-green-700 border-green-200 text-xs font-normal px-2 py-0.5">
                  {client.serviceType}
                </Badge>
              )}
            </div>
            <div className="flex flex-wrap items-center gap-2 text-xs text-(--text-neutral-600)">
              {client.age && <span className="border-r border-(--text-neutral-400) pr-1.5">Age: {client.age}</span>}
              {!client.isMVAClient && (
                <span className="border-r border-(--text-neutral-400) pr-1.5">MVA Client</span>
              )}
              {client.lastSession && (
                <span>Last session: {client.lastSession}</span>
              )}
            </div>
          </div>

          {/* Action Icons */}
          <div className="flex shrink-0 items-center gap-1">
            {!readOnly && (
              <button
                onClick={onEdit}
                className="p-1.5 rounded-md hover:bg-gray-100 border border-(--text-neutral-100) transition-colors cursor-pointer"
                title="Edit"
              >
                <Pencil size={18} className="text-gray-600" />
              </button>
            )}
            {showActivateFile ? (
              <button
                onClick={() => setIsActivateFileModalOpen(true)}
                disabled={isActivatingFile}
                className="p-1.5 rounded-md hover:bg-green-50 border border-(--text-neutral-100) transition-colors cursor-pointer"
                title="Activate File"
              >
                <FolderOpen size={18} className="text-green-600" />
              </button>
            ) : (
              <button
                onClick={() => setIsCloseFileModalOpen(true)}
                disabled={isClosingFile}
                className="p-1.5 rounded-md hover:bg-gray-100 border border-(--text-neutral-100) transition-colors cursor-pointer"
                title="Close File"
              >
                <Folder size={18} className="text-gray-600" />
              </button>
            )}
            <button
              onClick={onDelete}
              className="p-1.5 rounded-md hover:bg-red-50 border border-(--text-neutral-100) transition-colors cursor-pointer"
              title="Delete"
            >
              <Trash2 size={18} className="text-red-600" />
            </button>
          </div>
        </div>

        {/* Key Identifiers - Cleaner Card Design */}
        <div className="grid grid-cols-4 gap-4">
          {/* Client ID Card */}
          <div className="flex items-center gap-3 p-3 border border-gray-200 rounded-lg bg-white">
            <div className="p-2 rounded-lg bg-gray-50">
              <User size={18} className="text-gray-600" strokeWidth={1.5} />
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-xs text-gray-500 mb-0.5">Client ID</p>
              <p className="text-sm font-semibold text-gray-900 truncate">
                {client.clientId || client.referenceNumber}
              </p>
            </div>
          </div>

          {/* Assigned Therapist Card */}
          <div className="flex items-center gap-3 p-3 border border-gray-200 rounded-lg bg-white">
            <div className="p-2 rounded-lg bg-gray-50">
              <Users size={18} className="text-gray-600" strokeWidth={1.5} />
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-xs text-gray-500 mb-0.5">Assigned Therapist</p>
              <p
                className="text-sm font-semibold text-gray-900 truncate"
                title={client.therapist || "Unassigned"}
              >
                {client.therapist || "Unassigned"}
              </p>
            </div>
          </div>

          {/* Insurance Card */}
          <div className="flex items-center gap-3 p-3 border border-gray-200 rounded-lg bg-white">
            <div className="p-2 rounded-lg bg-gray-50">
              <Shield size={18} className="text-gray-600" strokeWidth={1.5} />
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-xs text-gray-500 mb-0.5">Insurance</p>
              <p className="text-sm font-semibold text-gray-900 truncate">
                {client.insurance || "N/A"}
              </p>
            </div>
          </div>

          {/* Client Portal Card with External Link */}
          <div className="flex items-center gap-3 p-3 border border-gray-200 rounded-lg bg-white">
            <div className="p-2 rounded-lg bg-green-50">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" className="text-green-600">
                <circle cx="12" cy="12" r="10" />
                <path d="M9 12l2 2 4-4" />
              </svg>
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-xs text-gray-500 mb-0.5">Client Portal</p>
              <p className="text-sm font-semibold text-gray-900">
                {client.portalAccessEnabled ? "Enabled" : "Disabled"}
              </p>
            </div>
            {client.portalAccessEnabled && (
              <button className="p-1 hover:bg-gray-100 rounded transition-colors cursor-pointer" title="Open portal">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="text-gray-600">
                  <path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6" />
                  <polyline points="15 3 21 3 21 9" />
                  <line x1="10" y1="14" x2="21" y2="3" />
                </svg>
              </button>
            )}
          </div>
        </div>
      </div>

      <ConfirmationModal
        type="close"
        isOpen={isCloseFileModalOpen}
        onClose={() => setIsCloseFileModalOpen(false)}
        onConfirm={() => {
          void handleCloseFile();
        }}
        confirmButtonLoading={isClosingFile}
        confirmButtonLoadingText="Closing..."
      />

      <ConfirmationModal
        type="activate"
        isOpen={isActivateFileModalOpen}
        onClose={() => setIsActivateFileModalOpen(false)}
        onConfirm={() => {
          void handleActivateFile();
        }}
        confirmButtonLoading={isActivatingFile}
        confirmButtonLoadingText="Activating..."
      />
    </>
  );
};

export default ClientProfileHeader;

