export function getSessionModalityLabel(sessionMode?: string | null): string {
  const normalized = (sessionMode || "").trim().toLowerCase().replace(/_/g, "-");

  if (normalized === "online" || normalized === "virtual") {
    return "Virtual";
  }

  if (normalized === "in-person" || normalized === "inperson") {
    return "In-Person";
  }

  return "In-Person";
}

export function isVirtualSession(session: {
  sessionMode?: string | null;
  type?: string | null;
  zoomEnabled?: boolean;
}): boolean {
  if (typeof session.zoomEnabled === "boolean") {
    return session.zoomEnabled;
  }

  const normalized = (session.sessionMode || session.type || "")
    .trim()
    .toLowerCase()
    .replace(/_/g, "-")
    .replace(/\s+/g, "-");

  return normalized === "online" || normalized === "virtual";
}

