function parseWorkingHours(rawWorkingHours: string | null | undefined): WorkingHoursEntry[] {
  if (!rawWorkingHours) return [];
  try {
    const parsed = JSON.parse(rawWorkingHours);
    return Array.isArray(parsed)
      ? parsed.filter((entry): entry is WorkingHoursEntry => typeof entry === "object" && entry !== null)
      : [];
  } catch {
    return [];
  }
}

function normalizeWorkingMode(mode?: string): string {
  return (mode || "")
    .trim()
    .toLowerCase()
    .replace(/[_\s]+/g, "-");
}

function normalizeWorkingDay(day?: string): string {
  return (day || "").trim().toLowerCase();
}

function isSameCalendarDay(left: Date, right: Date): boolean {
  return (
    left.getFullYear() === right.getFullYear() &&
    left.getMonth() === right.getMonth() &&
    left.getDate() === right.getDate()
  );
}

function getSlotDate(date: Date, slot: string): Date {
  const [clock, suffix] = slot.split(" ");
  const [hoursString, minutesString = "00"] = clock.split(":");
  let hours = Number.parseInt(hoursString, 10);
  if (suffix === "AM" && hours === 12) hours = 0;
  if (suffix === "PM" && hours !== 12) hours += 12;

  return new Date(
    date.getFullYear(),
    date.getMonth(),
    date.getDate(),
    hours,
    Number.parseInt(minutesString, 10),
    0,
    0,
  );
}

function buildAvailableTimeSlots(
  date: Date | null,
  sessionMode: "virtual" | "in-person",
  sessionDuration: number,
  profile: TherapistAvailabilityProfile | null,
): string[] {
  if (!date || !profile) return [];

  const dayKey = date
    .toLocaleDateString("en-US", { weekday: "long" })
    .toLowerCase();
  const entries = parseWorkingHours(profile.workingHours).filter(
    (entry) => {
      const normalizedMode = normalizeWorkingMode(entry.mode);
      const normalizedDay = normalizeWorkingDay(entry.day);
      const modeMatches =
        normalizedMode === "both" ||
        (sessionMode === "virtual" &&
          (normalizedMode === "virtual" || normalizedMode === "online")) ||
        (sessionMode === "in-person" &&
          (normalizedMode === "in-person" || normalizedMode === "inperson"));

      return entry.enabled !== false && normalizedDay === dayKey && modeMatches;
    },
  );

  const slots: string[] = [];
  entries.forEach((entry) => {
    if (!entry.start || !entry.end) return;
    const [startHour, startMinute = 0] = entry.start.split(":").map(Number);
    const [endHour, endMinute = 0] = entry.end.split(":").map(Number);
    const cursor = new Date(date);
    cursor.setHours(startHour, startMinute, 0, 0);
    const end = new Date(date);
    end.setHours(endHour, endMinute, 0, 0);

    while (cursor.getTime() + sessionDuration * 60 * 1000 <= end.getTime()) {
      slots.push(
        cursor.toLocaleTimeString("en-US", {
          hour: "2-digit",
          minute: "2-digit",
          hour12: true,
        }),
      );
      cursor.setMinutes(cursor.getMinutes() + sessionDuration);
    }
  });

  const uniqueSlots = Array.from(new Set(slots));
  const now = new Date();

  if (!isSameCalendarDay(date, now)) {
    return uniqueSlots;
  }

  return uniqueSlots.filter((slot) => getSlotDate(date, slot).getTime() > now.getTime());
}

