import { DateTime } from "luxon";
import {
  calendarDateParts,
  formatApiTimeTo12h,
  formatTime12hInTimezone,
  resolveTherapistTimezone,
} from "@/utils/therapistTimezone";

export function resolvePortalTimezone(timezone?: string | null): string {
  return resolveTherapistTimezone(timezone);
}

export function formatPortalSlotStartTime(
  _dateIso: string,
  startHHmm: string,
  _timezone?: string | null,
): string {
  // API slot times are HH:mm in the client's profile timezone.
  return formatApiTimeTo12h(startHHmm);
}

export function formatPortalSessionDateLabel(
  sessionDateIso: string,
  timezone?: string | null,
): string {
  const zone = resolvePortalTimezone(timezone);
  const dt = DateTime.fromISO(sessionDateIso, { zone: "utc" }).setZone(zone);
  if (!dt.isValid) return "-";
  return dt.toFormat("EEEE, MMMM d");
}

export function formatPortalSessionTimeLabel(
  sessionDateIso: string,
  timezone?: string | null,
): string {
  return formatTime12hInTimezone(sessionDateIso, timezone) || "-";
}

export function formatPortalCalendarDateLong(
  date: Date,
  timezone?: string | null,
): string {
  const zone = resolvePortalTimezone(timezone);
  const { year, month, day } = calendarDateParts(date);
  const dt = DateTime.fromObject({ year, month, day }, { zone });
  if (!dt.isValid) return "-";
  return dt.toFormat("EEEE, MMMM d");
}

export function formatPortalCalendarDateShort(
  date: Date,
  timezone?: string | null,
): string {
  const zone = resolvePortalTimezone(timezone);
  const { year, month, day } = calendarDateParts(date);
  const dt = DateTime.fromObject({ year, month, day }, { zone });
  if (!dt.isValid) return "-";
  return dt.toFormat("EEE, MMM d");
}

export function isPortalCalendarDateBeforeToday(
  date: Date,
  timezone?: string | null,
): boolean {
  const zone = resolvePortalTimezone(timezone);
  const { year, month, day } = calendarDateParts(date);
  const selectedDay = DateTime.fromObject({ year, month, day }, { zone });
  const today = DateTime.now().setZone(zone).startOf("day");
  if (!selectedDay.isValid) return false;
  return selectedDay < today;
}

