export type StaffPermissionName = string;

export function normalizeStaffPermission(
  permission?: string | null,
): string {
  return (permission ?? "").trim().toUpperCase();
}

export function normalizeStaffPermissions(
  permissions?: Array<string | null | undefined> | null,
): string[] {
  if (!permissions?.length) return [];

  const unique = new Set<string>();
  for (const permission of permissions) {
    const normalized = normalizeStaffPermission(permission);
    if (normalized) unique.add(normalized);
  }

  return Array.from(unique);
}

export function hasStaffPermission(
  permissions: StaffPermissionName[],
  required: StaffPermissionName,
): boolean {
  const normalizedRequired = normalizeStaffPermission(required);
  if (!normalizedRequired) return false;
  return permissions.some(
    (permission) => normalizeStaffPermission(permission) === normalizedRequired,
  );
}

export function hasAnyStaffPermission(
  permissions: StaffPermissionName[],
  required: StaffPermissionName[],
): boolean {
  if (!required.length) return true;
  return required.some((permission) => hasStaffPermission(permissions, permission));
}

export function shouldBypassStaffPermissionFiltering(options: {
  role: string | null;
  isPlatformAdmin?: boolean;
  isTenantAdmin?: boolean;
  permissions: StaffPermissionName[];
  permissionsReady: boolean;
}): boolean {
  if (!options.permissionsReady) return true;
  if (options.role === "super-admin" || options.role === "user") return true;
  if (options.isPlatformAdmin || options.isTenantAdmin) return true;
  return options.permissions.length === 0;
}

import type { MenuItem } from "@/types/user.type";

type MenuPermissionRule = string[] | null;

const ADMIN_MENU_PERMISSIONS: Record<string, MenuPermissionRule> = {
  dashboard: null,
  clients: [
    "CLIENT_VIEW",
    "CLIENT_VIEW_ALL",
    "CLIENT_VIEW_TEAM",
    "CLIENT_VIEW_OWN",
    "CLIENT_CREATE",
    "CLIENT_EDIT",
  ],
  scheduling: [
    "SESSION_VIEW",
    "SESSION_CREATE",
    "SESSION_EDIT",
    "SESSION_DELETE",
  ],
  billings: [
    "BILLING_VIEW",
    "BILLING_MANAGE",
    "BILLING_CREATE",
    "BILLING_EDIT",
    "BILLING_EXPORT",
  ],
  tasks: [
    "CLIENT_VIEW",
    "CLIENT_VIEW_ALL",
    "CLIENT_VIEW_TEAM",
    "CLIENT_VIEW_OWN",
    "SESSION_VIEW",
  ],
  content: null,
  library: ["FORM_VIEW", "FORM_TEMPLATE_MANAGE", "FORM_FILL"],
  assessment: ["ASSESSMENT_VIEW", "ASSESSMENT_ASSIGN"],
  "clinical-forms": ["FORM_VIEW", "FORM_TEMPLATE_MANAGE", "FORM_FILL"],
  "process-checklists": ["FORM_VIEW", "FORM_TEMPLATE_MANAGE"],
  "user-access": null,
  "user-profiles": ["USER_VIEW", "USER_MANAGE", "USER_CREATE", "USER_EDIT"],
  "role-management": ["USER_MANAGE"],
  "duplicate-detection": ["CLIENT_VIEW_ALL", "USER_MANAGE", "CLIENT_VIEW"],
  system: null,
  notifications: null,
  settings: ["USER_MANAGE"],
  compliance: null,
  "hipaa-audit": ["AUDIT_VIEW", "AUDIT_EXPORT"],
  "privacy-consent": ["CONSENT_ADMIN_VIEW"],
};

const THERAPIST_MENU_PERMISSIONS: Record<string, MenuPermissionRule> = {
  dashboard: null,
  clients: [
    "CLIENT_VIEW_OWN",
    "CLIENT_VIEW",
    "CLIENT_VIEW_TEAM",
    "CLIENT_VIEW_ALL",
    "CLIENT_EDIT",
  ],
  scheduling: ["SESSION_VIEW", "SESSION_CREATE", "SESSION_EDIT"],
  billings: ["BILLING_VIEW", "BILLING_MANAGE", "BILLING_CREATE", "BILLING_EDIT"],
  tasks: ["CLIENT_VIEW_OWN", "CLIENT_VIEW", "CLIENT_VIEW_TEAM", "SESSION_VIEW"],
};

export function getStaffMenuPermissionRule(
  menuId: string,
  portal: "admin" | "therapist",
): MenuPermissionRule | undefined {
  const source =
    portal === "admin" ? ADMIN_MENU_PERMISSIONS : THERAPIST_MENU_PERMISSIONS;
  return source[menuId];
}

export function flattenStaffMenuPaths(menuItems: MenuItem[]): string[] {
  const paths: string[] = [];

  for (const item of menuItems) {
    if (item.path) paths.push(item.path);
    if (item.children?.length) {
      paths.push(...flattenStaffMenuPaths(item.children));
    }
  }

  return paths;
}

export function findFirstStaffMenuPath(menuItems: MenuItem[]): string | null {
  for (const item of menuItems) {
    if (item.children?.length) {
      const childPath = findFirstStaffMenuPath(item.children);
      if (childPath) return childPath;
    }

    if (item.path) return item.path;
  }

  return null;
}

import { getStaffMenuPermissionRule } from "@/config/staffMenuPermissions";
import type { MenuItem } from "@/types/user.type";
import { hasAnyStaffPermission } from "@/utils/staffPermissions";

function canAccessMenuItem(
  item: MenuItem,
  permissions: string[],
  portal: "admin" | "therapist",
): boolean {
  const rule = getStaffMenuPermissionRule(item.id, portal);

  if (item.children?.length) {
    const visibleChildren = item.children.filter((child) =>
      canAccessMenuItem(child, permissions, portal),
    );
    return visibleChildren.length > 0;
  }

  if (rule === null) return true;
  if (!rule?.length) return true;
  return hasAnyStaffPermission(permissions, rule);
}

export function filterStaffMenuByPermissions(
  menuItems: MenuItem[],
  permissions: string[],
  portal: "admin" | "therapist",
): MenuItem[] {
  return menuItems
    .map((item) => {
      if (item.children?.length) {
        const children = item.children.filter((child) =>
          canAccessMenuItem(child, permissions, portal),
        );

        if (!children.length) return null;
        return { ...item, children };
      }

      return canAccessMenuItem(item, permissions, portal) ? item : null;
    })
    .filter((item): item is MenuItem => item !== null);
}

export function isStaffPathAllowed(
  pathname: string,
  menuItems: MenuItem[],
): boolean {
  const normalizedPath = pathname.replace(/\/+$/, "") || "/";

  return menuItems.some((item) => {
    if (item.path && matchesStaffMenuPath(normalizedPath, item.path)) {
      return true;
    }

    return item.children?.some((child) =>
      child.path ? matchesStaffMenuPath(normalizedPath, child.path) : false,
    );
  });
}

function matchesStaffMenuPath(pathname: string, menuPath: string): boolean {
  const normalizedMenuPath = menuPath.replace(/\/+$/, "") || "/";
  return (
    pathname === normalizedMenuPath ||
    pathname.startsWith(`${normalizedMenuPath}/`)
  );
}

