export function mapApiRolesToAppRole(
  roles: string[] | undefined,
  permissions?: string[],
): AppRole {
  if (!roles || roles.length === 0) {
    return permissions?.length ? "admin" : "user";
  }

  const normalized = roles.map((role) => role.toUpperCase());
  const map: Record<string, AppRole> = {
    SUPER_ADMIN: "super-admin",
    PLATFORM_SUPER_ADMIN: "super-admin",
    ADMIN: "admin",
    TENANT_ADMIN: "admin",
    THERAPIST: "therapist",
    SUPERVISOR: "admin",
    CLIENT: "user",
    ROLE_CLIENT: "user",
  };

  const mapped = normalized
    .map((role) => map[role])
    .filter(Boolean) as AppRole[];

  for (const role of ROLE_PRIORITY) {
    if (mapped.includes(role)) {
      return role;
    }
  }

  const isClientOnly = normalized.every(
    (role) => role === "CLIENT" || role === "ROLE_CLIENT",
  );
  if (isClientOnly) {
    return "user";
  }

  const therapistSignals = new Set([
    "THERAPIST",
    "ROLE_THERAPIST",
    "CLIENT_VIEW_OWN",
    "SESSION_VIEW",
  ]);
  const hasTherapistSignal =
    normalized.some((role) => therapistSignals.has(role)) ||
    permissions?.some((permission) =>
      ["CLIENT_VIEW_OWN", "SESSION_VIEW", "SESSION_CREATE"].includes(
        permission.toUpperCase(),
      ),
    );

  if (hasTherapistSignal && !normalized.includes("ADMIN") && !normalized.includes("SUPERVISOR")) {
    return "therapist";
  }

  return "admin";
}

