import { useEffect, useMemo } from "react";
import { useGetAuthMeQuery } from "@/store/api/authApi";
import { setStaffPermissions } from "@/store/authSlice";
import { useAppDispatch, useAppSelector } from "@/store/hooks";
import {
  normalizeStaffPermissions,
  shouldBypassStaffPermissionFiltering,
} from "@/utils/staffPermissions";

export function useStaffPermissions() {
  const dispatch = useAppDispatch();
  const role = useAppSelector((state) => state.auth.role);
  const accessToken = useAppSelector((state) => state.auth.accessToken);
  const storedPermissions = useAppSelector((state) => state.auth.permissions);

  const isStaffPortal = role === "admin" || role === "therapist";
  const { data: authMe, isLoading, isFetching } = useGetAuthMeQuery(undefined, {
    skip: !accessToken || !isStaffPortal,
  });

  useEffect(() => {
    if (!authMe?.permissions) return;
    const normalized = normalizeStaffPermissions(authMe.permissions);
    dispatch(setStaffPermissions(normalized));
  }, [authMe?.permissions, dispatch]);

  const permissions = useMemo(
    () =>
      normalizeStaffPermissions(authMe?.permissions ?? storedPermissions ?? []),
    [authMe?.permissions, storedPermissions],
  );

  const permissionsReady = !isStaffPortal || (!isLoading && !isFetching);
  const shouldBypass = shouldBypassStaffPermissionFiltering({
    role,
    isPlatformAdmin: authMe?.isPlatformAdmin,
    isTenantAdmin: authMe?.isTenantAdmin,
    permissions,
    permissionsReady,
  });

  return {
    permissions,
    permissionsReady,
    shouldBypass,
    authMe,
  };
}

import { useMemo } from "react";
import { findFirstStaffMenuPath } from "@/config/staffMenuPermissions";
import type { MenuItem } from "@/types/user.type";
import { filterStaffMenuByPermissions } from "@/utils/filterStaffMenuByPermissions";
import { useStaffPermissions } from "@/hooks/useStaffPermissions";

export function useFilteredStaffMenuItems(
  menuItems: MenuItem[],
  portal: "admin" | "therapist",
) {
  const { permissions, shouldBypass } = useStaffPermissions();

  return useMemo(() => {
    if (shouldBypass) return menuItems;
    return filterStaffMenuByPermissions(menuItems, permissions, portal);
  }, [menuItems, permissions, portal, shouldBypass]);
}

export function useDefaultStaffLandingPath(
  menuItems: MenuItem[],
  portal: "admin" | "therapist",
) {
  const filteredMenuItems = useFilteredStaffMenuItems(menuItems, portal);

  return useMemo(
    () => findFirstStaffMenuPath(filteredMenuItems),
    [filteredMenuItems],
  );
}

import { useEffect } from "react";
import { Navigate, useLocation } from "react-router-dom";
import type { MenuItem } from "@/types/user.type";
import { isStaffPathAllowed } from "@/utils/filterStaffMenuByPermissions";
import {
  useDefaultStaffLandingPath,
  useFilteredStaffMenuItems,
} from "@/hooks/useFilteredStaffMenuItems";
import { useStaffPermissions } from "@/hooks/useStaffPermissions";

type StaffPermissionGateProps = {
  portal: "admin" | "therapist";
  menuItems: MenuItem[];
  children: React.ReactNode;
};

export default function StaffPermissionGate({
  portal,
  menuItems,
  children,
}: StaffPermissionGateProps) {
  const location = useLocation();
  const { shouldBypass, permissionsReady } = useStaffPermissions();
  const filteredMenuItems = useFilteredStaffMenuItems(menuItems, portal);
  const defaultPath = useDefaultStaffLandingPath(menuItems, portal);

  const isAllowed =
    shouldBypass || isStaffPathAllowed(location.pathname, filteredMenuItems);

  useEffect(() => {
    if (!permissionsReady || shouldBypass || isAllowed || !defaultPath) return;
    if (location.pathname !== defaultPath) {
      // Navigation handled by render branch below.
    }
  }, [
    defaultPath,
    isAllowed,
    location.pathname,
    permissionsReady,
    shouldBypass,
  ]);

  if (!permissionsReady) {
    return <>{children}</>;
  }

  if (!shouldBypass && !isAllowed && defaultPath) {
    return <Navigate to={defaultPath} replace />;
  }

  if (
    !shouldBypass &&
    filteredMenuItems.length === 0 &&
    permissionsReady
  ) {
    return <Navigate to="/errors/403" replace />;
  }

  return <>{children}</>;
}

import { Navigate, useLocation } from "react-router-dom";
import type { MenuItem } from "@/types/user.type";
import { isStaffPathAllowed } from "@/utils/filterStaffMenuByPermissions";
