import { useStaffPermissions } from "@/hooks/useStaffPermissions";
import {
  hasAnyStaffPermission,
  hasStaffPermission,
  type StaffPermissionName,
} from "@/utils/staffPermissions";

export function useHasStaffPermission(required: StaffPermissionName): boolean {
  const { permissions, shouldBypass } = useStaffPermissions();
  if (shouldBypass) return true;
  return hasStaffPermission(permissions, required);
}

export function useHasAnyStaffPermission(
  required: StaffPermissionName[],
): boolean {
  const { permissions, shouldBypass } = useStaffPermissions();
  if (shouldBypass) return true;
  return hasAnyStaffPermission(permissions, required);
}

import type { ReactNode } from "react";
import { useStaffPermissions } from "@/hooks/useStaffPermissions";
import {
  hasAnyStaffPermission,
  hasStaffPermission,
  type StaffPermissionName,
} from "@/utils/staffPermissions";

type StaffPermissionProps = {
  anyOf?: StaffPermissionName[];
  allOf?: StaffPermissionName[];
  permission?: StaffPermissionName;
  children: ReactNode;
  fallback?: ReactNode;
};

export default function StaffPermission({
  anyOf,
  allOf,
  permission,
  children,
  fallback = null,
}: StaffPermissionProps) {
  const { permissions, shouldBypass } = useStaffPermissions();

  if (shouldBypass) {
    return <>{children}</>;
  }

  if (permission && hasStaffPermission(permissions, permission)) {
    return <>{children}</>;
  }

  if (anyOf?.length && hasAnyStaffPermission(permissions, anyOf)) {
    return <>{children}</>;
  }

  if (
    allOf?.length &&
    allOf.every((entry) => hasStaffPermission(permissions, entry))
  ) {
    return <>{children}</>;
  }

  if (!permission && !anyOf?.length && !allOf?.length) {
    return <>{children}</>;
  }

  return <>{fallback}</>;
}

