};

// Predefined action items for common use cases
export const createClientActions = (
  onChecklist: () => void,
  onScheduledSession: () => void,
  onEdit: () => void,
  onCreateTask: () => void,
  onDelete: () => void,
  options?: { disableCreateTask?: boolean; disableEdit?: boolean },
  permissions?: ClientActionPermissions,
): ActionItem[] => {
  const items: Array<ActionItem | null> = [
    permissions?.canChecklist === false
      ? null
      : {
          id: "checklist",
          label: "Checklist",
          icon: <CheckCheck size={18} className="text-(--text-neutral-600)" />,
          onClick: onChecklist,
        },
    permissions?.canScheduleSession === false
      ? null
      : {
          id: "scheduled-session",
