export function isSessionMenuActionAllowed(
  action: string,
  permissions: {
    canViewSessions: boolean;
    canEditSession: boolean;
    canDeleteSession: boolean;
  },
): boolean {
  if (action === "edit" || action === "reopen-note") {
    return permissions.canEditSession;
  }

  if (action === "delete-session" || action === "cancel-series") {
    return permissions.canDeleteSession;
  }

  if (
    [
      "SCHEDULED",
      "CONFIRMED",
      "OVERDUE",
      "IN_PROGRESS",
      "COMPLETED",
      "CANCELLED",
      "RESCHEDULING",
      "NO_SHOW",
    ].includes(action)
  ) {
    return permissions.canEditSession;
  }

  return permissions.canViewSessions;
}

