import { useNavigate } from "react-router-dom";

const PROFILE_FIELD_LIMITS = {
  firstName: 50,
  lastName: 50,
  email: 254,
  phone: 20,
} as const;

const NAME_PATTERN = /^[A-Za-z\s'-]+$/;
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function sanitizeName(value: string, maxLength: number): string {
  return value
    .replace(/[^A-Za-z\s'-]/g, "")
    .slice(0, maxLength);
}

function sanitizeEmail(value: string): string {
  return value.replace(/\s/g, "").slice(0, PROFILE_FIELD_LIMITS.email);
}

function sanitizePhone(value: string): string {
  return value.replace(/\D/g, "").slice(0, PROFILE_FIELD_LIMITS.phone);
}

type ProfileFieldErrors = Partial<
  Record<"firstName" | "lastName" | "emailAddress" | "phoneNumber", string>
>;

function validateProfileFields(values: {
  firstName: string;
  lastName: string;
  emailAddress: string;
  phoneNumber: string;
}): ProfileFieldErrors {
  const errors: ProfileFieldErrors = {};
  const firstName = values.firstName.trim();
  const lastName = values.lastName.trim();
  const emailAddress = values.emailAddress.trim();
  const phoneNumber = values.phoneNumber.trim();

  if (!firstName) {
    errors.firstName = "First name is required.";
  } else if (firstName.length > PROFILE_FIELD_LIMITS.firstName) {
    errors.firstName = `First name must be ${PROFILE_FIELD_LIMITS.firstName} characters or less.`;
  } else if (!NAME_PATTERN.test(firstName)) {
    errors.firstName = "First name can only contain letters, spaces, hyphens, and apostrophes.";
  }

  if (!lastName) {
    errors.lastName = "Last name is required.";
  } else if (lastName.length > PROFILE_FIELD_LIMITS.lastName) {
    errors.lastName = `Last name must be ${PROFILE_FIELD_LIMITS.lastName} characters or less.`;
  } else if (!NAME_PATTERN.test(lastName)) {
    errors.lastName = "Last name can only contain letters, spaces, hyphens, and apostrophes.";
  }

  if (!emailAddress) {
    errors.emailAddress = "Email address is required.";
  } else if (emailAddress.length > PROFILE_FIELD_LIMITS.email) {
    errors.emailAddress = `Email must be ${PROFILE_FIELD_LIMITS.email} characters or less.`;
  } else if (!EMAIL_PATTERN.test(emailAddress)) {
    errors.emailAddress = "Enter a valid email address.";
  }

  if (phoneNumber) {
    if (phoneNumber.length > PROFILE_FIELD_LIMITS.phone) {
      errors.phoneNumber = `Phone number must be ${PROFILE_FIELD_LIMITS.phone} digits or less.`;
    } else if (!/^\d+$/.test(phoneNumber)) {
      errors.phoneNumber = "Phone number must contain digits only.";
    }
  }

  return errors;
}

function getFieldShellClassName(hasError = false): string {
  return cn(
    "relative h-[60px] overflow-hidden rounded-[16px] border bg-white",
    hasError ? "border-[#f3a4a4]" : "border-[#dce5ee]",
  );
}

