export const TENANT_SETTINGS_LIMITS = {
  logoUrl: 500,
  supportEmail: 254,
  supportAddress: 500,
  brandColor: 7,
} as const;

export const TIMEZONE_OPTIONS = [
  { value: "America/New_York", label: "America/New_York (EST)" },
  { value: "America/Chicago", label: "America/Chicago (CST)" },
  { value: "America/Los_Angeles", label: "America/Los_Angeles (PST)" },
] as const;

export const REGION_OPTIONS = [
  { value: "us-east-1", label: "us-east-1 (N. Virginia)" },
  { value: "us-west-2", label: "us-west-2 (Oregon)" },
] as const;

export const DATA_RESIDENCY_OPTIONS = [
  { value: "US", label: "United States (US)" },
  { value: "EU", label: "Europe (EU)" },
] as const;

export const LOCALE_OPTIONS = [
  { value: "en-US", label: "English (United States)" },
  { value: "en-GB", label: "English (United Kingdom)" },
  { value: "en-CA", label: "English (Canada)" },
  { value: "es-ES", label: "Spanish (Spain)" },
  { value: "fr-FR", label: "French (France)" },
] as const;

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const HEX_COLOR_PATTERN = /^#([0-9a-fA-F]{6})$/;

export function sanitizeSupportEmail(value: string): string {
  return value.replace(/\s/g, "").slice(0, TENANT_SETTINGS_LIMITS.supportEmail);
}

export function sanitizeLogoUrl(value: string): string {
  return value.trim().slice(0, TENANT_SETTINGS_LIMITS.logoUrl);
}

export function sanitizeSupportAddress(value: string): string {
  return value.slice(0, TENANT_SETTINGS_LIMITS.supportAddress);
}

export function sanitizeBrandColor(value: string): string {
  const trimmed = value.trim().slice(0, TENANT_SETTINGS_LIMITS.brandColor);
  if (!trimmed) return "";
  if (trimmed.startsWith("#")) return trimmed;
  return `#${trimmed}`.slice(0, TENANT_SETTINGS_LIMITS.brandColor);
}

export function normalizeSelectValue(
  value: string,
  options: ReadonlyArray<{ value: string; label: string }>
): string {
  const trimmed = value.trim();
  if (!trimmed) return "";

  const exact = options.find((option) => option.value === trimmed);
  if (exact) return exact.value;

  const byLabel = options.find(
    (option) => option.label === trimmed || option.label.includes(trimmed),
  );
  if (byLabel) return byLabel.value;

  const byPartial = options.find(
    (option) =>
      trimmed.includes(option.value) ||
      option.label.toLowerCase().includes(trimmed.toLowerCase()),
  );
  return byPartial?.value ?? trimmed;
}

export function validateTenantSettings(values: {
  timezone: string;
  region: string;
  dataResidency: string;
  locale: string;
  logoUrl: string;
  brandPrimaryColor: string;
  brandSecondaryColor: string;
  brandAccentColor: string;
  supportEmail: string;
  supportAddress: string;
}): string | null {
  if (!values.timezone.trim()) return "Timezone is required.";
  if (!values.region.trim()) return "Region is required.";
  if (!values.dataResidency.trim()) return "Data residency is required.";
  if (!values.locale.trim()) return "Locale is required.";

  const email = values.supportEmail.trim();
  if (email && !EMAIL_PATTERN.test(email)) {
    return "Enter a valid support email address.";
  }

  for (const color of [
    values.brandPrimaryColor,
    values.brandSecondaryColor,
    values.brandAccentColor,
  ]) {
    const trimmed = color.trim();
    if (trimmed && !HEX_COLOR_PATTERN.test(trimmed)) {
      return "Brand colors must use a valid hex value (e.g. #1A2B3C).";
    }
  }

  return null;
}

import { type ReactNode, useEffect, useMemo, useState } from "react";
import { ArrowLeft, Loader2 } from "lucide-react";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import SuperAdminHeaderActions from "@/components/shared/SuperAdminHeaderActions";
import Toast from "@/components/shared/Toast";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";
import {
  useGetOrganisationsQuery,
  useGetOrganisationSettingsQuery,
  useUpdateOrganisationSettingsMutation,
  type OrganisationSettings,
} from "@/store/api/superAdminApi";
import { getApiErrorMessage } from "@/utils/apiError";
import {
  DATA_RESIDENCY_OPTIONS,
  LOCALE_OPTIONS,
  normalizeSelectValue,
  REGION_OPTIONS,
  sanitizeBrandColor,
  sanitizeLogoUrl,
  sanitizeSupportAddress,
  sanitizeSupportEmail,
  TENANT_SETTINGS_LIMITS,
  TIMEZONE_OPTIONS,
  validateTenantSettings,
} from "./tenantSettings.utils";

function getEmptySettings(): OrganisationSettings {
  return {
    timezone: "",
    region: "",
    dataResidency: "",
    locale: "",
    logoUrl: "",
    brandPrimaryColor: "",
    brandSecondaryColor: "",
    brandAccentColor: "",
    supportEmail: "",
    supportAddress: "",
  };
}

function getColorPickerValue(value: string): string {
  const trimmed = value.trim();
  return /^#([0-9a-fA-F]{6})$/.test(trimmed) ? trimmed : "#000000";
}

function normalizeSettings(settings: OrganisationSettings): OrganisationSettings {
  return {
    ...settings,
    timezone: normalizeSelectValue(settings.timezone, TIMEZONE_OPTIONS),
    region: normalizeSelectValue(settings.region, REGION_OPTIONS),
    dataResidency: normalizeSelectValue(settings.dataResidency, DATA_RESIDENCY_OPTIONS),
    locale: normalizeSelectValue(settings.locale, LOCALE_OPTIONS),
  };
}

const inputClassName = cn(
  "h-10 rounded-[14px] border-[#dce5ee] bg-white px-4 shadow-none",
  "text-[14px] text-[#2b3946] placeholder:text-[#97a4b0]",
  "focus-visible:border-[#dce5ee] focus-visible:ring-0",
);

const selectTriggerClassName = cn(
  "h-10 w-full rounded-[14px] border-[#dce5ee] bg-white px-4 shadow-none",
  "text-[14px] text-[#2b3946] data-[placeholder]:text-[#97a4b0] [&_svg]:text-[#97a4b0]",
);

function TenantSettings() {
  const { slug } = useParams();
  const location = useLocation();
  const navigate = useNavigate();
  const [values, setValues] = useState<OrganisationSettings>(getEmptySettings);
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const [toastType, setToastType] = useState<"success" | "error" | "info">("info");

  const organisationIdFromState =
    (location.state as { organisationId?: number | null } | null)?.organisationId ?? null;
  const shouldResolveIdBySlug = organisationIdFromState === null && Boolean(slug);

  const slugLookupFilters = useMemo(
    () => ({
      search: slug ?? "",
      status: "",
      plan: "",
      createdFrom: "",
      createdTo: "",
      region: "",
      dataResidency: "",
      page: 1,
      pageSize: 25,
      sort: "createdAt",
      order: "desc" as const,
      exportData: false,
    }),
    [slug],
  );

  const { data: organisationListData } = useGetOrganisationsQuery(slugLookupFilters, {
    skip: !shouldResolveIdBySlug,
  });

  const resolvedOrganisation = useMemo(() => {
    return organisationListData?.rows.find((row) => row.slug === slug) ?? null;
  }, [organisationListData?.rows, slug]);

  const resolvedOrganisationId = useMemo(() => {
    if (organisationIdFromState) return organisationIdFromState;
    if (!resolvedOrganisation) return null;
    const parsed = Number.parseInt(resolvedOrganisation.id, 10);
    return Number.isNaN(parsed) ? null : parsed;
  }, [organisationIdFromState, resolvedOrganisation]);

  const orgName = useMemo(() => {
    if (resolvedOrganisation?.name) return resolvedOrganisation.name;
    if (!slug) return "Organisation";
    return slug
      .split("-")
      .filter(Boolean)
      .map((part) => part[0]?.toUpperCase() + part.slice(1))
      .join(" ");
  }, [resolvedOrganisation?.name, slug]);

  const {
    data: settingsData,
    isLoading: isLoadingSettings,
    isError: isSettingsError,
    error: settingsError,
    refetch: refetchSettings,
  } = useGetOrganisationSettingsQuery(resolvedOrganisationId ?? 0, {
    skip: resolvedOrganisationId === null,
  });
  const [updateOrganisationSettings, { isLoading: isSaving }] =
    useUpdateOrganisationSettingsMutation();

  useEffect(() => {
    if (settingsData) {
      setValues(normalizeSettings(settingsData));
    } else {
      setValues(getEmptySettings());
    }
  }, [settingsData]);

  useEffect(() => {
    if (!isSettingsError) return;
    setToastType("error");
    setToastMessage(getApiErrorMessage(settingsError));
  }, [isSettingsError, settingsError]);

  function showToast(type: "success" | "error", message: string) {
    setToastType(type);
    setToastMessage(message);
  }

  function handleBackToOrganisation() {
    if (!slug) {
      navigate("/super-admin/organisations");
      return;
    }

    navigate("/super-admin/organisations/" + slug, {
      state: {
        organisationId: resolvedOrganisationId,
        organisationSlug: slug,
      },
    });
  }

  function setField<K extends keyof OrganisationSettings>(
    key: K,
    value: OrganisationSettings[K],
  ) {
    setValues((previous) => ({ ...previous, [key]: value }));
  }

  function handleDiscard() {
    setValues(normalizeSettings(settingsData ?? getEmptySettings()));
    handleBackToOrganisation();
  }

  async function handleSave() {
    if (!resolvedOrganisationId) {
      showToast("error", "Organisation id is missing.");
      return;
    }

    const validationError = validateTenantSettings(values);
    if (validationError) {
      showToast("error", validationError);
      return;
    }

    try {
      await updateOrganisationSettings({
        id: resolvedOrganisationId,
        body: {
          ...values,
          timezone: values.timezone.trim(),
          region: values.region.trim(),
          dataResidency: values.dataResidency.trim(),
          locale: values.locale.trim(),
          logoUrl: values.logoUrl.trim(),
          brandPrimaryColor: values.brandPrimaryColor.trim(),
          brandSecondaryColor: values.brandSecondaryColor.trim(),
          brandAccentColor: values.brandAccentColor.trim(),
          supportEmail: values.supportEmail.trim(),
          supportAddress: values.supportAddress.trim(),
        },
      }).unwrap();
      await refetchSettings();
      showToast("success", `Tenant settings updated for ${orgName}.`);
    } catch (error) {
      showToast("error", getApiErrorMessage(error));
    }
  }

  return (
    <div className="relative flex h-full min-h-0 w-full flex-col bg-[#FAFAFB]">
      {toastMessage ? (
        <Toast
          message={toastMessage}
          type={toastType}
          onClose={() => setToastMessage(null)}
        />
      ) : null}

      {isSaving ? (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-white/50 backdrop-blur-[1px]">
          <div className="flex flex-col items-center gap-2 rounded-xl border border-[#e3ebf3] bg-white p-4 shadow-lg">
            <Loader2 className="h-7 w-7 animate-spin text-[#435564]" />
            <span className="text-sm font-medium text-[#435564]">Saving settings...</span>
          </div>
        </div>
      ) : null}

      <div className="flex shrink-0 flex-col gap-6 pb-4">
        <div className="flex items-center justify-between gap-4">
          <div className="flex min-w-0 flex-1 items-center gap-3">
            <button
              type="button"
              className="inline-flex shrink-0 items-center gap-2 rounded-full border border-[#dce5ee] bg-white px-3 py-1.5 text-[12px] font-medium text-[#2b3946] hover:bg-[#f7fafc]"
              onClick={handleBackToOrganisation}
            >
              <ArrowLeft size={14} aria-hidden="true" />
              Back
            </button>

            <div className="min-w-0 flex flex-1 items-center gap-1.5 overflow-hidden text-[13px] font-medium text-[#7c8a97]">
              <button
                type="button"
                onClick={() => navigate("/super-admin/dashboard")}
                className="shrink-0 cursor-pointer transition-colors hover:text-[#2b3946] hover:underline"
              >
                Super Admin
              </button>
              <span className="shrink-0">/</span>
              <button
                type="button"
                onClick={() => navigate("/super-admin/organisations")}
                className="shrink-0 cursor-pointer transition-colors hover:text-[#2b3946] hover:underline"
              >
                Organisations
              </button>
              <span className="shrink-0">/</span>
              <button
                type="button"
                onClick={handleBackToOrganisation}
                className="min-w-0 truncate cursor-pointer transition-colors hover:text-[#2b3946] hover:underline"
                title={orgName}
              >
                {orgName}
              </button>
              <span className="shrink-0">/</span>
              <span className="min-w-0 truncate text-[#2b3946]" title="Tenant Settings">
                Tenant Settings
              </span>
            </div>
          </div>

          <SuperAdminHeaderActions />
        </div>

        <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
          <div>
            <h1 className="text-[#1f2d38] text-[24px] font-semibold leading-7">
              Tenant Settings
            </h1>
            <p className="mt-1 text-[#667483] text-[13px] leading-5">
              Configure timezone, residency, locale, branding, and support details.
            </p>
          </div>

          <div className="flex shrink-0 items-center gap-3">
            <Button
              variant="outline"
              className="h-10 rounded-full border-[#dce5ee] bg-white px-4 text-[12px] font-medium text-[#667483]"
              onClick={handleDiscard}
              disabled={isSaving}
            >
              Discard
            </Button>
            <Button
              className="h-10 rounded-full bg-[#435564] px-5 text-[12px] font-semibold text-white hover:bg-[#394957]"
              onClick={handleSave}
              disabled={isSaving || isLoadingSettings}
            >
              {isSaving ? "Saving..." : "Save Changes"}
            </Button>
          </div>
        </div>
      </div>

      <div
        className="min-h-0 flex-1 overflow-y-auto pb-6 pr-1"
        style={{
          scrollBehavior: "smooth",
          scrollbarGutter: "stable",
          overscrollBehavior: "contain",
        }}
      >
        <div className="rounded-[16px] border border-[#e3ebf3] bg-white p-5 shadow-[0_1px_2px_rgba(15,23,42,0.04)]">
          {isLoadingSettings ? (
            <div className="mb-4 text-sm text-[#667483]">Loading tenant settings...</div>
          ) : null}

          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            <Field label="Timezone" required>
              <Select
                value={values.timezone || undefined}
                onValueChange={(value) => setField("timezone", value)}
              >
                <SelectTrigger className={selectTriggerClassName}>
                  <SelectValue placeholder="Choose timezone" />
                </SelectTrigger>
                <SelectContent className="rounded-[14px] border border-[#dce5ee] bg-white shadow-[0_12px_28px_rgba(15,23,42,0.08)]">
                  {TIMEZONE_OPTIONS.map((option) => (
                    <SelectItem
                      key={option.value}
                      value={option.value}
                      className="text-[#2b3946] focus:bg-[#f4f7fa] focus:text-[#2b3946]"
                    >
                      {option.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </Field>

            <Field label="Region" required>
              <Select
                value={values.region || undefined}
                onValueChange={(value) => setField("region", value)}
              >
                <SelectTrigger className={selectTriggerClassName}>
                  <SelectValue placeholder="Choose infrastructure region" />
                </SelectTrigger>
                <SelectContent className="rounded-[14px] border border-[#dce5ee] bg-white shadow-[0_12px_28px_rgba(15,23,42,0.08)]">
                  {REGION_OPTIONS.map((option) => (
                    <SelectItem
                      key={option.value}
                      value={option.value}
                      className="text-[#2b3946] focus:bg-[#f4f7fa] focus:text-[#2b3946]"
                    >
                      {option.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </Field>

            <Field label="Data Residency" required>
              <Select
                value={values.dataResidency || undefined}
                onValueChange={(value) => setField("dataResidency", value)}
              >
                <SelectTrigger className={selectTriggerClassName}>
                  <SelectValue placeholder="Choose data residency" />
