function CreateAddOnModal(props: CreateAddOnModalProps) {
  const [createAddOn, { isLoading: isSaving }] = useCreateAddOnCatalogItemMutation();
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const [toastType, setToastType] = useState<"success" | "error" | "info">("info");

  const [code, setCode] = useState("");
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [priceUsd, setPriceUsd] = useState("");
  const [billingCycle, setBillingCycle] = useState<AddOnBillingCycle>("MONTHLY");
  const [status, setStatus] = useState<AddOnCatalogStatus>("ACTIVE");

  useEffect(() => {
    if (!props.open) return;

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") props.onClose();
    }

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [props]);

  useEffect(() => {
    if (!props.open) return;
    setCode("");
    setName("");
    setDescription("");
    setPriceUsd("");
    setBillingCycle("MONTHLY");
    setStatus("ACTIVE");
    setToastMessage(null);
  }, [props.open]);

  function showToast(type: "success" | "error", message: string) {
    setToastType(type);
    setToastMessage(message);
  }

  async function handleCreate() {
    const validationError = validateCreateAddOnFields({
      code,
      name,
      description,
      priceUsd,
    });
    if (validationError) {
      showToast("error", validationError);
      return;
    }

    try {
      const created = await createAddOn({
        code: code.trim(),
        name: name.trim(),
        description: description.trim(),
        priceUsd: parseAddOnPriceUsd(priceUsd),
        billingCycle,
        status,
      }).unwrap();

      showToast("success", "Add-on created successfully.");
      props.onCreated?.(created);
      window.setTimeout(() => {
        props.onClose();
      }, 700);
    } catch (error) {
      showToast("error", getApiErrorMessage(error));
    }
  }

  if (!props.open) return null;

  return (
    <div className="fixed inset-0 z-[10040]">
      {toastMessage ? (
        <Toast
          message={toastMessage}
          type={toastType}
          onClose={() => setToastMessage(null)}
        />
      ) : null}

      <button
        type="button"
        className="absolute inset-0 bg-[rgba(15,23,42,0.26)] backdrop-blur-[2px]"
        aria-label="Close modal"
        onClick={props.onClose}
        disabled={isSaving}
      />

      <div className="absolute inset-0 flex items-end justify-center p-0 sm:items-center sm:p-4 sm:py-8">
        <div
          className={cn(
            "flex max-h-[min(100dvh,100%)] w-full max-w-[640px] flex-col overflow-hidden",
            "rounded-t-[14px] border border-[#e3eaf1] bg-white sm:max-h-[min(90dvh,calc(100dvh-2rem))] sm:rounded-[14px]",
            "shadow-[0_24px_60px_rgba(15,23,42,0.16)]",
          )}
          role="dialog"
          aria-modal="true"
          aria-label="Create add-on"
        >
          <div className="flex shrink-0 items-start justify-between gap-4 border-b border-[#e8eef4] px-[18px] py-[14px]">
            <div className="min-w-0 truncate pr-2 text-[20px] font-semibold leading-7 text-[#1f2d38]">
              Create Add-on
            </div>

            <button
              type="button"
              onClick={props.onClose}
              disabled={isSaving}
              className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-[#1f2d38] transition-colors hover:bg-[#f3f6f9] disabled:opacity-60"
              aria-label="Close"
            >
              <X size={18} strokeWidth={1.8} aria-hidden="true" />
            </button>
          </div>

          <div
            className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-[18px] py-[18px]"
            style={{ WebkitOverflowScrolling: "touch" }}
          >
            <div className="flex flex-col gap-[12px]">
              <div className={getFieldShellClassName()}>
                <div className={getLabelClassName()}>
                  Code <span className="text-[#ef4444]">*</span>
                </div>
                <Input
                  value={code}
                  maxLength={CREATE_ADD_ON_LIMITS.codeMax}
                  placeholder="e.g. extra_storage"
                  onChange={(event) => setCode(sanitizeAddOnCode(event.target.value))}
                  className={getInputClassName()}
                />
              </div>

              <div className={getFieldShellClassName()}>
                <div className={getLabelClassName()}>
                  Name <span className="text-[#ef4444]">*</span>
                </div>
                <Input
                  value={name}
                  maxLength={CREATE_ADD_ON_LIMITS.nameMax}
                  placeholder="Enter add-on name"
                  onChange={(event) => setName(sanitizeAddOnName(event.target.value))}
                  className={getInputClassName()}
                />
              </div>

              <div className={getFieldShellClassName()}>
                <div className={getLabelClassName()}>Description</div>
                <Textarea
                  value={description}
                  maxLength={CREATE_ADD_ON_LIMITS.descriptionMax}
                  placeholder="Optional description"
                  onChange={(event) =>
                    setDescription(sanitizeAddOnDescription(event.target.value))
                  }
                  className={getTextareaClassName()}
                />
              </div>

              <div className={getFieldShellClassName()}>
                <div className={getLabelClassName()}>
                  Price (USD) <span className="text-[#ef4444]">*</span>
                </div>
                <Input
                  value={priceUsd}
                  maxLength={CREATE_ADD_ON_LIMITS.priceMaxChars}
                  inputMode="decimal"
                  placeholder="0.00"
                  onChange={(event) => setPriceUsd(sanitizeAddOnPrice(event.target.value))}
                  className={getInputClassName()}
                />
              </div>

              <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                <div className="min-w-0">
                  <div className="mb-1 text-[11px] font-medium leading-4 text-[#667483]">
                    Billing Cycle <span className="text-[#ef4444]">*</span>
                  </div>
                  <Select
                    value={billingCycle}
                    onValueChange={(value) => setBillingCycle(value as AddOnBillingCycle)}
                  >
                    <SelectTrigger className={getSelectTriggerClassName()}>
                      <SelectValue placeholder="Select billing cycle" />
                    </SelectTrigger>
                    <SelectContent
                      position="popper"
                      side="bottom"
                      align="start"
                      collisionPadding={12}
                      className={getSelectContentClassName()}
                    >
                      <SelectItem value="MONTHLY">Monthly</SelectItem>
                      <SelectItem value="ANNUAL">Annual</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div className="min-w-0">
                  <div className="mb-1 text-[11px] font-medium leading-4 text-[#667483]">
                    Status <span className="text-[#ef4444]">*</span>
                  </div>
                  <Select
                    value={status}
                    onValueChange={(value) => setStatus(value as AddOnCatalogStatus)}
                  >
                    <SelectTrigger className={getSelectTriggerClassName()}>
                      <SelectValue placeholder="Select status" />
                    </SelectTrigger>
                    <SelectContent
                      position="popper"
                      side="bottom"
                      align="start"
                      collisionPadding={12}
                      className={getSelectContentClassName()}
                    >
                      <SelectItem value="ACTIVE">Active</SelectItem>
                      <SelectItem value="INACTIVE">Archived</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
            </div>
          </div>

          <div className="flex shrink-0 flex-wrap items-center justify-end gap-[10px] border-t border-[#e8eef4] px-[18px] py-[15px]">
            <Button
              type="button"
              variant="outline"
              className={getSecondaryButtonClassName()}
              onClick={props.onClose}
              disabled={isSaving}
            >
              Cancel
            </Button>
            <Button
              type="button"
              className={getPrimaryButtonClassName()}
              onClick={handleCreate}
              disabled={isSaving}
            >
              {isSaving ? "Creating..." : "Create Add-on"}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default CreateAddOnModal;

