            variant="outline"
            className={getSecondaryButtonClassName()}
            onClick={handleApplyDefaults}
          >
            <RefreshCw size={14} aria-hidden="true" />
            Apply Plan Defaults
          </Button>
          <Button type="button" className={getPrimaryButtonClassName()}>
            <CheckCircle2 size={15} aria-hidden="true" />
            Save Entitlements
          </Button>
        </div>
      </div>

      <FeatureCatalogTable
        rows={rows}
        isLoading={isLoading}
        onToggleDefault={async function (keyName, next) {
          setRows(function (previousRows) {
            return previousRows.map(function (row) {
              if (row.keyName === keyName) {
                return { ...row, globalDefault: next };
              }

              return row;
            });
          });
          try {
            await toggleFeatureFlagDefault({ key: keyName, enabled: next }).unwrap();
            showToast("success", "Global default updated successfully.");
            await refetch();
          } catch (error) {
            setRows(function (previousRows) {
              return previousRows.map(function (row) {
                if (row.keyName === keyName) {
                  return { ...row, globalDefault: !next };
                }
                return row;
              });
            });
            showToast("error", getApiErrorMessage(error));
          }
        }}
        onViewHistory={setHistoryRow}
        onDelete={setRowToDelete}
        onEdit={setRowToEdit}
      />

      {historyRow ? (
        <div className="fixed inset-0 z-50">
          <button
            type="button"
            className="absolute inset-0 bg-black/20"
            aria-label="Close history"
            onClick={function () {
              setHistoryRow(null);
            }}
          />

          <div className="absolute right-0 top-0 h-full w-full max-w-[560px] border-l border-[#e3ebf3] bg-white shadow-[-8px_0_24px_rgba(15,23,42,0.08)]">
            <div className="flex items-start justify-between border-b border-[#edf2f7] px-6 py-5">
              <div>
                <div className="text-[18px] font-semibold leading-7 text-[#1f2d38]">
                  Feature History
                </div>
                <div className="mt-3 flex items-center gap-3">
                  <span className="text-[13px] font-semibold text-[#1f2d38]">
                    {historyRow.name}
                  </span>
                  <span className="text-[11px] text-[#8a96a3]">
                    {historyRow.keyName}
                  </span>
                </div>
              </div>

              <button
                type="button"
                className="grid h-8 w-8 place-items-center rounded-full text-[#1f2d38] transition-colors hover:bg-[#f4f7fa]"
                aria-label="Close history panel"
                onClick={function () {
                  setHistoryRow(null);
                }}
              >
                <X size={18} aria-hidden="true" />
              </button>
            </div>

            <div className="flex h-[calc(100%-96px)] flex-col gap-8 overflow-auto px-6 py-6">
              {isHistoryLoading ? (
                <div className="text-sm text-[#667483]">Loading history...</div>
              ) : null}
              {!isHistoryLoading && historyRows.length === 0 ? (
                <div className="text-sm text-[#667483]">No history found.</div>
              ) : null}
              {historyRows.map(function (event, index) {
                return (
                  <div key={event.id || `${event.createdAt}-${index}`} className="relative pl-7">
                    {index !== historyRows.length - 1 ? (
                      <span className="absolute left-[3px] top-3 h-[calc(100%+24px)] w-px bg-[#d8e2ec]" />
                    ) : (
                      <span className="absolute left-[3px] top-3 h-[calc(100%-16px)] w-px bg-[#d8e2ec]" />
                    )}
                    <span className="absolute left-0 top-2 h-2.5 w-2.5 rounded-full bg-[#98a4b3]" />

                    <div className="text-[13px] font-medium leading-5 text-[#334155]">
                      {event.createdAt ? (
                        new Intl.DateTimeFormat("en-US", {
                          year: "numeric",
                          month: "short",
                          day: "2-digit",
                          hour: "numeric",
                          minute: "2-digit",
                        }).format(new Date(event.createdAt))
                      ) : "-"}
                    </div>

                    <div className="mt-4 flex items-center gap-3">
                      <div className="flex h-8 w-8 items-center justify-center rounded-full bg-[#efe6dd] text-[10px] font-semibold text-[#7a6757]">
                        {event.authId ? <User size={14} /> : "SA"}
                      </div>
                      <div className="text-[13px] font-medium text-[#2b3946]">
                        {event.action
                          ? event.action
                              .split("_")
                              .map(
                                (word) =>
                                  word.charAt(0).toUpperCase() +
                                  word.slice(1).toLowerCase()
                              )
                              .join(" ")
                          : "Updated"}
                      </div>
                    </div>

                    <div className="mt-4 rounded-[20px] border border-[#EDEEF1] bg-[#FAFAFB] px-5 py-5">
                      <div className="text-[13px] text-[#1f2d38] break-words">
                        {event.details || event.resourceType || "Feature catalog change"}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      ) : null}

      <ConfirmationModal
        type="delete"
        isOpen={Boolean(rowToDelete)}
        onClose={() => setRowToDelete(null)}
        onConfirm={handleConfirmDelete}
        title={`Delete feature "${rowToDelete?.name || rowToDelete?.keyName || ""}"?`}
        description="Are you sure you want to delete this feature catalog entry?"
        confirmButtonText={isDeletingFeature ? "Deleting..." : "Delete feature"}
        confirmButtonDisabled={isDeletingFeature}
      />

      <EditFeatureModal
        row={rowToEdit}
        onClose={() => setRowToEdit(null)}
        onUpdated={refetch}
      />
    </SuperAdminPageShell>
  );
};

