import { useEffect } from "react";
import { Loader, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { cn } from "@/lib/utils";
import {
  CREATE_ROLE_FIELD_LIMITS,
  sanitizeDisplayName,
  sanitizeRoleDescription,
  sanitizeRoleName,
} from "../createRole.utils";

export interface EditRoleFormValues {
  roleId: number;
  key: string;
  name: string;
  displayName: string;
  description: string;
  isActive: boolean;
  organisationId: number | null;
}

interface EditRoleModalProps {
  form: EditRoleFormValues | null;
  isLoading: boolean;
  isSaving: boolean;
  onClose(): void;
  onSave(): void;
  onChange(updater: (previous: EditRoleFormValues) => EditRoleFormValues): void;
}

function getSecondaryButtonClassName(): string {
  return cn(
    "h-[34px] min-w-[83px] rounded-full border border-[#dbe4ec] bg-white px-5",
    "text-[#5e6c78] text-[13px] font-medium leading-5 shadow-none hover:bg-[#f7fafc]",
  );
}

function getPrimaryButtonClassName(): string {
  return cn(
    "h-[34px] min-w-[83px] rounded-full bg-[#435564] px-5",
    "text-white text-[13px] font-medium leading-5 shadow-none hover:bg-[#394957]",
  );
}

function getFieldInputClassName(): string {
  return cn(
    "h-[44px] rounded-[14px] border border-[#dbe4ec] bg-white px-[13px] shadow-none",
    "text-[13px] font-normal leading-5 text-[#2b3946] placeholder:text-[#97a4b0]",
    "focus-visible:border-[#dce5ee] focus-visible:ring-0",
  );
}

function EditRoleModal(props: EditRoleModalProps) {
  useEffect(() => {
    if (!props.form) return;

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape" && !props.isSaving) props.onClose();
    }

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [props]);

  if (!props.form) return null;

  return (
    <div className="fixed inset-0 z-[10040]">
      <button
        type="button"
        className="absolute inset-0 bg-[rgba(15,23,42,0.26)] backdrop-blur-[2px]"
        aria-label="Close modal"
        onClick={props.onClose}
        disabled={props.isSaving}
      />

      <div className="absolute inset-0 flex items-end justify-center p-0 sm:items-center sm:p-4 sm:py-8">
        <div
          className={cn(
            "flex max-h-[min(100dvh,100%)] w-full max-w-[560px] flex-col overflow-hidden",
            "rounded-t-[14px] border border-[#e3eaf1] bg-white sm:max-h-[min(90dvh,calc(100dvh-2rem))] sm:rounded-[14px]",
            "shadow-[0_24px_60px_rgba(15,23,42,0.16)]",
          )}
          role="dialog"
          aria-modal="true"
          aria-label="Edit role"
        >
          <div className="flex shrink-0 items-start justify-between gap-4 border-b border-[#e8eef4] px-[18px] py-[14px]">
            <div className="min-w-0 truncate pr-2 text-[20px] font-semibold leading-7 text-[#1f2d38]">
              Edit Role
            </div>
            <button
              type="button"
              onClick={props.onClose}
              disabled={props.isSaving || props.isLoading}
              className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-[#1f2d38] transition-colors hover:bg-[#f3f6f9] disabled:opacity-60"
              aria-label="Close"
            >
              <X size={18} strokeWidth={1.8} aria-hidden="true" />
            </button>
          </div>

          {props.isLoading ? (
            <div className="flex min-h-[240px] flex-1 items-center justify-center px-[18px] py-10">
              <div className="flex items-center gap-2 text-[#667483]">
                <Loader className="h-5 w-5 animate-spin text-[#435564]" />
                <span className="text-sm">Loading role details...</span>
              </div>
            </div>
          ) : (
            <div
              className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-[18px] py-[18px]"
              style={{ WebkitOverflowScrolling: "touch" }}
            >
              <div className="space-y-4">
                <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                  <div className="min-w-0">
                    <label className="mb-1 block text-[11px] font-medium text-[#667483]">
                      Name <span className="text-[#ef4444]">*</span>
                    </label>
                    <Input
                      value={props.form.name}
                      onChange={(event) =>
                        props.onChange((previous) => ({
                          ...previous,
                          name: sanitizeRoleName(event.target.value),
                        }))
                      }
                      maxLength={CREATE_ROLE_FIELD_LIMITS.roleName}
                      className={getFieldInputClassName()}
                    />
                    <p className="mt-1.5 text-[11px] text-[#a0acb8]">
                      Letters, numbers, and underscores only ({props.form.name.trim().length}/
                      {CREATE_ROLE_FIELD_LIMITS.roleName})
                    </p>
                  </div>

                  <div className="min-w-0">
                    <label className="mb-1 block text-[11px] font-medium text-[#667483]">
                      Display Name <span className="text-[#ef4444]">*</span>
                    </label>
                    <Input
                      value={props.form.displayName}
                      onChange={(event) =>
                        props.onChange((previous) => ({
                          ...previous,
                          displayName: sanitizeDisplayName(event.target.value),
                        }))
                      }
                      maxLength={CREATE_ROLE_FIELD_LIMITS.displayName}
                      className={getFieldInputClassName()}
                    />
                    <p className="mt-1.5 text-[11px] text-[#a0acb8]">
                      Shown in the UI ({props.form.displayName.length}/
                      {CREATE_ROLE_FIELD_LIMITS.displayName})
                    </p>
                  </div>
                </div>

                <div className="min-w-0">
                  <label className="mb-1 block text-[11px] font-medium text-[#667483]">
                    Description
                  </label>
                  <Textarea
                    value={props.form.description}
                    onChange={(event) =>
                      props.onChange((previous) => ({
                        ...previous,
                        description: sanitizeRoleDescription(event.target.value),
                      }))
                    }
                    maxLength={CREATE_ROLE_FIELD_LIMITS.description}
                    className="min-h-[98px] resize-none rounded-[14px] border border-[#dbe4ec] bg-white px-[13px] py-3 text-[13px] text-[#2b3946] placeholder:text-[#97a4b0] focus-visible:border-[#dce5ee] focus-visible:ring-0"
                  />
                  <p className="mt-1.5 text-[11px] text-[#a0acb8]">
                    {props.form.description.length}/{CREATE_ROLE_FIELD_LIMITS.description}
                  </p>
                </div>

                <div className="flex items-center justify-between rounded-[12px] border border-[#e4ebf3] bg-[#fbfdff] px-3 py-2.5">
                  <div className="text-[14px] font-medium text-[#2f3d4b]">Role Active</div>
                  <Switch
                    checked={props.form.isActive}
                    onCheckedChange={(value) =>
                      props.onChange((previous) => ({
                        ...previous,
                        isActive: value,
                      }))
                    }
                    className="h-5 w-8"
                    onClassName="bg-[#435564]"
                    offClassName="bg-[#dfe5ec]"
                  />
                </div>
              </div>
            </div>
          )}

          <div className="flex shrink-0 flex-wrap items-center justify-end gap-[10px] border-t border-[#e8eef4] px-[18px] py-[15px]">
            <Button
              type="button"
              variant="outline"
              className={getSecondaryButtonClassName()}
              onClick={props.onClose}
              disabled={props.isSaving || props.isLoading}
            >
              Cancel
            </Button>
            <Button
              type="button"
              className={getPrimaryButtonClassName()}
              onClick={props.onSave}
              disabled={props.isSaving || props.isLoading}
            >
              {props.isSaving ? "Saving..." : "Save"}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

