type MenuItemWithRoute = MenuItem & { routeId?: StaffRouteId };

function filterStaffMenuItems(
  items: MenuItemWithRoute[],
  permissions: string[],
): MenuItem[] {
  return items
    .map(function (item) {
      if (item.children?.length) {
        const children = filterStaffMenuItems(
          item.children as MenuItemWithRoute[],
          permissions,
        );
        if (!children.length) return null;
        return { ...item, children };
      }

      if (item.routeId && !canAccessStaffRoute(permissions, item.routeId)) {
        return null;
      }

      const { routeId: _routeId, ...menuItem } = item;
      return menuItem;
    })
    .filter(Boolean) as MenuItem[];
}

export function buildStaffMenuItems(permissions: string[]): MenuItem[] {
  if (!permissions.length) {
    return STAFF_MENU_DEFINITION.map(function (item) {
      const { routeId: _routeId, ...menuItem } = item;
      if (menuItem.children) {
        return {
          ...menuItem,
          children: menuItem.children.map(function (child) {
            const { routeId: _childRouteId, ...childItem } = child as MenuItemWithRoute;
            return childItem;
          }),
        };
      }
      return menuItem;
    });
  }

  return filterStaffMenuItems(STAFF_MENU_DEFINITION, permissions);
}

