import type { AppRole } from "./roleMapper";

export type StoredSession = {
  accessToken: string;
  refreshToken: string;
  role: AppRole;
  tenantSubdomain?: string;
  tenantSlug?: string;
  user?: unknown;
  client?: unknown;
  apiRoles?: string[];
  permissions?: string[];
};

const AUTH_SESSION_KEY = "auth_session";
const LEGACY_USER_KEY = "loggedInUser";

export function setAuthSession(session: StoredSession) {
  localStorage.setItem(AUTH_SESSION_KEY, JSON.stringify(session));
  localStorage.setItem(LEGACY_USER_KEY, JSON.stringify({ role: session.role }));
}

export function getAuthSession(): StoredSession | null {
  const raw = localStorage.getItem(AUTH_SESSION_KEY);
  if (!raw || raw === "undefined") {
    return null;
  }

  try {
    return JSON.parse(raw) as StoredSession;
  } catch {
    return null;
  }
}

export function clearAuthSession() {
  localStorage.removeItem(AUTH_SESSION_KEY);
  localStorage.removeItem(LEGACY_USER_KEY);
}

export function getStoredUserRole(): StoredSession["role"] | null {
  const session = getAuthSession();
  if (session?.role) {
    return session.role;
  }

  const legacyRaw = localStorage.getItem(LEGACY_USER_KEY);
  if (!legacyRaw || legacyRaw === "undefined") {
    return null;
  }

  try {
    const legacy = JSON.parse(legacyRaw) as { role?: StoredSession["role"] };
    return legacy.role ?? null;
  } catch {
    return null;
  }
}

import { createSlice, type PayloadAction } from "@reduxjs/toolkit";
import { getAuthSession, setAuthSession, clearAuthSession } from "@/utils/authStorage";
import type { AppRole } from "@/utils/roleMapper";
import type { ClientProfile, StaffProfile } from "@/store/api/authApi";

type AuthState = {
  accessToken: string | null;
  refreshToken: string | null;
  role: AppRole | null;
  tenantSubdomain: string | null;
  tenantSlug: string | null;
  user: StaffProfile | null;
  client: ClientProfile | null;
  apiRoles: string[];
  permissions: string[];
};

const stored = getAuthSession();

const initialState: AuthState = {
  accessToken: stored?.accessToken ?? null,
  refreshToken: stored?.refreshToken ?? null,
  role: stored?.role ?? null,
  tenantSubdomain: stored?.tenantSubdomain ?? null,
  tenantSlug: stored?.tenantSlug ?? null,
  user: (stored?.user as StaffProfile) ?? null,
  client: (stored?.client as ClientProfile) ?? null,
  apiRoles: stored?.apiRoles ?? [],
  permissions: stored?.permissions ?? [],
};

type SessionPayload = {
  accessToken: string;
  refreshToken: string;
  role: AppRole;
  tenantSubdomain?: string;
  tenantSlug?: string;
  user?: StaffProfile;
  client?: ClientProfile;
  apiRoles?: string[];
  permissions?: string[];
};

function persistSession(state: AuthState, overrides?: Partial<SessionPayload>) {
  if (!state.role || !state.accessToken || !state.refreshToken) return;

  setAuthSession({
    accessToken: overrides?.accessToken ?? state.accessToken,
    refreshToken: overrides?.refreshToken ?? state.refreshToken,
    role: overrides?.role ?? state.role,
    tenantSubdomain: overrides?.tenantSubdomain ?? state.tenantSubdomain ?? undefined,
    tenantSlug: overrides?.tenantSlug ?? state.tenantSlug ?? undefined,
    user: overrides?.user ?? state.user ?? undefined,
    client: overrides?.client ?? state.client ?? undefined,
    apiRoles: overrides?.apiRoles ?? state.apiRoles,
    permissions: overrides?.permissions ?? state.permissions,
  });
}

const authSlice = createSlice({
  name: "auth",
  initialState,
  reducers: {
    setSession: (state, action: PayloadAction<SessionPayload>) => {
      state.accessToken = action.payload.accessToken;
      state.refreshToken = action.payload.refreshToken;
      state.role = action.payload.role;
      state.tenantSubdomain = action.payload.tenantSubdomain ?? null;
      state.tenantSlug = action.payload.tenantSlug ?? null;
      state.user = action.payload.user ?? null;
      state.client = action.payload.client ?? null;
      state.apiRoles = action.payload.apiRoles ?? [];
      state.permissions = action.payload.permissions ?? [];
      persistSession(state, action.payload);
    },
    setStaffAccess: (
      state,
      action: PayloadAction<{ apiRoles?: string[]; permissions?: string[] }>,
    ) => {
      if (action.payload.apiRoles) {
        state.apiRoles = action.payload.apiRoles;
      }
      if (action.payload.permissions) {
        state.permissions = action.payload.permissions;
      }
      persistSession(state);
    },
    clearSession: (state) => {
      state.accessToken = null;
      state.refreshToken = null;
      state.role = null;
      state.tenantSubdomain = null;
      state.tenantSlug = null;
      state.user = null;
      state.client = null;
      state.apiRoles = [];
      state.permissions = [];
      clearAuthSession();
    },
    updateTokens: (
      state,
      action: PayloadAction<{ accessToken: string; refreshToken: string }>,
    ) => {
      state.accessToken = action.payload.accessToken;
      state.refreshToken = action.payload.refreshToken;
      persistSession(state, action.payload);
    },
  },
});

export const { setSession, setStaffAccess, clearSession, updateTokens } = authSlice.actions;
export default authSlice.reducer;

import { useMemo } from "react";
import { useAppSelector } from "@/store/hooks";
import {
  canAccessStaffRoute,
  canStaffCapability,
  getStaffCapabilities,
  hasPermission,
  type StaffCapability,
  type StaffRouteId,
} from "@/utils/staffPermissions";

export function useStaffAccess() {
  const role = useAppSelector((state) => state.auth.role);
  const apiRoles = useAppSelector((state) => state.auth.apiRoles);
  const permissions = useAppSelector((state) => state.auth.permissions);

  const capabilities = useMemo(
    () => getStaffCapabilities(role, apiRoles),
    [role, apiRoles],
  );

  return {
    role,
    apiRoles,
    permissions,
    capabilities,
    can(permission: string) {
      return hasPermission(permissions, permission);
    },
    canRoute(routeId: StaffRouteId) {
      if (role !== "staff") return true;
      return canAccessStaffRoute(permissions, routeId);
    },
    canCapability(capability: StaffCapability) {
      return canStaffCapability(role, apiRoles, permissions, capability);
    },
  };
}

import { useEffect } from "react";
import { useGetAuthMeQuery } from "@/store/api/authApi";
import { useAppDispatch, useAppSelector } from "@/store/hooks";
import { setStaffAccess } from "@/store/authSlice";
import { normalizeApiRoles } from "@/utils/staffPermissions";

export function useStaffPermissionsBootstrap(): void {
  const dispatch = useAppDispatch();
  const accessToken = useAppSelector((state) => state.auth.accessToken);
  const role = useAppSelector((state) => state.auth.role);

  const { data } = useGetAuthMeQuery(undefined, {
    skip: !accessToken || role !== "staff",
    refetchOnMountOrArgChange: true,
  });

  useEffect(() => {
    if (!data || role !== "staff") return;

    dispatch(
      setStaffAccess({
        apiRoles: normalizeApiRoles(data.roles),
        permissions: data.permissions ?? data.authorities ?? [],
      }),
    );
  }, [data, dispatch, role]);
}

