import type { Task } from "@/pages/therapist/tasks/tasks.static";
import { Calendar } from "lucide-react";
import { MessageSquareText } from "lucide-react";
import { Badge } from "../ui/badge";
import { Button } from "../ui/button";

interface StaffTaskCardProps {
  task: Task;
  onViewDetails: (task: Task) => void;
}

const StaffTaskCard = ({ task, onViewDetails }: StaffTaskCardProps) => {
  const displayDueDate = task.dueDate?.trim() || "---";

  const getPriorityColor = (priority: string) => {
    switch (priority.toLowerCase()) {
      case "high":
        return "bg-red-50 text-red-600 hover:bg-red-50 border-transparent";
      case "medium":
        return "bg-amber-50 text-amber-600 hover:bg-amber-50 border-transparent";
      case "low":
        return "bg-[#EEF4FF] text-[#444CE7] hover:bg-[#EEF4FF] border-transparent";
      default:
        return "bg-gray-100 text-gray-700 hover:bg-gray-100 border-transparent";
    }
  };

  const getStatusColor = (status: string) => {
    switch (status.toLowerCase()) {
      case "completed":
        return "bg-[#ECFDF3] text-[#027A48] hover:bg-[#ECFDF3] border-transparent";
      case "in progress":
        return "bg-blue-50 text-blue-700 hover:bg-blue-50 border-transparent";
      case "pending":
        return "bg-gray-100 text-gray-700 hover:bg-gray-100 border-transparent";
      case "needs attention":
        return "bg-amber-50 text-amber-700 hover:bg-amber-50 border-transparent";
      default:
        return "bg-gray-100 text-gray-700 hover:bg-gray-100 border-transparent";
    }
  };

  return (
    <div className="bg-white rounded-[20px] border border-[#EDEEF1] shadow-sm flex flex-col overflow-hidden">
      <div className="p-5 flex flex-col gap-4">
        <div className="flex justify-between items-start">
          <div className="flex gap-2">
            <Badge
              className={`rounded-full px-3 py-1 text-xs font-medium shadow-none ${getPriorityColor(task.priority)}`}
            >
              {task.priority}
            </Badge>
            <Badge
              className={`rounded-full px-3 py-1 text-xs font-medium shadow-none ${getStatusColor(task.status)}`}
            >
              {task.status}
            </Badge>
          </div>
          <div className="flex items-center gap-1.5 text-[#5B616E]">
            <MessageSquareText size={18} strokeWidth={1.5} />
            <span className="text-sm font-medium">{task.commentsCount}</span>
          </div>
        </div>

        <div className="flex flex-col gap-1.5 min-w-0">
          <h3 className="text-lg font-bold text-[#101828] truncate" title={task.title}>
            {task.title}
          </h3>
          <p className="flex min-w-0 items-center justify-between gap-2 text-sm text-[#5B616E]">
            <span className="shrink-0">Client:</span>
            <span
              className="min-w-0 flex-1 truncate text-right text-[#101828]"
              title={task.clientName}
            >
              {task.clientName}
            </span>
          </p>
          <p className="text-sm text-[#5B616E] flex items-center justify-between gap-2 min-w-0">
            <span className="shrink-0">Therapist:</span>
            <span
              className="text-[#101828] truncate min-w-0 text-right"
              title={task.assignee || "Unassigned"}
            >
              {task.assignee || "Unassigned"}
            </span>
          </p>
          <p className="text-sm text-[#5B616E] flex justify-between items-center gap-1.5">
            Created Date:{" "}
            <span className="text-[#101828]">{task.createdDate}</span>
          </p>
        </div>
      </div>

      <div className="bg-(--bg-upload-container) px-5 py-4 border-t border-[#EDEEF1] flex justify-between items-center mt-auto">
        <div className="flex items-center gap-2 text-sm text-[#344054] font-medium">
          <Calendar size={18} className="text-[#5B616E]" strokeWidth={1.5} />
          <span>Due: {displayDueDate}</span>
        </div>
        <Button
          variant="outline"
          className="rounded-full h-9 px-4 font-semibold text-sm border-(--neutral-200) bg-transparent text-(--text-primary-dark) cursor-pointer"
          onClick={() => onViewDetails(task)}
        >
          View Details
        </Button>
      </div>
    </div>
  );
};

