          Rate your session
        </h2>
        <p className="mt-1 text-sm text-(--text-neutral-600)">
          {session.serviceName || session.sessionType || "Therapy Session"} ·{" "}
          {formatBookedSessionDate(session.sessionDate)} at{" "}
          {formatBookedSessionTime(session.sessionDate, session.sessionTime)}
        </p>

        <div className="mt-6 space-y-4">
          <div>
            <label
              htmlFor="session-rating"
              className="mb-2 block text-sm font-medium text-(--text-primary-dark)"
            >
              Rating (0–10)
            </label>
            <input
              id="session-rating"
              type="number"
              min={0}
              max={10}
              step={1}
              value={rating}
              onChange={(event) => setRating(event.target.value)}
              className="h-11 w-full rounded-xl border border-(--neutral-100) px-4 text-sm outline-none focus:border-(--bg-primary-dark)"
            />
          </div>

          <div>
            <label className="mb-2 block text-sm font-medium text-(--text-primary-dark)">
              Comment (optional)
