function sanitizeEmail(value: string): string {
  return value.replace(/\s/g, "").slice(0, PROFILE_FIELD_LIMITS.email);
}

function sanitizePhone(value: string): string {
  const digitsOnly = value.replace(/\D/g, "");
  if (!digitsOnly && !value.includes("+")) {
    return "";
  }
  return `+${digitsOnly}`.slice(0, PROFILE_FIELD_LIMITS.phone);
}

function normalizePhoneFromApi(value: string): string {
  const trimmed = value.trim();
  if (!trimmed) return "";
  return sanitizePhone(trimmed.startsWith("+") ? trimmed : `+${trimmed}`);
}

