import { useState } from "react";
import {
  Pencil,
  Monitor,
  Calendar,
  Check,
  X,
  RefreshCw,
  AlertCircle,
  Play,
  FileText,
  Mic,
  Repeat,
  type LucideIcon,
} from "lucide-react";
import { useLocation } from "react-router-dom";
import { getAllowedBackendSessionStatuses } from "@/utils/sessionStatusTransitions";
import { isRecurringSeriesSession } from "@/utils/recurringSessions";
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
} from "../ui/dropdown-menu";

interface SessionActionsMenuProps {
  onAction?: (action: string) => void;
  hasSubmittedNote?: boolean;
  canRecordSession?: boolean;
  currentStatus?: string;
  recurrenceGroupId?: string | null;
  hideStatusActions?: boolean;
  isVirtualSession?: boolean;
  hideEditAction?: boolean;
}

type SessionMenuItem = {
  icon: LucideIcon;
  label: string;
  action: string;
  iconColor: string;
  iconBg: string;
  hidden?: boolean;
  disabled?: boolean;
};

const isVisibleMenuItem = (item: SessionMenuItem) => !item.hidden;

const SessionActionsMenu = ({
  onAction,
  hasSubmittedNote = false,
  canRecordSession = true,
  currentStatus = "scheduled",
  recurrenceGroupId = null,
  hideStatusActions = false,
  isVirtualSession = false,
  hideEditAction = false,
}: SessionActionsMenuProps) => {
  const [isOpen, setIsOpen] = useState(false);
  const location = useLocation();
  const isAdmin = location.pathname.includes("admin");
  const allowedStatusActions = new Set(getAllowedBackendSessionStatuses(currentStatus));
  const normalizedStatus = currentStatus.trim().toLowerCase().replace(/[\s_-]+/g, "_");
  const showCancelSeries =
    isRecurringSeriesSession(recurrenceGroupId) && normalizedStatus !== "cancelled";
  const hideEditSessionDetails =
    normalizedStatus === "completed" || normalizedStatus === "cancelled";

  const recordSessionItem: SessionMenuItem = {
    icon: Mic,
    label: "Record Session",
    action: "record-session",
    iconColor: canRecordSession ? "text-[#ff4d4f]" : "text-(--text-neutral-400)",
    iconBg: canRecordSession ? "bg-[#fff1f1]" : "bg-(--neutral-100)",
    disabled: !canRecordSession,
  };

  const statusItems: SessionMenuItem[] = hideStatusActions
    ? []
    : [
        {
          icon: Calendar,
          label: "Mark as Scheduled",
          action: "SCHEDULED",
          iconColor: "text-[#5878F8]",
          iconBg: "bg-[#EBEFFF]",
          hidden:
            !allowedStatusActions.has("SCHEDULED") ||
            normalizedStatus === "rescheduling",
        },
        {
          icon: Check,
          label: "Mark as Confirmed",
          action: "CONFIRMED",
          iconColor: "text-blue-600",
          iconBg: "bg-blue-50",
          hidden: !allowedStatusActions.has("CONFIRMED"),
        },
        {
          icon: AlertCircle,
          label: "Mark as Overdue",
          action: "OVERDUE",
          iconColor: "text-(--status-overdue-dark)",
          iconBg: "bg-(--status-overdue-light)",
          hidden: !allowedStatusActions.has("OVERDUE"),
        },
        {
          icon: Play,
          label: "Mark as In Progress",
          action: "IN_PROGRESS",
          iconColor: "text-purple-600",
          iconBg: "bg-purple-50",
          hidden: !allowedStatusActions.has("IN_PROGRESS"),
        },
        {
          icon: Check,
          label: "Mark as Completed",
          action: "COMPLETED",
          iconColor: "text-[#0ABF7C]",
          iconBg: "bg-[#EBFEF4]",
          hidden: !allowedStatusActions.has("COMPLETED"),
        },
        {
          icon: X,
          label: "Mark as Cancelled",
          action: "CANCELLED",
          iconColor: "text-[#EF4444]",
          iconBg: "bg-[#FEF2F2]",
          hidden:
            !allowedStatusActions.has("CANCELLED") ||
            normalizedStatus === "in_progress" ||
            normalizedStatus === "confirmed" ||
            normalizedStatus === "rescheduling",
        },
        {
          icon: RefreshCw,
          label: "Mark as Rescheduled",
          action: "RESCHEDULING",
          iconColor: "text-[#C33EF3]",
          iconBg: "bg-[#F3E8FF]",
          hidden: !allowedStatusActions.has("RESCHEDULING"),
        },
        {
          icon: AlertCircle,
          label: "Mark as No-Show",
          action: "NO_SHOW",
          iconColor: "text-[#FBAC00]",
          iconBg: "bg-[#FFF7ED]",
          hidden: !allowedStatusActions.has("NO_SHOW"),
        },
      ];

  const menuItems = (
    hasSubmittedNote
      ? [
          {
            icon: Pencil,
            label: "Edit Session Details",
            action: "edit",
            iconColor: "text-(--text-neutral-800)",
            iconBg: "bg-transparent",
            hidden: hideEditSessionDetails || hideEditAction,
          },
          {
            icon: FileText,
            label: "Download PDF",
            action: "download-note-pdf",
            iconColor: "text-(--text-primary-500)",
            iconBg: "bg-(--primary-50)",
          },
          {
            icon: FileText,
            label: "Reopen Note",
            action: "reopen-note",
            iconColor: "text-(--text-neutral-800)",
            iconBg: "bg-transparent",
          },
          recordSessionItem,
          {
            icon: FileText,
            label: "View Transcript",
            action: "view-transcript",
            iconColor: "text-(--text-primary-500)",
            iconBg: "bg-(--primary-50)",
          },
          ...statusItems,
          {
            icon: X,
            label: "Delete Session",
            action: "delete-session",
            iconColor: "text-[#EF4444]",
            iconBg: "bg-[#FEF2F2]",
          },
        ]
      : [
          {
            icon: Pencil,
            label: "Edit Session Details",
            action: "edit",
            iconColor: "text-(--text-neutral-800)",
            iconBg: "bg-transparent",
            hidden: hideEditSessionDetails || hideEditAction,
          },
          ...(!isAdmin && isVirtualSession
            ? [
                {
                  icon: Monitor,
                  label: "Join Meeting",
                  action: "join",
                  iconColor: "text-(--text-neutral-800)",
                  iconBg: "bg-transparent",
                },
              ]
            : []),
          recordSessionItem,
          {
            icon: FileText,
            label: "View Transcript",
            action: "view-transcript",
            iconColor: "text-(--text-primary-500)",
            iconBg: "bg-(--primary-50)",
          },
          ...statusItems,
          ...(showCancelSeries
            ? [
                {
                  icon: Repeat,
                  label: "Cancel Upcoming Series",
                  action: "cancel-series",
                  iconColor: "text-[#EF4444]",
                  iconBg: "bg-[#FEF2F2]",
                },
              ]
            : []),
        ]
  ).filter(isVisibleMenuItem);

  const handleAction = (action: string) => {
    onAction?.(action);
    setIsOpen(false);
  };

  return (
    <DropdownMenu open={isOpen} onOpenChange={setIsOpen}>
      <DropdownMenuTrigger asChild>
        <button
          className="p-1 hover:bg-(--neutral-100) rounded cursor-pointer outline-none"
        >
          <svg
            width="16"
            height="16"
            viewBox="0 0 16 16"
            fill="none"
            className="text-(--text-neutral-600)"
          >
            <circle cx="8" cy="3" r="1.5" fill="currentColor" />
            <circle cx="8" cy="8" r="1.5" fill="currentColor" />
            <circle cx="8" cy="13" r="1.5" fill="currentColor" />
          </svg>
        </button>
      </DropdownMenuTrigger>

      <DropdownMenuContent
        align="end"
        sideOffset={8}
        className="w-56 bg-white rounded-xl shadow-lg border border-(--neutral-200) p-0 z-[100] overflow-hidden py-2"
      >
        {menuItems.map((item) => {
          const Icon = item.icon;
          return (
            <DropdownMenuItem
              key={item.action}
              onSelect={(e) => {
                if (item.disabled) {
                  e.preventDefault();
                  return;
                }
                handleAction(item.action);
              }}
              disabled={item.disabled ?? false}
              className="w-full px-4 py-2 border-b border-(--neutral-100) last:border-none flex items-center gap-3 hover:bg-(--neutral-50) focus:bg-(--neutral-50) text-left transition-colors cursor-pointer rounded-none disabled:cursor-not-allowed disabled:opacity-60 disabled:hover:bg-transparent"
            >
              <div
                className={`w-5 h-5 rounded-full ${item.iconBg} flex items-center justify-center`}
              >
                <Icon size={18} className={item.iconColor} />
              </div>
              <span className="text-sm text-(--text-primary-dark)">
                {item.label}
              </span>
            </DropdownMenuItem>
          );
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  );
};

export default SessionActionsMenu;

