      (sessionId) =>
        !hasSessionTranscriptContent(sessionId) &&
        !sessionsWithApiTranscript.has(sessionId) &&
        !probedTranscriptSessionIdsRef.current.has(sessionId),
    );

  if (idsToProbe.length === 0) return;

  idsToProbe.forEach((sessionId) => {
    probedTranscriptSessionIdsRef.current.add(sessionId);
  });

  let cancelled = false;

  void (async () => {
    const found = new Set<number>();

    await Promise.all(
      idsToProbe.map(async (sessionId) => {
        try {
          const response = await triggerGetSessionTranscript(sessionId).unwrap();
          const finalTranscript =
            response.content?.trim() || response.finalTranscript?.trim() || "";
          if (finalTranscript) {
