export function useClosedFileNotice(panelOpen: boolean, client: Client | null) {
  const [isNoticeOpen, setIsNoticeOpen] = useState(false);

  useEffect(() => {
    if (!panelOpen || !client) {
      setIsNoticeOpen(false);
      return;
