    if (isClientInactive(client)) {
      setIsNoticeOpen(true);
      return;
    }

    setIsNoticeOpen(false);
  }, [panelOpen, client?.id, client?.clientStatus]);

  return {
    isNoticeOpen,
    closeNotice: () => setIsNoticeOpen(false),
  };
}

