import { useCallback, useEffect, useMemo, useState } from "react";
import type { Invoice } from "@/types/invoice.type";

export const extractBillingItems = (payload: unknown): unknown[] => {
  if (!payload) return [];
  if (Array.isArray(payload)) return payload;
  if (typeof payload !== "object") return [];

  const root = payload as Record<string, unknown>;
  const direct =
    root.items ??
    root.records ??
    root.results ??
    root.data ??
    root.content;

  if (Array.isArray(direct)) return direct;
  if (direct && typeof direct === "object") {
    const nested = direct as Record<string, unknown>;
    if (Array.isArray(nested.items)) return nested.items;
    if (Array.isArray(nested.records)) return nested.records;
    if (Array.isArray(nested.results)) return nested.results;
    if (Array.isArray(nested.content)) return nested.content;
  }
  return [];
};

export const mapBillingHistoryToInvoices = (responseArray: unknown[]): Invoice[] =>
  responseArray
    .map((inv) => {
      if (!inv || typeof inv !== "object") return null;
      const record = inv as Record<string, unknown>;
      const mappedId = String(record.billingId ?? record.id ?? "");
      if (!mappedId) return null;

      const amountDue = Number(record.amountDue ?? 0);
      const paymentAmount = Number(record.paymentAmount ?? 0);
      const clientId = record.clientId ?? (record.client as { id?: unknown } | undefined)?.id;

      return {
        id: mappedId,
        clientId: clientId ? String(clientId) : undefined,
        client: String(record.clientName ?? "Unknown Client"),
        therapist: String(record.assignedTherapistName ?? ""),
        clientType: "individual",
        date: record.sessionDate
          ? new Date(String(record.sessionDate)).toLocaleDateString(undefined, {
              year: "numeric",
              month: "short",
              day: "numeric",
            })
          : "---",
        service: String(record.serviceName ?? record.serviceCode ?? "General Session"),
        amount: String(amountDue.toFixed(2)),
        paid: String(paymentAmount.toFixed(2)),
        status: String(record.billingStatus ?? record.paymentStatus ?? "pending").toLowerCase() as Invoice["status"],
      } satisfies Invoice;
    })
    .filter((entry): entry is Invoice => Boolean(entry));

/**
 * Keeps paginated billing rows in local state while also reading page-1 rows
 * directly from RTK Query cache on render (avoids empty UI after navigation).
 */
export function useAccumulatedBillingInvoices(
  historyResponse: unknown | undefined,
  page: number,
) {
  const [allInvoices, setAllInvoices] = useState<Invoice[]>([]);

  const currentPageRows = useMemo(() => {
    if (!historyResponse) return [];
    return mapBillingHistoryToInvoices(extractBillingItems(historyResponse));
  }, [historyResponse]);

  useEffect(() => {
    if (!historyResponse) return;

    setAllInvoices((previous) => {
      if (page === 1) return currentPageRows;
      const existingIds = new Set(previous.map((entry) => entry.id));
      const next = [...previous];
      currentPageRows.forEach((entry) => {
        if (!existingIds.has(entry.id)) next.push(entry);
      });
      return next;
    });
  }, [page, historyResponse, currentPageRows]);

  const displayedInvoices = useMemo(() => {
    if (allInvoices.length > 0) return allInvoices;
    if (page === 1) return currentPageRows;
    return allInvoices;
  }, [allInvoices, page, currentPageRows]);

  const clearInvoices = useCallback(() => {
    setAllInvoices([]);
  }, []);

  return {
    displayedInvoices,
    clearInvoices,
    setAllInvoices,
  };
}

