    if (historyResponse) {
      pagesRef.current[page] = currentPageRows;
    }

    return mergeInvoicePages(pagesRef.current, page);
  }, [page, currentPageRows, historyResponse, revision]);

  const isReadyToLoadMore = useMemo(() => {
    if (!historyResponse) return false;
    return Object.prototype.hasOwnProperty.call(pagesRef.current, page);
  }, [historyResponse, page, currentPageRows, revision]);

  const clearInvoices = useCallback(() => {
    pagesRef.current = {};
    setRevision((value) => value + 1);
  }, []);

  return {
    displayedInvoices,
    clearInvoices,
    isReadyToLoadMore,
  };
}

/**
 * Accumulates raw billing history API items by page (for custom row mappers).
 */
export function useAccumulatedBillingHistoryItems(
  historyResponse: unknown | undefined,
  page: number,
) {
  const pagesRef = useRef<Record<number, unknown[]>>({});
  const [revision, setRevision] = useState(0);

  const currentPageItems = useMemo(() => {
    if (!historyResponse) return [];
    return extractBillingItems(historyResponse);
  }, [historyResponse]);

  const displayedItems = useMemo(() => {
    if (historyResponse) {
      pagesRef.current[page] = currentPageItems;
    }

    return mergeBillingItemPages(pagesRef.current, page);
  }, [page, currentPageItems, historyResponse, revision]);

  const isReadyToLoadMore = useMemo(() => {
    if (!historyResponse) return false;
    return Object.prototype.hasOwnProperty.call(pagesRef.current, page);
  }, [historyResponse, page, currentPageItems, revision]);

  const clearItems = useCallback(() => {
    pagesRef.current = {};
    setRevision((value) => value + 1);
  }, []);

  return {
    displayedItems,
    clearItems,
    isReadyToLoadMore,
  };
}

/**
 * Accumulates billing list pages by number. Each page is stored synchronously
 * when its API response arrives so page 2 can never replace page 1.
 */
export function useAccumulatedBillingInvoices(
  historyResponse: unknown | undefined,
  page: number,
) {
  const mapPageItems = useCallback(
    (items: unknown[]) => mapBillingHistoryToInvoices(items),
    [],
  );

  return useAccumulatedBillingPages(historyResponse, page, mapPageItems);
}

