export type BulkColumnMapping = "domain" | "subdomain" | "composite" | "content" | "skip";

export const BULK_COLUMN_MAPPING_OPTIONS: Array<{ value: BulkColumnMapping; label: string }> = [
  { value: "skip", label: "Skip" },
  { value: "domain", label: "Domain" },
  { value: "subdomain", label: "Subdomain" },
  { value: "composite", label: "Composite (Title)" },
  { value: "content", label: "Content" },
];

export interface ParsedBulkEntryRow {
  rowNumber: number;
  domain?: string;
  subdomain?: string;
  title: string;
  content: string;
  isValid: boolean;
  validationError?: string;
}

export function parsePastedBulkRows(pastedData: string): string[][] {
  const lines = pastedData
    .replace(/^\uFEFF/, "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line.length > 0);

  if (!lines.length) return [];

  const separator = lines[0].includes("\t") ? "\t" : ",";
  return lines.map((line) => line.split(separator).map((cell) => cell.trim()));
}

export function autoMapColumnHeader(header: string): BulkColumnMapping {
  const normalized = header.trim().toLowerCase();
  if (normalized === "domain" || normalized === "category") return "domain";
  if (
    normalized === "subdomain" ||
    normalized === "sub-domain" ||
    normalized === "subcategory"
  ) {
    return "subdomain";
  }
  if (
    normalized === "composite" ||
    normalized === "title" ||
    normalized === "name" ||
    normalized === "entry"
  ) {
    return "composite";
  }
  if (
    normalized === "content" ||
    normalized === "description" ||
    normalized === "text" ||
    normalized === "definition"
  ) {
    return "content";
  }
  return "skip";
}

export function buildInitialColumnMappings(
  columnCount: number,
  firstRowIsHeader: boolean,
  headerCells: string[],
): BulkColumnMapping[] {
  if (firstRowIsHeader && headerCells.length > 0) {
    return headerCells.map((header) => autoMapColumnHeader(header));
  }

  return Array.from({ length: columnCount }, (_, index) => {
    if (columnCount >= 4) {
      if (index === 0) return "domain";
      if (index === 1) return "subdomain";
      if (index === 2) return "composite";
      if (index === 3) return "content";
    }
    if (columnCount === 2) {
      return index === 0 ? "composite" : "content";
    }
    if (columnCount === 3) {
      if (index === 0) return "domain";
      if (index === 1) return "composite";
      return "content";
    }
    return "skip";
  });
}

export function buildParsedBulkRows(
  allRows: string[][],
  columnMappings: BulkColumnMapping[],
  firstRowIsHeader: boolean,
): ParsedBulkEntryRow[] {
  const dataRows = firstRowIsHeader ? allRows.slice(1) : allRows;

  return dataRows.map((cells, index) => {
    const rowNumber = firstRowIsHeader ? index + 2 : index + 1;
    let domain: string | undefined;
    let subdomain: string | undefined;
    let title = "";
    let content = "";

    columnMappings.forEach((mapping, columnIndex) => {
      const value = cells[columnIndex]?.trim() ?? "";
      if (!value) return;

      switch (mapping) {
        case "domain":
          domain = value;
          break;
        case "subdomain":
          subdomain = value;
          break;
        case "composite":
          title = value;
          break;
        case "content":
          content = value;
          break;
        default:
          break;
      }
    });

    let validationError: string | undefined;
    if (!title && !content) {
      validationError = "Missing title and content";
    } else if (!title) {
      validationError = "Missing title";
    } else if (!content) {
      validationError = "Missing content";
    }

    return {
      rowNumber,
      domain,
      subdomain,
      title,
      content,
      isValid: Boolean(title && content),
      validationError,
    };
  });
}

export function validateBulkImportSetup(
  columnMappings: BulkColumnMapping[],
  categoryId?: number,
): string | null {
  const hasComposite = columnMappings.includes("composite");
  const hasContent = columnMappings.includes("content");
  const hasDomain = columnMappings.includes("domain");
  const hasSubdomain = columnMappings.includes("subdomain");

  if (!hasComposite || !hasContent) {
    return "Composite (title) and Content columns must be mapped.";
  }
  if (hasSubdomain && !hasDomain) {
    return "Subdomain cannot be mapped without Domain.";
  }
  if (!hasDomain && !hasSubdomain && !categoryId) {
    return "Select a category tab or map Domain columns.";
  }
  return null;
}

export function buildBulkImportPayload(
  validRows: ParsedBulkEntryRow[],
  categoryId: number | undefined,
  columnMappings: BulkColumnMapping[],
): {
  categoryId?: number;
  entries: Array<{
    title: string;
    content: string;
    domain?: string;
    subdomain?: string;
  }>;
} {
  const hasDomainMapping = columnMappings.includes("domain");
  const hasSubdomainMapping = columnMappings.includes("subdomain");
  const useCategoryMode = !hasDomainMapping && !hasSubdomainMapping && !!categoryId;

  if (useCategoryMode) {
    return {
      categoryId,
      entries: validRows.map((row) => ({
        title: row.title,
        content: row.content,
      })),
    };
  }

  return {
    entries: validRows.map((row) => ({
      domain: row.domain || undefined,
      subdomain: row.subdomain || undefined,
      title: row.title,
      content: row.content,
    })),
  };
}

