import { useEffect, useMemo, useState } from "react";
import { Check, Loader2, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import CustomTextarea from "@/components/form/CustomTextarea";
import { cn } from "@/lib/utils";
import type { BulkLibraryEntriesImportResponse } from "@/store/api/admin/libraryEntries.api";
import {
  BULK_COLUMN_MAPPING_OPTIONS,
  buildBulkImportPayload,
  buildInitialColumnMappings,
  buildParsedBulkRows,
  parsePastedBulkRows,
  validateBulkImportSetup,
  type BulkColumnMapping,
  type ParsedBulkEntryRow,
} from "@/utils/libraryBulkImport";

interface BulkAddModalProps {
  isOpen: boolean;
  onClose: () => void;
  categoryId?: number;
  categoryName?: string;
  onImport: (payload: {
    categoryId?: number;
    entries: Array<{
      title: string;
      content: string;
      domain?: string;
      subdomain?: string;
    }>;
  }) => Promise<BulkLibraryEntriesImportResponse>;
  isSubmitting?: boolean;
}

const BulkAddModal = ({
  isOpen,
  onClose,
  categoryId,
  categoryName,
  onImport,
  isSubmitting = false,
}: BulkAddModalProps) => {
  const [step, setStep] = useState(1);
  const [pastedData, setPastedData] = useState("");
  const [firstRowIsHeader, setFirstRowIsHeader] = useState(true);
  const [columnMappings, setColumnMappings] = useState<BulkColumnMapping[]>([]);
  const [importResult, setImportResult] = useState<BulkLibraryEntriesImportResponse | null>(
    null,
  );

  const allRows = useMemo(() => parsePastedBulkRows(pastedData), [pastedData]);
  const headerCells = allRows[0] ?? [];
  const columnCount = useMemo(() => {
    if (!allRows.length) return 0;
    return Math.max(...allRows.map((row) => row.length));
  }, [allRows]);

  const columnLabels = useMemo(() => {
    if (!columnCount) return [];
    if (firstRowIsHeader && headerCells.length > 0) {
      return Array.from({ length: columnCount }, (_, index) => {
        const header = headerCells[index]?.trim();
        return header ? `Column ${index + 1}: ${header}` : `Column ${index + 1}`;
      });
    }
    return Array.from({ length: columnCount }, (_, index) => `Column ${index + 1}`);
  }, [columnCount, firstRowIsHeader, headerCells]);

  useEffect(() => {
    if (!isOpen) return;
    setStep(1);
    setPastedData("");
    setFirstRowIsHeader(true);
    setColumnMappings([]);
    setImportResult(null);
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen || step < 2 || columnCount === 0) return;
    setColumnMappings(
      buildInitialColumnMappings(columnCount, firstRowIsHeader, headerCells),
    );
  }, [columnCount, firstRowIsHeader, headerCells, isOpen, step]);

  const parsedRows = useMemo(
    () => buildParsedBulkRows(allRows, columnMappings, firstRowIsHeader),
    [allRows, columnMappings, firstRowIsHeader],
  );

  const validRows = useMemo(
    () => parsedRows.filter((row) => row.isValid),
    [parsedRows],
  );

  const setupError = useMemo(
    () => validateBulkImportSetup(columnMappings, categoryId),
    [categoryId, columnMappings],
  );

  const useCategoryMode =
    !columnMappings.includes("domain") &&
    !columnMappings.includes("subdomain") &&
    !!categoryId;

  const canProceedFromPaste = allRows.length > 0;
  const canProceedFromMapping = !setupError && validRows.length > 0;

  const handleClose = () => {
    if (isSubmitting) return;
    onClose();
  };

  const handleImport = async () => {
    if (!canProceedFromMapping || setupError) return;

    const payload = buildBulkImportPayload(validRows, categoryId, columnMappings);
    const result = await onImport(payload);
    setImportResult(result);
    setStep(4);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-60 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="flex max-h-[95vh] w-full max-w-4xl flex-col overflow-hidden rounded-3xl bg-white shadow-xl">
        <div className="flex items-start justify-between gap-4 border-b border-(--neutral-100) p-6 pb-4">
          <div>
            <h2 className="text-xl font-bold text-(--neutral-950)">Bulk Add Library Entries</h2>
            <p className="mt-1 text-sm text-(--text-neutral-600)">
              Paste from Excel or CSV. Values are imported into library categories and entries.
            </p>
            {categoryName ? (
              <p className="mt-2 text-xs font-medium text-(--text-neutral-600)">
                Active tab: {categoryName}
                {useCategoryMode ? " (category tab mode)" : ""}
              </p>
            ) : null}
          </div>
          <button
            type="button"
            onClick={handleClose}
            disabled={isSubmitting}
            className="rounded-full p-1 text-(--text-neutral-600) transition-colors hover:bg-(--neutral-50) hover:text-(--neutral-950) cursor-pointer"
          >
            <X size={24} />
          </button>
        </div>

        <div className="flex items-center gap-2 px-6 pt-4">
          {[1, 2, 3].map((stepIndex) => (
            <div
              key={stepIndex}
              className={cn(
                "flex h-7 w-7 items-center justify-center rounded-full text-xs font-semibold",
                step >= stepIndex
                  ? "bg-(--bg-primary-dark) text-white"
                  : "bg-(--neutral-100) text-(--text-neutral-600)",
              )}
            >
              {stepIndex}
            </div>
          ))}
        </div>

        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
          {step === 1 ? (
            <div className="space-y-4">
              <CustomTextarea
                label="Paste data"
                value={pastedData}
                onChange={(event) => setPastedData(event.target.value)}
                placeholder={
                  "Domain\tSubdomain\tComposite\tContent\nAnxiety\tCognitive\tCognitive Restructuring\tA technique to identify and challenge..."
                }
                className="min-h-48"
                required
              />
              <p className="text-xs text-(--text-neutral-600) px-1">
                Paste tab-separated Excel rows or comma-separated CSV text. File upload is not
                supported.
              </p>
              <div className="flex items-center gap-3">
                <Checkbox
                  id="first-row-header"
                  checked={firstRowIsHeader}
                  onChange={(event) => setFirstRowIsHeader(event.target.checked)}
                />
                <label
                  htmlFor="first-row-header"
                  className="cursor-pointer text-sm font-medium text-(--neutral-950)"
                >
                  First row is header
                </label>
              </div>
            </div>
          ) : null}

          {step === 2 ? (
            <div className="space-y-4">
              <p className="text-sm text-(--text-neutral-600)">
                Map each pasted column to Domain, Subdomain, Composite (title), Content, or Skip.
              </p>
              <div className="space-y-3">
                {columnLabels.map((label, index) => (
                  <div
                    key={`${label}-${index}`}
                    className="grid grid-cols-1 gap-2 md:grid-cols-[1fr_220px] md:items-center"
                  >
                    <span className="text-sm font-medium text-(--neutral-950)">{label}</span>
                    <select
                      value={columnMappings[index] ?? "skip"}
                      onChange={(event) => {
                        const nextValue = event.target.value as BulkColumnMapping;
                        setColumnMappings((previous) => {
                          const next = [...previous];
                          next[index] = nextValue;
                          return next;
                        });
                      }}
                      className="h-11 rounded-xl border border-(--neutral-100) bg-white px-3 text-sm text-(--neutral-950)"
                    >
                      {BULK_COLUMN_MAPPING_OPTIONS.map((option) => (
                        <option key={option.value} value={option.value}>
                          {option.label}
                        </option>
                      ))}
                    </select>
                  </div>
                ))}
              </div>
              {setupError ? (
                <p className="text-sm text-red-600">{setupError}</p>
              ) : (
                <p className="text-sm text-(--text-neutral-600)">
                  {useCategoryMode
                    ? `Category tab mode: valid rows will import into "${categoryName}".`
                    : "Domain mode: categories will be created or resolved from Domain/Subdomain columns."}
                </p>
              )}
            </div>
          ) : null}

          {step === 3 ? (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-sm font-bold text-(--neutral-950)">
                  Preview ({parsedRows.length} rows)
                </h3>
                <div className="flex items-center gap-2 text-xs text-(--border-success)">
                  <Check size={16} />
                  {validRows.length} valid
                </div>
              </div>
              <div className="overflow-x-auto rounded-xl border border-(--neutral-100)">
                <table className="w-max min-w-full text-left text-sm">
                  <thead className="bg-(--bg-primary-50) text-xs text-(--text-neutral-600)">
                    <tr>
                      <th className="px-3 py-2 whitespace-nowrap">Row</th>
                      {!useCategoryMode ? (
                        <>
                          <th className="px-3 py-2 whitespace-nowrap">Domain</th>
                          <th className="px-3 py-2 whitespace-nowrap">Subdomain</th>
                        </>
                      ) : null}
                      <th className="px-3 py-2 whitespace-nowrap">Title</th>
                      <th className="px-3 py-2 whitespace-nowrap">Content</th>
                      <th className="px-3 py-2 whitespace-nowrap">Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {parsedRows.map((row) => (
                      <PreviewRow
                        key={row.rowNumber}
                        row={row}
                        showDomainColumns={!useCategoryMode}
                      />
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          ) : null}

          {step === 4 && importResult ? (
            <div className="space-y-4">
              <h3 className="text-lg font-semibold text-(--neutral-950)">Import Results</h3>
              <div className="grid grid-cols-2 gap-3 md:grid-cols-5">
                <ResultCard label="Total" value={importResult.total} />
                <ResultCard label="Successful" value={importResult.successful} tone="success" />
                <ResultCard label="Skipped" value={importResult.skipped} />
                <ResultCard label="Failed" value={importResult.failed} tone="danger" />
                <ResultCard
                  label="Categories Created"
                  value={importResult.categoriesCreated}
                />
              </div>
              {importResult.errors.length > 0 ? (
                <div className="rounded-xl border border-red-100 bg-red-50 p-4">
                  <p className="mb-2 text-sm font-semibold text-red-700">Errors</p>
                  <div className="space-y-1">
                    {importResult.errors.map((entry, index) => (
                      <p key={`${entry.row}-${index}`} className="text-sm text-red-700">
                        Row {entry.row}
                        {entry.title ? ` (${entry.title})` : ""}: {entry.error}
                      </p>
                    ))}
                  </div>
                </div>
              ) : null}
            </div>
          ) : null}
        </div>

        <div className="flex items-center justify-between gap-3 border-t border-(--neutral-100) p-6">
          <div>
            {step > 1 && step < 4 ? (
              <Button
                type="button"
                variant="outline"
                onClick={() => setStep((previous) => previous - 1)}
                disabled={isSubmitting}
                className="h-11 rounded-full px-6"
              >
                Back
              </Button>
            ) : null}
          </div>
          <div className="flex items-center gap-3">
            <Button
              type="button"
              variant="outline"
              onClick={handleClose}
              disabled={isSubmitting}
              className="h-11 rounded-full px-6"
            >
              {step === 4 ? "Close" : "Cancel"}
            </Button>
            {step === 1 ? (
              <Button
                type="button"
                onClick={() => setStep(2)}
                disabled={!canProceedFromPaste}
                className="h-11 rounded-full px-6"
              >
                Next
              </Button>
            ) : null}
            {step === 2 ? (
              <Button
                type="button"
                onClick={() => setStep(3)}
                disabled={!canProceedFromMapping}
                className="h-11 rounded-full px-6"
              >
                Preview
              </Button>
            ) : null}
            {step === 3 ? (
              <Button
                type="button"
                onClick={() => void handleImport()}
                disabled={!canProceedFromMapping || isSubmitting}
                className="h-11 rounded-full px-6"
              >
                {isSubmitting ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Importing...
                  </>
                ) : (
                  `Import ${validRows.length} Entries`
                )}
              </Button>
            ) : null}
          </div>
        </div>
      </div>
    </div>
  );
};

function PreviewRow({
  row,
  showDomainColumns,
}: {
  row: ParsedBulkEntryRow;
  showDomainColumns: boolean;
}) {
  return (
    <tr className="border-t border-(--neutral-100)">
      <td className="px-3 py-2 whitespace-nowrap text-(--text-neutral-600)">{row.rowNumber}</td>
      {showDomainColumns ? (
        <>
          <td className="px-3 py-2 whitespace-nowrap">{row.domain || "-"}</td>
          <td className="px-3 py-2 whitespace-nowrap">{row.subdomain || "-"}</td>
