  const lines = pastedData
    .replace(/^\uFEFF/, "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);
  if (lines.length === 0) return [];

  const separator = detectDelimiter(lines[0]);
  return lines.map((line) => line.split(separator).map((cell) => cell.trim()));
