export type BulkImportMode = "categoryTab" | "domain";

export interface ImportReadiness {
  ok: boolean;
  message?: string;
  validCount: number;
  invalidCount: number;
}

export interface BulkImportRequirements {
  mode: BulkImportMode | null;
  modeLabel: string;
  requiredColumns: string[];
  optionalColumns: string[];
  rules: string[];
}

export function getBulkImportMode(
  columnMapping: BulkColumnRole[],
  categoryId: number | null | undefined,
): BulkImportMode | null {
  if (hasColumnRole(columnMapping, "domain")) return "domain";
  if (!hasColumnRole(columnMapping, "subdomain") && categoryId) return "categoryTab";
  return null;
}

export function getBulkImportRequirements(
  columnMapping: BulkColumnRole[],
  categoryId: number | null | undefined,
  categoryName?: string,
): BulkImportRequirements {
  const mode = getBulkImportMode(columnMapping, categoryId);

  if (mode === "categoryTab") {
    return {
      mode,
      modeLabel: `Category tab mode${categoryName ? ` (${categoryName})` : ""}`,
      requiredColumns: ["Composite (Title)", "Content"],
      optionalColumns: [],
      rules: [
        "Every row must have a title and content.",
        "Category is taken from the active library tab — not from the CSV.",
        "Rows missing title or content are skipped and not sent to the server.",
      ],
    };
  }

  if (mode === "domain") {
    return {
      mode,
      modeLabel: "Domain mode",
      requiredColumns: ["Domain", "Composite (Title)", "Content"],
      optionalColumns: ["Subdomain"],
      rules: [
        "Every imported row must have domain, title, and content.",
        "Subdomain is optional; when present, domain is required on the same row.",
        "Categories are created or matched from Domain / Subdomain values.",
        "The active tab category is not used when Domain is mapped.",
        "Rows missing required fields are not sent to the server.",
      ],
    };
  }

  return {
    mode: null,
    modeLabel: "Import mode not ready",
    requiredColumns: ["Composite (Title)", "Content"],
    optionalColumns: [],
    rules: [
      "Map Composite (Title) and Content columns, then either select a category tab or map Domain.",
      "Subdomain cannot be mapped without Domain.",
    ],
  };
}

function validateParsedRow(
  title: string,
  content: string,
  domain: string | undefined,
  subdomain: string | undefined,
  mode: BulkImportMode | null,
): { isValid: boolean; validationError?: string } {
  const hasTitle = title.length > 0;
  const hasContent = content.length > 0;
  const hasDomain = Boolean(domain);
  const hasSubdomain = Boolean(subdomain);

  if (!hasTitle && !hasContent) {
    return { isValid: false, validationError: "Missing title and content" };
  }
  if (!hasTitle) {
    return { isValid: false, validationError: "Missing Composite (title)" };
  }
  if (!hasContent) {
    return { isValid: false, validationError: "Missing content" };
  }
  if (hasSubdomain && !hasDomain) {
    return { isValid: false, validationError: "Subdomain requires domain on this row" };
  }
  if (mode === "domain" && !hasDomain) {
    return { isValid: false, validationError: "Missing domain (required in domain mode)" };
  }

  return { isValid: true };
}

