      message: "Map Composite (Title) and Content columns before importing.",
    };
  }
  if (hasSubdomain && !hasDomain) {
    return {
      ok: false,
      message: "Subcategory cannot be mapped without Category.",
    };
  }
  if (!hasDomain && !hasSubdomain && !categoryId) {
    return {
      ok: false,
      message:
        "Select a category tab or map a Category column. Active tab mode uses the current tab; category column mode reads category names from the CSV.",
    };
  }
  return { ok: true };
}

export function getImportReadiness(
  columnMapping: BulkColumnRole[],
  categoryId: number | null | undefined,
  parsedRows: ParsedBulkRow[],
): ImportReadiness {
  const mappingCheck = canImportBulkRows(columnMapping, categoryId);
  const validRows = parsedRows.filter((row) => row.isValid);
  const invalidCount = parsedRows.length - validRows.length;

  if (!mappingCheck.ok) {
    return {
      ok: false,
      message: mappingCheck.message,
      validCount: validRows.length,
      invalidCount,
    };
  }

  if (parsedRows.length === 0) {
    return {
      ok: false,
      message: "No data rows found. Paste at least one row of entry data below the header.",
      validCount: 0,
      invalidCount: 0,
    };
  }

  if (validRows.length === 0) {
    const mode = getBulkImportMode(columnMapping, categoryId);
    return {
      ok: false,
      message:
        mode === "domain"
          ? "No valid rows to import. Each row needs Category, Composite (title), and Content."
          : "No valid rows to import. Each row needs Composite (title) and Content.",
      validCount: 0,
      invalidCount,
    };
  }

  const unsafeRow = validRows.find((row) => row.subdomain && !row.domain);
  if (unsafeRow) {
    return {
      ok: false,
      message: `Row ${unsafeRow.rowNumber}: Subcategory requires category on the same row.`,
      validCount: validRows.length,
      invalidCount,
    };
  }

  return {
    ok: true,
    validCount: validRows.length,
    invalidCount,
  };
}

export function validateBulkImportPayload(
  columnMapping: BulkColumnRole[],
  categoryId: number | null | undefined,
  validRows: ParsedBulkRow[],
): { ok: boolean; message?: string } {
  if (validRows.length === 0) {
    return { ok: false, message: "No valid rows to import." };
  }

  const mappingCheck = canImportBulkRows(columnMapping, categoryId);
  if (!mappingCheck.ok) {
    return { ok: false, message: mappingCheck.message };
  }

  const mode = getBulkImportMode(columnMapping, categoryId);
  const payload = buildBulkImportPayload(categoryId, columnMapping, validRows);

  if (mode === "categoryTab" && !payload.categoryId) {
    return { ok: false, message: "Category tab mode requires an active category tab." };
  }

  if (mode === "domain") {
    const missingDomain = payload.entries.some((entry) => !entry.domain?.trim());
    if (missingDomain) {
      return {
        ok: false,
        message: "Category column mode requires a category value on every row being imported.",
      };
    }
  }

  const subdomainWithoutDomain = payload.entries.some(
    (entry) => entry.subdomain?.trim() && !entry.domain?.trim(),
  );
  if (subdomainWithoutDomain) {
    return {
      ok: false,
      message: "One or more rows have Subcategory without Category. Fix those rows before importing.",
    };
  }

  return { ok: true };
}

export function buildBulkImportPayload(
  categoryId: number | null | undefined,
  columnMapping: BulkColumnRole[],
  validRows: ParsedBulkRow[],
): BulkImportPayload {
  const hasDomain = hasColumnRole(columnMapping, "domain");
  const hasSubdomain = hasColumnRole(columnMapping, "subdomain");
  const useCategoryMode = !hasDomain && !hasSubdomain && !!categoryId;

  if (useCategoryMode) {
    return {
      categoryId: categoryId ?? undefined,
      entries: validRows.map((row) => ({
        title: row.title,
        content: row.content,
      })),
    };
  }

  return {
    entries: validRows.map((row) => ({
      domain: row.domain || undefined,
      subdomain: row.subdomain || undefined,
      title: row.title,
      content: row.content,
    })),
  };
}

