                        key={`${entry.id}-${tag}`}
                        className="rounded-full bg-(--neutral-50) px-2 py-0.5 text-xs text-(--text-neutral-600)"
                      >
                        {tag}
                      </span>
                    ))}
                  </div>
                ) : null}
              </button>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

