          <button
            type="button"
            onClick={handleClose}
            disabled={isSubmitting}
            className="cursor-pointer rounded-full p-1.5 text-(--text-neutral-600) transition-colors hover:bg-(--neutral-50) hover:text-(--neutral-950)"
          >
            <X size={20} />
          </button>
        </div>

        <form
          id={formId}
          onSubmit={(event) => void handleSubmit(event)}
          className="flex min-h-0 flex-1 flex-col overflow-hidden"
        >
          <div className="flex-1 space-y-4 overflow-y-auto px-5 py-4 custom-scrollbar">
            <CustomInput
              label="Template name"
              value={name}
              onChange={(event) => setName(event.target.value)}
              required
              placeholder="Initial Clinical Assessment Report"
            />

            <CustomTextarea
              label="Description"
              value={description}
              onChange={(event) => setDescription(event.target.value)}
              placeholder="Optional admin notes"
              rows={2}
              className="min-h-0"
              textareaClassName="min-h-16 resize-y"
            />

            <CustomTextarea
              label="AI instructions"
              value={aiInstructions}
              onChange={(event) => setAiInstructions(event.target.value)}
              placeholder="Optional tone or structure guidance"
              rows={2}
              className="min-h-0"
              textareaClassName="min-h-16 resize-y"
            />

            <div className="space-y-1.5">
              <p className="text-sm font-medium text-(--neutral-950)">
                Template file (.docx or .pdf) <span className="text-red-500">*</span>
              </p>
              <label
                className={cn(
                  "flex cursor-pointer items-center gap-3 rounded-xl border border-dashed border-(--neutral-200) bg-(--neutral-50) px-4 py-3 transition-colors hover:border-(--neutral-300) hover:bg-white",
                  file && "border-(--neutral-100) bg-white",
