import { useEffect, useId, useMemo, useState } from "react";
import { Loader2, X } from "lucide-react";
import type { ReportTemplate } from "@/store/api/adminApi";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import CustomInput from "@/components/form/CustomInput";
import CustomTextarea from "@/components/form/CustomTextarea";
import { cn } from "@/lib/utils";
import {
  clampToMaxLength,
  fieldHintWithLimit,
  normalizeDocumentTypesText,
  parseDocumentTypes,
  REPORT_TEMPLATE_LIMITS,
  validateReportTemplateEditForm,
} from "@/utils/reportTemplateValidation";

interface EditTemplateModalProps {
  template: ReportTemplate | null;
  isSubmitting?: boolean;
  onClose: () => void;
  onSubmit: (payload: {
    name?: string;
    description?: string;
    aiInstructions?: string;
    structureText?: string;
    defaultIncludeProfile?: boolean;
    defaultIncludeNotes?: boolean;
    defaultIncludeAssessments?: boolean;
    supportingFilesGuidance?: string;
    supportingFilesExpected?: boolean;
    supportingFileTypes?: string[];
  }) => Promise<void>;
}

function FieldError({ message }: { message?: string }) {
  if (!message) return null;
  return <p className="px-1 text-xs text-red-600">{message}</p>;
}

const EditTemplateModal = ({
  template,
  isSubmitting = false,
  onClose,
  onSubmit,
}: EditTemplateModalProps) => {
  const formId = useId();
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [aiInstructions, setAiInstructions] = useState("");
  const [structureText, setStructureText] = useState("");
  const [defaultIncludeProfile, setDefaultIncludeProfile] = useState(true);
  const [defaultIncludeNotes, setDefaultIncludeNotes] = useState(true);
  const [defaultIncludeAssessments, setDefaultIncludeAssessments] = useState(true);
  const [supportingFilesGuidance, setSupportingFilesGuidance] = useState("");
  const [supportingFilesExpected, setSupportingFilesExpected] = useState(false);
  const [documentTypesText, setDocumentTypesText] = useState("");
  const [submitAttempted, setSubmitAttempted] = useState(false);

  useEffect(() => {
    if (!template) return;
    setName(template.name ?? "");
    setDescription(template.description ?? "");
    setAiInstructions(template.aiInstructions ?? "");
    setStructureText(template.structureText ?? "");
    setDefaultIncludeProfile(Boolean(template.defaultIncludeProfile));
    setDefaultIncludeNotes(Boolean(template.defaultIncludeNotes));
    setDefaultIncludeAssessments(Boolean(template.defaultIncludeAssessments));
    setSupportingFilesGuidance(template.supportingFilesGuidance ?? "");
    setSupportingFilesExpected(Boolean(template.supportingFilesExpected));
    setDocumentTypesText((template.supportingFileTypes ?? []).join("\n"));
    setSubmitAttempted(false);
  }, [template]);

  const validation = useMemo(
    () =>
      validateReportTemplateEditForm({
        name,
        description,
        aiInstructions,
        structureText,
        supportingFilesGuidance,
        documentTypesText,
      }),
    [name, description, aiInstructions, structureText, supportingFilesGuidance, documentTypesText],
  );

  if (!template) return null;

  const showErrors = submitAttempted;
  const canSubmit = validation.ok;

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setSubmitAttempted(true);
    if (!validation.ok) return;

    await onSubmit({
      name: name.trim(),
      description,
      aiInstructions,
      structureText,
      defaultIncludeProfile,
      defaultIncludeNotes,
      defaultIncludeAssessments,
      supportingFilesGuidance,
      supportingFilesExpected,
      supportingFileTypes: parseDocumentTypes(documentTypesText),
    });
  };

  const handleClose = () => {
    if (isSubmitting) return;
    onClose();
  };

  return (
    <div className="fixed inset-0 z-60 flex items-center justify-center bg-black/50 p-4 backdrop-blur-sm">
      <div className="relative flex max-h-[88vh] w-full max-w-lg flex-col overflow-hidden rounded-2xl bg-white shadow-xl">
        <div className="flex shrink-0 items-start justify-between gap-3 border-b border-(--neutral-100) px-5 py-4">
          <div className="min-w-0">
            <h2 className="truncate text-lg font-bold text-(--neutral-950)" title={template.name}>
              Edit Template
            </h2>
            <p className="mt-0.5 truncate text-sm text-(--text-neutral-600)" title={template.originalName ?? template.name}>
              {template.originalName ?? "Update template metadata and structure"}
            </p>
          </div>
          <button
            type="button"
            onClick={handleClose}
            disabled={isSubmitting}
            className="cursor-pointer rounded-full p-1.5 text-(--text-neutral-600) transition-colors hover:bg-(--neutral-50) hover:text-(--neutral-950)"
          >
            <X size={20} />
          </button>
        </div>

        <form
          id={formId}
          onSubmit={(event) => void handleSubmit(event)}
          className="flex min-h-0 flex-1 flex-col overflow-hidden"
        >
          <div className="flex flex-1 flex-col gap-6 overflow-y-auto px-5 py-4 custom-scrollbar">
            <div>
              <CustomInput
                label="Template name"
                value={name}
                onChange={(event) =>
                  setName(clampToMaxLength(event.target.value, REPORT_TEMPLATE_LIMITS.name))
                }
                maxLength={REPORT_TEMPLATE_LIMITS.name}
                required
              />
              <FieldError message={showErrors ? validation.errors.name : undefined} />
            </div>

            <div>
              <CustomTextarea
                label="Description"
                value={description}
                onChange={(event) =>
                  setDescription(
                    clampToMaxLength(event.target.value, REPORT_TEMPLATE_LIMITS.description),
                  )
                }
                maxLength={REPORT_TEMPLATE_LIMITS.description}
                hint={fieldHintWithLimit(
                  "Optional admin notes",
                  description.length,
                  REPORT_TEMPLATE_LIMITS.description,
                )}
                rows={2}
                className="min-h-0"
                textareaClassName="min-h-16 resize-y"
              />
              <FieldError message={showErrors ? validation.errors.description : undefined} />
            </div>

            <div>
              <CustomTextarea
                label="AI instructions"
                value={aiInstructions}
                onChange={(event) =>
                  setAiInstructions(
                    clampToMaxLength(event.target.value, REPORT_TEMPLATE_LIMITS.aiInstructions),
                  )
                }
                maxLength={REPORT_TEMPLATE_LIMITS.aiInstructions}
                hint={fieldHintWithLimit(
                  "Optional tone or structure guidance",
                  aiInstructions.length,
                  REPORT_TEMPLATE_LIMITS.aiInstructions,
                )}
                rows={2}
                className="min-h-0"
                textareaClassName="min-h-16 resize-y"
              />
              <FieldError message={showErrors ? validation.errors.aiInstructions : undefined} />
            </div>

            <div>
              <CustomTextarea
                label="Structure text"
                value={structureText}
                onChange={(event) =>
                  setStructureText(
                    clampToMaxLength(event.target.value, REPORT_TEMPLATE_LIMITS.structureText),
                  )
                }
                maxLength={REPORT_TEMPLATE_LIMITS.structureText}
                hint={fieldHintWithLimit(
                  "Extracted outline used by AI generation",
                  structureText.length,
                  REPORT_TEMPLATE_LIMITS.structureText,
                )}
                rows={6}
                className="min-h-0"
                textareaClassName="min-h-32 resize-y font-mono text-xs"
              />
              <FieldError message={showErrors ? validation.errors.structureText : undefined} />
            </div>

            <div className="rounded-xl border border-(--neutral-100) bg-(--neutral-50) p-3 space-y-2.5">
              <p className="text-xs font-semibold uppercase tracking-wide text-(--text-neutral-600)">
                Default data sources
              </p>
              <label className="flex cursor-pointer items-center gap-2.5 text-sm text-(--neutral-950)">
                <Checkbox
                  id={`${formId}-include-profile`}
                  checked={defaultIncludeProfile}
                  onChange={(event) => setDefaultIncludeProfile(event.target.checked)}
                />
                Include client profile
              </label>
              <label className="flex cursor-pointer items-center gap-2.5 text-sm text-(--neutral-950)">
                <Checkbox
                  id={`${formId}-include-notes`}
                  checked={defaultIncludeNotes}
                  onChange={(event) => setDefaultIncludeNotes(event.target.checked)}
                />
                Include sessions & notes
              </label>
              <label className="flex cursor-pointer items-center gap-2.5 text-sm text-(--neutral-950)">
                <Checkbox
                  id={`${formId}-include-assessments`}
                  checked={defaultIncludeAssessments}
                  onChange={(event) => setDefaultIncludeAssessments(event.target.checked)}
                />
                Include assessments
              </label>
            </div>

            <div>
              <CustomTextarea
                label="Supporting files guidance"
                value={supportingFilesGuidance}
                onChange={(event) =>
                  setSupportingFilesGuidance(
                    clampToMaxLength(
                      event.target.value,
                      REPORT_TEMPLATE_LIMITS.supportingFilesGuidance,
                    ),
                  )
                }
                maxLength={REPORT_TEMPLATE_LIMITS.supportingFilesGuidance}
                hint={fieldHintWithLimit(
                  "Shown to therapists when generating a report",
                  supportingFilesGuidance.length,
                  REPORT_TEMPLATE_LIMITS.supportingFilesGuidance,
                )}
                rows={2}
                className="min-h-0"
                textareaClassName="min-h-16 resize-y"
              />
              <FieldError
                message={showErrors ? validation.errors.supportingFilesGuidance : undefined}
              />
            </div>

            <label className="flex cursor-pointer items-center gap-2.5 text-sm text-(--neutral-950)">
              <Checkbox
                id={`${formId}-supporting-expected`}
                checked={supportingFilesExpected}
                onChange={(event) => setSupportingFilesExpected(event.target.checked)}
              />
              Expect supporting files before generation
            </label>

            <div>
              <CustomTextarea
                label="Document types"
                value={documentTypesText}
                onChange={(event) =>
                  setDocumentTypesText(normalizeDocumentTypesText(event.target.value))
                }
                hint={fieldHintWithLimit(
                  "One type per line, max 150 characters each",
                  parseDocumentTypes(documentTypesText).length,
                  REPORT_TEMPLATE_LIMITS.maxDocumentTypes,
                )}
                rows={3}
                className="min-h-0"
                textareaClassName="min-h-20 resize-y"
              />
              <FieldError message={showErrors ? validation.errors.documentTypesText : undefined} />
            </div>
          </div>

          <div className="flex shrink-0 items-center justify-end gap-3 border-t border-(--neutral-100) px-5 py-4">
            <Button
              type="button"
              variant="outline"
              onClick={handleClose}
              disabled={isSubmitting}
              className="h-10 cursor-pointer rounded-full border-(--neutral-100) bg-white px-5 text-sm font-normal text-(--text-neutral-600) hover:bg-(--neutral-50)"
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={!canSubmit || isSubmitting}
              className={cn(
                "h-10 rounded-full px-5 text-sm font-normal transition-all",
                canSubmit && !isSubmitting ? "cursor-pointer" : "cursor-not-allowed",
              )}
            >
              {isSubmitting ? (
                <>
                  <Loader2 size={16} className="animate-spin" />
                  Saving...
                </>
              ) : (
                "Save"
              )}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

