const HTML_TAG_PATTERN = /<\/?[a-z][\s\S]*>/i;

function stripMarkdownCodeFence(value: string): string {
  const trimmed = value.trim();
  if (!trimmed.startsWith("```")) return trimmed;

  const lines = trimmed.split("\n");
  const openFence = lines[0]?.match(/^```(\w+)?\s*$/);
  if (!openFence) return trimmed;

  lines.shift();
  if (lines.length > 0 && lines[lines.length - 1]?.trim() === "```") {
    lines.pop();
  }

  return lines.join("\n").trim();
}

function plainTextToHtml(value: string): string {
  const escaped = value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");

  return escaped
    .split(/\n{2,}/)
    .filter(Boolean)
    .map((paragraph) => `<p>${paragraph.replace(/\n/g, "<br>")}</p>`)
    .join("");
}

/** Prepare AI-generated report text for rich-text editing (strip fences, render HTML). */
export function normalizeReportContentForEditor(content: string): string {
  if (!content) return "";

  const withoutFence = stripMarkdownCodeFence(content.trim());
  if (!withoutFence) return "";

  if (HTML_TAG_PATTERN.test(withoutFence)) {
    return withoutFence;
  }

  return plainTextToHtml(withoutFence);
}

