input.contents:
import { useEffect, useMemo, useState } from "react";
import { Download, Loader2, Save, X } from "lucide-react";
import CustomJoditEditor from "@/components/shared/CustomJoditEditor";
import Toast from "@/components/shared/Toast";
import { Button } from "@/components/ui/button";
import {
  useFinalizeClientReportMutation,
  useGetClientReportQuery,
  useUnfinalizeClientReportMutation,
  useUpdateClientReportDraftMutation,
} from "@/store/api/adminApi";
import { getApiErrorMessage } from "@/utils/apiError";
import { getAuthSession } from "@/utils/authStorage";
import { buildTenantApiBase } from "@/utils/tenantUrls";
import { normalizeReportContentForEditor } from "@/utils/normalizeReportContent";
import { cn } from "@/lib/utils";

interface ClientReportEditorDrawerProps {
  reportId: number | null;
  clientId: number;
  readOnly?: boolean;
  onClose: () => void;
  onUpdated?: () => void;
}

const ClientReportEditorDrawer = ({
  reportId,
  clientId,
  readOnly = false,
  onClose,
  onUpdated,
}: ClientReportEditorDrawerProps) => {
  const session = getAuthSession();
  const apiBase = buildTenantApiBase(session?.tenantSubdomain);
  const [content, setContent] = useState("");
  const [downloadingFormat, setDownloadingFormat] = useState<"pdf" | "docx" | null>(null);
  const [toast, setToast] = useState<{ message: string; type: "success" | "error" } | null>(null);

  const skip = !reportId;
  const { data: report, isLoading, refetch } = useGetClientReportQuery(reportId ?? 0, { skip });
  const [saveDraft, { isLoading: isSaving }] = useUpdateClientReportDraftMutation();
  const [finalizeReport, { isLoading: isFinalizing }] = useFinalizeClientReportMutation();
  const [unfinalizeReport, { isLoading: isUnfinalizing }] = useUnfinalizeClientReportMutation();

  const isFinalized = Boolean(report?.isFinalized);
  const editorReadOnly = readOnly || isFinalized;
  const isBusy = isSaving || isFinalizing || isUnfinalizing || Boolean(downloadingFormat);

  const resolvedContent = useMemo(() => {
    if (!report) return "";
    const raw = report.finalContent ?? report.draftContent ?? report.generatedContent ?? "";
    return normalizeReportContentForEditor(raw);
  }, [report]);

  useEffect(() => {
    setContent(resolvedContent);
  }, [resolvedContent, reportId]);

  if (!reportId) return null;

  const showToast = (message: string, type: "success" | "error") => setToast({ message, type });

  const handleClose = () => {
    if (isBusy) return;
    onClose();
  };

  const handleSave = async () => {
    if (!reportId) return;
    try {
      await saveDraft({ reportId, clientId, draftContent: content }).unwrap();
      showToast("Draft saved successfully", "success");
      refetch();
      onUpdated?.();
    } catch (error) {
      showToast(getApiErrorMessage(error) || "Failed to save draft", "error");
    }
  };

  const handleFinalize = async () => {
    if (!reportId) return;
    try {
      if (!isFinalized && content !== resolvedContent) {
        await saveDraft({ reportId, clientId, draftContent: content }).unwrap();
      }
      await finalizeReport({ reportId, clientId }).unwrap();
      showToast("Report finalized successfully", "success");
      refetch();
      onUpdated?.();
    } catch (error) {
      showToast(getApiErrorMessage(error) || "Failed to finalize report", "error");
    }
  };

  const handleUnfinalize = async () => {
    if (!reportId) return;
    try {
      await unfinalizeReport({ reportId, clientId }).unwrap();
      showToast("Report reopened for editing", "success");
      refetch();
      onUpdated?.();
    } catch (error) {
      showToast(getApiErrorMessage(error) || "Failed to reopen report", "error");
    }
  };

  const openDownload = async (format: "pdf" | "docx") => {
    if (!reportId || !session?.accessToken) return;
    setDownloadingFormat(format);
    try {
      const response = await fetch(`${apiBase}/api/v1/reports/${reportId}/download/${format}`, {
        headers: {
          Authorization: `Bearer ${session.accessToken}`,
        },
      });
      if (!response.ok) {
        throw new Error("Download failed");
      }
      if (format === "pdf") {
        const html = await response.text();
        const blob = new Blob([html], { type: "text/html;charset=utf-8" });
        const url = window.URL.createObjectURL(blob);
        window.open(url, "_blank", "noopener,noreferrer");
        window.setTimeout(() => window.URL.revokeObjectURL(url), 60_000);
        showToast("PDF opened in a new tab", "success");
        return;
      }
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = `client-report-${reportId}.docx`;
      anchor.click();
      window.URL.revokeObjectURL(url);
      showToast("Word document downloaded", "success");
    } catch (error) {
      showToast(getApiErrorMessage(error) || "Failed to download report", "error");
    } finally {
      setDownloadingFormat(null);
    }
  };

  const generatedLabel = report?.generatedAt
    ? new Date(report.generatedAt).toLocaleString()
    : null;

  return (
    <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4 backdrop-blur-sm">
      <div
        className="relative flex max-h-[92vh] w-full max-w-4xl flex-col overflow-hidden rounded-2xl bg-white shadow-xl"
        role="dialog"
        aria-modal="true"
        aria-labelledby="client-report-editor-title"
      >
        <div className="flex shrink-0 items-start justify-between gap-3 border-b border-(--neutral-100) px-5 py-4">
          <div className="min-w-0 flex-1">
            <div className="flex flex-wrap items-center gap-2">
              <h2
                id="client-report-editor-title"
                className="truncate text-lg font-bold text-(--neutral-950)"
                title={report?.templateName ?? "Client Report"}
              >
                {report?.templateName ?? "Client Report"}
              </h2>
              <span
                className={cn(
                  "shrink-0 rounded-full px-2.5 py-0.5 text-xs font-medium",
                  isFinalized
                    ? "bg-(--bg-primary-50) text-(--text-primary-dark)"
                    : "bg-(--neutral-100) text-(--text-neutral-600)",
                )}
              >
                {isFinalized ? "Finalized" : "Draft"}
              </span>
            </div>
            <p className="mt-0.5 text-sm text-(--text-neutral-600)">
              {editorReadOnly ? "View report content" : "Review and edit report content"}
              {generatedLabel ? ` · Generated ${generatedLabel}` : ""}
            </p>
          </div>
          <button
            type="button"
            onClick={handleClose}
            disabled={isBusy}
            className="cursor-pointer rounded-full p-1.5 text-(--text-neutral-600) transition-colors hover:bg-(--neutral-50) hover:text-(--neutral-950) disabled:cursor-not-allowed disabled:opacity-50"
          >
            <X size={20} />
          </button>
        </div>

        <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
          {isLoading ? (
            <div className="flex flex-1 items-center justify-center px-5 py-16 text-sm text-(--text-neutral-600)">
              <Loader2 className="mr-2 animate-spin" size={18} />
              Loading report...
            </div>
          ) : (
            <div className="flex min-h-0 flex-1 flex-col overflow-hidden px-5 py-4">
              <div className="flex min-h-[min(52vh,480px)] flex-1 flex-col overflow-hidden rounded-xl border border-(--neutral-200) bg-white">
                <div className="min-h-0 flex-1 overflow-hidden p-1">
                  <CustomJoditEditor
                    content={content}
                    setContent={setContent}
                    readonly={editorReadOnly}
                    placeholder="Report content..."
                    scrollable
                    minHeight={280}
                    editorHeight="100%"
                  />
                </div>
              </div>
            </div>
          )}

          <div className="flex shrink-0 flex-wrap items-center justify-end gap-3 border-t border-(--neutral-100) px-5 py-4">
            {!editorReadOnly ? (
              <Button
                type="button"
                variant="outline"
                onClick={() => void handleSave()}
                disabled={isSaving || isFinalizing}
                className="h-10 cursor-pointer rounded-full border-(--neutral-100) bg-white px-5 text-sm font-normal text-(--text-neutral-600) hover:bg-(--neutral-50)"
              >
                {isSaving ? (
                  <>
                    <Loader2 size={16} className="animate-spin" />
                    Saving...
                  </>
                ) : (
                  <>
                    <Save size={16} />
                    Save draft
                  </>
                )}
              </Button>
            ) : null}

            {!readOnly && !isFinalized ? (
              <Button
                type="button"
                onClick={() => void handleFinalize()}
                disabled={isFinalizing || isSaving}
                className="h-10 cursor-pointer rounded-full px-5 text-sm font-normal"
              >
                {isFinalizing ? (
                  <>
                    <Loader2 size={16} className="animate-spin" />
                    Finalizing...
                  </>
                ) : (
                  "Finalize"
                )}
              </Button>
            ) : null}

            {!readOnly && isFinalized ? (
              <Button
                type="button"
                variant="outline"
                onClick={() => void handleUnfinalize()}
                disabled={isUnfinalizing}
                className="h-10 cursor-pointer rounded-full border-(--neutral-100) px-5 text-sm font-normal"
              >
                {isUnfinalizing ? (
                  <>
                    <Loader2 size={16} className="animate-spin" />
                    Reopening...
                  </>
                ) : (
                  "Reopen"
                )}
              </Button>
            ) : null}

            <Button
              type="button"
              variant="outline"
              onClick={() => void openDownload("pdf")}
              disabled={Boolean(downloadingFormat)}
              className="h-10 cursor-pointer rounded-full border-(--neutral-100) px-5 text-sm font-normal"
            >
              {downloadingFormat === "pdf" ? (
                <Loader2 size={16} className="animate-spin" />
              ) : (
                <Download size={16} />
              )}
              PDF
            </Button>
            <Button
              type="button"
              variant="outline"
              onClick={() => void openDownload("docx")}
              disabled={Boolean(downloadingFormat)}
              className="h-10 cursor-pointer rounded-full border-(--neutral-100) px-5 text-sm font-normal"
            >
              {downloadingFormat === "docx" ? (
                <Loader2 size={16} className="animate-spin" />
              ) : (
                <Download size={16} />
              )}
              Word
            </Button>
          </div>
        </div>
      </div>

      {toast ? (
        <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />
      ) : null}
    </div>
  );
};

export default ClientReportEditorDrawer;

