function validateReportTemplateTextFields(
  values: Pick<
    ReportTemplateFormValues,
    "name" | "description" | "aiInstructions" | "supportingFilesGuidance" | "documentTypesText"
  > & { structureText?: string },
  options?: { requireName?: boolean; includeStructureText?: boolean },
): Record<string, string> {
  const errors: Record<string, string> = {};
  const requireName = options?.requireName ?? true;

  const trimmedName = values.name.trim();
  if (requireName && !trimmedName) {
    errors.name = "Template name is required.";
  } else if (trimmedName.length > REPORT_TEMPLATE_LIMITS.name) {
    errors.name = `Name must be ${REPORT_TEMPLATE_LIMITS.name} characters or fewer.`;
  }

  if (values.description.length > REPORT_TEMPLATE_LIMITS.description) {
    errors.description = `Description must be ${REPORT_TEMPLATE_LIMITS.description} characters or fewer.`;
  }

  if (values.aiInstructions.length > REPORT_TEMPLATE_LIMITS.aiInstructions) {
    errors.aiInstructions = `AI instructions must be ${REPORT_TEMPLATE_LIMITS.aiInstructions} characters or fewer.`;
  }

  if (options?.includeStructureText && (values.structureText?.length ?? 0) > REPORT_TEMPLATE_LIMITS.structureText) {
    errors.structureText = `Structure text must be ${REPORT_TEMPLATE_LIMITS.structureText} characters or fewer.`;
  }

  if (values.supportingFilesGuidance.length > REPORT_TEMPLATE_LIMITS.supportingFilesGuidance) {
    errors.supportingFilesGuidance = `Guidance must be ${REPORT_TEMPLATE_LIMITS.supportingFilesGuidance} characters or fewer.`;
  }

  const documentTypes = parseDocumentTypes(values.documentTypesText);
  if (documentTypes.length > REPORT_TEMPLATE_LIMITS.maxDocumentTypes) {
    errors.documentTypesText = `Add up to ${REPORT_TEMPLATE_LIMITS.maxDocumentTypes} document types.`;
  }

  const longType = documentTypes.find(
    (type) => type.length > REPORT_TEMPLATE_LIMITS.documentTypeLabel,
  );
  if (longType) {
    errors.documentTypesText = `Each document type must be ${REPORT_TEMPLATE_LIMITS.documentTypeLabel} characters or fewer.`;
  }

  return errors;
}

