import { useEffect, useState } from "react";
import { X } from "lucide-react";
import { Button } from "../ui/button";
import CustomInput from "../form/CustomInput";
import CustomTextarea from "../form/CustomTextarea";
import CustomSelect from "../form/CustomSelect";
import { cn } from "@/lib/utils";
import type { SessionNoteAiTemplate } from "@/store/api/admin/sessionNoteAiTemplates.api";

export type SessionNoteAiTemplateModalTab = "create" | "preview";

interface SessionNoteAiTemplateModalProps {
  isOpen: boolean;
  onClose: () => void;
  initialTab?: SessionNoteAiTemplateModalTab;
  templates: SessionNoteAiTemplate[];
  selectedTemplateId: number | null;
  previewContent: string;
  isSaving?: boolean;
  onSave: (payload: { id?: number; name: string; instructions: string }) => void;
}

const SessionNoteAiTemplateModal = ({
  isOpen,
  onClose,
  initialTab = "create",
  templates,
  selectedTemplateId,
  previewContent,
  isSaving = false,
  onSave,
}: SessionNoteAiTemplateModalProps) => {
  const [activeTab, setActiveTab] =
    useState<SessionNoteAiTemplateModalTab>(initialTab);
  const [editingTemplateId, setEditingTemplateId] = useState<number | "new">("new");
  const [templateName, setTemplateName] = useState("");
  const [instructions, setInstructions] = useState("");
  const [formError, setFormError] = useState<string | null>(null);

  useEffect(() => {
    if (!isOpen) return;
    setActiveTab(initialTab);
    setFormError(null);
  }, [initialTab, isOpen]);

  useEffect(() => {
    if (!isOpen) return;

    if (selectedTemplateId) {
      const selected = templates.find((template) => template.id === selectedTemplateId);
      if (selected) {
        setEditingTemplateId(selected.id);
        setTemplateName(selected.name);
        setInstructions(selected.instructions);
        return;
      }
    }

    if (templates.length > 0) {
      const first = templates[0];
      setEditingTemplateId(first.id);
      setTemplateName(first.name);
      setInstructions(first.instructions);
      return;
    }

    setEditingTemplateId("new");
    setTemplateName("");
    setInstructions("");
  }, [isOpen, selectedTemplateId, templates]);

  if (!isOpen) return null;

  const templateOptions = [
    { value: "new", label: "New template" },
    ...templates.map((template) => ({
      value: String(template.id),
      label: template.name,
    })),
  ];

  const handleTemplateSelect = (value: string) => {
    if (value === "new") {
      setEditingTemplateId("new");
      setTemplateName("");
      setInstructions("");
      setFormError(null);
      return;
    }

    const template = templates.find((entry) => entry.id === Number(value));
    if (!template) return;
    setEditingTemplateId(template.id);
    setTemplateName(template.name);
    setInstructions(template.instructions);
    setFormError(null);
  };

  const handleSave = () => {
    const trimmedName = templateName.trim();
    const trimmedInstructions = instructions.trim();

    if (!trimmedName) {
      setFormError("Template name is required.");
      return;
    }
    if (!trimmedInstructions) {
      setFormError("Custom instructions are required.");
      return;
    }

    setFormError(null);
    onSave({
      id: editingTemplateId === "new" ? undefined : editingTemplateId,
      name: trimmedName,
      instructions: trimmedInstructions,
    });
  };

  return (
    <div className="fixed inset-0 z-10000 flex items-center justify-center bg-black/50 p-4">
      <div className="flex max-h-[90vh] w-full max-w-2xl flex-col overflow-hidden rounded-2xl bg-white shadow-xl">
        <div className="flex shrink-0 items-start justify-between border-b border-(--neutral-200) p-6">
          <div>
            <h2 className="text-xl font-semibold text-(--text-primary-dark)">
              AI Template &amp; Preview
            </h2>
            <p className="mt-1 text-sm text-(--text-neutral-600)">
              Edit the instructions that guide the AI, or preview the generated note.
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="rounded-lg p-1 transition-colors hover:bg-(--neutral-50)"
            aria-label="Close"
          >
            <X size={22} className="text-(--text-neutral-600)" />
          </button>
        </div>

        <div className="mx-6 mt-5 flex gap-2 rounded-full bg-(--neutral-100) p-1">
          <button
            type="button"
            onClick={() => setActiveTab("create")}
            className={cn(
              "flex-1 rounded-full px-4 py-2 text-sm font-medium transition-all",
              activeTab === "create"
                ? "bg-white text-(--text-primary-dark) shadow-sm"
                : "text-(--text-neutral-500) hover:text-(--text-neutral-700)",
            )}
          >
            Create Template
          </button>
          <button
            type="button"
            onClick={() => setActiveTab("preview")}
            className={cn(
              "flex-1 rounded-full px-4 py-2 text-sm font-medium transition-all",
              activeTab === "preview"
                ? "bg-white text-(--text-primary-dark) shadow-sm"
                : "text-(--text-neutral-500) hover:text-(--text-neutral-700)",
            )}
          >
            Preview Generated Note
          </button>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-5">
          {activeTab === "create" ? (
            <div className="space-y-5">
              {templates.length > 0 ? (
                <CustomSelect
                  label="Saved templates"
                  placeholder="Select a template"
                  value={editingTemplateId === "new" ? "new" : String(editingTemplateId)}
                  onChange={handleTemplateSelect}
                  options={templateOptions}
                  isSearch={templateOptions.length > 6}
                />
              ) : null}

              <CustomInput
                label="Template Name"
                placeholder="e.g., CBT Session Template, EMDR Progress Notes"
                value={templateName}
                onChange={(event) => setTemplateName(event.target.value)}
                hint="Give your template a descriptive name for easy identification."
              />

              <CustomTextarea
                label="Custom Instructions"
                placeholder="Example: Create a session note template focused on cognitive behavioral therapy techniques, including detailed mood tracking, homework assignments, and specific CBT interventions used. Format it professionally for clinical documentation."
                value={instructions}
                onChange={(event) => setInstructions(event.target.value)}
                hint="Specific instructions about format, focus areas, therapy approach, or any special requirements."
                rows={8}
                className="min-h-48"
                textareaClassName="min-h-40 resize-y"
              />

              {formError ? (
                <p className="text-sm text-(--status-denied)">{formError}</p>
              ) : null}
            </div>
          ) : (
            <div className="min-h-64 rounded-xl border border-(--neutral-200) bg-(--neutral-50) p-4">
              {previewContent.trim() ? (
                <pre className="whitespace-pre-wrap font-sans text-sm leading-6 text-(--text-primary-dark)">
                  {previewContent}
                </pre>
              ) : (
                <p className="text-sm text-(--text-neutral-600)">
                  Generated note preview will appear here after you use{" "}
                  <span className="font-medium">Generate Final Note</span> from the
                  clinical actions menu.
                </p>
              )}
            </div>
          )}
        </div>

        <div className="flex shrink-0 items-center justify-end gap-3 border-t border-(--neutral-200) p-6">
          <Button
            type="button"
            variant="outline"
            onClick={onClose}
            className="h-11 rounded-full border-(--neutral-200) px-6 text-sm font-normal"
          >
            Cancel
          </Button>
          {activeTab === "create" ? (
            <Button
              type="button"
              onClick={handleSave}
              disabled={isSaving}
              className="h-11 rounded-full bg-(--bg-primary-dark) px-6 text-sm font-semibold text-white hover:bg-(--bg-primary-dark)/90 disabled:opacity-50"
            >
              {isSaving ? "Saving..." : "Save Template"}
            </Button>
          ) : null}
        </div>
      </div>
    </div>
  );
};

export default SessionNoteAiTemplateModal;

import { ChevronDown, Sparkles } from "lucide-react";
import { Button } from "../ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
