  isSmartFilling = false,
  isGenerating = false,
  canGenerateFinalNote,
  onSmartFill,
  onGenerateFinalNote,
  onCreateTemplate,
}: SessionNoteClinicalActionsMenuProps) => {
  const isBusy = isSmartFilling || isGenerating;

  return (
    <DropdownMenu>
