          <ChevronDown size={16} />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="min-w-52 rounded-xl p-1">
        <DropdownMenuItem
          className="cursor-pointer rounded-lg px-3 py-2 text-sm"
          disabled={disabled || isSmartFilling}
          onClick={onSmartFill}
        >
          Smart Fill from transcript
        </DropdownMenuItem>
        <DropdownMenuItem
          className="cursor-pointer rounded-lg px-3 py-2 text-sm"
          disabled={disabled || !canGenerateFinalNote || isGenerating}
          onClick={onGenerateFinalNote}
        >
          Generate Final Note
        </DropdownMenuItem>
        <DropdownMenuItem
          className="cursor-pointer rounded-lg px-3 py-2 text-sm"
          disabled={disabled}
          onClick={onCreateTemplate}
        >
          Create Template
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
};

export default SessionNoteClinicalActionsMenu;

