export function useStaffPermissionsBootstrap(): {
  isStaffAccessLoading: boolean;
} {
  const dispatch = useAppDispatch();
  const accessToken = useAppSelector((state) => state.auth.accessToken);
  const role = useAppSelector((state) => state.auth.role);
  const staffAccessResolved = useAppSelector((state) => state.auth.staffAccessResolved);

  const { data, isFetching, isLoading } = useGetAuthMeQuery(undefined, {
    skip: !accessToken || role !== "staff",
    refetchOnMountOrArgChange: true,
  });

  useEffect(() => {
    if (!data || role !== "staff") return;

    dispatch(
      setStaffAccess({
        apiRoles: normalizeApiRoles(data.roles),
        permissions: data.permissions ?? data.authorities ?? [],
      }),
    );
  }, [data, dispatch, role]);

  const isStaffAccessLoading =
    role === "staff" && !staffAccessResolved && (isLoading || isFetching);

  return { isStaffAccessLoading };
}

