import { useMemo } from "react";
import { useStaffAccess } from "@/hooks/useStaffAccess";
import { isSupervisorApiRole } from "@/utils/staffPermissions";

export function useStaffPortalRestrictions() {
  const { can, apiRoles } = useStaffAccess();

  return useMemo(() => {
    const isSupervisor = isSupervisorApiRole(apiRoles);
    const canManageSessions = can("SESSION_EDIT") || can("SESSION_CREATE");
    const canDeleteSessions = can("SESSION_DELETE");
    const canManageTasks = can("CONSENT_ADMIN_VIEW");
    const canAssignAssessments = can("ASSESSMENT_ASSIGN");
    const canManageAssessmentTemplates =
      can("ASSESSMENT_VIEW") && (can("FORM_TEMPLATE_MANAGE") || can("ASSESSMENT_ASSIGN"));
    const canManageClinicalForms =
      can("FORM_TEMPLATE_MANAGE") || can("FORM_VIEW");
    const canManageChecklists = can("CONSENT_ADMIN_VIEW");

    return {
      isSupervisor,
      /** Legacy supervisor-only UI blocks (pass as `staffMode` to shared admin components). */
      supervisorStaffMode: isSupervisor,
      canManageSessions,
      canDeleteSessions,
      canManageTasks,
      canAssignAssessments,
      canManageAssessmentTemplates,
      canManageClinicalForms,
      canManageChecklists,
      hideSchedulingEdits: isSupervisor || !canManageSessions,
      hideSessionTabActions: isSupervisor || !canManageSessions,
      hideTableScheduledSession: isSupervisor || !canManageSessions,
      hideTableCreateTask: isSupervisor || !canManageTasks,
    };
  }, [apiRoles, can]);
}

