      canPerm(permissions, "SESSION_EDIT") || canPerm(permissions, "SESSION_CREATE");
    const canDeleteSessions = canPerm(permissions, "SESSION_DELETE");
    const canManageTasks = canPerm(permissions, "CONSENT_ADMIN_VIEW");
