      canPerm(permissions, "ASSESSMENT_VIEW") &&
      (canPerm(permissions, "FORM_TEMPLATE_MANAGE") ||
        canPerm(permissions, "ASSESSMENT_ASSIGN"));
    const canManageClinicalForms =
      canPerm(permissions, "FORM_TEMPLATE_MANAGE") || canPerm(permissions, "FORM_VIEW");
    const canManageChecklists = canPerm(permissions, "CONSENT_ADMIN_VIEW");

    return {
      isSupervisor,
      supervisorStaffMode: isSupervisor,
      canManageSessions,
      canDeleteSessions,
      canManageTasks,
      canAssignAssessments,
      canManageAssessmentTemplates,
